    @MainActor
    func testLiveReviewPolicyDenialAndFailedRefreshDoNotSendResources() throws {
        for mode in ["deny", "refreshDeny", "refreshFail", "rotate"] {
            try assertLiveReviewPolicyReads(mode: mode)
        }
    }

    @MainActor
    private func assertLiveReviewPolicyReads(mode: String) throws {
        for endpoint in ["source", "sources", "themes"] {
            let (runtime, lease) = try makeActiveRuntime()
            let vault = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
            let source = recordID("00000000-0000-0000-0000-000000000202")
            let auth = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
            let start = Date(); var clock = start
            func snapshot(_ expires: Date, enabled: Bool = true) -> FeatureGatePolicySnapshot {
                FeatureGatePolicySnapshot(accessMode: .useCachedPolicy, policyVersion: "review-policy",
                    policyRevision: 11, emergencyRevision: 1, expiresAt: expires,
                    featureEnabled: enabled, releaseVisible: enabled,
                    reason: enabled ? "candidateReviewEnabled" : "candidateReviewDisabled")
            }
            var policy = snapshot(start.addingTimeInterval(600))
            let gate = FeatureGateService.makeQATestService(accountGeneration: { auth.sessionId },
                policy: { _, _ in policy }, now: { clock })
            XCTAssertTrue(gate.captureServerPolicyManagedRoute(.ownerTruthCandidateReview).allowed)
            clock = start.addingTimeInterval(816)
            XCTAssertEqual(gate.requestServerPolicyManagedDecision(for: .ownerTruthCandidateReview).reason,
                "capturedPolicyExpired")
            if mode == "fresh" || mode == "deny" {
                policy = snapshot(clock.addingTimeInterval(600), enabled: mode != "deny")
            }
            var refreshes = 0
            let client = DreamJourneyBackendClient.makeQATestClient(
                baseURL: URL(string: "https://owner-truth.qa.invalid")!,
                session: try makeOwnerTruthHTTPTestSession(), authenticatedSession: { auth },
                currentUserID: { lease.subjectId }, privateAccessAllowed: { true },
                featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
                freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
                featureDecisionRevalidator: { gate.revalidateServerPolicyManagedRequest($0) },
                accountLeaseRuntime: runtime, candidateInboxPolicyRefresher: { completion in
                    refreshes += 1
                    if mode == "rotate" { runtime.publish(session: nil) }
                    if mode == "refreshFail" { completion(.failure(URLError(.notConnectedToInternet))); return }
                    policy = snapshot(clock.addingTimeInterval(600), enabled: mode != "refreshDeny" && mode != "deny")
                    completion(.success(()))
                })
            let record: [String: Any] = ["sourceId": source.rawValue.uuidString, "sourceKind": "text",
                "sourceVersion": 1, "state": "active", "textPreview": "合成证据", "text": "合成证据完整正文",
                "origin": NSNull(), "createdAt": "2026-10-02T00:00:00Z", "updatedAt": "2026-10-02T00:00:00Z",
                "organizationStatus": "awaitingReview", "extractionStatus": "succeeded", "failureCode": NSNull(),
                "candidateCount": 1, "pendingCount": 1, "confirmedCount": 0, "rejectedCount": 0]
            let payload: [String: Any]
            if endpoint == "source" {
                payload = ["schemaVersion": OwnerTruthSourceRecordDetail.schemaVersion, "vaultId": lease.vaultId, "record": record]
            } else if endpoint == "sources" {
                payload = ["schemaVersion": OwnerTruthSourceRecordPage.schemaVersion, "vaultId": lease.vaultId,
                    "records": [record], "nextCursor": NSNull()]
            } else {
                payload = ["schemaVersion": "owner-truth-live-theme-inbox-v1", "vaultId": lease.vaultId,
                    "themes": [], "nextCursor": NSNull()]
            }
            let data = try JSONSerialization.data(withJSONObject: payload)
            OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
                XCTAssertEqual(request.httpMethod, "GET")
                let suffix = endpoint == "themes" ? "live-memory-themes" : endpoint == "source" ? "source-records/\(source.rawValue.uuidString)" : "source-records"
                XCTAssertEqual(request.url?.path, "/v2/vaults/\(lease.vaultId)/\(suffix)")
                loader.respond(statusCode: 200, body: data)
            }
            defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
            var received: Result<Void, Error>?
            if endpoint == "source" {
                client.fetchOwnerTruthSourceRecord(vaultID: vault, sourceID: source) {
                    received = $0.map { XCTAssertEqual($0.text, "合成证据完整正文") }
                }
            } else if endpoint == "sources" {
                client.fetchOwnerTruthSourceRecords(vaultID: vault, query: try OwnerTruthSourceRecordQuery()) {
                    received = $0.map { XCTAssertEqual($0.records.count, 1) }
                }
            } else {
                client.fetchOwnerTruthLiveThemes(lease: lease) { received = $0.map { XCTAssertTrue($0.themes.isEmpty) } }
            }
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { received != nil })
            let success = mode == "fresh" || mode == "refresh"
            if success {
                XCTAssertNoThrow(try XCTUnwrap(received).get(), "\(mode)/\(endpoint)")
            } else {
                guard case .failure(let error) = received else { XCTFail("denial must fail"); continue }
                if mode == "rotate" {
                    guard case .accountScopeChanged? = error as? DreamJourneyBackendClient.ClientError else { XCTFail("must reject old lease"); continue }
                } else if mode != "refreshFail" {
                    guard case .featurePolicyDenied(_, let reason)? = error as? DreamJourneyBackendClient.ClientError else {
                        XCTFail("policy denial must not become accountScopeChanged: \(error)"); continue
                    }
                    XCTAssertEqual(reason, "candidateReviewDisabled")
                }
            }
            XCTAssertEqual(refreshes, ["fresh", "deny"].contains(mode) ? 0 : 1)
            XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, success ? 1 : 0)
            OwnerTruthReviewReadyHTTPURLProtocol.reset()
        }
    }

    func testSeptember30BatchCannotOverwriteConcurrentAcknowledgement() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("batch-ack-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        func event(_ n: Int) -> NativeLiveCanonicalTranscriptEvent {
            NativeLiveCanonicalTranscriptEvent(canonicalTurnID: "turn-\(n)", role: .owner, text: "合成事实\(n)",
                finality: .complete, observationID: "observation-\(n)", ingressOrdinal: UInt64(n),
                sealing: .observeAndSeal, capturedAt: Date(timeIntervalSince1970: Double(n)))
        }
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let initial = try store.upsertCanonicalTurn(event(1), for: lease, productSessionID: "batch")
        let id = try XCTUnwrap(initial.pendingTurns.first?.messageID)
        let lock = NSLock(); var failures = 0
        DispatchQueue.concurrentPerform(iterations: 2) { index in
            do {
                let other = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
                if index == 0 { _ = try other.acknowledge(messageID: id, for: lease, productSessionID: "batch") }
                else { _ = try other.persistCanonicalBatch((2...33).map { .event(event($0)) }, for: lease, productSessionID: "batch") }
            } catch { lock.lock(); failures += 1; lock.unlock() }
        }
        let rebuilt = try XCTUnwrap(store.load(for: lease, productSessionID: "batch"))
        XCTAssertEqual(failures, 0); XCTAssertEqual(rebuilt.ownerTurnCount, 33)
        XCTAssertEqual(rebuilt.pendingTurns.count, 32)
        XCTAssertFalse(rebuilt.pendingTurns.contains { $0.messageID == id })
        XCTAssertEqual(rebuilt.canonicalCoverageSummary.serverConfirmedCount, 1)
    }

    @MainActor
    func testLiveReviewPolicyThemeWritesCaptureFreshAuthorityButNeverReplay() throws {
        for denied in [false, true] {
            for confirming in [false, true] {
                let (runtime, lease) = try makeActiveRuntime()
                let auth = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
                let start = Date(); var clock = start
                var policy = FeatureGatePolicySnapshot(accessMode: .useCachedPolicy, policyVersion: "theme-write",
                    policyRevision: 11, emergencyRevision: 1, expiresAt: start.addingTimeInterval(600),
                    featureEnabled: true, releaseVisible: true, reason: "candidateReviewEnabled")
                let gate = FeatureGateService.makeQATestService(accountGeneration: { auth.sessionId },
                    policy: { _, _ in policy }, now: { clock })
                XCTAssertTrue(gate.captureServerPolicyManagedRoute(.ownerTruthCandidateReview).allowed)
                clock = start.addingTimeInterval(816)
                policy = FeatureGatePolicySnapshot(accessMode: .useCachedPolicy, policyVersion: "theme-write",
                    policyRevision: 11, emergencyRevision: 1, expiresAt: clock.addingTimeInterval(600),
                    featureEnabled: !denied, releaseVisible: !denied, reason: denied ? "candidateReviewDisabled" : "candidateReviewEnabled")
                var refreshes = 0
                let client = DreamJourneyBackendClient.makeQATestClient(
                    baseURL: URL(string: "https://owner-truth.qa.invalid")!,
                    session: try makeOwnerTruthHTTPTestSession(), authenticatedSession: { auth },
                    currentUserID: { lease.subjectId }, privateAccessAllowed: { true },
                    featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
                    freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
                    featureDecisionRevalidator: { gate.revalidateServerPolicyManagedRequest($0) },
                    authSessionRefresher: { _, completion in refreshes += 1; completion(auth) },
                    accountLeaseRuntime: runtime,
                    candidateInboxPolicyRefresher: { completion in refreshes += 1; completion(.success(())) })
                let topic = UUID().uuidString.lowercased(), source = UUID().uuidString.lowercased()
                let atoms = [UUID().uuidString.lowercased(), UUID().uuidString.lowercased()]
                let candidates = [recordID("00000000-0000-0000-0000-0000000007b1"), recordID("00000000-0000-0000-0000-0000000007b2")]
                let memberPairs = zip(atoms, candidates).map { atom, candidate in
                    (atom, ["candidateId": candidate.rawValue.uuidString.lowercased(), "sourceId": source,
                        "proposalHash": String(repeating: "c", count: 64)])
                }
                let theme = try OwnerTruthLiveTheme(object: ["schemaVersion": "owner-truth-live-theme-v1",
                    "topicId": topic, "version": 1, "proposalHash": String(repeating: "a", count: 64),
                    "ownerId": lease.subjectId, "vaultId": lease.vaultId, "state": "pending", "sourceId": source,
                    "theme": ["title": "合成主题", "summary": "合成测试事实", "dimensions": ["knowledgeSkills"], "atomIds": atoms],
                    "members": Dictionary(uniqueKeysWithValues: memberPairs),
                    "memberDetails": Dictionary(uniqueKeysWithValues: zip(atoms, candidates).map { atom, candidate in
                        (atom, ["candidateId": candidate.rawValue.uuidString.lowercased(), "statement": "合成测试事实"])
                    })], lease: lease)
                let proposal = try relatedGroupProposal(vaultID: lease.vaultId, candidateIDs: candidates, themeBinding: theme.binding)
                OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
                    XCTAssertEqual(request.httpMethod, "POST")
                    XCTAssertEqual(request.url?.path, "/v2/vaults/\(lease.vaultId)/live-memory-themes/\(topic)/\(confirming ? "confirm" : "preview")")
                    loader.respond(statusCode: 401, body: Data("{\"code\":\"access_expired\"}".utf8))
                }
                defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
                var finished = false
                func checkDenied(_ error: Error) {
                    guard case .featurePolicyDenied(_, let reason)? = error as? DreamJourneyBackendClient.ClientError else {
                        return XCTFail("true policy denial must not become accountScopeChanged")
                    }
                    XCTAssertEqual(reason, "candidateReviewDisabled")
                }
                if confirming {
                    client.confirmOwnerTruthLiveTheme(lease: lease, theme: theme, commandID: "synthetic-confirm",
                        edits: [:], rejecting: false, proposal: proposal) { outcome in
                        if denied {
                            if case .notSent(let error) = outcome { checkDenied(error) }
                            else { XCTFail("denied write must not be sent") }
                        } else if case .outcomeUnknown = outcome { /* never replay */ }
                        else { XCTFail("exposed 401 must stay unknown") }
                        finished = true
                    }
                } else {
                    client.previewOwnerTruthLiveTheme(lease: lease, theme: theme, commandID: "synthetic-preview",
                        edits: [:], rejecting: false) { result in
                        if case .failure(let error) = result { if denied { checkDenied(error) } }
                        else { XCTFail("401 must not succeed") }
                        finished = true
                    }
                }
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { finished })
                XCTAssertEqual(refreshes, 0)
                XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, denied ? 0 : 1)
                OwnerTruthReviewReadyHTTPURLProtocol.reset()
            }
        }
    }

    @MainActor
    func testSeptember30BatchAdmissionBoundsQueuedAndInflightOperations() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("batch-bound-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        let entered = DispatchSemaphore(value: 0), release = DispatchSemaphore(value: 0)
        var first = true
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root, atomicWrite: { data, url in
            if first { first = false; entered.signal(); _ = release.wait(timeout: .now() + 10) }
            _ = try KnowledgeLocalStoragePolicy.write(data, to: url)
        })
        let coordinator = EchoLiveMemoryCaptureCoordinator(accountLease: lease, client: InterviewNaturalInputClientSpy(),
            accountLeaseRuntime: runtime, productSessionID: "bound", liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(rootDirectory: root.appendingPathComponent("checkpoint")),
            naturalInputPolicyAvailable: { false }, candidateReviewPolicyAvailable: { false })
        func submit(_ n: Int) {
            coordinator.registerCanonicalMember(NativeLiveCanonicalTranscriptMember(canonicalTurnID: "m-\(n)",
                role: .owner, capturedAt: Date(), ingressOrdinal: UInt64(n)))
        }
        submit(1)
        XCTAssertEqual(entered.wait(timeout: .now() + 3), .success)
        for n in 2...129 { submit(n) }
        XCTAssertNotNil(coordinator.firstCaptureFailure)
        XCTAssertFalse(coordinator.acceptsTurns, "the admission queue, not only disk-failure replay, must be bounded")
        release.signal()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
            (try? store.load(for: lease, productSessionID: "bound"))?.canonicalCoverageSummary.registeredMemberCount == 128
        })
        coordinator.finish()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
            (try? store.load(for: lease, productSessionID: "bound"))?.hasCanonicalOverflowGap == true
        })
    }

    func testSeptember30BatchCommitPreservesIdentityAndUsesOneWrite() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("batch-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        var writes = 0
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root, atomicWrite: { data, url in
            _ = try KnowledgeLocalStoragePolicy.write(data, to: url); writes += 1
        })
        let operations: [OwnerTruthInterviewLiveTurnOutboxStore.CanonicalWrite] = (1...32).map { n in
            .handoff(NativeLiveCanonicalTranscriptMember(canonicalTurnID: "body-\(n)", handoffID: "h-\(n)",
                role: .owner, capturedAt: Date(timeIntervalSince1970: Double(n)), ingressOrdinal: UInt64(n)), nil)
        }
        let first = try store.persistCanonicalBatch(operations, for: lease, productSessionID: "batch")
        XCTAssertEqual(first.committedCount, 32); XCTAssertNil(first.firstError); XCTAssertEqual(writes, 1)
        let rebuilt = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let replay = try rebuilt.persistCanonicalBatch(operations, for: lease, productSessionID: "batch")
        XCTAssertEqual(replay.snapshot?.canonicalCoverageSummary.registeredMemberCount, 32)
        XCTAssertEqual(replay.snapshot?.canonicalConflictCount, 0)
        XCTAssertThrowsError(try store.persistCanonicalBatch(operations + operations, for: lease, productSessionID: "batch"))
    }

