            .load(for: lease, productSessionID: "batch")?.canonicalCoverageSummary.registeredMemberCount, 1)
    }

    func testSeptember30BatchDiskFailureAndUnknownCommitKeepOriginalIdentity() throws {
        let (_, lease) = try makeActiveRuntime()
        for mode in ["before", "after", "stale"] {
            let root = FileManager.default.temporaryDirectory.appendingPathComponent("batch-disk-\(mode)-\(UUID())")
            defer { try? FileManager.default.removeItem(at: root) }
            let original = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
            let member = NativeLiveCanonicalTranscriptMember(canonicalTurnID: "one", handoffID: "original-handoff",
                role: .owner, capturedAt: Date(timeIntervalSince1970: 1), ingressOrdinal: 1)
            // Seed a valid file so a no-op write cannot pass on validity alone.
            _ = try original.registerCanonicalMember(NativeLiveCanonicalTranscriptMember(canonicalTurnID: "seed",
                role: .owner, capturedAt: Date(timeIntervalSince1970: 0), ingressOrdinal: 2), for: lease, productSessionID: "batch")
            let faulty = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root, atomicWrite: { data, url in
                if mode == "after" { _ = try KnowledgeLocalStoragePolicy.write(data, to: url) }
                if mode != "stale" { throw NSError(domain: "SyntheticDisk", code: 1) }
            })
            if mode == "after" {
                XCTAssertEqual(try faulty.persistCanonicalBatch([.handoff(member, nil)], for: lease,
                    productSessionID: "batch").committedCount, 1)
            } else {
                XCTAssertThrowsError(try faulty.persistCanonicalBatch([.handoff(member, nil)], for: lease, productSessionID: "batch"))
                XCTAssertEqual(try original.load(for: lease, productSessionID: "batch")?.canonicalCoverageSummary.registeredMemberCount, 1)
            }
            // Fresh instance, exact original handoff. Neither unknown write nor replay duplicates it.
            let restored = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
            _ = try restored.persistCanonicalBatch([.handoff(member, nil)], for: lease, productSessionID: "batch")
            XCTAssertEqual(try restored.load(for: lease, productSessionID: "batch")?.canonicalCoverageSummary.registeredMemberCount, 2)
        }
    }

    func testSeptember30BatchMultipleStoresSerializeReadModifyWrite() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("batch-concurrent-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        let lock = NSLock(); var errors = 0
        DispatchQueue.concurrentPerform(iterations: 64) { index in
            do {
                let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
                let member = NativeLiveCanonicalTranscriptMember(canonicalTurnID: "member-\(index)", role: .owner,
                    capturedAt: Date(timeIntervalSince1970: Double(index)), ingressOrdinal: UInt64(index + 1))
                if index.isMultiple(of: 2) {
                    _ = try store.persistCanonicalBatch([.member(member)], for: lease, productSessionID: "batch")
                } else {
                    _ = try store.registerCanonicalMember(member, for: lease, productSessionID: "batch")
                }
            } catch { lock.lock(); errors += 1; lock.unlock() }
        }
        XCTAssertEqual(errors, 0)
        XCTAssertEqual(try OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
            .load(for: lease, productSessionID: "batch")?.canonicalCoverageSummary.registeredMemberCount, 64)
    }

    @MainActor
    func testSeptember30PacedSDKPersistenceDrain() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("queue-cost-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        let sessionID = "queue-cost"
        let lock = NSLock()
        var rows: [String: [Double]] = [:], depths: [Int] = [], byteCounts: [Int] = []
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root, costObservation: { stage, ms, bytes in
            lock.lock(); defer { lock.unlock() }
            rows[stage, default: []].append(ms)
            if stage == "atomicReplace" { byteCounts.append(bytes) }
        })
        let coordinator = EchoLiveMemoryCaptureCoordinator(accountLease: lease,
            client: InterviewNaturalInputClientSpy(), accountLeaseRuntime: runtime, productSessionID: sessionID,
            liveTurnOutboxStore: store,
            followUpStore: EchoLiveMemoryFollowUpStore(rootDirectory: root.appendingPathComponent("follow")),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(rootDirectory: root.appendingPathComponent("checkpoint")),
            criticalDiagnosticsStore: NativeLiveDiagnosticsRingStore(rootDirectory: root.appendingPathComponent("diagnostic")),
            persistenceCostObservation: { stage, ms, depth in
                lock.lock(); defer { lock.unlock() }
                rows[stage, default: []].append(ms)
                if stage == "queueWait" { depths.append(depth) }
            }, naturalInputPolicyAvailable: { false }, candidateReviewPolicyAvailable: { false })
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(accountLease: lease, coordinator: coordinator)
        let manager = DialogEngineManager.shared, generation = UUID(), operation = UUID()
        manager.setCanonicalIngressDeliverySchedulerForTesting { $0() }
        manager.installCanonicalIngressForTesting(engineGeneration: generation, dialogOperationID: operation, delegate: controller)
        defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operation) }
        let pace = 0.06
        var accepted = 0
        var identities = Set<String>()
        var windows: [[String: Any]] = []
        let start = ProcessInfo.processInfo.systemUptime
        func send(_ kind: DialogProviderCanonicalIngressKind, _ body: [String: Any]) throws {
            // SDK replay uses a wall-clock schedule, not a per-event durable barrier.
            let due = start + Double(accepted) * pace
            while ProcessInfo.processInfo.systemUptime < due {
                RunLoop.current.run(until: Date().addingTimeInterval(min(0.005, due - ProcessInfo.processInfo.systemUptime)))
            }
            let delivered = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(kind: kind,
                data: JSONSerialization.data(withJSONObject: body), engineGeneration: generation))
            if let member = delivered.member { identities.insert(member.canonicalTurnID) }
            accepted += 1
        }
        for n in 0..<72 {
            try send(.asrInfo, ["question_id": "density-\(n)"])
            for j in 0..<78 {
                try send(.asrResponse, ["results": [["text": "第\(n)条合成事实" + String(repeating: "内容", count: j + 1), "is_interim": j != 77]]])
            }
            try send(.asrEnded, ["question_id": "density-\(n)"])
            if (n + 1) % 24 == 0 {
                lock.lock()
                let wait = Array((rows["queueWait"] ?? []).suffix(1920)).sorted()
                let d = Array(depths.suffix(1920))
                windows.append(["members": n + 1, "p95QueueWaitMs": wait.isEmpty ? 0 : wait[Int(Double(wait.count - 1) * 0.95)],
                                "maxDepth": d.max() ?? 0, "lastDepth": d.last ?? 0])
                lock.unlock()
            }
        }
        manager.closeCanonicalIngressForTesting(dialogOperationID: operation)
        let stopAt = ProcessInfo.processInfo.systemUptime
        controller.finishLiveMemoryCaptureForTesting()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 15) {
            guard coordinator.pendingCanonicalHandoffCountForTesting == 0,
                  coordinator.pendingCanonicalRecoveryCountForTesting == 0,
                  let durable = try? store.load(for: lease, productSessionID: sessionID) else { return false }
            return durable.closeIntentRequestedAt != nil && durable.pendingCloseManifestHandoffCount == 0
        }, "accepted SDK queue and close intent must be durable within the unchanged 15-second closing deadline")
        let drainMs = (ProcessInfo.processInfo.systemUptime - stopAt) * 1000
        let snapshot = try XCTUnwrap(OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root).load(for: lease, productSessionID: sessionID))
        XCTAssertEqual(snapshot.ownerTurnCount, 72)
        XCTAssertEqual(snapshot.pendingTurns.count, 72)
        XCTAssertEqual(identities.count, 72)
        XCTAssertEqual(snapshot.pendingCloseManifestHandoffCount, 0)
        XCTAssertEqual(snapshot.canonicalConflictCount, 0)
        XCTAssertNotNil(snapshot.closeIntentRequestedAt)
        XCTAssertNil(coordinator.firstCaptureFailure)
        lock.lock()
        let stats = rows.mapValues { samples -> [String: Double] in
            let a = samples.sorted()
            return ["p50Ms": a[a.count / 2], "p95Ms": a[Int(Double(a.count - 1) * 0.95)], "maxMs": a.last!, "count": Double(a.count)]
        }
        let result: [String: Any] = ["acceptedSDKEvents": accepted, "members": identities.count, "paceSeconds": pace,
            "windows": windows, "phaseStats": stats, "atomicBytes": byteCounts.reduce(0,+), "drainMs": drainMs]
        lock.unlock()
        print("SDK_QUEUE_COST=" + String(decoding: try JSONSerialization.data(withJSONObject: result, options: [.sortedKeys]), as: UTF8.self))
        // A bounded fixture must not conceal unbounded growth behind a final drain.
        XCTAssertLessThan(windows.last?["lastDepth"] as? Int ?? 9999, 16)
    }

    func testSeptember30SampledAudioPreservesFirstFailure() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("diagnostic-cost-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        let lock = NSLock(); var samples: [String: [Double]] = [:]; var bytes = 0
        let store = NativeLiveDiagnosticsRingStore(rootDirectory: root, costObservation: { stage, ms, count in
            lock.lock(); defer { lock.unlock() }
            samples[stage, default: []].append(ms)
            if stage == "atomicReplace" { bytes += count }
        })
        for ordinal in 1...500 {
            store.record(accountLease: lease, providerSessionID: "sample", source: "sdk", event: "providerCallback",
                eventCode: 3018, callbackOrdinal: UInt64(ordinal))
            store.waitForPendingWrites()
        }
        store.recordFirstCriticalFailure(accountLease: lease, providerSessionID: "sample", stage: "capture", reason: "syntheticFailure")
        store.waitForPendingWrites()
        let result = NativeLiveDiagnosticsRingStore(rootDirectory: root).snapshot(accountLease: lease, providerSessionID: "sample")
        XCTAssertEqual(result.events.filter { $0.eventCode == 3018 }.count, 10)
        XCTAssertEqual(result.droppedCount, 490)
        XCTAssertEqual(result.firstCriticalFailure?.reason, "syntheticFailure")
        lock.lock(); defer { lock.unlock() }
        XCTAssertEqual(samples["atomicReplace"]?.count, 11)
        let report: [String: Any] = ["inputCallbacks": 500, "sampledCallbacks": 10, "firstErrorPreserved": true,
            "writtenBytes": bytes, "stageTotalsMs": samples.mapValues { $0.reduce(0,+) }]
        print("DIAGNOSTIC_COST=" + String(decoding: try JSONSerialization.data(withJSONObject: report, options: [.sortedKeys]), as: UTF8.self))
    }

    func testSeptember30CanonicalPersistenceCost() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("contract-cost-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        var writtenBytes = 0, writes = 0
        var phases: [String: [Double]] = [:]
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root, costObservation: { stage, ms, _ in phases[stage, default: []].append(ms) }, atomicWrite: { data, url in
            _ = try KnowledgeLocalStoragePolicy.write(data, to: url)
            writtenBytes += data.count; writes += 1
        })
        var rows: [[String: Any]] = []
        for window in 0..<3 {
            var samples: [Double] = []
            let before = writtenBytes
            for n in (window * 24)..<((window + 1) * 24) {
                for callback in 0..<16 {
                    let ordinal = UInt64(n * 16 + callback + 1)
                    let member = NativeLiveCanonicalTranscriptMember(canonicalTurnID: "synthetic-\(n)",
                        handoffID: "handoff-\(ordinal)", role: n % 2 == 0 ? .owner : .assistant,
                        capturedAt: Date(timeIntervalSince1970: Double(ordinal)), ingressOrdinal: ordinal)
                    let start = ProcessInfo.processInfo.systemUptime
                    try store.persistCanonicalHandoff(member: member, event: nil, for: lease, productSessionID: "cost")
                    samples.append((ProcessInfo.processInfo.systemUptime - start) * 1000)
                }
            }
            samples.sort()
            rows.append(["window": window, "handoffs": samples.count, "p50ms": samples[samples.count / 2],
                "p95ms": samples[Int(Double(samples.count - 1) * 0.95)], "maxms": samples.last!,
                "writtenBytes": writtenBytes - before])
        }
        let rebuilt = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        XCTAssertEqual(try rebuilt.load(for: lease, productSessionID: "cost")?.canonicalCoverageSummary.registeredMemberCount, 72)
        XCTAssertEqual(writes, 1152)
        let result: [String: Any] = ["logicalWindows": "0-10/10-20/20-40; density fixture, not wall time", "samples": rows, "writes": writes, "phaseTotalsMs": phases.mapValues { $0.reduce(0,+) }]
        print("CONTRACT_COST=" + String(decoding: try JSONSerialization.data(withJSONObject: result, options: [.sortedKeys]), as: UTF8.self))
    }



    @MainActor
    func testRecoveryActualHTTPFourScenesShort20Short40() throws {
