    @MainActor
    private func verifyRecoveryGracefulClose(waitForDeadline: Bool, tenMinute: Bool = false) throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vault = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("recovery-controller-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let client = InterviewNaturalInputClientSpy()
        client.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        var received = false
        var final: Int?
        var version = 1
        func progressObject() throws -> [String: Any] {
            let start = try XCTUnwrap(client.startCommand)
            var value: [String: Any] = ["protocol": "live-recovery-v1", "sessionId": start.sessionID.rawValue.uuidString,
                "generation": 1, "version": version, "state": final == nil ? "collecting" : "repairing",
                "continuousSequence": received ? 1 : 0, "highestSeenSequence": received ? 1 : 0,
                "endPositionKnown": final != nil, "receivedRanges": received ? [[1,1]] : [],
                "missingRanges": final != nil && !received ? [[1,1]] : [], "rangeOffset": 0,
                "rangePageTruncated": false, "snapshotRevision": 0]
            if let final { value["finalSequence"] = final }
            if received {
                value["sessionBinding"] = ["threadId": start.threadID.rawValue.uuidString,
                    "sessionVersion": 100, "threadVersion": 100, "authorityEpoch": 0,
                    "state": "active", "boundary": "open", "productSessionId": "recovery-controller"]
                value["snapshotRevision"] = 1
                value["publication"] = ["snapshotRevision": 1, "state": "published", "themeCount": 1]
            }
            return value
        }
        func progress() throws -> OwnerTruthLiveRecoveryProgress {
            try OwnerTruthLiveRecoveryProgress(backendJSONObject: progressObject(),
                expectedSessionID: XCTUnwrap(client.startCommand).sessionID, expectedGeneration: 1)
        }
        client.startHandler = { command in Result {
            var object: [String: Any] = ["schemaVersion": OwnerTruthInterviewNaturalInputReceipt.schemaVersion,
                "vaultId": vault.rawValue, "receipt": ["status": "created", "threadId": command.threadID.rawValue.uuidString,
                    "sessionId": command.sessionID.rawValue.uuidString, "threadVersion": 1, "sessionVersion": 1,
                    "state": "active", "boundary": "open", "authorityEpoch": 0]]
            object["recovery"] = try progressObject()
            return try OwnerTruthInterviewNaturalInputReceipt(backendJSONObject: object, expectedVaultID: vault)
        } }
        client.recoveryAuthorizationHandler = { try progress() }
        client.recoveryControlHandler = { action, sequence in
            if action == "close", let sequence { final = sequence }
            version += 1
            return try progress()
        }
        client.deferAppend = true
        let coordinator = EchoLiveMemoryCaptureCoordinator(accountLease: lease, client: client,
            accountLeaseRuntime: runtime, productSessionID: "recovery-controller", liveTurnOutboxStore: store,
            criticalDiagnosticsStore: NativeLiveDiagnosticsRingStore(rootDirectory: root.appendingPathComponent("diagnostics")),
            recoveryEnabled: true, naturalInputPolicyAvailable: { true }, naturalInputPolicyRefresh: { $0(true) },
            candidateReviewPolicyAvailable: { true })
        coordinator.appendOwnerTurn("我去年在杭州读书。")
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 4) { client.appendCommand != nil })
        XCTAssertEqual(try store.load(for: lease, productSessionID: "recovery-controller")?.acceptedRecoveryProtocol,
                       "live-recovery-v1")
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(accountLease: lease, coordinator: coordinator)
        controller.bindPublicationPageForTesting(lease: lease, productSessionID: "recovery-controller")
        let started = Date()
        if tenMinute {
            var goodbye: (() -> Void)?
            var pauseCount = 0
            controller.beginLiveLimitForTesting(now: 0, pause: { pauseCount += 1; return true },
                playback: { text, done in XCTAssertTrue(text.contains("有点累")); goodbye = done })
            controller.tickLiveLimitForTesting(now: 600, busy: true)
            XCTAssertNil(goodbye)
            controller.tickLiveLimitForTesting(now: 610, busy: false)
            XCTAssertEqual(pauseCount, 1)
            XCTAssertTrue(controller.liveLimitSessionOpenForTesting)
            XCTAssertNil(try store.load(for: lease, productSessionID: "recovery-controller")?.closeRequestedLastClientSequenceNumber)
            try XCTUnwrap(goodbye)()
            XCTAssertFalse(controller.liveLimitSessionOpenForTesting)
        } else {
        controller.requestRecoveryPressureStopForTesting(utteranceActive: true)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            (try? store.load(for: lease, productSessionID: "recovery-controller"))?.recoveryGracefulStopRequestedAt != nil
        })
        let rebuilt = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        XCTAssertNotNil(try rebuilt.load(for: lease, productSessionID: "recovery-controller")?.recoveryGracefulStopRequestedAt)
        XCTAssertNil(try rebuilt.load(for: lease, productSessionID: "recovery-controller")?.closeRequestedLastClientSequenceNumber)
        if !waitForDeadline { controller.finishRecoveryUtteranceForTesting() }
        }
        let rebuilt = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 7) { client.recoveryControls.contains { $0.0 == "close" && $0.1 == 1 } })
        if waitForDeadline { XCTAssertGreaterThanOrEqual(Date().timeIntervalSince(started), 4.9) }
        XCTAssertLessThan(Date().timeIntervalSince(started), 7)
        XCTAssertEqual(try rebuilt.load(for: lease, productSessionID: "recovery-controller")?.ownerTurnCount, 1)

        XCTAssertFalse(received)
        XCTAssertEqual(try store.load(for: lease, productSessionID: "recovery-controller")?.pendingTurns.count, 1)
        XCTAssertTrue(client.endCommands.isEmpty)
        received = true
        let command = try XCTUnwrap(client.appendCommand)
        client.completeDeferredAppend(.success(try interviewNaturalInputReceipt(vaultID: vault, append: command)))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 4) {
            (try? store.load(for: lease, productSessionID: "recovery-controller"))?.pendingTurns.isEmpty == true
        })
        XCTAssertTrue(client.endCommands.isEmpty)
        XCTAssertTrue(client.admissionCommands.isEmpty)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 8) { coordinator.state == .pendingReview })
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            controller.liveMemoryCapturePresentationForTesting().statusText == "整理完成，已存入待确认记忆"
        }, "Actual recovery publication must reach the page, not just coordinator.state")
        let countAfterPublication = client.recoveryControls.count
        // Exceed the normal 5-second poll interval: a settled publication must
        // not rebind ready, regress to saving or keep polling in a tight loop.
        let until = Date().addingTimeInterval(6)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 7) { Date() >= until })
        XCTAssertEqual(client.recoveryControls.count, countAfterPublication)
        XCTAssertEqual(coordinator.state, .pendingReview)
    }

