    func testRecoveryStartNegotiationIsExplicitAndBindsOriginalSession() throws {
        let vault = try XCTUnwrap(OwnerTruthVaultID("recovery-vault"))
        let command = try OwnerTruthInterviewNaturalInputStartCommand(commandID: "recovery-start",
            threadID: OwnerTruthRecordID(rawValue: UUID()), sessionID: OwnerTruthRecordID(rawValue: UUID()),
            entryMode: .live, productSessionID: "recovery", recoveryProtocol: "live-recovery-v1")
        var object: [String: Any] = ["schemaVersion": OwnerTruthInterviewNaturalInputReceipt.schemaVersion,
            "vaultId": vault.rawValue, "receipt": ["status": "created",
                "threadId": command.threadID.rawValue.uuidString, "sessionId": command.sessionID.rawValue.uuidString,
                "threadVersion": 1, "sessionVersion": 1, "state": "active", "boundary": "open", "authorityEpoch": 0]]
        let unsupported = try OwnerTruthInterviewNaturalInputReceipt(backendJSONObject: object, expectedVaultID: vault)
        XCTAssertFalse(unsupported.matches(command), "A successful legacy start is not recovery negotiation")
        var progress: [String: Any] = ["protocol": "live-recovery-v1", "sessionId": command.sessionID.rawValue.uuidString,
            "generation": 1, "version": 1, "state": "collecting", "continuousSequence": 0,
            "highestSeenSequence": 0, "finalSequence": NSNull(), "endPositionKnown": false,
            "receivedRanges": [], "missingRanges": [], "rangeOffset": 0,
            "nextRangeOffset": NSNull(), "rangePageTruncated": false, "snapshotRevision": 0, "repairDeadline": NSNull()]
        object["recovery"] = progress
        let accepted = try OwnerTruthInterviewNaturalInputReceipt(backendJSONObject: object, expectedVaultID: vault)
        XCTAssertTrue(accepted.matches(command))
        let restored = try JSONDecoder().decode(OwnerTruthInterviewNaturalInputReceipt.self,
            from: JSONEncoder().encode(accepted))
        XCTAssertEqual(restored.recoveryProgress, accepted.recoveryProgress)
        progress["sessionId"] = UUID().uuidString; object["recovery"] = progress
        XCTAssertThrowsError(try OwnerTruthInterviewNaturalInputReceipt(backendJSONObject: object, expectedVaultID: vault))
    }

    func testRecoveryProgressRejectsMixedGenerationAndFalseContinuousWatermark() throws {
        let id = OwnerTruthRecordID(rawValue: UUID())
        let object: [String: Any] = ["protocol": "live-recovery-v1", "sessionId": id.rawValue.uuidString,
            "generation": 1, "version": 3, "state": "repairing", "continuousSequence": 2,
            "highestSeenSequence": 4, "finalSequence": 4, "endPositionKnown": true,
            "receivedRanges": [[1,2],[4,4]], "missingRanges": [[3,3]], "rangeOffset": 0,
            "nextRangeOffset": NSNull(), "rangePageTruncated": false, "snapshotRevision": 0,
            "repairDeadline": NSNull()]
        XCTAssertEqual(try OwnerTruthLiveRecoveryProgress(backendJSONObject: object,
            expectedSessionID: id, expectedGeneration: 1).missingRanges, [[3,3]])
        XCTAssertThrowsError(try OwnerTruthLiveRecoveryProgress(backendJSONObject: object,
            expectedSessionID: id, expectedGeneration: 2))
        var falseComplete = object; falseComplete["continuousSequence"] = 4
        XCTAssertThrowsError(try OwnerTruthLiveRecoveryProgress(backendJSONObject: falseComplete,
            expectedSessionID: id, expectedGeneration: 1))
        var overlap = object; overlap["missingRanges"] = [[2,3]]
        XCTAssertThrowsError(try OwnerTruthLiveRecoveryProgress(backendJSONObject: overlap,
            expectedSessionID: id, expectedGeneration: 1))
        XCTAssertThrowsError(try OwnerTruthLiveRecoveryProgress(backendJSONObject: object,
            expectedSessionID: id, expectedGeneration: 1, expectedVersion: 2))
    }

    func testResilientReplayKeepsIdentityAndBudgetAcrossStoreRebuild() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("resilient-\(UUID())")
        defer { try? FileManager.default.removeItem(at: root) }
        var now = Date(timeIntervalSince1970: 1_800_000_000)
        let product = "resilient-replay"
        var store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root, now: { now })
        let start = try OwnerTruthInterviewNaturalInputStartCommand(commandID: "start",
            threadID: OwnerTruthRecordID(rawValue: UUID()), sessionID: OwnerTruthRecordID(rawValue: UUID()),
            entryMode: .live, productSessionID: product, recoveryProtocol: "live-recovery-v1")
        _ = try store.prepareStart(start, for: lease, productSessionID: product)
        _ = try store.markStartDispatchState(.mayExpose, command: start, for: lease, productSessionID: product)
        _ = try store.markStartDispatchState(.committed, command: start, for: lease, productSessionID: product)
        try store.acceptRecoveryProtocol("live-recovery-v1", sessionID: start.sessionID, for: lease, productSessionID: product)
        let snapshot = try store.enqueue(role: .owner, text: "本地合成事实", for: lease, productSessionID: product)
        let delivery = try XCTUnwrap(snapshot.pendingTurns.first)
        let command = try delivery.appendCommand(threadID: start.threadID, sessionID: start.sessionID,
            expectedThreadVersion: 1, expectedSessionVersion: 1)
        _ = try store.prepareAppendExposure(command: command, retry: false, for: lease, productSessionID: product)
        _ = try store.markDispatchState(.outcomeUnknown, messageID: delivery.messageID, for: lease, productSessionID: product)
        for _ in 0..<3 {
            store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root, now: { now })
            XCTAssertEqual(try store.claimRecoveryReplay(messageID: delivery.messageID, for: lease, productSessionID: product), command)
            XCTAssertThrowsError(try store.claimRecoveryReplay(messageID: delivery.messageID, for: lease, productSessionID: product), "cannot overlap an exposed attempt")
            _ = try store.markDispatchState(.outcomeUnknown, messageID: delivery.messageID, for: lease, productSessionID: product)
        }
        XCTAssertThrowsError(try store.claimRecoveryReplay(messageID: delivery.messageID, for: lease, productSessionID: product))
        now = now.addingTimeInterval(61)
        store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root, now: { now })
        XCTAssertThrowsError(try store.claimRecoveryReplay(messageID: delivery.messageID, for: lease, productSessionID: product))
        XCTAssertEqual(try store.load(for: lease, productSessionID: product)?.pendingTurns.count, 1)
        let cycle = UUID()
        XCTAssertFalse(try store.beginForegroundRecoveryCycle(id: cycle, for: lease, productSessionID: product))
        now = now.addingTimeInterval(240)
        XCTAssertTrue(try store.beginForegroundRecoveryCycle(id: cycle, for: lease, productSessionID: product))
        XCTAssertFalse(try store.beginForegroundRecoveryCycle(id: cycle, for: lease, productSessionID: product))
        try store.deferRecoveryReplay(until: now.addingTimeInterval(20), for: lease, productSessionID: product)
        XCTAssertThrowsError(try store.claimRecoveryReplay(messageID: delivery.messageID, for: lease, productSessionID: product))
        now = now.addingTimeInterval(20)
        XCTAssertEqual(try store.claimRecoveryReplay(messageID: delivery.messageID, for: lease, productSessionID: product), command)
    }

