            authenticatedSession: { store.currentSession }, currentUserID: { original.userId }, privateAccessAllowed: { true },
            featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
            freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
            accountLeaseRuntime: runtime)
        var refreshLoader: OwnerTruthReviewReadyHTTPURLProtocol?
        var refreshCount = 0
        var ticketCount = 0
        let ticket = try micVoiceTicketResponse(ownerID: original.userId, productSessionID: "shared-survivor")
        let rejection = Data("{\"detail\":\"invalid or expired access token\"}".utf8)
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            if request.url?.path == "/auth/refresh" {
                refreshCount += 1; refreshLoader = loader
            } else if request.url?.path == "/voice/realtime-token" {
                ticketCount += 1
                if request.value(forHTTPHeaderField: "Authorization") == "Bearer \(original.accessToken)" {
                    loader.respond(statusCode: 401, body: rejection)
                } else { loader.respond(statusCode: 200, body: ticket) }
            } else { XCTFail("Unexpected path"); loader.fail(URLError(.unsupportedURL)) }
        }
        let first = EchoVoiceLaunchAttempt(ownerID: lease.subjectId, accountLease: lease, initialCaptureID: nil)
        let second = EchoVoiceLaunchAttempt(ownerID: lease.subjectId, accountLease: lease, initialCaptureID: nil)
        first.beginBudget {}; second.beginBudget {}
        var firstSuccesses = 0
        let completed = expectation(description: "second launch survives shared refresh")
        client.fetchRealtimeVoiceConfig(userId: original.userId, launchAttempt: first) { result in
            if case .success = result { firstSuccesses += 1 }
        }
        client.fetchRealtimeVoiceConfig(userId: original.userId, launchAttempt: second) { result in
            guard case .success(let config) = result else { XCTFail("Survivor failed: \(result)"); completed.fulfill(); return }
            XCTAssertEqual(config.productSessionID, "shared-survivor")
            completed.fulfill()
        }
        // Observe the production coalescer, not a test-owned list of completions.
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            refreshLoader != nil && client.authRefreshWaiterCountForTesting == 2
        })
        first.cancelIfPending()
        let authObject = try JSONSerialization.jsonObject(with: JSONEncoder().encode(successor))
        refreshLoader?.respond(statusCode: 200, body: try JSONSerialization.data(withJSONObject: ["auth": authObject]))
        await fulfillment(of: [completed], timeout: 5)
        XCTAssertEqual(firstSuccesses, 0)
        XCTAssertEqual(refreshCount, 1)
        XCTAssertEqual(ticketCount, 3, "two rejected first requests, only the surviving second request")
        XCTAssertEqual(client.authRefreshWaiterCountForTesting, 0)
        XCTAssertEqual(store.currentSession?.sessionId, successor.sessionId)
        second.cancelIfPending()
        _ = await AccountSessionActor.shared.signOut(expectedGeneration: nil, reason: "mic-shared-auth-complete")
    }


    #if LIVE_MANAGER_CONTROLLED_SDK
