    @MainActor
    func testMICProductionManagerControlledSDKLifecycle() throws {
        for scenario in ["setupDeadline", "directiveFailure", "missingStarted", "lateAfterCancel", "handoff", "replacement", "cumulative", "authDeadline", "authRotation", "runtimeDeadline", "networkLoss"] {
            try XCTContext.runActivity(named: scenario) { _ in
                try exerciseMICProductionManager(scenario: scenario)
            }
        }
    }

    @MainActor
    private func exerciseMICProductionManager(scenario: String) throws {
        let owner = "mic-native-\(scenario)"
        let auth = try makeOwnerTruthHTTPTestAuthSession(userID: owner)
        let runtime = AccountLeaseRuntime.shared
        let previousUser = UserManager.shared.currentUser
        runtime.updateAuthorityEpoch("mic-native")
        runtime.publish(session: accountSession(subjectId: owner, vaultId: "mic-native-vault",
            generation: 1, generationID: UUID(), sessionID: auth.sessionId))
        UserManager.shared.setSyntheticCurrentUserForTesting(UserModel(id: owner, nickname: "Synthetic", phone: ""))
        let lease = try XCTUnwrap(runtime.capture(forSubjectId: owner))
        let manager = DialogEngineManager.shared
        manager.destroyEngine()
        SpeechEngine.resetControlledBoundary()
        let controller = EchoViewController()
        let farewellRoot = FileManager.default.temporaryDirectory.appendingPathComponent("native-farewell-\(UUID())")
        let farewellOutbox = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: farewellRoot)
        var farewellCapture: EchoLiveMemoryCaptureCoordinator?
        var captureIndex = 0
        defer {
            try? FileManager.default.removeItem(at: farewellRoot)
            controller.cancelVoiceLaunchForTesting()
            manager.destroyEngine()
            SpeechEngine.resetControlledBoundary()
            OwnerTruthReviewReadyHTTPURLProtocol.reset()
            UserManager.shared.setSyntheticCurrentUserForTesting(previousUser)
            runtime.publish(session: nil)
        }
        var uptime: TimeInterval = 100
        var wallClock = Date(timeIntervalSince1970: 1_800_000_000)
        var watchdog: DispatchWorkItem?
        var pendingAuth: ((BackendAuthSessionContract?) -> Void)?
        var policyReady = scenario != "cumulative"
        var policyRefreshes = 0
        var authRefreshes = 0
        var currentAuth = auth
        let successor = try makeOwnerTruthHTTPTestAuthSession(userID: owner,
            sessionID: "native-next", parentSessionID: auth.sessionId,
            tokenFamilyID: auth.tokenFamilyId, sessionVersion: 2, accessTokenSuffix: "native-next")
        let gate = FeatureGateService.makeQATestService(
            accountGeneration: { currentAuth.sessionId }, policy: { _, _ in
                FeatureGatePolicySnapshot(accessMode: .useCachedPolicy, policyVersion: "native-policy",
                    policyRevision: 7, emergencyRevision: 0, expiresAt: wallClock.addingTimeInterval(policyReady ? 300 : -1),
                    featureEnabled: true, releaseVisible: true, reason: "allowed")
            }, now: { wallClock })
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!, session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { currentAuth }, currentUserID: { owner }, privateAccessAllowed: { true },
            featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
            freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
            authSessionRefresher: { _, done in
                authRefreshes += 1
                if scenario == "authDeadline" || scenario == "authRotation" { pendingAuth = done; return }
                uptime += 4
                currentAuth = successor
                done(successor)
            },
            accountLeaseRuntime: runtime,
            candidateInboxDiagnosticSink: { event in
                if scenario == "cumulative", event.event == "requestRuntimeChecked" { uptime += 1 }
                if scenario == "runtimeDeadline", event.event == "requestRuntimeChecked" {
                    uptime = 116
                    watchdog?.perform()
                }
            },
            liveReadPolicyRefresher: { done in
                policyRefreshes += 1
                uptime += 5
                wallClock = wallClock.addingTimeInterval(-3600)
                policyReady = true
                done(.success(()))
            })
        let ticket = try micVoiceTicketResponse(ownerID: owner, productSessionID: "native-\(scenario)")
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            XCTAssertEqual(request.url?.path, "/voice/realtime-token")
            if scenario == "networkLoss" { loader.fail(URLError(.networkConnectionLost)); return }
            if ["cumulative", "authDeadline", "authRotation"].contains(scenario), OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count == 1 {
                loader.respond(statusCode: 401, body: Data("{\"detail\":\"invalid or expired access token\"}".utf8))
            } else { loader.respond(statusCode: 200, body: ticket) }
        }
        var terminals: [String] = []
        var listening = 0
        controller.installVoiceLaunchBoundariesForTesting(
            accountLease: lease, client: client, timeout: 15,
            clock: { uptime }, scheduler: { _, work in watchdog = work },
            permission: { done in
                if scenario == "handoff" { uptime += 1 }
                done(true)
            }, configureSDK: nil, startSDK: nil, prepareAudio: nil,
            capturesMemory: scenario.hasPrefix("farewell"))
        if scenario.hasPrefix("farewell") {
            controller.setVoiceLaunchCaptureFactoryForTesting { currentLease, _ in
                captureIndex += 1
                let capture = EchoLiveMemoryCaptureCoordinator(accountLease: currentLease,
                    client: InterviewNaturalInputClientSpy(), accountLeaseRuntime: runtime,
                    productSessionID: captureIndex == 1 ? "native-farewell" : "native-farewell-next",
                    liveTurnOutboxStore: farewellOutbox,
                    naturalInputPolicyAvailable: { false }, candidateReviewPolicyAvailable: { false })
                farewellCapture = capture
                return capture
            }
        }
        controller.setVoiceDelegateEventSchedulerForTesting { $0() }
        controller.onVoiceLaunchTerminalForTesting { terminals.append($0) }
        controller.onVoiceListeningForTesting { listening += 1 }
        if scenario == "handoff" { SpeechEngine.onInitialize = { uptime += 2 } }
        if scenario == "setupDeadline" { SpeechEngine.onInitialize = { uptime = 116 } }
        if scenario == "cumulative" { SpeechEngine.onInitialize = { uptime += 5 } }
        if scenario == "directiveFailure" { SpeechEngine.startResult = MICControlledSDKValue(rawValue: -17) }
        controller.tapMicrophoneForTesting()
        if ["authDeadline", "authRotation", "runtimeDeadline", "networkLoss"].contains(scenario) {
            if scenario.hasPrefix("auth") {
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { pendingAuth != nil })
                if scenario == "authRotation" { runtime.publish(session: nil) }
                uptime = 116
                watchdog?.perform()
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { terminals.count == 1 })
                currentAuth = successor
                pendingAuth?(successor)
            }
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { terminals.count == 1 })
            EchoVoiceLaunchDiagnosticStore.shared.waitForPendingWrites()
            let record = try XCTUnwrap(EchoVoiceLaunchDiagnosticStore.shared.recent(ownerID: owner).last)
            XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, scenario == "runtimeDeadline" ? 0 : 1)
            XCTAssertEqual(authRefreshes, scenario.hasPrefix("auth") ? 1 : 0)
            if scenario == "authRotation" { XCTAssertEqual(terminals, ["accountLeaseInvalid"]) }
            else if scenario != "networkLoss" { XCTAssertEqual(terminals, ["voiceLaunchTimeout"]) }
            else {
                XCTAssertEqual(record.errorFamily, "network")
                XCTAssertNil(record.httpStatus)
                XCTAssertEqual(record.requestCount, 1)
            }
            XCTAssertTrue(SpeechEngine.instances.isEmpty)
            XCTAssertFalse(manager.isDialogActive)
            XCTAssertEqual(listening, 0)
            XCTAssertFalse(controller.hasEchoAudioLeaseForTesting)
            return
        }
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { !SpeechEngine.instances.isEmpty })
        let engine = try XCTUnwrap(SpeechEngine.instances.last)
        XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, scenario == "cumulative" ? 2 : 1)
        XCTAssertEqual(policyRefreshes, scenario == "cumulative" ? 1 : 0)
        XCTAssertEqual(authRefreshes, scenario == "cumulative" ? 1 : 0)
        if scenario == "setupDeadline" || scenario == "cumulative" {
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { terminals.count == 1 })
            XCTAssertEqual(engine.count(SEDirectiveStartEngine), 0)
            XCTAssertEqual(terminals, ["voiceLaunchTimeout"])
        } else if scenario == "directiveFailure" {
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { terminals.count == 1 })
            XCTAssertEqual(engine.count(SEDirectiveStartEngine), 1)
            XCTAssertEqual(terminals, ["voiceSDKStartFailed"])
            engine.emit(SEEventSessionStarted)
            engine.emit(SEEngineError)
        } else {
            XCTAssertEqual(engine.count(SEDirectiveStartEngine), 1)
            if scenario == "handoff" || scenario == "replacement" || scenario == "stopClose" || scenario.hasPrefix("farewell") {
                if scenario == "handoff" { uptime += 3 }
                engine.emit(SEEventSessionStarted)
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { listening == 1 })
                XCTAssertTrue(manager.isDialogActive)
                if scenario == "handoff" {
                    let headers = try XCTUnwrap(engine.parameters[SE_PARAMS_KEY_REQUEST_HEADERS_STRING])
                    let headerObject = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(headers.utf8)) as? [String: String])
                    XCTAssertEqual(headerObject["X-DreamJourney-Voice-Session"], "djv_synthetic_ticket")
                    let payload = try XCTUnwrap(engine.directives.first(where: { $0.0 == SEDirectiveStartEngine })?.1)
                    let object = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(payload.utf8)) as? [String: Any])
                    let dialog = try XCTUnwrap(object["dialog"] as? [String: Any])
                    XCTAssertEqual(dialog["system_role"] as? String, "Synthetic formal-memory role")
                    EchoVoiceLaunchDiagnosticStore.shared.waitForPendingWrites()
                    let records = EchoVoiceLaunchDiagnosticStore.shared.recent(ownerID: owner)
                    let last = try XCTUnwrap(records.last)
                    let current = records.filter { $0.attemptID == last.attemptID }
                    XCTAssertEqual(current.map(\.elapsedMilliseconds), current.map(\.elapsedMilliseconds).sorted())
                    XCTAssertEqual(current.last(where: { $0.stage == .permissionEnd })?.elapsedMilliseconds, 1_000)
                    XCTAssertEqual(current.last(where: { $0.stage == .sdkStart })?.elapsedMilliseconds, 1_000, "sdkStart marks stage entry before Manager initialization")
                    XCTAssertEqual(current.last(where: { $0.stage == .listening })?.elapsedMilliseconds, 6_000)
                    XCTAssertEqual(last.requestCount, 1)
                }
                if scenario.hasPrefix("farewell") {
                    let outbox = farewellOutbox
                    let capture = try XCTUnwrap(farewellCapture)
                    capture.appendOwnerTurn("合成测试：我每周六整理工具柜。")
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
                        (try? outbox.load(for: lease, productSessionID: "native-farewell"))?.ownerTurnCount == 1
                    })
                    // Positive control: prove this native callback binding really reaches the
                    // persisted transcript before checking that farewell is excluded.
                    let priorText = Data("{\"reply_id\":\"prior-business\",\"content\":\"这是上一轮的合成回答。\"}".utf8)
                    engine.emit(SEEventChatResponse, data: priorText)
                    engine.emit(SEEventChatEnded, data: priorText)
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
                        (try? outbox.load(for: lease, productSessionID: "native-farewell"))?.pendingTurns.count == 2
                    }, "Positive control: real native assistant ingress must persist before farewell")
                    let parameters = engine.parameters
                    let starts = engine.count(SEDirectiveStartEngine)
                    let greetings = engine.count(SEDirectiveEventSayHello)
                    XCTAssertFalse(manager.submitLiveFarewell("错误绑定", bindingHandle: nil, completion: {
                        XCTFail("Foreign binding must not start or complete farewell")
                    }))
                    let old = Data("{\"reply_id\":\"old-greeting\",\"tts_type\":\"chat_tts_text\"}".utf8)
                    engine.emit(SEEventTTSEnded, data: old)
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { manager.controlledCallbackDrainForTesting == 0 })
                    if scenario == "farewellReject" { SpeechEngine.sayHelloResult = MICControlledSDKValue(rawValue: -17) }
                    controller.beginLiveLimitForTesting(now: 0)
                    controller.tickLiveLimitForTesting(now: 600, busy: false)
                    // Same assertion must fail against the previous system-TTS implementation.
                    XCTAssertEqual(engine.count(SEDirectiveEventSayHello), greetings + 1,
                        "Farewell must be submitted to the existing provider engine, never iOS system speech")
                    guard engine.count(SEDirectiveEventSayHello) == greetings + 1 else {
                        controller.stopVoiceForTesting(); return
                    }
                    XCTAssertEqual(engine.parameters, parameters, "Keep the current speaker and session configuration")
                    XCTAssertEqual(engine.count(SEDirectiveStartEngine), starts, "No second voice session")
                    XCTAssertEqual(SpeechEngine.instances.count, 1)
                    XCTAssertEqual(manager.isRecorderPaused, scenario != "farewellReject")
                    controller.tickLiveLimitForTesting(now: 601, busy: false)
                    XCTAssertEqual(engine.count(SEDirectiveEventSayHello), greetings + 1)
                    let metadata = Data("{\"reply_id\":\"farewell-current\",\"tts_type\":\"chat_tts_text\",\"text\":\"我们先休息一下\"}".utf8)
                    // Previously seen client TTS and ordinary reply endings must not claim this request.
                    engine.emit(SEEventTTSSentenceStart, data: old)
                    engine.emit(SEEventTTSEnded, data: old)
                    engine.emit(SEEventTTSEnded, data: Data("{\"reply_id\":\"previous-reply\",\"tts_type\":\"default\"}".utf8))
                    engine.emit(SEPlayerFinishPlayAudio)
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { manager.controlledCallbackDrainForTesting == 0 })
                    XCTAssertEqual(controller.liveLimitSessionOpenForTesting, scenario != "farewellReject")
                    if scenario == "farewellReject" {
                        // Directive rejection closes immediately; no alternate speaker or retry.
                    } else if scenario == "farewellCancel" {
                        controller.stopVoiceForTesting()
                        engine.emit(SEEventTTSSentenceStart, data: metadata)
                        engine.emit(SEEventTTSEnded, data: metadata)
                    } else if scenario == "farewellEmpty" {
                        engine.emit(SEEventTTSSentenceStart, data: metadata)
                        engine.emit(SEPlayerStartPlayAudio)
                        engine.emit(SEEventTTSEnded, data: metadata)
                        engine.emit(SEPlayerFinishPlayAudio)
                        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { manager.controlledCallbackDrainForTesting == 0 })
                        XCTAssertTrue(controller.liveLimitSessionOpenForTesting, "Empty playback is not audible completion")
                        controller.tickLiveLimitForTesting(now: 620, busy: false)
                    } else if scenario == "farewellError" {
                        engine.emit(SEEngineError)
                    } else if scenario == "farewellTimeout" {
                        controller.tickLiveLimitForTesting(now: 620, busy: false)
                    } else {
                        engine.emit(SEEventTTSSentenceStart, data: metadata)
                        if scenario == "farewellPlayer" { engine.emit(SEPlayerStartPlayAudio) }
                        engine.emit(SEEventChatResponse, data: metadata)
                        engine.emit(SEEventChatEnded, data: metadata)
                        let pcm = Data(repeating: 32, count: 2048)
                        if scenario == "farewellPlayer" {
                            // Delegated mode can expose real player PCM without decoder callbacks.
                            engine.emit(SEPlayerAudioData, data: pcm)
                        } else { engine.emit(SEDecoderAudioData, data: pcm) }
                        engine.emit(SEEventTTSEnded, data: metadata)
                        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { manager.controlledCallbackDrainForTesting == 0 })
                        XCTAssertTrue(controller.liveLimitSessionOpenForTesting, "Synthesis completion is not audible completion")
                        if scenario == "farewellPlayer" {
                            engine.emit(SEPlayerFinishPlayAudio)
                        } else {
                            engine.emit(SEPlayerAudioData, data: pcm)
                            engine.emit(SEPlayerAudioData, data: Data(repeating: 0, count: 9600))
                        }
                    }
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { !controller.liveLimitSessionOpenForTesting })
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
                        (try? outbox.load(for: lease, productSessionID: "native-farewell"))?.closeIntentRequestedAt != nil
                    }, "Every farewell outcome must still persist close intent")
                    let saved = try XCTUnwrap(outbox.load(for: lease, productSessionID: "native-farewell"))
                    XCTAssertEqual(saved.ownerTurnCount, 1, "The already saved owner tail survives")
                    XCTAssertEqual(saved.pendingTurns.count, 2, "Only the existing owner and assistant turns survive; farewell must not create a memory turn")
                    engine.emit(SEEventTTSEnded, data: metadata)
                    engine.emit(SEPlayerFinishPlayAudio)
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { manager.controlledCallbackDrainForTesting == 0 })
                    XCTAssertFalse(manager.isDialogActive)
                    if scenario == "farewellCancel" {
                        uptime = 200
                        controller.onVoiceListeningForTesting { listening += 1 }
                        controller.tapMicrophoneForTesting()
                        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { SpeechEngine.instances.count == 2 })
                        let replacement = try XCTUnwrap(SpeechEngine.instances.last)
                        replacement.emit(SEEventSessionStarted)
                        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { listening == 2 })
                        engine.emit(SEEventTTSSentenceStart, data: metadata)
                        engine.emit(SEDecoderAudioData, data: Data(repeating: 32, count: 2048))
                        engine.emit(SEEventTTSEnded, data: metadata)
                        engine.emit(SEPlayerFinishPlayAudio)
                        engine.emit(SEEngineError)
                        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { manager.controlledCallbackDrainForTesting == 0 })
                        XCTAssertTrue(manager.isDialogActive, "Old farewell/error must not close the replacement session")
                        XCTAssertEqual(replacement.count(SEDirectiveSyncStopEngine), 1, "Only initial pre-start stop")
                    }
                    return
                }
                if scenario == "stopClose" {
                    let root = FileManager.default.temporaryDirectory.appendingPathComponent("stop-close-\(UUID())")
                    defer { try? FileManager.default.removeItem(at: root) }
                    let outbox = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
                    let capture = EchoLiveMemoryCaptureCoordinator(accountLease: lease,
                        client: InterviewNaturalInputClientSpy(), accountLeaseRuntime: runtime,
                        productSessionID: "native-stop-close", liveTurnOutboxStore: outbox,
                        naturalInputPolicyAvailable: { false }, candidateReviewPolicyAvailable: { false })
                    controller.installLiveMemoryCaptureForTesting(accountLease: lease, coordinator: capture)
                    capture.appendOwnerTurn("合成测试：我每周六整理工具柜。")
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
                        (try? outbox.load(for: lease, productSessionID: "native-stop-close"))?.ownerTurnCount == 1
                    })
                    var nativeStops = 0
                    SpeechEngine.onSyncStop = {
                        nativeStops += 1
                        XCTAssertFalse(capture.acceptsTurns, "Capture must close before external SDK stop returns or delivers onDialogEnded")
                        XCTAssertTrue(self.waitForOwnerTruthHTTPUI(timeout: 2) {
                            (try? outbox.load(for: lease, productSessionID: "native-stop-close"))?.closeIntentRequestedAt != nil
                        }, "Durable close cannot depend on native stop completion")
                    }
                    var goodbye: (() -> Void)?
                    controller.beginLiveLimitForTesting(now: 0, pause: { true }, playback: { _, done in goodbye = done })
                    controller.tickLiveLimitForTesting(now: 610, busy: false)
                    try XCTUnwrap(goodbye)()
                    XCTAssertEqual(nativeStops, 1)
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
                        (try? outbox.load(for: lease, productSessionID: "native-stop-close"))?.closeIntentRequestedAt != nil
                    })
                    let before = try outbox.load(for: lease, productSessionID: "native-stop-close")?.closeIntentRequestedAt
                    controller.stopVoiceForTesting()
                    XCTAssertEqual(try outbox.load(for: lease, productSessionID: "native-stop-close")?.closeIntentRequestedAt, before)
                    SpeechEngine.onSyncStop = nil
                    return
                }
                // The handoff removes the launch timer without terminating a live session.
                uptime = 120
                watchdog?.perform()
                XCTAssertTrue(manager.isDialogActive)
                XCTAssertEqual(listening, 1)
                XCTAssertTrue(terminals.isEmpty)
                XCTAssertTrue(manager.controlledCanonicalIngressOpenForTesting)
                XCTAssertEqual(engine.count(SEDirectiveSyncStopEngine), 1, "only the initial pre-start stop; launch deadline must not stop a live session")
                let greetings = engine.count(SEDirectiveEventSayHello)
                XCTAssertEqual(greetings, 1)
                engine.emit(SEEventSessionStarted)
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
                    manager.controlledCallbackDrainForTesting == 0
                })
                XCTAssertEqual(engine.count(SEDirectiveEventSayHello), greetings)
                XCTAssertTrue(manager.isDialogActive)
                if scenario == "handoff" {
                    engine.emit(SERecorderAudioData, data: Data(repeating: 32, count: 1024))
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { controller.orbAudioSampleForTesting?.channel == .input })
                    XCTAssertGreaterThan(controller.orbAudioSampleForTesting?.level ?? 0, 0)
                    engine.emit(SEPlayerAudioData, data: Data(repeating: 32, count: 1024))
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { controller.orbAudioSampleForTesting?.channel == .output })
                    let lastSample = controller.orbAudioSampleForTesting?.nonce
                    controller.cancelVoiceLaunchForTesting()
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { controller.isVoiceIdleForTesting })
                    engine.emit(SERecorderAudioData, data: Data(repeating: 64, count: 1024))
                    RunLoop.current.run(until: Date().addingTimeInterval(0.1))
                    XCTAssertEqual(controller.orbAudioSampleForTesting?.nonce, lastSample, "Closed SDK callbacks must not reach the orb")
                }
                if scenario == "replacement" {
                    controller.cancelVoiceLaunchForTesting()
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { controller.isVoiceIdleForTesting })
                    XCTAssertFalse(manager.controlledCanonicalIngressOpenForTesting)
                    XCTAssertEqual(engine.count(SEDirectiveSyncStopEngine), 2, "initial stop plus the owned session stop")
                    uptime = 200
                    controller.onVoiceListeningForTesting { listening += 1 }
                    controller.tapMicrophoneForTesting()
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { SpeechEngine.instances.count == 2 })
                    let replacement = try XCTUnwrap(SpeechEngine.instances.last)
                    engine.emit(SEEventSessionStarted)
                    engine.emit(SEEngineError)
                    replacement.emit(SEEventSessionStarted)
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { listening == 2 })
                    XCTAssertTrue(manager.isDialogActive)
                    XCTAssertEqual(replacement.count(SEDirectiveStartEngine), 1)
                    XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 2)
                }
                return
            }
            if scenario == "lateAfterCancel" {
                controller.cancelVoiceLaunchForTesting()
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { controller.isVoiceIdleForTesting })
                uptime = 116
                watchdog?.perform()
                XCTAssertTrue(terminals.isEmpty, "User cancellation must not become a timeout")
            } else {
                uptime = 116
                watchdog?.perform()
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { terminals.count == 1 })
                XCTAssertEqual(terminals, ["voiceLaunchTimeout"])
            }
            engine.emit(SEEventSessionStarted)
            engine.emit(SEEngineError)
        }
        // Drain the real delegate queue before checking that late callbacks stay inert.
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { manager.controlledCallbackDrainForTesting == 0 })
        XCTAssertEqual(terminals.count, scenario == "lateAfterCancel" ? 0 : 1)
        XCTAssertEqual(listening, 0)
        XCTAssertFalse(manager.isDialogActive)
        XCTAssertEqual(engine.count(SEDirectiveEventSayHello), 0)
        XCTAssertFalse(controller.hasEchoAudioLeaseForTesting)
        XCTAssertFalse(manager.controlledCanonicalIngressOpenForTesting, "cancelled pending launch must close the actual ingress binding")
        let expectedStops = ["missingStarted", "lateAfterCancel"].contains(scenario) ? 2 : (scenario == "directiveFailure" ? 1 : 0)
        XCTAssertEqual(engine.count(SEDirectiveSyncStopEngine), expectedStops, scenario)
    }
    #endif


