    func testB6FollowUpV1MigrationIsAtomicAndRetainsLegacyFallback() throws {
        let (_, lease) = try makeActiveRuntime()
        let defaultsName = "b6-follow-up-v2-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("b6-follow-up-v2-\(UUID().uuidString)", isDirectory: true)
        defer {
            defaults.removePersistentDomain(forName: defaultsName)
            try? FileManager.default.removeItem(at: root)
        }
        let timestamp = Date(timeIntervalSince1970: 1_700_000_000)
        let record = EchoLiveMemoryFollowUpRecord(
            productSessionID: "b6-legacy-follow-up",
            reviewBatchID: UUID(uuidString: "00000000-0000-0000-0000-0000000007d1")!,
            createdAt: timestamp,
            updatedAt: timestamp
        )
        let scope = [lease.subjectId, lease.vaultId, lease.authorityEpoch]
            .joined(separator: "|")
        let digest = SHA256.hash(data: Data(scope.utf8)).map {
            String(format: "%02x", $0)
        }.joined()
        let legacyKey = "echo.live-memory-follow-up.v1.\(digest)"
        defaults.set(try JSONEncoder().encode([record]), forKey: legacyKey)

        let store = EchoLiveMemoryFollowUpStore(defaults: defaults, rootDirectory: root)
        XCTAssertEqual(store.records(for: lease), [record])
        let durableURL = store.durableFileURLForTesting(for: lease)
        XCTAssertTrue(FileManager.default.fileExists(atPath: durableURL.path))
        XCTAssertNotNil(defaults.data(forKey: legacyKey), "V1 remains the safe migration fallback")

        try Data("{".utf8).write(to: durableURL, options: .atomic)
        XCTAssertEqual(store.records(for: lease), [record], "corrupt V2 must fall back to V1")
        XCTAssertGreaterThan(try Data(contentsOf: durableURL).count, 1, "fallback repairs V2")

        let blockedRoot = root.appendingPathComponent("migration-blocked")
        try Data("not-a-directory".utf8).write(to: blockedRoot, options: .atomic)
        let blockedStore = EchoLiveMemoryFollowUpStore(
            defaults: defaults,
            rootDirectory: blockedRoot
        )
        XCTAssertEqual(blockedStore.records(for: lease), [record])
        XCTAssertNotNil(defaults.data(forKey: legacyKey), "failed migration must preserve V1")
        XCTAssertFalse(
            FileManager.default.fileExists(
                atPath: blockedStore.durableFileURLForTesting(for: lease).path
            )
        )
    }

    func testB6CompletionCheckpointReceiptsAreMonotonicAndIdempotent() throws {
        let (_, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let threadID = recordID("00000000-0000-0000-0000-0000000007d2")
        let sessionID = recordID("00000000-0000-0000-0000-0000000007d3")
        let batchID = recordID("00000000-0000-0000-0000-0000000007d4")
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("b6-monotonic-checkpoint-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = EchoLiveMemoryCompletionCheckpointStore(rootDirectory: root)
        let productSessionID = "b6-monotonic-checkpoint"
        let end = try OwnerTruthInterviewEndCommand(
            commandID: "b6-monotonic-end",
            threadID: threadID,
            sessionID: sessionID,
            expectedThreadVersion: 1,
            expectedSessionVersion: 1,
            lastClientSequenceNumber: 1
        )
        let ended = try interviewNaturalInputReceipt(vaultID: vaultID, end: end)
        let acknowledgement = try OwnerTruthInterviewReviewBatchAcknowledgementCommand(
            commandID: "b6-monotonic-ack",
            reviewBatchID: batchID,
            threadID: threadID,
            sessionID: sessionID,
            expectedSessionVersion: ended.sessionVersion,
            expectedReviewBatchVersion: 1
        )
        let acknowledged = try pendingReviewBatchAcknowledgementReceipt(
            vaultID: lease.vaultId,
            reviewBatchID: batchID,
            threadID: threadID,
            sessionID: sessionID,
            reviewBatchVersion: 2,
            sessionVersion: ended.sessionVersion + 1
        )
        let admission = try OwnerTruthInterviewCandidateProposalAdmissionCommand(
            commandID: "b6-monotonic-admit",
            reviewBatchID: batchID,
            expectedReviewBatchVersion: acknowledged.reviewBatchVersion
        )
        let admitted = try candidateProposalAdmissionReceipt(
            vaultID: lease.vaultId,
            reviewBatchID: batchID
        )

        try store.prepareEnd(end, productSessionID: productSessionID, for: lease)
        try store.acceptEnd(ended, productSessionID: productSessionID, for: lease)
        try store.prepareAcknowledgement(
            acknowledgement,
            productSessionID: productSessionID,
            for: lease
        )
        try store.acceptAcknowledgement(
            acknowledged,
            productSessionID: productSessionID,
            for: lease
        )
        try store.prepareAdmission(admission, productSessionID: productSessionID, for: lease)
        try store.acceptAdmission(admitted, productSessionID: productSessionID, for: lease)

        try store.acceptEnd(ended, productSessionID: productSessionID, for: lease)
        try store.prepareAcknowledgement(
            acknowledgement,
            productSessionID: productSessionID,
            for: lease
        )
        try store.acceptAcknowledgement(
            acknowledged,
            productSessionID: productSessionID,
            for: lease
        )
        try store.prepareAdmission(admission, productSessionID: productSessionID, for: lease)
        let final = try store.acceptAdmission(
            admitted,
            productSessionID: productSessionID,
            for: lease
        )

        XCTAssertEqual(final.phase, .admitted)
        XCTAssertEqual(final.admittedReviewBatchID, batchID)
    }

