        coordinator.appendOwnerTurn("隔离的检查点失败测试。")
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) { client.appendCommand != nil })
        coordinator.finish()

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            coordinator.state == .statusUnknown
        })
        XCTAssertEqual(client.acknowledgementCommands.count, 1)
        XCTAssertTrue(client.admissionCommands.isEmpty)
        if let lockedScopeDirectory {
            try FileManager.default.setAttributes(
                [.posixPermissions: 0o700],
                ofItemAtPath: lockedScopeDirectory.path
            )
        }
        let checkpoint = try XCTUnwrap(checkpointStore.load(
            productSessionID: productSessionID,
            for: lease
        ))
        XCTAssertEqual(checkpoint.phase, .acknowledgementPrepared)
        XCTAssertNotNil(checkpoint.acknowledgementCommand)
        XCTAssertNil(checkpoint.acknowledgementReceipt)
        diagnostics.waitForPendingWrites()
        let rebuiltDiagnostics = NativeLiveDiagnosticsRingStore(rootDirectory: diagnosticsRoot)
        let firstRequestFailure = rebuiltDiagnostics.snapshot(
            accountLease: lease, providerSessionID: productSessionID
        ).firstRequestFailure
        XCTAssertEqual(firstRequestFailure?.source, "ackCheckpointCommit")
        XCTAssertEqual(firstRequestFailure?.requestExposure, "responseAccepted")
    }

