            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let capturedAt = Date(timeIntervalSince1970: 1_700_000_100)

        coordinator.appendCanonicalTurn(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "owner-question-settled",
            role: .owner,
            text: "这段内容仍在等待权威最终稿",
            finality: .interim,
            capturedAt: capturedAt
        ))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            (try? store.load(for: lease, productSessionID: productSessionID))?
                .unsealedCanonicalTurnCount == 1
        })

        coordinator.finish()

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            guard case .coverageGap(unsealedTurnCount: 1) = coordinator.state,
                  let snapshot = try? store.load(
                    for: lease,
                    productSessionID: productSessionID
                  ) else { return false }
            return snapshot.closeIntentRequestedAt != nil
                && snapshot.closeRequestedLastClientSequenceNumber == nil
                && snapshot.unsealedCanonicalTurnCount == 1
        })
        XCTAssertEqual(client.endCommands.count, 0)

        coordinator.appendCanonicalTurn(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "owner-question-settled",
            role: .owner,
            text: "这段内容已经获得权威最终稿。",
            finality: .complete,
            capturedAt: capturedAt
        ))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            guard let snapshot = try? store.load(
                for: lease,
                productSessionID: productSessionID
            ) else { return false }
            return snapshot.unsealedCanonicalTurnCount == 0
                && snapshot.closeRequestedLastClientSequenceNumber == 1
        })
    }

