    func testCAP01EquivalentPeriodAndSealedPreExposureConflictKeepImmutableDelivery() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("cap01-pre-exposure-revision-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let sessionID = "cap01-pre-exposure-revision"
        let capturedAt = Date(timeIntervalSince1970: 1_700_000_260)

        let first = try store.upsertCanonicalTurn(
            NativeLiveCanonicalTranscriptEvent(
                canonicalTurnID: "owner-cap01-q2",
                role: .owner,
                text: "合法正文",
                finality: .complete,
                capturedAt: capturedAt
            ),
            for: lease,
            productSessionID: sessionID
        )
        let original = try XCTUnwrap(first.pendingTurns.first)

        let equivalent = try store.upsertCanonicalTurn(
            NativeLiveCanonicalTranscriptEvent(
                canonicalTurnID: "owner-cap01-q2",
                role: .owner,
                text: "合法正文。",
                finality: .complete,
                capturedAt: capturedAt
            ),
            for: lease,
            productSessionID: sessionID
        )
        XCTAssertEqual(equivalent.pendingTurns, [original])
        XCTAssertEqual(equivalent.canonicalConflictCount, 0)

        let conflict = try store.upsertCanonicalTurn(
            NativeLiveCanonicalTranscriptEvent(
                canonicalTurnID: "owner-cap01-q2",
                role: .owner,
                text: "封存后不得覆盖的不同正文",
                finality: .complete,
                capturedAt: capturedAt
            ),
            for: lease,
            productSessionID: sessionID
        )
        let preserved = try XCTUnwrap(conflict.pendingTurns.first)
        XCTAssertEqual(preserved, original)
        XCTAssertEqual(conflict.canonicalConflictCount, 1)
        XCTAssertEqual(conflict.firstCanonicalConflictReason, .immutableBodyConflict)

        let command = try OwnerTruthInterviewNaturalInputAppendCommand(
            commandID: preserved.commandID,
            threadID: recordID("00000000-0000-0000-0000-00000000ca01"),
            sessionID: recordID("00000000-0000-0000-0000-00000000ca02"),
            messageID: preserved.messageID,
            expectedThreadVersion: 1,
            expectedSessionVersion: 1,
            text: preserved.text,
            role: preserved.role,
            captureMode: .live,
            clientSequenceNumber: preserved.clientSequenceNumber,
            capturedAt: preserved.capturedAt
        )
        _ = try store.prepareAppendExposure(
            command: command,
            retry: false,
            for: lease,
            productSessionID: sessionID
        )
        let exposedConflict = try store.upsertCanonicalTurn(
            NativeLiveCanonicalTranscriptEvent(
                canonicalTurnID: "owner-cap01-q2",
                role: .owner,
                text: "曝光后不得覆盖的不同正文！",
                finality: .complete,
                capturedAt: capturedAt
            ),
            for: lease,
            productSessionID: sessionID
        )
        XCTAssertEqual(exposedConflict.pendingTurns, [preserved])
        XCTAssertEqual(exposedConflict.frozenAppendCommands[preserved.messageID], command)
        XCTAssertEqual(exposedConflict.canonicalConflictCount, 1)
        XCTAssertEqual(exposedConflict.firstCanonicalConflictReason, .immutableBodyConflict)
        XCTAssertEqual(
            OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
                .recoverableProductSessionID(for: lease),
            sessionID
        )
    }

    func testCAP07EachLocalOutboxStageRecoversOneAtomicWriteFailure() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("cap07-one-write-failure-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let writer = FailFirstAttemptPerAtomicWrite()
        let store = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root,
            atomicWrite: writer.write
        )
        let sessionID = "cap07-one-write-failure"
        let capturedAt = Date(timeIntervalSince1970: 1_700_000_270)
        let member = NativeLiveCanonicalTranscriptMember(
            canonicalTurnID: "owner-cap07-q1",
            handoffID: "cap07-register-handoff",
            role: .owner,
            capturedAt: capturedAt,
            ingressOrdinal: 1,
            ingressKind: .asrInfo
        )

        _ = try store.registerCanonicalMember(
            member,
            for: lease,
            productSessionID: sessionID
        )
        let body = try store.upsertCanonicalTurn(
            NativeLiveCanonicalTranscriptEvent(
                canonicalTurnID: member.canonicalTurnID,
                role: .owner,
                text: "CAP07 原子写恢复正文",
                finality: .complete,
                observationID: "cap07-body",
                ingressOrdinal: 2,
                sealing: .observeAndSeal,
                capturedAt: capturedAt
            ),
            for: lease,
            productSessionID: sessionID
        )
        let delivery = try XCTUnwrap(body.pendingTurns.first)
        let command = try OwnerTruthInterviewNaturalInputAppendCommand(
            commandID: delivery.commandID,
            threadID: recordID("00000000-0000-0000-0000-00000000cb01"),
            sessionID: recordID("00000000-0000-0000-0000-00000000cb02"),
            messageID: delivery.messageID,
            expectedThreadVersion: 1,
            expectedSessionVersion: 1,
            text: delivery.text,
            role: delivery.role,
            captureMode: .live,
            clientSequenceNumber: delivery.clientSequenceNumber,
            capturedAt: delivery.capturedAt
        )
        _ = try store.prepareAppendExposure(
            command: command,
            retry: false,
            for: lease,
            productSessionID: sessionID
        )
        _ = try XCTUnwrap(store.acknowledge(
            messageID: delivery.messageID,
            for: lease,
            productSessionID: sessionID
        ))
        _ = try store.requestClose(for: lease, productSessionID: sessionID)
        _ = try store.markClosing(
            lastClientSequenceNumber: delivery.clientSequenceNumber,
            for: lease,
            productSessionID: sessionID
        )

        let rebuilt = try XCTUnwrap(
            OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root).load(
                for: lease,
                productSessionID: sessionID
            )
        )
        XCTAssertEqual(writer.failureCount, 6)
        XCTAssertEqual(writer.successCount, 6)
        XCTAssertEqual(rebuilt.ownerTurnCount, 1)
        XCTAssertEqual(rebuilt.lastClientSequenceNumber, 1)
        XCTAssertEqual(rebuilt.closeRequestedLastClientSequenceNumber, 1)
        XCTAssertNotNil(rebuilt.closeIntentRequestedAt)
        XCTAssertTrue(rebuilt.pendingTurns.isEmpty)
        XCTAssertEqual(rebuilt.canonicalCoverageSummary.serverConfirmedCount, 1)
        XCTAssertEqual(rebuilt.canonicalConflictCount, 0)
    }

    @MainActor
    func testCAP08PersistentDiskFailureKeepsFirstErrorAndControllerOwnership() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("cap08-persistent-write-failure-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let writer = AlwaysFailingAtomicWrite()
        let measurementLock = NSLock()
        var completedBatchCount = 0, completedOperationCount = 0
        let store = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root,
            atomicWrite: writer.write
        )
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: InterviewNaturalInputClientSpy(),
            accountLeaseRuntime: runtime,
            productSessionID: "cap08-persistent-write-failure",
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            persistenceCostObservation: { phase, _, count in
                if phase == "mainCompletionWait" {
                    measurementLock.lock(); defer { measurementLock.unlock() }
                    completedBatchCount += 1
                    completedOperationCount += count
                }
            },
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )

        coordinator.appendCanonicalTurn(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "owner-cap08-q1",
            role: .owner,
            text: "不会进入诊断的合成正文",
            finality: .complete,
            capturedAt: Date(timeIntervalSince1970: 1_700_000_280)
        ))

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            coordinator.state == .unavailable
                && coordinator.firstCaptureFailure?.stage == .canonicalBody
        })
        XCTAssertEqual(coordinator.firstCaptureFailure?.reason, "storageFailure")
        XCTAssertEqual(writer.attemptCount, 2)
        XCTAssertTrue(coordinator.acceptsTurns)
        XCTAssertEqual(coordinator.pendingCanonicalRecoveryCountForTesting, 1)
        XCTAssertFalse(coordinator.canReleaseCaptureOwnership)
        XCTAssertTrue(controller.hasActiveLiveMemoryCaptureForTesting(coordinator))
        XCTAssertNil(try store.load(
            for: lease,
            productSessionID: "cap08-persistent-write-failure"
        ))

        for index in 1...128 {
            coordinator.appendCanonicalTurn(NativeLiveCanonicalTranscriptEvent(
                canonicalTurnID: "owner-cap08-buffer-\(index)",
                role: .owner,
                text: "有界故障缓冲中的合成正文 \(index)",
                finality: .complete,
                observationID: "cap08-buffer-observation-\(index)",
                ingressOrdinal: UInt64(index + 1),
                sealing: .observeAndSeal,
                capturedAt: Date(timeIntervalSince1970: 1_700_000_280 + Double(index))
            ))
        }
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            measurementLock.lock(); let completed = completedOperationCount; measurementLock.unlock()
            return !coordinator.acceptsTurns
                && coordinator.pendingCanonicalRecoveryCountForTesting == 128 && completed == 128
        })
        // The failure budget remains exactly two atomic attempts per actual
        // commit. Batching must not manufacture 256 redundant disk operations.
        measurementLock.lock(); let batches = completedBatchCount; measurementLock.unlock()
        XCTAssertEqual(writer.attemptCount, batches * 2)
        XCTAssertLessThanOrEqual(writer.attemptCount, 256)
        XCTAssertEqual(completedOperationCount, 128)
        XCTAssertEqual(coordinator.firstCaptureFailure?.stage, .canonicalBody)
        XCTAssertEqual(coordinator.firstCaptureFailure?.reason, "storageFailure")
        XCTAssertTrue(controller.hasActiveLiveMemoryCaptureForTesting(coordinator))
    }

    @MainActor
