    func testLiveCanonicalOutboxRetainsDeduplicationAfterAcknowledgement() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("echo-live-canonical-ack-dedup-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "echo-live-canonical-ack-dedup"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let event = NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "owner-question-dedup",
            role: .owner,
            text: "这是一条用于验证确认后去重的合成表达。",
            finality: .complete,
            capturedAt: Date(timeIntervalSince1970: 1_700_000_300)
        )

        let first = try store.upsertCanonicalTurn(
            event,
            for: lease,
            productSessionID: productSessionID
        )
        let delivery = try XCTUnwrap(first.pendingTurns.first)
        let acknowledged = try XCTUnwrap(store.acknowledge(
            messageID: delivery.messageID,
            for: lease,
            productSessionID: productSessionID
        ))
        XCTAssertTrue(acknowledged.pendingTurns.isEmpty)

        let duplicate = try store.upsertCanonicalTurn(
            event,
            for: lease,
            productSessionID: productSessionID
        )
        XCTAssertTrue(duplicate.pendingTurns.isEmpty)
        XCTAssertEqual(duplicate.lastClientSequenceNumber, 1)

        let conflict = try store.upsertCanonicalTurn(
            NativeLiveCanonicalTranscriptEvent(
                canonicalTurnID: event.canonicalTurnID,
                role: event.role,
                text: "同一稳定身份不允许在确认后改写为另一段内容。",
                finality: .complete,
                capturedAt: event.capturedAt
            ),
            for: lease,
            productSessionID: productSessionID
        )
        XCTAssertEqual(conflict.canonicalConflictCount, 1)
        XCTAssertEqual(conflict.firstCanonicalConflictReason, .immutableBodyConflict)
        XCTAssertTrue(conflict.pendingTurns.isEmpty)
        XCTAssertEqual(conflict.lastClientSequenceNumber, 1)
    }

