            candidateReviewPolicyAvailable: { true }
        )
        let controller = EchoViewController()
        var scheduledDeliveries: [() -> Void] = []
        controller.setCanonicalTranscriptDeliverySchedulerForTesting { delivery in
            scheduledDeliveries.append(delivery)
        }
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )

        controller.onCanonicalTranscriptEvent(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "owner-final-before-stop",
            role: .owner,
            text: "停止前已经由 SDK 交付的最终合成内容",
