        }

        func enqueueOwner(_ index: Int, at capturedAt: Date) throws {
            _ = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
                kind: DialogProviderSDKEventClassifier.canonicalIngressKind(
                    rawValue: DialogProviderSDKEventClassifier.asrInfo
                ),
                data: try JSONSerialization.data(withJSONObject: [
                    "question_id": "owner-q\(index)",
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt
            ))
            _ = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
                kind: DialogProviderSDKEventClassifier.canonicalIngressKind(
                    rawValue: DialogProviderSDKEventClassifier.asrResponse
                ),
                data: try JSONSerialization.data(withJSONObject: [
                    "results": [[
                        "text": "第 \(index) 问完整用户表达。",
                        "is_interim": false,
                    ]],
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.1)
            ))
            _ = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrEnded,
                data: try JSONSerialization.data(withJSONObject: [
                    "question_id": "owner-q\(index)",
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.2)
            ))
        }

        func enqueueAssistant(_ index: Int, at capturedAt: Date) throws {
            let replyID = "assistant-r\(index)"
            XCTAssertNotNil(manager.enqueueCanonicalAssistantProviderMessageForTesting(
                kind: .response,
                data: try JSONSerialization.data(withJSONObject: [
                    "reply_id": replyID,
                    "delta": "第 \(index) 问完整助手回答。",
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt
            ))
            XCTAssertNotNil(manager.enqueueCanonicalAssistantProviderMessageForTesting(
                kind: .ended,
                data: try JSONSerialization.data(withJSONObject: ["reply_id": replyID]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.1)
            ))
        }

        let startedAt = Date(timeIntervalSince1970: 1_700_400_100)
        let opening = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
            kind: DialogProviderSDKEventClassifier.canonicalIngressKind(
                rawValue: DialogProviderSDKEventClassifier.ttsSentenceStart
            ),
            data: try JSONSerialization.data(withJSONObject: [
                "question_id": "opening-q0",
                "reply_id": "opening-r0",
            ]),
            engineGeneration: generation,
            capturedAt: startedAt
        ))
        XCTAssertNil(opening.member)
        try enqueueOwner(1, at: startedAt.addingTimeInterval(1))
        try enqueueAssistant(1, at: startedAt.addingTimeInterval(2))
        try enqueueOwner(2, at: startedAt.addingTimeInterval(3))
        try enqueueAssistant(2, at: startedAt.addingTimeInterval(4))

        while !scheduledDeliveries.isEmpty {
            scheduledDeliveries.removeFirst()()
        }

        var persistenceFlushed = false
        coordinator.flushPersistenceForTesting {
            persistenceFlushed = true
        }
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { persistenceFlushed })

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            guard let snapshot = try? store.load(
                for: lease,
                productSessionID: productSessionID
            ) else { return false }
            return snapshot.ownerTurnCount == 2
                && snapshot.pendingTurns.count == 4
                && snapshot.lastClientSequenceNumber == 4
                && snapshot.unsealedCanonicalTurnCount == 0
                && client.appendCommand != nil
        })
        let snapshot = try XCTUnwrap(store.load(for: lease, productSessionID: productSessionID))
        XCTAssertEqual(snapshot.pendingTurns.map(\.role), [.owner, .assistant, .owner, .assistant])
        XCTAssertEqual(snapshot.pendingTurns.map(\.clientSequenceNumber), [1, 2, 3, 4])
        XCTAssertEqual(snapshot.canonicalCoverageSummary.registeredMemberCount, 4)
        XCTAssertEqual(snapshot.canonicalCoverageSummary.memberWithoutBodyCount, 0)
        XCTAssertEqual(snapshot.canonicalCoverageSummary.partialTurnCount, 0)
        XCTAssertEqual(snapshot.canonicalCoverageSummary.completeBlockedTurnCount, 0)
        XCTAssertEqual(snapshot.canonicalCoverageSummary.deliveryCount, 4)

        let firstAppend = try XCTUnwrap(client.appendCommand)
        client.deferAppend = false
        client.completeDeferredAppend(.success(
            try interviewNaturalInputReceipt(vaultID: vaultID, append: firstAppend)
        ))
        coordinator.finish()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            client.admissionCommands.count == 1
                && (try? checkpointStore.load(
                    productSessionID: productSessionID,
                    for: lease
                ))?.phase == .admitted
        })
        XCTAssertEqual(client.startCommands.count, 1)
        XCTAssertEqual(client.appendCommands.count, 4)
        XCTAssertEqual(client.endCommands.count, 1)
        XCTAssertEqual(client.acknowledgementCommands.count, 1)
        XCTAssertEqual(client.admissionCommands.count, 1)
        XCTAssertEqual(client.acknowledgementCommands.first?.reviewBatchID, reviewBatchID)
        XCTAssertEqual(client.admissionCommands.first?.reviewBatchID, reviewBatchID)
        XCTAssertEqual(
            client.endCommands.first?.lastClientSequenceNumber,
            snapshot.lastClientSequenceNumber
        )
        XCTAssertEqual(
            try checkpointStore.load(productSessionID: productSessionID, for: lease)?.phase,
            .admitted
        )
    }

    @MainActor
    func testManagerNonASREventsCannotRollbackCurrentQuestionWindow() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("manager-nonasr-window-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: InterviewNaturalInputClientSpy(),
            accountLeaseRuntime: runtime,
            productSessionID: "manager-nonasr-window",
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { false },
            candidateReviewPolicyAvailable: { false }
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )
        let manager = DialogEngineManager.shared
        let generation = UUID()
        let operationID = UUID()
        manager.installCanonicalIngressForTesting(
            engineGeneration: generation,
            dialogOperationID: operationID,
            delegate: controller
        )
        defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operationID) }

        func enqueue(
            rawEventCode: Int,
            json: [String: Any],
            at offset: TimeInterval
        ) throws -> DialogProviderCanonicalIngressResult {
            try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
                kind: DialogProviderSDKEventClassifier.canonicalIngressKind(
                    rawValue: rawEventCode
                ),
                data: try JSONSerialization.data(withJSONObject: json),
                engineGeneration: generation,
                capturedAt: Date(timeIntervalSince1970: 1_700_400_200 + offset)
            ))
        }

        let opening = try enqueue(
            rawEventCode: DialogProviderSDKEventClassifier.ttsSentenceStart,
            json: ["question_id": "opening-q0"],
            at: 0
        )
        let q1 = try enqueue(
            rawEventCode: DialogProviderSDKEventClassifier.asrInfo,
            json: ["question_id": "owner-q1"],
            at: 1
        )
        let q2 = try enqueue(
            rawEventCode: DialogProviderSDKEventClassifier.asrInfo,
            json: ["question_id": "owner-q2"],
            at: 2
        )
        let lateNonASRQ1 = try enqueue(
            rawEventCode: DialogProviderSDKEventClassifier.ttsSentenceStart,
            json: ["question_id": "owner-q1", "text": "不是用户转写"],
            at: 3
        )
        let q2Final = try enqueue(
            rawEventCode: DialogProviderSDKEventClassifier.asrResponse,
            json: [
                "results": [["text": "第二问的明确终稿。", "is_interim": false]],
            ],
            at: 4
        )

        XCTAssertNil(opening.member)
        XCTAssertNil(opening.event)
        XCTAssertNil(lateNonASRQ1.member)
        XCTAssertNil(lateNonASRQ1.event)
        XCTAssertNotNil(q1.member)
        XCTAssertNotNil(q2.member)
        XCTAssertEqual(q2Final.event?.canonicalTurnID, q2.member?.canonicalTurnID)
        XCTAssertNotEqual(q2Final.event?.canonicalTurnID, q1.member?.canonicalTurnID)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            guard let snapshot = try? store.load(
                for: lease,
                productSessionID: "manager-nonasr-window"
            ) else { return false }
            return snapshot.ownerTurnCount == 0
                && snapshot.pendingTurns.isEmpty
                && snapshot.unsealedCanonicalTurnCount == 2
                && snapshot.canonicalCoverageSummary.registeredMemberCount == 2
                && snapshot.canonicalCoverageSummary.memberWithoutBodyCount == 1
                && snapshot.canonicalCoverageSummary.completeBlockedTurnCount == 1
        })

        let q2Ended = try enqueue(
            rawEventCode: DialogProviderSDKEventClassifier.asrEnded,
            json: [:],
            at: 5
        )
        // ASREnded is a boundary signal, not another transcript body. Its
        // separately reserved sealing handoff is proven by the disk state.
        XCTAssertNil(q2Ended.event)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            guard let snapshot = try? store.load(
                for: lease,
                productSessionID: "manager-nonasr-window"
            ) else { return false }
            return snapshot.unsealedCanonicalTurnCount == 1
                && snapshot.canonicalCoverageSummary.registeredMemberCount == 2
                && snapshot.canonicalCoverageSummary.memberWithoutBodyCount == 1
                && snapshot.canonicalCoverageSummary.completeBlockedTurnCount == 1
        })
    }

    @MainActor
    func testManagerIngressFreezesIdentifierWindowBeforeEchoQueueAndStop() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let client = InterviewNaturalInputClientSpy()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("manager-live-ingress-stop-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "manager-live-ingress-stop"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let controller = EchoViewController()
        var scheduledDeliveries: [() -> Void] = []
        controller.setCanonicalTranscriptDeliverySchedulerForTesting { delivery in
            scheduledDeliveries.append(delivery)
        }
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )

        let manager = DialogEngineManager.shared
        let generation = UUID()
        let operationID = UUID()
        manager.installCanonicalIngressForTesting(
            engineGeneration: generation,
            dialogOperationID: operationID,
            delegate: controller
        )
        defer { manager.closeCanonicalIngressForTesting() }

        let q1Info = try JSONSerialization.data(withJSONObject: [
            "question_id": "q-1",
        ])
        let q1FinalWithoutIdentifier = try JSONSerialization.data(withJSONObject: [
            "results": [[
                "text": "第一条在停止前已经进入 SDK 原始回调。",
                "is_interim": false,
            ]],
        ])
        let q2Info = try JSONSerialization.data(withJSONObject: [
            "question_id": "q-2",
        ])

        let q1Member = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrInfo,
            data: q1Info,
            engineGeneration: generation,
            capturedAt: Date(timeIntervalSince1970: 1_700_001_000)
        )?.member)
        let q1Final = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrResponse,
            data: q1FinalWithoutIdentifier,
            engineGeneration: generation,
            capturedAt: Date(timeIntervalSince1970: 1_700_001_001)
        )?.event)
        let q2Member = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrInfo,
            data: q2Info,
            engineGeneration: generation,
            capturedAt: Date(timeIntervalSince1970: 1_700_001_002)
        )?.member)

        XCTAssertEqual(q1Final.canonicalTurnID, q1Member.canonicalTurnID)
        XCTAssertNotEqual(q1Final.canonicalTurnID, q2Member.canonicalTurnID)
        XCTAssertEqual(q1Final.finalityEvidence, .explicitFinal)
        XCTAssertEqual(
            scheduledDeliveries.count,
            4,
            "Q2 registration must also hand off the frozen Q1 seal before stop"
        )

        manager.closeCanonicalIngressForTesting(dialogOperationID: operationID)
        controller.finishLiveMemoryCaptureForTesting()

        // Q2 was registered synchronously at ingress while Q1's final body is
        // still waiting for Echo delivery. The frozen Q1 identity must survive.
        scheduledDeliveries.forEach { $0() }
        scheduledDeliveries.removeAll()

        let rejectedAfterStop = manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrInfo,
            data: try JSONSerialization.data(withJSONObject: ["question_id": "q-3"]),
            engineGeneration: generation
        )
        XCTAssertNil(rejectedAfterStop)

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            (try? store.load(for: lease, productSessionID: productSessionID))?
                .ownerTurnCount == 1
        })
        let snapshot = try XCTUnwrap(
            store.load(for: lease, productSessionID: productSessionID)
        )
        XCTAssertEqual(snapshot.ownerTurnCount, 1)
        XCTAssertEqual(snapshot.pendingTurns.map(\.text), [
            "第一条在停止前已经进入 SDK 原始回调。",
        ])
        XCTAssertEqual(snapshot.unsealedCanonicalTurnCount, 1)
    }

