            else { return false }
            return coordinator.pendingCanonicalHandoffCountForTesting == 1
                && snapshot.closeIntentRequestedAt != nil
                && snapshot.pendingCloseManifestHandoffCount == 1
                && snapshot.unsealedCanonicalTurnCount == 2
        })

        deliveries.removeFirst()()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            guard let snapshot = try? store.load(for: lease, productSessionID: sessionID)
            else { return false }
            return coordinator.pendingCanonicalHandoffCountForTesting == 0
                && snapshot.pendingTurns.map(\.text) == ["停止前最终版"]
                && snapshot.closeIntentRequestedAt != nil
                && snapshot.pendingCloseManifestHandoffCount == 0
                && snapshot.closeRequestedLastClientSequenceNumber == 1
                && snapshot.canonicalConflictCount == 0
        })
    }

