        manager.installCanonicalIngressForTesting(
            engineGeneration: generation,
            dialogOperationID: operationID,
            delegate: controller
        )
        defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operationID) }

        func enqueue(_ code: Int, _ payload: [String: Any]) throws {
            XCTAssertNotNil(manager.enqueueCanonicalRawProviderMessageForTesting(
                rawEventCode: code,
                data: try JSONSerialization.data(withJSONObject: payload),
                engineGeneration: generation
            ))
        }
        try enqueue(DialogProviderSDKEventClassifier.asrInfo, [
            "question_id": "cap03-q1",
        ])
        try enqueue(DialogProviderSDKEventClassifier.asrResponse, [
            "question_id": "cap03-q1",
            "results": [[
                "text": "语音来源的唯一严格终稿。",
                "is_interim": false,
            ]],
        ])
        try enqueue(DialogProviderSDKEventClassifier.queryConfirmed, [
            "question_id": "cap03-q1",
            "text": "确认回执中不同的非权威正文。",
        ])

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            guard let snapshot = try? store.load(for: lease, productSessionID: sessionID)
            else { return false }
            return snapshot.pendingTurns.isEmpty
                && snapshot.ownerTurnCount == 0
                && snapshot.canonicalConflictCount == 0
                && snapshot.unsealedCanonicalTurnCount == 1
        })

        try enqueue(DialogProviderSDKEventClassifier.asrEnded, [
            "question_id": "cap03-q1",
        ])

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            guard let snapshot = try? store.load(for: lease, productSessionID: sessionID)
            else { return false }
            return snapshot.pendingTurns.map(\.text) == ["语音来源的唯一严格终稿。"]
                && snapshot.ownerTurnCount == 1
                && snapshot.canonicalConflictCount == 0
                && snapshot.unsealedCanonicalTurnCount == 0
        })
    }

