        func enqueue(_ code: Int, _ payload: [String: Any]) throws
            -> DialogProviderCanonicalIngressResult {
            try XCTUnwrap(manager.enqueueCanonicalRawProviderMessageForTesting(
                rawEventCode: code,
                data: try JSONSerialization.data(withJSONObject: payload),
                engineGeneration: generation
            ))
        }
        let earlyTTS = try enqueue(DialogProviderSDKEventClassifier.ttsSentenceStart, [
