                && snapshot.pendingTurns.map(\.role) == [.assistant]
                && snapshot.canonicalConflictCount == 0
                && snapshot.unsealedCanonicalTurnCount == 0
                && snapshot.canonicalCoverageSummary.deliveryCount == 1
        })
    }

    @MainActor
    func testManagerFrozenNewMemberDelaysNonEmptyCloseBoundaryUntilOriginalHandoff() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("manager-nonempty-close-handoff-\(UUID().uuidString)")
