        clientA.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        clientA.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        clientA.typedAppendHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, append: command))
        }
        clientA.endHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, end: command) }
        }
        clientA.continuationHandler = { _ in
            Result {
                try self.interviewNaturalInputContinuation(
                    vaultID: vaultID,
                    state: .readyForNarrative,
                    canContinue: true,
                    canContinueLater: true
                )
            }
        }
        let storeA = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root.appendingPathComponent("a")
        )
        let storeB = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root.appendingPathComponent("b")
        )
        let coordinatorA = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: clientA,
            accountLeaseRuntime: runtime,
            productSessionID: "nonempty-close-a",
            liveTurnOutboxStore: storeA,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion-a")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let coordinatorB = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: InterviewNaturalInputClientSpy(),
            accountLeaseRuntime: runtime,
            productSessionID: "nonempty-close-b",
            liveTurnOutboxStore: storeB,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion-b")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinatorA
        )
        let manager = DialogEngineManager.shared
        manager.setCanonicalIngressDeliverySchedulerForTesting { $0() }
        defer {
            manager.setCanonicalIngressDeliverySchedulerForTesting { $0() }
            manager.closeCanonicalIngressForTesting()
        }
        let generationA = UUID()
        let operationA = UUID()
        manager.installCanonicalIngressForTesting(
            engineGeneration: generationA,
            dialogOperationID: operationA,
            delegate: controller
        )

        _ = manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrInfo,
            data: try JSONSerialization.data(withJSONObject: ["question_id": "settled-q1"]),
            engineGeneration: generationA
        )
        _ = manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrResponse,
            data: try JSONSerialization.data(withJSONObject: [
                "results": [["text": "第一问已经完整落盘。", "is_interim": false]],
            ]),
            engineGeneration: generationA
        )
        _ = manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrEnded,
            data: try JSONSerialization.data(withJSONObject: [
                "question_id": "settled-q1",
            ]),
            engineGeneration: generationA
        )
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            guard let snapshot = try? storeA.load(
                for: lease,
                productSessionID: "nonempty-close-a"
            ) else { return false }
            return snapshot.ownerTurnCount == 1
                && snapshot.unsealedCanonicalTurnCount == 0
                && clientA.appendCommands.count == 1
        })

        var frozenQ2Deliveries: [() -> Void] = []
        manager.setCanonicalIngressDeliverySchedulerForTesting {
            frozenQ2Deliveries.append($0)
        }
        _ = manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrInfo,
            data: try JSONSerialization.data(withJSONObject: ["question_id": "frozen-q2"]),
            engineGeneration: generationA
        )
        _ = manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrResponse,
            data: try JSONSerialization.data(withJSONObject: [
                "results": [["text": "第二问已冻结但尚未交接。", "is_interim": false]],
            ]),
            engineGeneration: generationA
        )
        XCTAssertEqual(frozenQ2Deliveries.count, 2)

        manager.stopCanonicalIngressForTesting(
            engineGeneration: generationA,
            dialogOperationID: operationA
        )
        XCTAssertEqual(
            frozenQ2Deliveries.count,
            3,
            "production stop must freeze the final seal before closing ingress"
        )
        controller.finishLiveMemoryCaptureForTesting()
        RunLoop.main.run(until: Date().addingTimeInterval(0.05))
        let beforeHandoff = try XCTUnwrap(storeA.load(
            for: lease,
            productSessionID: "nonempty-close-a"
        ))
        XCTAssertNotNil(
            beforeHandoff.closeIntentRequestedAt,
            "stop must durably freeze the accepted handoff manifest before queued delivery"
        )
        XCTAssertEqual(beforeHandoff.pendingCloseManifestHandoffCount, 3)
        XCTAssertEqual(beforeHandoff.unsealedCanonicalTurnCount, 3)
        XCTAssertTrue(clientA.endCommands.isEmpty)

        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinatorB
        )
        manager.installCanonicalIngressForTesting(
            engineGeneration: UUID(),
            dialogOperationID: UUID(),
            delegate: controller
        )
        frozenQ2Deliveries.forEach { $0() }
        frozenQ2Deliveries.removeAll()

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            guard let snapshot = try? storeA.load(
                for: lease,
                productSessionID: "nonempty-close-a"
            ) else { return false }
            return snapshot.ownerTurnCount == 2
                && snapshot.unsealedCanonicalTurnCount == 0
                && snapshot.closeRequestedLastClientSequenceNumber == 2
                && clientA.endCommands.last?.lastClientSequenceNumber == 2
        })
        XCTAssertEqual(
            clientA.appendCommands.map(\.text),
            ["第一问已经完整落盘。", "第二问已冻结但尚未交接。"]
        )
        XCTAssertNil(try storeB.load(for: lease, productSessionID: "nonempty-close-b"))
        XCTAssertNil(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrInfo,
            data: try JSONSerialization.data(withJSONObject: ["question_id": "late-q3"]),
            engineGeneration: generationA
        ))
    }

