    func testLiveOutboxPersistsExposureAndRefusesUnknownToExposedRegression() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("echo-live-exposure-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "echo-live-exposure"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let prepared = try store.enqueue(
            role: .owner,
            text: "合成的持久派送内容。",
            for: lease,
            productSessionID: productSessionID
        )
        let messageID = try XCTUnwrap(prepared.pendingTurns.first?.messageID)
        XCTAssertEqual(prepared.pendingDispatchStates[messageID], .preparedNotExposed)

        _ = try store.markDispatchState(
            .mayExpose,
            messageID: messageID,
            for: lease,
            productSessionID: productSessionID
        )
        let restored = try XCTUnwrap(
            OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root).load(
                for: lease,
                productSessionID: productSessionID
            )
        )
        XCTAssertEqual(restored.pendingDispatchStates[messageID], .mayExpose)

        _ = try store.markDispatchState(
            .outcomeUnknown,
            messageID: messageID,
            for: lease,
            productSessionID: productSessionID
        )
        XCTAssertThrowsError(try store.markDispatchState(
            .mayExpose,
            messageID: messageID,
            for: lease,
            productSessionID: productSessionID
        ))
    }

    func testLiveNaturalInputRefreshUsesFreshAuthorityForTypedWrites() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        let expired = FeatureDecision(
            decisionId: "expired-live-decision",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v1",
            policyRevision: 1,
            emergencyRevision: 0,
            validatedPolicyRevision: 1,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: false,
            reason: "capturedPolicyExpired",
            expiresAt: Date(timeIntervalSince1970: 1)
        )
        let fresh = FeatureDecision(
            decisionId: "fresh-live-decision",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v2",
            policyRevision: 2,
            emergencyRevision: 0,
            validatedPolicyRevision: 2,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: true,
            reason: "allowed",
            expiresAt: Date().addingTimeInterval(300)
        )
        client.freshNaturalInputDecision = expired
        client.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        client.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        client.typedAppendHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, append: command))
        }
        var refreshCount = 0
        let useCase = OwnerTruthInterviewNaturalInputUseCase(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { false },
            entryMode: .live,
            productSessionID: "ttl-live-session",
            refreshLiveRequestPolicy: { completion in
                refreshCount += 1
                client.freshNaturalInputDecision = fresh
                completion(true)
            }
        )

        useCase.send(.start)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            useCase.viewState.phase == OwnerTruthInterviewNaturalInputPhase.ready
                && client.typedStartAuthorities.count == 1
        })
        let delivery = try OwnerTruthInterviewLiveTurnDelivery(
            commandID: "stable-append-command",
            messageID: recordID("00000000-0000-0000-0000-0000000009f1"),
            clientSequenceNumber: 1,
            role: .owner,
            text: "TTL 后仍使用原命令派送的合成表达。",
            capturedAt: Date(timeIntervalSince1970: 1_700_000_500)
        )
        useCase.send(.submitPersistedLiveTurn(delivery))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            client.typedAppendAuthorities.count == 1
                && useCase.viewState.phase == OwnerTruthInterviewNaturalInputPhase.ready
        })

        XCTAssertEqual(refreshCount, 1)
        XCTAssertEqual(client.typedStartAuthorities.first?.featureDecision.decisionId, "fresh-live-decision")
        XCTAssertEqual(client.typedAppendAuthorities.first?.featureDecision.decisionId, "fresh-live-decision")
        XCTAssertEqual(client.appendCommands.first?.commandID, delivery.commandID)
    }

