        client.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        client.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        client.typedAppendHandler = { _ in
            .outcomeUnknown(URLError(.timedOut))
        }
        let useCase = OwnerTruthInterviewNaturalInputUseCase(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { false },
            entryMode: .live,
            productSessionID: "synthetic-original-error-scene"
        )
        let delivery = try OwnerTruthInterviewLiveTurnDelivery(
            commandID: "synthetic-original-error-command",
            messageID: recordID("00000000-0000-0000-0000-0000000009f2"),
            clientSequenceNumber: 1,
            role: .owner,
            text: "本地合成超时正文。",
            capturedAt: Date(timeIntervalSince1970: 1_700_000_500)
        )
        var observed: (domain: String, code: Int, exposure: String, commandID: String)?
        useCase.onAppendTransportFailure = { error, command, exposure in
            let original = error as NSError
            observed = (original.domain, original.code, exposure, command.commandID)
        }
        useCase.send(.start)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            useCase.viewState.phase == .ready
        })
        useCase.send(.submitPersistedLiveTurn(delivery))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) { observed != nil })
        XCTAssertEqual(observed?.domain, NSURLErrorDomain)
        XCTAssertEqual(observed?.code, NSURLErrorTimedOut)
        XCTAssertEqual(observed?.exposure, "outcomeUnknown")
        XCTAssertEqual(observed?.commandID, delivery.commandID)
        XCTAssertEqual(client.appendCommands.count, 1)
        XCTAssertEqual(useCase.viewState.notice, .outcomeUnknown)
    }

