    func testLiveAppendAuthenticationEvidenceAndRetryBudgetSurviveStoreReconstruction() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-append-auth-durable-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "live-append-auth-durable"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let snapshot = try store.enqueue(
            role: .owner,
            text: "认证拒绝持久化边界的合成表达。",
            for: lease,
            productSessionID: productSessionID
        )
        let delivery = try XCTUnwrap(snapshot.pendingTurns.first)
        let command = try OwnerTruthInterviewNaturalInputAppendCommand(
            commandID: delivery.commandID,
            threadID: recordID("00000000-0000-0000-0000-0000000009a1"),
            sessionID: recordID("00000000-0000-0000-0000-0000000009a2"),
            messageID: delivery.messageID,
            expectedThreadVersion: 7,
            expectedSessionVersion: 11,
            text: delivery.text,
            role: delivery.role,
            captureMode: .live,
            clientSequenceNumber: delivery.clientSequenceNumber,
            capturedAt: delivery.capturedAt
        )
        let evidence = try OwnerTruthInterviewPreHandlerAuthenticationRejectionEvidence(
            command: command,
            transportAttempt: 1
        )

        _ = try store.prepareAppendExposure(
            command: command,
            retry: false,
            for: lease,
            productSessionID: productSessionID
        )
        _ = try store.recordAuthenticationRejection(
            evidence,
            messageID: delivery.messageID,
            for: lease,
            productSessionID: productSessionID
        )
        let restoredStore = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let restored = try XCTUnwrap(restoredStore.load(
            for: lease,
            productSessionID: productSessionID
        ))
        XCTAssertEqual(restored.frozenAppendCommands[delivery.messageID], command)
        XCTAssertEqual(restored.authenticationRejectionEvidence[delivery.messageID], evidence)
        XCTAssertFalse(restored.authenticationRetryClaimedMessageIDs.contains(delivery.messageID))

        _ = try restoredStore.claimAuthenticationRetry(
            messageID: delivery.messageID,
            for: lease,
            productSessionID: productSessionID
        )
        XCTAssertThrowsError(try restoredStore.claimAuthenticationRetry(
            messageID: delivery.messageID,
            for: lease,
            productSessionID: productSessionID
        ))
        _ = try restoredStore.prepareAppendExposure(
            command: command,
            retry: true,
            for: lease,
            productSessionID: productSessionID
        )
        let afterRetry = try XCTUnwrap(restoredStore.load(
            for: lease,
            productSessionID: productSessionID
        ))
        XCTAssertEqual(
            afterRetry.pendingDispatchStates[delivery.messageID],
            .authenticationRetryExposed
        )
        XCTAssertEqual(afterRetry.frozenAppendCommands[delivery.messageID], command)
        XCTAssertTrue(afterRetry.authenticationRetryClaimedMessageIDs.contains(delivery.messageID))

        let afterAcknowledgement = try XCTUnwrap(restoredStore.acknowledge(
            messageID: delivery.messageID,
            for: lease,
            productSessionID: productSessionID
        ))
        XCTAssertTrue(afterAcknowledgement.pendingTurns.isEmpty)
        XCTAssertTrue(afterAcknowledgement.frozenAppendCommands.isEmpty)
        XCTAssertTrue(afterAcknowledgement.authenticationRejectionEvidence.isEmpty)
        XCTAssertTrue(afterAcknowledgement.authenticationRetryClaimedMessageIDs.isEmpty)
    }

    @MainActor
    func testLiveAuthenticationRetryExposureReconstructionRemainsReadOnly() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-auth-retry-exposed-rebuild-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
