        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let start = try OwnerTruthInterviewNaturalInputStartCommand(
            commandID: "live-auth-retry-start",
            threadID: recordID("00000000-0000-0000-0000-0000000009c1"),
            sessionID: recordID("00000000-0000-0000-0000-0000000009c2"),
            entryMode: .live,
            productSessionID: productSessionID
        )
        _ = try store.prepareStart(start, for: lease, productSessionID: productSessionID)
        _ = try store.markStartDispatchState(
            .mayExpose,
            command: start,
            for: lease,
            productSessionID: productSessionID
        )
        _ = try store.markStartDispatchState(
            .committed,
            command: start,
            for: lease,
            productSessionID: productSessionID
        )
        let queued = try store.enqueue(
            role: .owner,
            text: "认证重试已经曝光后的合成正文。",
            for: lease,
            productSessionID: productSessionID
        )
        let messageID = try XCTUnwrap(queued.pendingTurns.first?.messageID)
        _ = try store.markDispatchState(
            .mayExpose,
            messageID: messageID,
            for: lease,
            productSessionID: productSessionID
        )
        _ = try store.markDispatchState(
            .authenticationRejected,
            messageID: messageID,
            for: lease,
            productSessionID: productSessionID
        )
        _ = try store.markDispatchState(
            .authenticationRetryExposed,
            messageID: messageID,
            for: lease,
            productSessionID: productSessionID
        )

        let client = InterviewNaturalInputClientSpy()
        client.scopedCurrentSessionHandler = { _, requestedProductSessionID in
            XCTAssertEqual(requestedProductSessionID, productSessionID)
            return .success(try! self.activeLiveCurrentSession(
                vaultID: vaultID,
                start: start,
                productSessionID: productSessionID,
                continuousClientSequence: 0
            ))
        }
        client.liveDeliveryStatusHandler = { sessionID, requestedProductSessionID, fromSequence in
            XCTAssertEqual(sessionID, start.sessionID)
            XCTAssertEqual(requestedProductSessionID, productSessionID)
            XCTAssertEqual(fromSequence, 1)
            return .success(try! self.liveDeliveryStatus(
                vaultID: vaultID,
                productSessionID: productSessionID,
                start: start,
                deliveries: []
            ))
        }

        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            client.liveDeliveryStatusRequestCount == 1 && coordinator.state == .statusUnknown
        })
        XCTAssertEqual(client.startCommands.count, 0)
        XCTAssertEqual(client.appendCommands.count, 0)
        XCTAssertEqual(
            try XCTUnwrap(store.load(for: lease, productSessionID: productSessionID))
                .pendingDispatchStates[messageID],
            .authenticationRetryExposed
        )
    }

    @MainActor
    func testLiveAuthenticationRetryPolicyDenyKeepsOriginalRejectedCommandUnclaimed() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-auth-retry-policy-deny-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "live-auth-retry-policy-deny"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let client = InterviewNaturalInputClientSpy()
        client.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        client.scopedCurrentSessionHandler = { _, _ in
            guard let start = client.startCommand else {
                return .success(try! self.emptyInterviewNaturalInputCurrentSession(vaultID: vaultID))
            }
            return .success(try! self.activeLiveCurrentSession(
                vaultID: vaultID, start: start,
                productSessionID: productSessionID, continuousClientSequence: 0
            ))
        }
        client.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        client.liveDeliveryStatusHandler = { _, _, _ in
            let start = try! XCTUnwrap(client.startCommand)
            return .success(try! self.liveDeliveryStatus(
                vaultID: vaultID,
                productSessionID: productSessionID,
                start: start,
                deliveries: []
            ))
        }
        var policyAvailable = true
        client.typedAppendHandler = { command in
            guard client.appendCommands.count == 1 else {
                XCTFail("an explicit retry-policy deny must stop before a retry append")
                return .notSent(URLError(.cancelled))
            }
            policyAvailable = false
            client.freshNaturalInputDecision = FeatureDecision(
                decisionId: "retry-policy-denied",
                feature: .echoTextInput,
                purpose: .request,
                policyVersion: "deny-v2",
                policyRevision: 2,
                emergencyRevision: 1,
                validatedPolicyRevision: 2,
                validatedEmergencyRevision: 1,
                accountGeneration: lease.generationId.uuidString,
                allowed: false,
                reason: "policyDenied",
                expiresAt: Date().addingTimeInterval(300)
            )
            let evidence = try! OwnerTruthInterviewPreHandlerAuthenticationRejectionEvidence(
                command: command,
                transportAttempt: 1
            )
            return .serverRejected(
                DreamJourneyBackendClient.ClientError
                    .verifiedPreHandlerAuthenticationRejection(evidence)
            )
        }
        var refreshCount = 0
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { policyAvailable },
            naturalInputPolicyRefresh: { completion in
                refreshCount += 1
                completion(true)
            },
            candidateReviewPolicyAvailable: { true }
        )
        coordinator.appendOwnerTurn("策略拒绝前已经持久化的合成表达。")

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            coordinator.state == .statusUnknown
        })
        XCTAssertEqual(refreshCount, 1)
        let original = try XCTUnwrap(client.appendCommands.first)
        let snapshot = try XCTUnwrap(store.load(for: lease, productSessionID: productSessionID))
        XCTAssertEqual(snapshot.pendingDispatchStates[original.messageID], .authenticationRejected)
        XCTAssertFalse(snapshot.authenticationRetryClaimedMessageIDs.contains(original.messageID))
        XCTAssertEqual(snapshot.frozenAppendCommands[original.messageID], original)
        XCTAssertEqual(client.appendCommands.count, 1)
    }

