        XCTAssertFalse(rejected.authenticationRetryClaimedMessageIDs.contains(original.messageID))
        XCTAssertEqual(rejected.frozenAppendCommands[original.messageID], original)

        policyAvailable = true
        let lateRefresh = try XCTUnwrap(pendingRefresh)
        pendingRefresh = nil
        lateRefresh(true)

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            guard client.appendCommands.count == 2,
                  let snapshot = try? store.load(
                    for: lease,
                    productSessionID: productSessionID
                  ) else { return false }
            return coordinator.state == .live && snapshot.pendingTurns.isEmpty
        })
        XCTAssertEqual(client.appendCommands.map(\.commandID), [original.commandID, original.commandID])
        XCTAssertEqual(client.appendCommands.map(\.messageID), [original.messageID, original.messageID])
    }

    @MainActor
    func testLiveAuthenticationRetryLateRefreshAfterAccountChangeCannotSendOrClaim() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-auth-retry-late-refresh-\(UUID().uuidString)")
