        client.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        client.liveDeliveryStatusHandler = { _, _, _ in
            let start = try! XCTUnwrap(client.startCommand)
            return .success(try! self.liveDeliveryStatus(
                vaultID: vaultID,
                productSessionID: productSessionID,
                start: start,
                deliveries: []
            ))
        }
        var policyAvailable = true
        client.typedAppendHandler = { command in
            guard client.appendCommands.count == 1 else {
                XCTFail("a stale retry preparation callback must not send")
                return .notSent(URLError(.cancelled))
            }
            policyAvailable = false
            let evidence = try! OwnerTruthInterviewPreHandlerAuthenticationRejectionEvidence(
                command: command,
                transportAttempt: 1
            )
            return .serverRejected(
                DreamJourneyBackendClient.ClientError
                    .verifiedPreHandlerAuthenticationRejection(evidence)
            )
        }
        var pendingRefresh: ((Bool) -> Void)?
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { policyAvailable },
            naturalInputPolicyRefresh: { pendingRefresh = $0 },
            candidateReviewPolicyAvailable: { true }
        )
        coordinator.appendOwnerTurn("账号变化前已经持久化的合成表达。")

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { pendingRefresh != nil })
        let original = try XCTUnwrap(client.appendCommands.first)
        let rejected = try XCTUnwrap(store.load(for: lease, productSessionID: productSessionID))
        XCTAssertEqual(rejected.pendingDispatchStates[original.messageID], .authenticationRejected)
        XCTAssertFalse(rejected.authenticationRetryClaimedMessageIDs.contains(original.messageID))
        XCTAssertEqual(rejected.frozenAppendCommands[original.messageID], original)
        let startRequestCount = client.startCommands.count
        let appendRequestCount = client.appendCommands.count
        let endRequestCount = client.endCommands.count
        let scopedCurrentSessionRequestCount = client.scopedCurrentSessionRequestCount
        let deliveryStatusRequestCount = client.liveDeliveryStatusRequestCount
        let acknowledgementRequestCount = client.acknowledgementCommands.count
        let admissionRequestCount = client.admissionCommands.count
        let pendingReviewInboxRequestCount = client.pendingReviewInboxRequestCount
        let proposalStatusRequestCount = client.proposalStatusRequestCount

        policyAvailable = true
        runtime.publish(session: accountSession(
            subjectId: "owner-b",
            vaultId: "vault-b",
            generation: lease.generation + 1,
            generationID: UUID()
        ))
        let lateRefresh = try XCTUnwrap(pendingRefresh)
        pendingRefresh = nil
        lateRefresh(true)
        let lateCallbackSettled = expectation(
            description: "stale policy refresh callback receives a bounded processing opportunity"
        )
        DispatchQueue.main.async { lateCallbackSettled.fulfill() }
        wait(for: [lateCallbackSettled], timeout: 1)

        let snapshot = try XCTUnwrap(store.load(for: lease, productSessionID: productSessionID))
        XCTAssertEqual(snapshot.pendingDispatchStates[original.messageID], .authenticationRejected)
        XCTAssertFalse(snapshot.authenticationRetryClaimedMessageIDs.contains(original.messageID))
        XCTAssertEqual(snapshot.frozenAppendCommands[original.messageID], original)
        XCTAssertEqual(client.startCommands.count, startRequestCount)
        XCTAssertEqual(client.appendCommands.count, appendRequestCount)
        XCTAssertEqual(client.endCommands.count, endRequestCount)
        XCTAssertEqual(client.scopedCurrentSessionRequestCount, scopedCurrentSessionRequestCount)
        XCTAssertEqual(client.liveDeliveryStatusRequestCount, deliveryStatusRequestCount)
        XCTAssertEqual(client.acknowledgementCommands.count, acknowledgementRequestCount)
        XCTAssertEqual(client.admissionCommands.count, admissionRequestCount)
        XCTAssertEqual(client.pendingReviewInboxRequestCount, pendingReviewInboxRequestCount)
        XCTAssertEqual(client.proposalStatusRequestCount, proposalStatusRequestCount)
        XCTAssertNotEqual(coordinator.state, .live)
    }

