        let original = try XCTUnwrap(client.appendCommands.first)
        let snapshot = try XCTUnwrap(store.load(for: lease, productSessionID: productSessionID))
        XCTAssertTrue(snapshot.authenticationRetryClaimedMessageIDs.contains(original.messageID))
        XCTAssertEqual(snapshot.frozenAppendCommands[original.messageID], original)
        XCTAssertEqual(client.appendCommands.map(\.commandID), [original.commandID, original.commandID])
        RunLoop.main.run(until: Date().addingTimeInterval(0.1))
        XCTAssertEqual(client.appendCommands.count, 2)
    }

    @MainActor
    func testLiveUnknownStartReconstructionUsesExactReadOnlyStatusWithoutSecondPost() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-start-readonly-recovery-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "live-start-readonly-recovery"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let allowedDecision = FeatureDecision(
            decisionId: "start-recovery-allow",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v1",
            policyRevision: 1,
            emergencyRevision: 0,
            validatedPolicyRevision: 1,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: true,
            reason: "allowed",
            expiresAt: Date().addingTimeInterval(300)
        )
        let firstClient = InterviewNaturalInputClientSpy()
        firstClient.freshNaturalInputDecision = allowedDecision
        firstClient.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        firstClient.typedStartHandler = { _ in
            .outcomeUnknown(URLError(.networkConnectionLost))
        }
        var firstCoordinator: EchoLiveMemoryCaptureCoordinator? = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: firstClient,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        firstCoordinator?.appendCanonicalTurn(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "owner-start-recovery",
            role: .owner,
            text: "启动结果未知后仍需保存的合成表达。",
            finality: .complete,
            finalityEvidence: .explicitFinal,
            evidenceSource: .resultsIsInterim,
            capturedAt: Date(timeIntervalSince1970: 1_700_400_000)
        ))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            firstClient.typedStartAuthorities.count == 1
                && firstCoordinator?.state == .statusUnknown
                && (try? store.load(for: lease, productSessionID: productSessionID))?
                    .startDispatchState == .outcomeUnknown
        })
        let originalStart = try XCTUnwrap(firstClient.startCommand)
        let originalAppendCommandID = try XCTUnwrap(
            store.load(for: lease, productSessionID: productSessionID)?
                .pendingTurns.first?.commandID
        )
        firstCoordinator = nil

        let restoredClient = InterviewNaturalInputClientSpy()
        restoredClient.freshNaturalInputDecision = allowedDecision
        restoredClient.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        restoredClient.typedAppendHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, append: command))
        }
        restoredClient.liveDeliveryStatusHandler = { sessionID, requestedProductSessionID, fromSequence in
            XCTAssertEqual(sessionID, originalStart.sessionID)
            XCTAssertEqual(requestedProductSessionID, productSessionID)
            XCTAssertEqual(fromSequence, 1)
            let commandHash = SHA256.hash(data: Data(originalStart.commandID.utf8)).map {
                String(format: "%02x", $0)
            }.joined()
            return Result {
                try OwnerTruthLiveDeliveryStatus(
                    backendJSONObject: [
                        "schemaVersion": OwnerTruthLiveDeliveryStatus.schemaVersion,
                        "vaultId": vaultID.rawValue,
                        "productSessionId": productSessionID,
                        "session": [
                            "threadId": originalStart.threadID.rawValue.uuidString.lowercased(),
                            "sessionId": originalStart.sessionID.rawValue.uuidString.lowercased(),
                            "state": OwnerTruthInterviewSessionLifecycle.active.rawValue,
                            "boundary": OwnerTruthInterviewSessionBoundary.open.rawValue,
                            "threadVersion": 1,
                            "sessionVersion": 1,
                            "authorityEpoch": 0,
                            "continuousClientSequence": 0,
                            "closeRequestedClientSequence": NSNull(),
                        ],
                        "observedAt": "2026-09-17T02:00:00Z",
                        "window": [
                            "fromClientSequence": 1,
                            "limit": 64,
                            "missingClientSequences": [],
                            "nextFromClientSequence": NSNull(),
                        ],
                        "deliveries": [],
                        "operations": [[
                            "operation": OwnerTruthLiveDeliveryOperationKind
                                .startInterviewSession.rawValue,
                            "commandIdHash": commandHash,
                            "receiptId": "00000000-0000-0000-0000-0000000009d4",
                            "threadId": originalStart.threadID.rawValue.uuidString.lowercased(),
                            "sessionId": originalStart.sessionID.rawValue.uuidString.lowercased(),
                            "resultState": OwnerTruthInterviewSessionLifecycle.active.rawValue,
                        ]],
                    ],
                    expectedVaultID: vaultID,
                    expectedSessionID: originalStart.sessionID,
                    expectedProductSessionID: productSessionID
                )
            }
        }
        let restoredCoordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: restoredClient,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )

        let restoredStartDrained = waitForOwnerTruthHTTPUI(timeout: 5) {
            restoredClient.liveDeliveryStatusRequestCount == 1
                && restoredClient.typedAppendAuthorities.count == 1
                && restoredCoordinator.state == .live
        }
        let restoredSnapshot = try? store.load(
            for: lease,
            productSessionID: productSessionID
        )
        XCTAssertTrue(
            restoredStartDrained,
            "statusGET=\(restoredClient.liveDeliveryStatusRequestCount) "
                + "appendPOST=\(restoredClient.typedAppendAuthorities.count) "
                + "state=\(restoredCoordinator.state) "
                + "startState=\(String(describing: restoredSnapshot?.startDispatchState)) "
                + "pending=\(restoredSnapshot?.pendingTurns.count ?? -1)"
        )
        XCTAssertEqual(firstClient.startCommands.count, 1)
        XCTAssertEqual(restoredClient.startCommands.count, 0)
        XCTAssertEqual(restoredClient.appendCommands.first?.commandID, originalAppendCommandID)
    }

    func testLiveUnknownPreparedStartCannotUseCurrentSessionAsCommandProof() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let productSessionID = "live-unknown-current-must-not-bind"
        let command = try OwnerTruthInterviewNaturalInputStartCommand(
            commandID: "unknown-start-command-proof",
            threadID: recordID("00000000-0000-0000-0000-0000000009e5"),
            sessionID: recordID("00000000-0000-0000-0000-0000000009e6"),
            entryMode: .live,
            productSessionID: productSessionID
        )

        func makeCurrent(sessionID: OwnerTruthRecordID) throws -> OwnerTruthInterviewNaturalInputCurrentSession {
            try OwnerTruthInterviewNaturalInputCurrentSession(
                backendJSONObject: [
                    "schemaVersion": OwnerTruthInterviewNaturalInputCurrentSession.schemaVersion,
                    "vaultId": vaultID.rawValue,
                    "currentSession": [
                        "status": "resumed",
                        "threadId": command.threadID.rawValue.uuidString.lowercased(),
                        "sessionId": sessionID.rawValue.uuidString.lowercased(),
                        "threadVersion": 1,
                        "sessionVersion": 1,
                        "state": "active",
                        "boundary": "open",
                        "entryMode": "live",
                        "productSessionId": productSessionID,
                    ],
                ],
                expectedVaultID: vaultID
            )
        }

        for currentSessionID in [
            recordID("00000000-0000-0000-0000-0000000009e7"),
            command.sessionID,
        ] {
            let client = InterviewNaturalInputClientSpy()
            client.scopedCurrentSessionHandler = { _, _ in
                .success(try! makeCurrent(sessionID: currentSessionID))
            }
            let useCase = OwnerTruthInterviewNaturalInputUseCase(
                accountLease: lease,
                client: client,
                accountLeaseRuntime: runtime,
                qaGateEnabled: { false },
                entryMode: .live,
                productSessionID: productSessionID,
                preparedStartCommand: command,
                preparedStartDispatchState: .outcomeUnknown
            )

            useCase.send(.start)

            XCTAssertEqual(useCase.viewState.phase, .failed)
            XCTAssertEqual(useCase.viewState.notice, .outcomeUnknown)
            XCTAssertTrue(client.startCommands.isEmpty)
        }
    }

    func testLiveSameUseCaseBindsExactStartReadOnlyResultAndDrainsOriginalTail() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        client.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        client.scopedCurrentSessionHandler = { expectedVaultID, _ in
            .success(try! self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID))
        }
        client.typedStartHandler = { _ in
            .outcomeUnknown(URLError(.networkConnectionLost))
        }
        client.typedAppendHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, append: command))
        }
        var preparedCommand: OwnerTruthInterviewNaturalInputStartCommand?
        var preparedState: OwnerTruthInterviewLiveStartDispatchState?
        let useCase = OwnerTruthInterviewNaturalInputUseCase(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { false },
            entryMode: .live,
            productSessionID: "live-same-usecase-readonly-start",
            willPrepareStartCommand: { preparedCommand = $0 },
            willExposeStartCommand: { _ in preparedState = .mayExpose },
            didClassifyStartCommand: { _, state in preparedState = state }
        )

        useCase.send(.start)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            useCase.viewState.notice == .outcomeUnknown
        })
        let command = try XCTUnwrap(preparedCommand)
        XCTAssertEqual(preparedState, .outcomeUnknown)
        XCTAssertEqual(client.startCommands.count, 1)

        useCase.bindReadOnlyVerifiedStart(
            try interviewNaturalInputReceipt(vaultID: vaultID, start: command)
        )
        XCTAssertEqual(useCase.viewState.phase, .ready)

        let delivery = try OwnerTruthInterviewLiveTurnDelivery(
            commandID: "same-usecase-tail-command",
            messageID: recordID("00000000-0000-0000-0000-0000000009e8"),
            clientSequenceNumber: 1,
            role: .owner,
            text: "原 start 只读命中后才能首次派送的合成队尾。",
            capturedAt: Date(timeIntervalSince1970: 1_700_700_000)
        )
        useCase.send(.submitPersistedLiveTurn(delivery))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            client.appendCommands.count == 1 && useCase.viewState.phase == .ready
        })
        XCTAssertEqual(client.startCommands.count, 1)
        XCTAssertEqual(client.appendCommands.first?.commandID, delivery.commandID)
    }

    func testLiveExpiredPolicyExplicitDenyDoesNotExposeOrPostAppend() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        var fakeNow = Date(timeIntervalSince1970: 1_700_100_000)
        let initialExpiry = fakeNow.addingTimeInterval(300)
        client.freshNaturalInputDecision = FeatureDecision(
            decisionId: "initial-live-allow",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v1",
            policyRevision: 1,
            emergencyRevision: 0,
            validatedPolicyRevision: 1,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: true,
            reason: "allowed",
            expiresAt: initialExpiry
        )
        client.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        client.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        var refreshCount = 0
        var exposedAppendCount = 0
        let useCase = OwnerTruthInterviewNaturalInputUseCase(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { false },
            entryMode: .live,
            productSessionID: "live-explicit-deny",
            refreshLiveRequestPolicy: { completion in
                refreshCount += 1
                client.freshNaturalInputDecision = FeatureDecision(
                    decisionId: "refreshed-live-deny",
                    feature: .echoTextInput,
                    purpose: .request,
                    policyVersion: "v2",
                    policyRevision: 2,
                    emergencyRevision: 1,
                    validatedPolicyRevision: 2,
                    validatedEmergencyRevision: 1,
                    accountGeneration: lease.generationId.uuidString,
                    allowed: false,
                    reason: "policyDenied",
                    expiresAt: fakeNow.addingTimeInterval(300)
                )
                completion(true)
            },
            authorityNow: { fakeNow },
            willExposeLiveTurnCommand: { _ in exposedAppendCount += 1 }
        )

        useCase.send(.start)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            useCase.viewState.phase == .ready
        })
        fakeNow = initialExpiry.addingTimeInterval(1)
        client.freshNaturalInputDecision = FeatureDecision(
            decisionId: "expired-live-authority",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v1",
            policyRevision: 1,
            emergencyRevision: 0,
            validatedPolicyRevision: 1,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: false,
            reason: "capturedPolicyExpired",
            expiresAt: initialExpiry
        )
        let delivery = try OwnerTruthInterviewLiveTurnDelivery(
            commandID: "deny-before-append",
            messageID: recordID("00000000-0000-0000-0000-0000000009d3"),
            clientSequenceNumber: 1,
            role: .owner,
            text: "明确拒绝时不得暴露的合成内容。",
            capturedAt: fakeNow
        )

        useCase.send(.submitPersistedLiveTurn(delivery))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            useCase.viewState.phase == .failed
                && useCase.viewState.notice == .requestNotSent
        })
        XCTAssertEqual(refreshCount, 1)
        XCTAssertEqual(exposedAppendCount, 0)
        XCTAssertEqual(client.typedAppendAuthorities.count, 0)
        XCTAssertEqual(client.appendCommands.count, 0)
    }

    func testB8FreshAuthorityFlowsThroughRealBackendInboxAndAcknowledgement() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let threadID = recordID("00000000-0000-0000-0000-0000000009e1")
        let sessionID = recordID("00000000-0000-0000-0000-0000000009e2")
        let reviewBatchID = recordID("00000000-0000-0000-0000-0000000009e3")
        let fakeNow = Date(timeIntervalSince1970: 1_700_500_000)
        var decision = FeatureDecision(
            decisionId: "ack-expired-decision",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v1",
            policyRevision: 1,
            emergencyRevision: 0,
            validatedPolicyRevision: 1,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: false,
            reason: "capturedPolicyExpired",
            expiresAt: fakeNow.addingTimeInterval(-1)
        )
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: { _ in decision },
            freshFeatureDecision: { _ in decision },
            accountLeaseRuntime: runtime
        )
        let inboxBody = try JSONSerialization.data(withJSONObject: [
            "schemaVersion": OwnerTruthInterviewPendingReviewBatchInbox.schemaVersion,
            "vaultId": lease.vaultId,
            "reviewBatches": [[
                "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased(),
                "threadId": threadID.rawValue.uuidString.lowercased(),
                "sessionId": sessionID.rawValue.uuidString.lowercased(),
                "reviewBatchVersion": 4,
                "sessionVersion": 3,
                "trigger": OwnerTruthInterviewReviewBatchTrigger.sessionExit.rawValue,
                "capturedCandidateBatchTurnCount": 1,
            ]],
        ])
        let acknowledgementBody = try JSONSerialization.data(withJSONObject: [
            "schemaVersion": OwnerTruthInterviewReviewBatchAcknowledgementReceipt.schemaVersion,
            "vaultId": lease.vaultId,
            "status": OwnerTruthInterviewReviewBatchAcknowledgementOutcome.acknowledged.rawValue,
            "session": [
                "threadId": threadID.rawValue.uuidString.lowercased(),
                "sessionId": sessionID.rawValue.uuidString.lowercased(),
                "sessionVersion": 4,
            ],
            "reviewBatch": [
                "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased(),
                "trigger": OwnerTruthInterviewReviewBatchTrigger.sessionExit.rawValue,
                "state": "acknowledged",
                "capturedCandidateBatchTurnCount": 1,
                "rowVersion": 5,
            ],
            "candidateProposal": ["status": "notStarted"],
            "memoryActivation": ["status": "notApplicable"],
        ])
        var requestMethods: [String] = []
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            requestMethods.append(request.httpMethod ?? "")
            switch request.httpMethod {
            case "GET": loader.respond(statusCode: 200, body: inboxBody)
            case "POST": loader.respond(statusCode: 201, body: acknowledgementBody)
            default:
                XCTFail("Unexpected acknowledgement request method")
                loader.fail(URLError(.badURL))
            }
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
        var refreshCount = 0
        let useCase = OwnerTruthInterviewReviewBatchAcknowledgementUseCase(
            accountLease: lease,
            threadID: threadID,
            sessionID: sessionID,
            inboxClient: client,
            acknowledgementClient: client,
            accountLeaseRuntime: runtime,
            releasePolicyAvailable: { true },
            diagnosticTraceID: "ack-fresh-authority-trace",
            requiresFreshRequestAuthority: true,
            refreshRequestPolicy: { completion in
                refreshCount += 1
                decision = FeatureDecision(
                    decisionId: "ack-fresh-decision",
                    feature: .echoTextInput,
                    purpose: .request,
                    policyVersion: "v2",
                    policyRevision: 2,
                    emergencyRevision: 0,
                    validatedPolicyRevision: 2,
                    validatedEmergencyRevision: 0,
                    accountGeneration: lease.generationId.uuidString,
                    allowed: true,
                    reason: "allowed",
                    expiresAt: fakeNow.addingTimeInterval(300)
                )
                completion(true)
            },
            authorityNow: { fakeNow }
        )

        useCase.send(.acknowledge)

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            useCase.viewState.phase == .acknowledged
        })
        XCTAssertEqual(refreshCount, 1)
        XCTAssertEqual(requestMethods, ["GET", "POST"])
        XCTAssertEqual(useCase.viewState.receipt?.reviewBatchID, reviewBatchID)
    }

