        let acknowledgementBody = try JSONSerialization.data(withJSONObject: [
            "schemaVersion": OwnerTruthInterviewReviewBatchAcknowledgementReceipt.schemaVersion,
            "vaultId": lease.vaultId,
            "status": OwnerTruthInterviewReviewBatchAcknowledgementOutcome.acknowledged.rawValue,
            "session": [
                "threadId": threadID.rawValue.uuidString.lowercased(),
                "sessionId": sessionID.rawValue.uuidString.lowercased(),
                "sessionVersion": 2,
            ],
            "reviewBatch": [
                "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased(),
