        })
        XCTAssertEqual(refreshCount, 1)
        XCTAssertEqual(
            OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.map(\.httpMethod),
            ["GET", "POST"]
        )
        XCTAssertFalse(
            featureGate.requestServerPolicyManagedDecision(for: .echoTextInput).allowed,
            "the expired captured route must remain denied and must not authorize the ack"
        )
    }

    func testLiveLogicalTwentyMinutesRefreshesMultipleTTLsWithMonotonicDelivery() throws {
