                accountGeneration: lease.generationId.uuidString,
                allowed: true,
                reason: "allowed",
                expiresAt: authorityExpiry
            )
        }
        client.freshNaturalInputDecision = allowedDecision()
        client.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        client.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        client.typedAppendHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, append: command))
        }
        var refreshCount = 0
        var exposedCommands: [String] = []
        let useCase = OwnerTruthInterviewNaturalInputUseCase(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { false },
            entryMode: .live,
            productSessionID: "logical-twenty-minute-live",
            refreshLiveRequestPolicy: { completion in
                refreshCount += 1
                authorityRevision += 1
                authorityExpiry = fakeNow.addingTimeInterval(300)
                client.freshNaturalInputDecision = allowedDecision()
                completion(true)
            },
            authorityNow: { fakeNow },
            willExposeLiveTurnCommand: { exposedCommands.append($0.commandID) }
        )

        useCase.send(.start)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            useCase.viewState.phase == .ready
        })

        for index in 1...10 {
            fakeNow = fakeNow.addingTimeInterval(120)
            if fakeNow >= authorityExpiry {
                client.freshNaturalInputDecision = FeatureDecision(
                    decisionId: "expired-live-\(authorityRevision)",
                    feature: .echoTextInput,
                    purpose: .request,
                    policyVersion: "v\(authorityRevision)",
                    policyRevision: authorityRevision,
                    emergencyRevision: 0,
                    validatedPolicyRevision: authorityRevision,
                    validatedEmergencyRevision: 0,
                    accountGeneration: lease.generationId.uuidString,
                    allowed: false,
                    reason: "capturedPolicyExpired",
                    expiresAt: authorityExpiry
                )
            }
            let delivery = try OwnerTruthInterviewLiveTurnDelivery(
                commandID: "twenty-minute-turn-\(index)",
                messageID: OwnerTruthRecordID(rawValue: UUID()),
                clientSequenceNumber: index,
                role: .owner,
                text: "逻辑二十分钟第 \(index) 条合成表达。",
                capturedAt: fakeNow
            )
            useCase.send(.submitPersistedLiveTurn(delivery))
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                client.typedAppendAuthorities.count == index
                    && useCase.viewState.phase == .ready
            })
        }

        XCTAssertEqual(refreshCount, 3)
        XCTAssertEqual(exposedCommands, (1...10).map { "twenty-minute-turn-\($0)" })
        XCTAssertEqual(
            client.appendCommands.compactMap(\.clientSequenceNumber),
            Array(1...10)
        )
        XCTAssertEqual(Set(client.typedAppendAuthorities.map {
            $0.featureDecision.decisionId
        }), Set(["live-allow-1", "live-allow-2", "live-allow-3", "live-allow-4"]))
    }

    @MainActor
    func testManagerEchoOutboxTenQuestionsShareOneExpiredPolicyRefresh() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("manager-ten-question-live-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "manager-ten-question-live"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        var fakeNow = Date(timeIntervalSince1970: 1_700_300_000)
        let initialExpiry = fakeNow.addingTimeInterval(300)
        client.freshNaturalInputDecision = FeatureDecision(
            decisionId: "ten-question-initial",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v1",
            policyRevision: 1,
            emergencyRevision: 0,
            validatedPolicyRevision: 1,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: true,
            reason: "allowed",
            expiresAt: initialExpiry
        )
        client.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        client.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        client.typedAppendHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, append: command))
        }
        var refreshCount = 0
        var pendingRefresh: ((Bool) -> Void)?
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            liveAuthorityNow: { fakeNow },
            naturalInputPolicyAvailable: { true },
            naturalInputPolicyRefresh: { completion in
                refreshCount += 1
                pendingRefresh = completion
            },
            candidateReviewPolicyAvailable: { true }
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )
        let manager = DialogEngineManager.shared
        let generation = UUID()
        let operationID = UUID()
        manager.installCanonicalIngressForTesting(
            engineGeneration: generation,
            dialogOperationID: operationID,
            delegate: controller
        )
        defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operationID) }

        func enqueueQuestion(_ index: Int) throws {
            let capturedAt = fakeNow.addingTimeInterval(Double(index))
            _ = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrInfo,
                data: try JSONSerialization.data(withJSONObject: [
                    "question_id": "question-\(index)",
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt
            ))
            _ = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrResponse,
                data: try JSONSerialization.data(withJSONObject: [
                    "results": [[
                        "text": "第 \(index) 条完整用户表达。",
                        "is_interim": false,
                    ]],
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.1)
            ))
            _ = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrEnded,
                data: try JSONSerialization.data(withJSONObject: [
                    "question_id": "question-\(index)",
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.15)
            ))
            XCTAssertTrue(manager.enqueueCanonicalAssistantForTesting(
                replyID: "reply-\(index)",
                text: "第 \(index) 条完整助手回答。",
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.2)
            ))
        }

        try enqueueQuestion(1)
        let firstQuestionDrained = waitForOwnerTruthHTTPUI(timeout: 3) {
            client.typedAppendAuthorities.count == 2
                && (try? store.load(for: lease, productSessionID: productSessionID))?
                    .ownerTurnCount == 1
        }
        let firstSnapshot = try? store.load(
            for: lease,
            productSessionID: productSessionID
        )
        XCTAssertTrue(
            firstQuestionDrained,
            "appendRoles=\(client.appendCommands.map { $0.role.rawValue }) "
                + "pending=\(firstSnapshot?.pendingTurns.map { $0.role.rawValue } ?? []) "
                + "unsealed=\(firstSnapshot?.unsealedCanonicalTurnCount ?? -1) "
                + "state=\(coordinator.state)"
        )

        fakeNow = initialExpiry.addingTimeInterval(1)
        client.freshNaturalInputDecision = FeatureDecision(
            decisionId: "ten-question-expired",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v1",
            policyRevision: 1,
            emergencyRevision: 0,
            validatedPolicyRevision: 1,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: false,
            reason: "capturedPolicyExpired",
            expiresAt: initialExpiry
        )
        for index in 2...10 {
            try enqueueQuestion(index)
        }
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            refreshCount == 1
                && (try? store.load(for: lease, productSessionID: productSessionID))?
                    .ownerTurnCount == 10
        })
        XCTAssertEqual(client.typedAppendAuthorities.count, 2)

        client.freshNaturalInputDecision = FeatureDecision(
            decisionId: "ten-question-refreshed",
            feature: .echoTextInput,
            purpose: .request,
            policyVersion: "v2",
            policyRevision: 2,
            emergencyRevision: 0,
            validatedPolicyRevision: 2,
            validatedEmergencyRevision: 0,
            accountGeneration: lease.generationId.uuidString,
            allowed: true,
            reason: "allowed",
            expiresAt: fakeNow.addingTimeInterval(300)
        )
        let refreshCompletion = try XCTUnwrap(pendingRefresh)
        pendingRefresh = nil
        refreshCompletion(true)

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
            client.typedAppendAuthorities.count == 20
                && coordinator.state == .live
        })
        XCTAssertEqual(refreshCount, 1)
        XCTAssertEqual(client.appendCommands.filter { $0.role == .owner }.count, 10)
        XCTAssertEqual(client.appendCommands.filter { $0.role == .assistant }.count, 10)
        XCTAssertEqual(
            client.appendCommands.compactMap(\.clientSequenceNumber),
            Array(1...20)
        )
        XCTAssertTrue(client.typedAppendAuthorities.dropFirst(2).allSatisfy {
            $0.featureDecision.decisionId == "ten-question-refreshed"
        })
    }

    @MainActor
    func testLiveSavingRetriesFailedCurrentReadOnceAndCompletesSameSession() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-saving-current-read-recovery-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "live-saving-current-read-recovery"
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let followUp = EchoLiveMemoryFollowUpStore(
            rootDirectory: root.appendingPathComponent("follow-up", isDirectory: true)
        )
        let checkpoint = EchoLiveMemoryCompletionCheckpointStore(
            rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
        )
        let now = Date(timeIntervalSince1970: 1_789_640_000)
        let policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "live-saving-v1",
            policyRevision: 1,
            emergencyRevision: 0,
            expiresAt: now.addingTimeInterval(300),
            featureEnabled: true,
            releaseVisible: true,
            reason: "liveSavingAllowed"
        )
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        let productionAccountGeneration = FeatureGateService.accountGeneration(
            forIdentitySource: authSession.sessionId
        )
        let featureGate = FeatureGateService.makeQATestService(
            accountGeneration: { productionAccountGeneration },
            policy: { _, _ in policy },
            now: { now }
        )
        featureGate.captureServerPolicyManagedRoute(.echoTextInput, risk: .ownerTextCore)
        featureGate.captureServerPolicyManagedRoute(.ownerTruthCandidateReview)

        let backend = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: {
                featureGate.requestServerPolicyManagedDecision(for: $0)
            },
            freshFeatureDecision: {
                featureGate.freshServerPolicyManagedRequestDecision(for: $0)
            },
            featureDecisionRevalidator: {
                featureGate.revalidateServerPolicyManagedRequest($0)
            },
            accountLeaseRuntime: runtime
        )

        let reviewBatchID = recordID("00000000-0000-0000-0000-000000000a81")
        var serverThreadID: String?
        var serverSessionID: String?
        var serverThreadVersion = 1
        var serverSessionVersion = 1
        var currentReadCount = 0
        var startPostCount = 0
        var appendPostCount = 0
        var endPostCount = 0
        var acknowledgementPostCount = 0
        var admissionPostCount = 0
        var statusGetCount = 0

        func responseData(_ object: [String: Any]) -> Data {
            try! JSONSerialization.data(withJSONObject: object)
        }

        func requestPayload() -> [String: Any] {
            guard let optionalBody = OwnerTruthReviewReadyHTTPURLProtocol
                    .recordedRequestBodies.last,
                  let body = optionalBody,
                  let object = try? JSONSerialization.jsonObject(with: body)
                    as? [String: Any] else {
                return [:]
            }
            return object
        }

        func naturalInputReceipt(
            payload: [String: Any],
            lifecycle: OwnerTruthInterviewSessionLifecycle,
            includeMessage: Bool,
            closeWatermark: Int? = nil
        ) -> Data {
            var receipt: [String: Any] = [
                "status": OwnerTruthCommandOutcome.created.rawValue,
                "threadId": payload["threadId"] as? String ?? serverThreadID ?? "",
                "sessionId": serverSessionID ?? payload["sessionId"] as? String ?? "",
                "threadVersion": serverThreadVersion,
                "sessionVersion": serverSessionVersion,
                "state": lifecycle.rawValue,
                "boundary": OwnerTruthInterviewSessionBoundary.open.rawValue,
                "authorityEpoch": 0,
            ]
            if includeMessage {
                receipt["messageId"] = payload["messageId"]
                receipt["messageSequence"] = payload["clientSequenceNumber"]
                receipt["clientSequenceNumber"] = payload["clientSequenceNumber"]
                receipt["continuousClientSequence"] = payload["clientSequenceNumber"]
                receipt["deliveryState"] = OwnerTruthInterviewNaturalInputDeliveryState
                    .contiguous.rawValue
            }
            if let closeWatermark {
                receipt["continuousClientSequence"] = closeWatermark
                receipt["deliveryState"] = OwnerTruthInterviewNaturalInputDeliveryState
                    .closedAfterContiguousDelivery.rawValue
            }
            return responseData([
                "schemaVersion": OwnerTruthInterviewNaturalInputReceipt.schemaVersion,
                "vaultId": lease.vaultId,
                "receipt": receipt,
            ])
        }

        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            let path = request.url?.path ?? ""
            let method = request.httpMethod ?? ""
            if method == "GET", path.hasSuffix("/interview-sessions/current") {
                currentReadCount += 1
                if currentReadCount == 1 {
                    loader.fail(URLError(.notConnectedToInternet))
                } else {
                    loader.respond(statusCode: 200, body: responseData([
                        "schemaVersion": OwnerTruthInterviewNaturalInputCurrentSession.schemaVersion,
                        "vaultId": lease.vaultId,
                        "currentSession": NSNull(),
                    ]))
                }
                return
            }
            if method == "POST", path.hasSuffix("/interview-sessions") {
                startPostCount += 1
                let payload = requestPayload()
                serverThreadID = payload["threadId"] as? String
                serverSessionID = payload["sessionId"] as? String
                loader.respond(
                    statusCode: 201,
                    body: naturalInputReceipt(
                        payload: payload,
                        lifecycle: .active,
                        includeMessage: false
                    )
                )
                return
            }
            if method == "GET", path.hasSuffix("/presentation") {
                loader.respond(statusCode: 200, body: responseData([
                    "schemaVersion": OwnerTruthInterviewNaturalInputContinuation.schemaVersion,
                    "vaultId": lease.vaultId,
                    "presentation": [
                        "state": OwnerTruthInterviewNaturalInputContinuationState
                            .readyForNarrative.rawValue,
                        "canContinue": true,
                        "canContinueLater": true,
                    ],
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/messages") {
                appendPostCount += 1
                let payload = requestPayload()
                serverThreadVersion = (payload["expectedThreadVersion"] as? Int ?? 0) + 1
                serverSessionVersion = (payload["expectedSessionVersion"] as? Int ?? 0) + 1
                loader.respond(
                    statusCode: 201,
                    body: naturalInputReceipt(
                        payload: payload,
                        lifecycle: .active,
                        includeMessage: true
                    )
                )
                return
            }
            if method == "POST", path.hasSuffix("/end") {
                endPostCount += 1
                let payload = requestPayload()
                serverThreadVersion = (payload["expectedThreadVersion"] as? Int ?? 0) + 1
                serverSessionVersion = (payload["expectedSessionVersion"] as? Int ?? 0) + 2
                loader.respond(
                    statusCode: 201,
                    body: naturalInputReceipt(
                        payload: payload,
                        lifecycle: .ended,
                        includeMessage: false,
                        closeWatermark: payload["lastClientSequenceNumber"] as? Int
                    )
                )
                return
            }
            if method == "GET", path.hasSuffix("/interview-review-batches/pending") {
                loader.respond(statusCode: 200, body: responseData([
                    "schemaVersion": OwnerTruthInterviewPendingReviewBatchInbox.schemaVersion,
                    "vaultId": lease.vaultId,
                    "reviewBatches": [[
                        "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased(),
                        "threadId": serverThreadID ?? "",
                        "sessionId": serverSessionID ?? "",
                        "reviewBatchVersion": 1,
                        "sessionVersion": serverSessionVersion,
                        "trigger": OwnerTruthInterviewReviewBatchTrigger.sessionExit.rawValue,
                        "capturedCandidateBatchTurnCount": 1,
                    ]],
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/acknowledgement") {
                acknowledgementPostCount += 1
                let payload = requestPayload()
                serverSessionVersion = (payload["expectedSessionVersion"] as? Int
                    ?? serverSessionVersion) + 1
                loader.respond(statusCode: 201, body: responseData([
                    "schemaVersion": OwnerTruthInterviewReviewBatchAcknowledgementReceipt
                        .schemaVersion,
                    "vaultId": lease.vaultId,
                    "status": OwnerTruthInterviewReviewBatchAcknowledgementOutcome
                        .acknowledged.rawValue,
                    "session": [
                        "threadId": serverThreadID ?? "",
                        "sessionId": serverSessionID ?? "",
                        "sessionVersion": serverSessionVersion,
                    ],
                    "reviewBatch": [
                        "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased(),
                        "trigger": OwnerTruthInterviewReviewBatchTrigger.sessionExit.rawValue,
                        "state": "acknowledged",
                        "capturedCandidateBatchTurnCount": 1,
                        "rowVersion": 2,
                    ],
                    "candidateProposal": ["status": "notStarted"],
                    "memoryActivation": ["status": "notApplicable"],
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/candidate-proposal/admit") {
                admissionPostCount += 1
                loader.respond(statusCode: 201, body: responseData([
                    "schemaVersion": OwnerTruthInterviewCandidateProposalAdmissionReceipt
                        .schemaVersion,
                    "vaultId": lease.vaultId,
                    "status": OwnerTruthCommandOutcome.created.rawValue,
                    "reviewBatch": [
                        "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased()
                    ],
                    "source": ["status": "admitted", "kind": "conversation", "version": 1],
                    "candidateExtraction": ["status": "requested", "ownerMessageCount": 1],
                    "candidate": ["status": "notCreated"],
                    "memoryActivation": ["status": "notApplicable"],
                ]))
                return
            }
            if method == "GET", path.hasSuffix("/candidate-proposal/status") {
                statusGetCount += 1
                loader.respond(statusCode: 200, body: responseData(
                    self.interviewCandidateProposalStatusPayload(
                        vaultID: lease.vaultId,
                        reviewBatchID: reviewBatchID,
                        candidateExtractionState: .succeeded,
                        candidateReviewState: .reviewReady
                    )
                ))
                return
            }
            XCTFail("Unexpected Live saving request: \(method) \(path)")
            loader.fail(URLError(.badURL))
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }

        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: backend,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: outbox,
            followUpStore: followUp,
            completionCheckpointStore: checkpoint,
            organizationStatusTimeout: 1,
            deliveryStatusTimeout: 0.2,
            liveAuthorityNow: { now },
            naturalInputPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(for: .echoTextInput).allowed
            },
            candidateReviewPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(
                    for: .ownerTruthCandidateReview
                ).allowed
            }
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )
        controller.onCanonicalTranscriptEvent(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "saving-owner-final",
            role: .owner,
            text: "完整的合成用户表达",
            finality: .complete,
            finalityEvidence: .explicitFinal,
            evidenceSource: .resultsIsInterim,
            capturedAt: now
        ))
        controller.onCanonicalTranscriptEvent(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "saving-assistant-final",
            role: .assistant,
            text: "完整的合成助手回答",
            finality: .complete,
            finalityEvidence: .confirmed,
            evidenceSource: .assistantStream,
            capturedAt: now.addingTimeInterval(1)
        ))

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            guard let snapshot = try? outbox.load(
                for: lease,
                productSessionID: productSessionID
            ) else { return false }
            return currentReadCount == 1
                && coordinator.state == .syncPaused
                && snapshot.pendingTurns.count == 2
                && snapshot.unsealedCanonicalTurnCount == 0
        })

        controller.finishLiveMemoryCaptureForTesting()

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
            coordinator.state == .pendingReview
        })
        XCTAssertEqual(
            controller.liveMemoryCapturePresentationForTesting().statusIdentifier,
            "echoLiveMemoryPendingReview"
        )
        XCTAssertEqual(currentReadCount, 2)
        XCTAssertEqual(startPostCount, 1)
        XCTAssertEqual(appendPostCount, 2)
        XCTAssertEqual(endPostCount, 1)
        XCTAssertEqual(acknowledgementPostCount, 1)
        XCTAssertEqual(admissionPostCount, 1)
        XCTAssertEqual(statusGetCount, 1)
    }

    @MainActor
    func testLiveSavingDeadlineReleasesHungCurrentReadAndRejectsLateSuccess() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-saving-hung-current-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "live-saving-hung-current"
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let client = InterviewNaturalInputClientSpy()
        client.deferCurrentSession = true

        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: outbox,
            followUpStore: EchoLiveMemoryFollowUpStore(
                rootDirectory: root.appendingPathComponent("follow-up", isDirectory: true)
            ),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
            ),
            organizationStatusTimeout: 1,
            deliveryStatusTimeout: 0.05,
            closingProgressTimeout: 0.05,
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )
        controller.onCanonicalTranscriptEvent(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "hung-current-owner-final",
            role: .owner,
            text: "截止测试的合成用户表达",
            finality: .complete,
            finalityEvidence: .explicitFinal,
            evidenceSource: .resultsIsInterim,
            capturedAt: Date(timeIntervalSince1970: 1_789_640_100)
        ))

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 1) {
            guard let snapshot = try? outbox.load(
                for: lease,
                productSessionID: productSessionID
            ) else { return false }
            return snapshot.pendingTurns.count == 1
                && snapshot.unsealedCanonicalTurnCount == 0
        })

        controller.finishLiveMemoryCaptureForTesting()

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 1) {
            coordinator.state == .syncPaused
                && controller.liveMemoryCapturePresentationForTesting().statusIdentifier
                    == "echoLiveMemorySyncPaused"
        })
        XCTAssertEqual(
            controller.liveMemoryCapturePresentationForTesting().statusIdentifier,
            "echoLiveMemorySyncPaused"
        )
        XCTAssertTrue(client.startCommands.isEmpty)
        XCTAssertTrue(client.appendCommands.isEmpty)
        XCTAssertTrue(client.endCommands.isEmpty)
        XCTAssertEqual(
            try XCTUnwrap(outbox.load(for: lease, productSessionID: productSessionID))
                .pendingTurns.count,
            1
        )

        client.completeDeferredCurrentSession(.success(
            try emptyInterviewNaturalInputCurrentSession(vaultID: vaultID)
        ))
        RunLoop.main.run(until: Date().addingTimeInterval(0.1))

        XCTAssertEqual(coordinator.state, .syncPaused)
        XCTAssertTrue(client.startCommands.isEmpty)
        XCTAssertTrue(client.appendCommands.isEmpty)
        XCTAssertTrue(client.endCommands.isEmpty)
        XCTAssertEqual(
            try XCTUnwrap(outbox.load(for: lease, productSessionID: productSessionID))
                .pendingTurns.count,
            1
        )
    }

    @MainActor
    func testLiveSavingKeepsTextEntryAvailableWithoutReusingClosingSession() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-saving-text-entry-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "live-saving-text-entry"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let client = InterviewNaturalInputClientSpy()
        client.deferCurrentSession = true
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            closingProgressTimeout: 2,
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let controller = EchoViewController()
        let window = UIWindow(frame: UIScreen.main.bounds)
        window.rootViewController = controller
        window.makeKeyAndVisible()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )
        coordinator.appendCanonicalTurn(NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "owner-saving-text-entry",
            role: .owner,
            text: "保存中打开新文字交互的合成内容",
            finality: .complete,
            finalityEvidence: .explicitFinal,
            evidenceSource: .resultsIsInterim,
            capturedAt: Date(timeIntervalSince1970: 1_700_001_400)
        ))

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            (try? store.load(for: lease, productSessionID: productSessionID))?
                .ownerTurnCount == 1
        })
        controller.finishLiveMemoryCaptureForTesting()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            controller.liveMemoryCapturePresentationForTesting().statusIdentifier
                == "echoLiveMemorySaving"
        })

        controller.enableOwnerTruthTextEntryForTesting()
        controller.tapOwnerTruthTextEntryForTesting()

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            controller.presentedOwnerTruthTextEntryForTesting().title == "文字回响"
        })
        let entry = controller.presentedOwnerTruthTextEntryForTesting()
        XCTAssertEqual(entry.title, "文字回响")
        XCTAssertEqual(entry.textFieldIdentifier, "echoTextQuestionField")
        XCTAssertNotNil(try store.load(for: lease, productSessionID: productSessionID))
        XCTAssertTrue(client.startCommands.isEmpty)
        XCTAssertNil(client.startCommand)
    }

