    @MainActor
    private func runConfiguredCAP15BidirectionalScenario(
        name: String,
        userTurns: [String],
        requiresShortGateReceipt: Bool
    ) throws {
        let environment = ProcessInfo.processInfo.environment
        guard environment["DJ_CAP15_BIDIRECTIONAL_CONFIG_JSON_BASE64"]?.isEmpty != false else {
            XCTFail("CAP15 accepts only the runner-owned disk configuration")
            throw NSError(domain: "DreamJourneyTests.CAP15", code: 1)
        }
        let configData: Data?
        if let configPath = environment["DJ_CAP15_BIDIRECTIONAL_CONFIG"],
           !configPath.isEmpty {
            configData = try? Data(contentsOf: URL(fileURLWithPath: configPath))
        } else { configData = nil }
        guard let configData else {
            throw XCTSkip("DJ_CAP15_BIDIRECTIONAL_CONFIG is not configured")
        }
        let object = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: configData)
                as? [String: Any]
        )
        if requiresShortGateReceipt {
            XCTAssertEqual(
                object["longScenarioName"] as? String,
                name,
                "the configured one-shot gate must target this exact long scenario"
            )
            try consumeCAP15ShortGate(
                config: object,
                baseURL: try XCTUnwrap((object["baseURL"] as? String).flatMap(URL.init(string:))),
                expectedStatusCode: 204
            )
        }
        let baseURL = try XCTUnwrap((object["baseURL"] as? String).flatMap(URL.init(string:)))
        let userID = try XCTUnwrap(object["userID"] as? String)
        let vaultID = try XCTUnwrap(object["vaultID"] as? String)
        let authorityEpoch = try XCTUnwrap(object["authorityEpoch"] as? String)
        let scenarioExpectation = try XCTUnwrap(
            (object["scenarioExpectations"] as? [String: Any])?[name]
                as? [String: Any]
        )
        let configuredLogicalDuration = try XCTUnwrap(
            scenarioExpectation["logicalDurationSeconds"] as? Double
        )
        let logicalStart = Date()
        let formatter = ISO8601DateFormatter()
        var authObject = try XCTUnwrap(object["auth"] as? [String: Any])
        authObject["accessExpiresAt"] = formatter.string(
            from: logicalStart.addingTimeInterval(configuredLogicalDuration + 600)
        )
        var authSession = try XCTUnwrap(BackendAuthSessionContract(json: authObject))
        let tokenFamilyID = try XCTUnwrap(authSession.tokenFamilyId)
        let sessionVersion = try XCTUnwrap(authSession.sessionVersion)
        let generationID = UUID()
        let accountSession = AccountSession(
            subjectId: userID,
            vaultId: vaultID,
            sessionId: authSession.sessionId,
            tokenFamilyId: tokenFamilyID,
            sessionVersion: sessionVersion,
            generation: 1,
            generationId: generationID,
            state: .active,
            activatedAt: Date()
        )
        let runtime = AccountLeaseRuntime(authorityEpoch: authorityEpoch)
        runtime.publish(session: accountSession)
        let lease = try XCTUnwrap(runtime.capture(forSubjectId: userID))
        var logicalNow = logicalStart
        var policyRefreshCount = 0
        var authRefreshCount = 0
        var policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "release-policy-v1",
            policyRevision: 1,
            emergencyRevision: 0,
            expiresAt: logicalNow.addingTimeInterval(300),
            featureEnabled: true,
            releaseVisible: true,
            reason: "isolatedPostgresOwnerAllowed"
        )
        let featureGate = FeatureGateService.makeQATestService(
            accountGeneration: {
                FeatureGateService.accountGeneration(forIdentitySource: authSession.sessionId)
            },
            policy: { _, _ in policy },
            now: { logicalNow }
        )
        featureGate.captureServerPolicyManagedRoute(.echoTextInput, risk: .ownerTextCore)
        featureGate.captureServerPolicyManagedRoute(.ownerTruthCandidateReview)
        let backend = DreamJourneyBackendClient.makeQATestClient(
            baseURL: baseURL,
            session: Session(configuration: .ephemeral),
            authenticatedSession: { authSession },
            currentUserID: { userID },
            privateAccessAllowed: {
                runtime.validate(lease, at: .request).allowed
            },
            featureDecision: {
                featureGate.requestServerPolicyManagedDecision(for: $0)
            },
            freshFeatureDecision: {
                featureGate.freshServerPolicyManagedRequestDecision(for: $0)
            },
            featureDecisionRevalidator: {
                featureGate.revalidateServerPolicyManagedRequest($0)
            },
            authSessionRefresher: { captured, completion in
                authRefreshCount += 1
                print("[CAP15AuthRefresh] stage=entered attempt=\(authRefreshCount)")
                guard captured.matchesCASIdentity(authSession) else {
                    print("[CAP15AuthRefresh] stage=casPreflight result=rejected")
                    completion(nil)
                    return
                }
                var request = URLRequest(url: baseURL.appendingPathComponent("auth/refresh"))
                request.httpMethod = "POST"
                request.setValue("application/json", forHTTPHeaderField: "Content-Type")
                request.httpBody = try? JSONSerialization.data(withJSONObject: [
                    "refreshToken": captured.refreshToken,
                ])
                URLSession(configuration: .ephemeral).dataTask(with: request) {
                    data, response, error in
                    let statusCode = (response as? HTTPURLResponse)?.statusCode
                    let object = data.flatMap {
                        try? JSONSerialization.jsonObject(with: $0) as? [String: Any]
                    }
                    var refreshedObject = object?["auth"] as? [String: Any]
                    refreshedObject?["accessExpiresAt"] = formatter.string(
                        from: logicalStart.addingTimeInterval(configuredLogicalDuration + 600)
                    )
                    let refreshed = refreshedObject.flatMap(BackendAuthSessionContract.init(json:))
                    DispatchQueue.main.async {
                        print(
                            "[CAP15AuthRefresh] stage=response status=\(statusCode ?? -1) "
                                + "decoded=\(refreshed != nil) transportError=\(error != nil)"
                        )
                        guard error == nil,
                              statusCode == 200,
                              captured.matchesCASIdentity(authSession),
                              let refreshed,
                              refreshed.isValidRefreshSuccessor(of: captured) else {
                            print("[CAP15AuthRefresh] stage=successorValidation result=rejected")
                            completion(nil)
                            return
                        }
                        authSession = refreshed
                        print("[CAP15AuthRefresh] stage=casCommit result=accepted")
                        completion(refreshed)
                    }
                }.resume()
            },
            accountLeaseRuntime: runtime
        )

        try runCAP15BidirectionalScenario(
            name: name,
            userTurns: userTurns,
            scenarioExpectation: scenarioExpectation,
            lease: lease,
            runtime: runtime,
            backend: backend,
            featureGate: featureGate,
            baseURL: baseURL,
            logicalStart: logicalStart,
            logicalNow: { logicalNow },
            advanceLogicalClock: { logicalNow = $0 },
            policyRefreshCount: { policyRefreshCount },
            authRefreshCount: { authRefreshCount },
            refreshPolicy: { completion in
                policyRefreshCount += 1
                policy = FeatureGatePolicySnapshot(
                    accessMode: .useCachedPolicy,
                    policyVersion: "release-policy-v1",
                    policyRevision: 1,
                    emergencyRevision: 0,
                    expiresAt: logicalNow.addingTimeInterval(300),
                    featureEnabled: true,
                    releaseVisible: true,
                    reason: "isolatedPostgresOwnerAllowed"
                )
                featureGate.invalidateCapturedRoutes()
                featureGate.captureServerPolicyManagedRoute(.echoTextInput, risk: .ownerTextCore)
                featureGate.captureServerPolicyManagedRoute(.ownerTruthCandidateReview)
                completion(true)
            }
        )
        if requiresShortGateReceipt {
            try consumeCAP15ShortGate(
                config: object,
                baseURL: baseURL,
                expectedStatusCode: 409
            )
        }
    }

    @MainActor
    private func cap15CanonicalDeliveryBindings(
        root: URL,
        productSessionID: String
    ) throws -> [String: (
        messageID: String,
        captureOrdinal: Int,
        ingressOrdinal: Int,
        handledIngressOrdinals: [Int],
        handledHandoffIDs: [String]
    )] {
        guard let enumerator = FileManager.default.enumerator(
            at: root,
            includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles]
        ) else {
            XCTFail("CAP15 outbox directory is unavailable")
            return [:]
        }
        for case let url as URL in enumerator where url.pathExtension == "json" {
            guard let data = try? Data(contentsOf: url),
                  let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                  object["productSessionID"] as? String == productSessionID,
                  let turns = object["canonicalTurns"] as? [[String: Any]],
                  let members = object["canonicalMembers"] as? [[String: Any]] else {
                continue
            }
            let memberBindings = Dictionary(uniqueKeysWithValues: members.compactMap {
                member -> (String, (ingressOrdinal: Int, handledIngressOrdinals: [Int]))? in
                guard let canonicalTurnID = member["canonicalTurnID"] as? String,
                      let ingressOrdinal = member["ingressOrdinal"] as? Int else {
                    return nil
                }
                let handled = (member["handledIngressOrdinals"] as? [Int]) ?? [ingressOrdinal]
                return (canonicalTurnID, (ingressOrdinal, handled))
            })
            let handledHandoffs = (object["handledCanonicalHandoffs"] as? [[String: Any]]) ?? []
            let handoffIDsByCanonicalID = Dictionary(grouping: handledHandoffs) {
                String(describing: $0["canonicalTurnID"] ?? "")
            }.mapValues { handoffs in
                handoffs.compactMap { $0["handoffID"] as? String }.sorted()
            }
            var bindings: [String: (
                messageID: String,
                captureOrdinal: Int,
                ingressOrdinal: Int,
                handledIngressOrdinals: [Int],
                handledHandoffIDs: [String]
            )] = [:]
            for turn in turns {
                guard let canonicalTurnID = turn["canonicalTurnID"] as? String,
                      let messageID = turn["deliveryMessageID"] as? String,
                      let captureOrdinal = turn["captureOrdinal"] as? Int,
                      let member = memberBindings[canonicalTurnID] else {
                    continue
                }
                bindings[canonicalTurnID] = (
                    messageID.lowercased(),
                    captureOrdinal,
                    member.ingressOrdinal,
                    member.handledIngressOrdinals,
                    handoffIDsByCanonicalID[canonicalTurnID] ?? []
                )
            }
            return bindings
        }
        XCTFail("CAP15 canonical delivery bindings are unavailable")
        return [:]
    }

    @MainActor
    private func runCAP15BidirectionalScenario(
        name: String,
        userTurns: [String],
        scenarioExpectation: [String: Any],
        lease: AccountLease,
        runtime: AccountLeaseRuntime,
        backend: DreamJourneyBackendClient,
        featureGate: FeatureGateService,
        baseURL: URL,
        logicalStart: Date,
        logicalNow: @escaping () -> Date,
        advanceLogicalClock: (Date) -> Void,
        policyRefreshCount: @escaping () -> Int,
        authRefreshCount: @escaping () -> Int,
        refreshPolicy: @escaping (@escaping (Bool) -> Void) -> Void
    ) throws {
        let root = FileManager.default.temporaryDirectory.appendingPathComponent(
            "cap15-bidirectional-\(name)-\(UUID().uuidString)",
            isDirectory: true
        )
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "cap15-bidirectional-\(name)-\(UUID().uuidString.lowercased())"
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let followUp = EchoLiveMemoryFollowUpStore(
            rootDirectory: root.appendingPathComponent("follow-up", isDirectory: true)
        )
        let checkpoint = EchoLiveMemoryCompletionCheckpointStore(
            rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
        )
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: backend,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: outbox,
            followUpStore: followUp,
            completionCheckpointStore: checkpoint,
            organizationStatusTimeout: 20,
            deliveryStatusTimeout: 5,
            liveAuthorityNow: logicalNow,
            naturalInputPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(for: .echoTextInput).allowed
            },
            naturalInputPolicyRefresh: refreshPolicy,
            candidateReviewPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(
                    for: .ownerTruthCandidateReview
                ).allowed
            },
            candidateReviewPolicyRefresh: refreshPolicy
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )
        let manager = DialogEngineManager.shared
        let generation = UUID()
        let operationID = UUID()
        let logicalDuration = try XCTUnwrap(
            scenarioExpectation["logicalDurationSeconds"] as? Double
        )
        let logicalStep = logicalDuration / Double(max(userTurns.count, 1))
        var clientLedger: [[String: Any]] = []
        manager.installCanonicalIngressForTesting(
            engineGeneration: generation,
            dialogOperationID: operationID,
            delegate: controller
        )
        defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operationID) }

        for (offset, text) in userTurns.enumerated() {
            let ordinal = offset + 1
            let questionID = "cap15-\(name)-question-\(ordinal)"
            let replyID = "cap15-\(name)-reply-\(ordinal)"
            let now = logicalStart.addingTimeInterval(logicalStep * Double(offset))
            advanceLogicalClock(now)
            let ownerIngress = try XCTUnwrap(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrInfo,
                data: try JSONSerialization.data(withJSONObject: ["question_id": questionID]),
                engineGeneration: generation,
                capturedAt: now
            ))
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrResponse,
                data: try JSONSerialization.data(withJSONObject: [
                    "results": [["text": text, "is_interim": false]],
                ]),
                engineGeneration: generation,
                capturedAt: now.addingTimeInterval(0.1)
            ))
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrEnded,
                data: try JSONSerialization.data(withJSONObject: ["question_id": questionID]),
                engineGeneration: generation,
                capturedAt: now.addingTimeInterval(0.2)
            ))
            XCTAssertNotNil(manager.enqueueCanonicalRawProviderMessageForTesting(
                rawEventCode: DialogProviderSDKEventClassifier.chatResponse,
                data: try JSONSerialization.data(withJSONObject: [
                    "reply_id": replyID,
                    "delta": "已收到第 \(ordinal) 条合成信息。",
                ]),
                engineGeneration: generation,
                capturedAt: now.addingTimeInterval(0.3)
            ))
            let assistantFinal = try XCTUnwrap(manager.enqueueCanonicalRawProviderMessageForTesting(
                rawEventCode: DialogProviderSDKEventClassifier.chatEnded,
                data: try JSONSerialization.data(withJSONObject: ["reply_id": replyID]),
                engineGeneration: generation,
                capturedAt: now.addingTimeInterval(0.4)
            ))
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 10) {
                (try? outbox.load(for: lease, productSessionID: productSessionID))?
                    .lastClientSequenceNumber == ordinal * 2
            })
            let persisted = try XCTUnwrap(
                outbox.load(for: lease, productSessionID: productSessionID)
            )
            let turnDeliveries = persisted.pendingTurns.filter {
                ((ordinal * 2 - 1)...(ordinal * 2)).contains($0.clientSequenceNumber)
            }.sorted { $0.clientSequenceNumber < $1.clientSequenceNumber }
            XCTAssertEqual(turnDeliveries.count, 2)
            let rawHandoffs: [(UInt64, NativeLiveCanonicalTranscriptMember)] = [
                (ownerIngress.callbackOrdinal, try XCTUnwrap(ownerIngress.member)),
                (assistantFinal.callbackOrdinal, try XCTUnwrap(assistantFinal.member)),
            ]
            let diskBindings = try cap15CanonicalDeliveryBindings(
                root: root,
                productSessionID: productSessionID
            )
            for (callbackOrdinal, member) in rawHandoffs {
                let binding = try XCTUnwrap(diskBindings[member.canonicalTurnID])
                let delivery = try XCTUnwrap(turnDeliveries.first {
                    $0.messageID.rawValue.uuidString.lowercased() == binding.messageID
                })
                let bodyDigest = SHA256.hash(data: Data(delivery.text.utf8)).map {
                    String(format: "%02x", $0)
                }.joined()
                clientLedger.append([
                    "rawCallbackOrdinal": Int(callbackOrdinal),
                    "rawCanonicalTurnID": member.canonicalTurnID,
                    "rawHandoffID": member.handoffID,
                    "rawIngressOrdinal": Int(member.ingressOrdinal),
                    "diskCanonicalTurnID": member.canonicalTurnID,
                    "diskCanonicalCaptureOrdinal": binding.captureOrdinal,
                    "diskCanonicalIngressOrdinal": binding.ingressOrdinal,
                    "diskHandledIngressOrdinals": binding.handledIngressOrdinals,
                    "diskHandledHandoffIDs": binding.handledHandoffIDs,
                    "diskCommandID": delivery.commandID,
                    "diskMessageID": delivery.messageID.rawValue.uuidString.lowercased(),
                    "diskSequence": delivery.clientSequenceNumber,
                    "role": delivery.role.rawValue,
                    "bodyDigest": bodyDigest,
                ])
            }
            _ = try cap15ControlRequest(
                baseURL: baseURL,
                path: "/__cap15/scenarios/\(name)/client-ledger",
                method: "POST",
                payload: [
                    "entries": clientLedger,
                    "logicalDurationSeconds": logicalDuration,
                    "logicalStart": logicalStart.timeIntervalSince1970,
                    "logicalEnd": logicalNow().timeIntervalSince1970,
                    "policyRefreshCount": policyRefreshCount(),
                    "authRefreshCount": authRefreshCount(),
                ],
                expectedStatusCode: 204
            )
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 15) {
                (try? outbox.load(for: lease, productSessionID: productSessionID))?
                    .canonicalCoverageSummary.serverConfirmedCount == ordinal * 2
            }, "round \(ordinal) must complete disk-to-HTTP confirmation before logical time advances")
        }

        advanceLogicalClock(logicalStart.addingTimeInterval(logicalDuration))
        _ = try cap15ControlRequest(
            baseURL: baseURL,
            path: "/__cap15/scenarios/\(name)/client-ledger",
            method: "POST",
            payload: [
                "entries": clientLedger,
                "logicalDurationSeconds": logicalDuration,
                "logicalStart": logicalStart.timeIntervalSince1970,
                "logicalEnd": logicalNow().timeIntervalSince1970,
                "policyRefreshCount": policyRefreshCount(),
                "authRefreshCount": authRefreshCount(),
            ],
            expectedStatusCode: 204
        )

        let snapshot = try XCTUnwrap(
            outbox.load(for: lease, productSessionID: productSessionID)
        )
        XCTAssertEqual(snapshot.ownerTurnCount, userTurns.count)
        XCTAssertEqual(snapshot.lastClientSequenceNumber, userTurns.count * 2)
        XCTAssertEqual(snapshot.canonicalConflictCount, 0)
        XCTAssertEqual(snapshot.unsealedCanonicalTurnCount, 0)

        controller.finishLiveMemoryCaptureForTesting()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 60) {
            coordinator.state == .pendingReview
        })
        XCTAssertNil(
            try outbox.load(for: lease, productSessionID: productSessionID),
            "a completed handoff must release the durable outbox only after pendingReview"
        )
        if userTurns.count == 2 {
            try assertCAP15PostgresColdStartRejectsForeignStart(
                originalStart: try XCTUnwrap(snapshot.preparedStartCommand),
                productSessionID: productSessionID,
                root: root.appendingPathComponent("cold-start-negative", isDirectory: true),
                lease: lease,
                runtime: runtime,
                backend: backend,
                featureGate: featureGate,
                baseURL: baseURL
            )
        }
        try assertCAP15CandidateInboxVisible(
            name: name,
            expectation: scenarioExpectation,
            lease: lease,
            runtime: runtime,
            backend: backend,
            featureGate: featureGate,
            baseURL: baseURL
        )
    }

    @MainActor
    private func assertCAP15PostgresColdStartRejectsForeignStart(
        originalStart: OwnerTruthInterviewNaturalInputStartCommand,
        productSessionID: String,
        root: URL,
        lease: AccountLease,
        runtime: AccountLeaseRuntime,
        backend: DreamJourneyBackendClient,
        featureGate: FeatureGateService,
        baseURL: URL
    ) throws {
        let variants: [(name: String, command: OwnerTruthInterviewNaturalInputStartCommand,
                        requiresBindingBlock: Bool)] = [
            (
                "wrong-command",
                try OwnerTruthInterviewNaturalInputStartCommand(
                    commandID: originalStart.commandID + "-foreign",
                    threadID: originalStart.threadID,
                    sessionID: originalStart.sessionID,
                    entryMode: .live, productSessionID: productSessionID
                ),
                true
            ),
            (
                "wrong-thread",
                try OwnerTruthInterviewNaturalInputStartCommand(
                    commandID: originalStart.commandID,
                    threadID: recordID("00000000-0000-0000-0000-0000000007ef"),
                    sessionID: originalStart.sessionID,
                    entryMode: .live, productSessionID: productSessionID
                ),
                true
            ),
            (
                "wrong-session",
                try OwnerTruthInterviewNaturalInputStartCommand(
                    commandID: originalStart.commandID,
                    threadID: originalStart.threadID,
                    sessionID: recordID("00000000-0000-0000-0000-0000000007f0"),
                    entryMode: .live, productSessionID: productSessionID
                ),
                false
            ),
        ]
        for variant in variants {
            let countsBefore = try cap15ControlRequest(
                baseURL: baseURL, path: "/__cap15/request-counts",
                method: "GET", payload: nil, expectedStatusCode: 200
            )
            let caseRoot = root.appendingPathComponent(variant.name)
            let foreignOutbox = OwnerTruthInterviewLiveTurnOutboxStore(
                rootDirectory: caseRoot.appendingPathComponent("outbox")
            )
            _ = try foreignOutbox.prepareStart(
                variant.command, for: lease, productSessionID: productSessionID
            )
            let queued = try foreignOutbox.enqueue(
                role: .owner, text: "Synthetic negative binding evidence.",
                for: lease, productSessionID: productSessionID
            )
            _ = try foreignOutbox.markClosing(
                lastClientSequenceNumber: queued.lastClientSequenceNumber,
                for: lease, productSessionID: productSessionID
            )
            let recovered = EchoLiveMemoryRecoveryService(
                registry: EchoLiveMemoryRecoveryRegistry()
            ).resumePendingWorkflows(
                accountLease: lease, excluding: [], client: backend,
                accountLeaseRuntime: runtime,
                liveTurnOutboxStore: foreignOutbox,
                followUpStore: EchoLiveMemoryFollowUpStore(
                    rootDirectory: caseRoot.appendingPathComponent("follow-up")
                ),
                completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                    rootDirectory: caseRoot.appendingPathComponent("completion")
                ),
                naturalInputPolicyAvailable: {
                    featureGate.requestServerPolicyManagedDecision(for: .echoTextInput).allowed
                },
                candidateReviewPolicyAvailable: {
                    featureGate.requestServerPolicyManagedDecision(
                        for: .ownerTruthCandidateReview
                    ).allowed
                }
            )
            let coordinator = try XCTUnwrap(recovered.coordinators.first)
            let controller = EchoViewController()
            controller.installLiveMemoryRecoveryForTesting(
                accountLease: lease, coordinator: coordinator
            )
            if variant.requiresBindingBlock {
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 15) {
                    coordinator.state == .contractBlocked(.bindingMismatch)
                }, "\(variant.name): unexpected PostgreSQL state \(coordinator.state)")
            } else {
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 15) {
                    if case .statusUnknown = coordinator.state { return true }
                    if case .contractBlocked = coordinator.state { return true }
                    return false
                }, "\(variant.name): unexpected PostgreSQL state \(coordinator.state)")
            }
            // Stop this test page's future policy callbacks before counting the next case.
            // Keep its already-issued real GET alive until the callback completes.
            controller.detachLiveMemoryRecoveryForTesting()
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 15) {
                !coordinator.hasActiveReadForTesting
            }, "\(variant.name): in-flight recovery GET did not complete before case teardown")
            coordinator.suspend()
            let countsAfter = try cap15ControlRequest(
                baseURL: baseURL, path: "/__cap15/request-counts",
                method: "GET", payload: nil, expectedStatusCode: 200
            )
            let readDelta = (countsAfter["deliveryStatusReadCount"] as? Int ?? -1)
                - (countsBefore["deliveryStatusReadCount"] as? Int ?? -1)
            XCTAssertGreaterThanOrEqual(readDelta, 1, "\(variant.name): cold-start read count")
            XCTAssertLessThanOrEqual(readDelta, 2, "\(variant.name): cold-start read count")
            let writeDelta = (countsAfter["businessWriteCount"] as? Int ?? -1)
                - (countsBefore["businessWriteCount"] as? Int ?? -1)
            print("[CAP15ColdStartCase] variant=\(variant.name) deliveryGETs=\(readDelta) "
                + "businessWrites=\(writeDelta)")
            XCTAssertEqual(
                countsAfter["businessWriteCount"] as? Int,
                countsBefore["businessWriteCount"] as? Int,
                "\(variant.name): cold-start verification must not write"
            )
            XCTAssertEqual(
                try foreignOutbox.load(for: lease, productSessionID: productSessionID)?
                    .preparedStartCommand,
                variant.command
            )
        }

        let staleRoot = root.appendingPathComponent("stale-account")
        let (staleRuntime, staleLease) = try makeActiveRuntime()
        let staleOutbox = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: staleRoot.appendingPathComponent("outbox")
        )
        _ = try staleOutbox.prepareStart(
            originalStart, for: staleLease, productSessionID: productSessionID
        )
        let staleTurn = try staleOutbox.enqueue(
            role: .owner, text: "Synthetic stale-account evidence.",
            for: staleLease, productSessionID: productSessionID
        )
        _ = try staleOutbox.markClosing(
            lastClientSequenceNumber: staleTurn.lastClientSequenceNumber, for: staleLease,
            productSessionID: productSessionID
        )
        let staleCountsBefore = try cap15ControlRequest(
            baseURL: baseURL, path: "/__cap15/request-counts",
            method: "GET", payload: nil, expectedStatusCode: 200
        )
        staleRuntime.publish(session: accountSession(
            subjectId: "foreign-owner", vaultId: "foreign-vault", generation: 2,
            generationID: UUID()
        ))
        let staleRecovery = EchoLiveMemoryRecoveryService(
            registry: EchoLiveMemoryRecoveryRegistry()
        ).resumePendingWorkflows(
            accountLease: staleLease, excluding: [], client: backend,
            accountLeaseRuntime: staleRuntime,
            liveTurnOutboxStore: staleOutbox,
            followUpStore: EchoLiveMemoryFollowUpStore(
                rootDirectory: staleRoot.appendingPathComponent("follow-up")
            ),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: staleRoot.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(for: .echoTextInput).allowed
            },
            candidateReviewPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(
                    for: .ownerTruthCandidateReview
                ).allowed
            }
        )
        XCTAssertTrue(staleRecovery.coordinators.isEmpty)
        let staleCountsAfter = try cap15ControlRequest(
            baseURL: baseURL, path: "/__cap15/request-counts",
            method: "GET", payload: nil, expectedStatusCode: 200
        )
        XCTAssertEqual(staleCountsAfter["deliveryStatusReadCount"] as? Int,
                       staleCountsBefore["deliveryStatusReadCount"] as? Int)
        XCTAssertEqual(staleCountsAfter["businessWriteCount"] as? Int,
                       staleCountsBefore["businessWriteCount"] as? Int)
        XCTAssertEqual(
            try staleOutbox.load(for: staleLease, productSessionID: productSessionID)?
                .preparedStartCommand,
            originalStart
        )

        let corruptRoot = root.appendingPathComponent("corrupt-follow-up")
        let corruptStore = EchoLiveMemoryFollowUpStore(rootDirectory: corruptRoot)
        let corruptURL = corruptStore.durableFileURLForTesting(for: lease)
        try FileManager.default.createDirectory(
            at: corruptURL.deletingLastPathComponent(), withIntermediateDirectories: true
        )
        let corruptBytes = Data("{".utf8)
        try corruptBytes.write(to: corruptURL, options: .atomic)
        let corruptCountsBefore = try cap15ControlRequest(
            baseURL: baseURL, path: "/__cap15/request-counts",
            method: "GET", payload: nil, expectedStatusCode: 200
        )
        let corruptRecovery = EchoLiveMemoryRecoveryService(
            registry: EchoLiveMemoryRecoveryRegistry()
        ).resumePendingWorkflows(
            accountLease: lease, excluding: [], client: backend,
            accountLeaseRuntime: runtime,
            liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(
                rootDirectory: corruptRoot.appendingPathComponent("outbox")
            ),
            followUpStore: corruptStore,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: corruptRoot.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(for: .echoTextInput).allowed
            },
            candidateReviewPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(
                    for: .ownerTruthCandidateReview
                ).allowed
            }
        )
        XCTAssertTrue(corruptRecovery.coordinators.isEmpty)
        XCTAssertEqual(corruptRecovery.blockedRecords.first?.reason,
                       .followUpDecodeInvalid)
        let corruptCountsAfter = try cap15ControlRequest(
            baseURL: baseURL, path: "/__cap15/request-counts",
            method: "GET", payload: nil, expectedStatusCode: 200
        )
        XCTAssertEqual(corruptCountsAfter["deliveryStatusReadCount"] as? Int,
                       corruptCountsBefore["deliveryStatusReadCount"] as? Int)
        XCTAssertEqual(corruptCountsAfter["businessWriteCount"] as? Int,
                       corruptCountsBefore["businessWriteCount"] as? Int)
        XCTAssertEqual(try Data(contentsOf: corruptURL), corruptBytes)
    }

    @MainActor
    private func assertCAP15CandidateInboxVisible(
        name: String,
        expectation: [String: Any],
        lease: AccountLease,
        runtime: AccountLeaseRuntime,
        backend: DreamJourneyBackendClient,
        featureGate: FeatureGateService,
        baseURL: URL
    ) throws {
        let sourceObject = try cap15ControlRequest(
            baseURL: baseURL,
            path: "/__cap15/scenarios/\(name)/source",
            method: "GET",
            payload: nil,
            expectedStatusCode: 200
        )
        let sourceID = try XCTUnwrap(
            (sourceObject["sourceId"] as? String)
                .flatMap(UUID.init(uuidString:))
                .map(OwnerTruthRecordID.init(rawValue:))
        )
        let expectedCount = try XCTUnwrap(expectation["candidateCount"] as? Int)
        let requiredFragments = try XCTUnwrap(
            expectation["requiredCandidateFragments"] as? [String]
        )
        let forbiddenFragments = expectation["forbiddenCandidateFragments"] as? [String] ?? []
        func loadState() throws -> OwnerTruthCandidateInboxViewState {
            let controller = OwnerTruthCandidateInboxViewController(
                accountLease: lease,
                client: backend,
                accountLeaseRuntime: runtime,
                qaGateEnabled: {
                    featureGate.requestServerPolicyManagedDecision(
                        for: .ownerTruthCandidateReview
                    ).allowed
                },
                sourceIDFilter: sourceID,
                pendingResultStore: OwnerTruthCandidateReviewTransientPendingResultStore()
            )
            var rendered: OwnerTruthCandidateInboxViewState?
            controller.onViewStateRendered = { state in
                if state.phase == .ready || state.phase == .empty { rendered = state }
            }
            let window = UIWindow(frame: UIScreen.main.bounds)
            window.rootViewController = controller
            window.makeKeyAndVisible()
            controller.loadViewIfNeeded()
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 20) { rendered != nil })
            return try XCTUnwrap(rendered)
        }
        func validate(_ state: OwnerTruthCandidateInboxViewState) throws {
            guard state.items.count == expectedCount else {
                throw NSError(domain: "DreamJourneyTests.CAP15CandidateCount", code: state.items.count)
            }
            let renderedText = state.items.map(\.primaryValue).joined(separator: "\n")
            guard requiredFragments.allSatisfy(renderedText.contains),
                  forbiddenFragments.allSatisfy({ !renderedText.contains($0) }),
                  state.items.allSatisfy({
                      !$0.primaryValue.isEmpty
                          && !$0.proposalPreview.isEmpty
                          && $0.evidenceCount > 0
                          && !$0.sourceReferences.isEmpty
                  }) else {
                throw NSError(domain: "DreamJourneyTests.CAP15CandidateBody", code: 1)
            }
        }
        try validate(loadState())
        _ = try cap15ControlRequest(
            baseURL: baseURL,
            path: "/__cap15/scenarios/\(name)/candidate-visibility",
            method: "POST",
            payload: [
                "sourceId": sourceID.rawValue.uuidString.lowercased(),
                "hidden": true,
            ],
            expectedStatusCode: 204
        )
        XCTAssertThrowsError(try validate(loadState()))
        _ = try cap15ControlRequest(
            baseURL: baseURL,
            path: "/__cap15/scenarios/\(name)/candidate-visibility",
            method: "POST",
            payload: ["hidden": false],
            expectedStatusCode: 204
        )
        try validate(loadState())
        _ = try cap15ControlRequest(
            baseURL: baseURL,
            path: "/__cap15/scenarios/\(name)/client-validation-complete",
            method: "POST",
            payload: [:],
            expectedStatusCode: 204
        )
    }

    private func consumeCAP15ShortGate(
        config: [String: Any],
        baseURL: URL,
        expectedStatusCode: Int
    ) throws {
        _ = try cap15ControlRequest(
            baseURL: baseURL,
            path: "/__cap15/gate/consume",
            method: "POST",
            payload: [
                "gateRunID": try XCTUnwrap(config["gateRunID"] as? String),
                "longAttemptID": try XCTUnwrap(config["longAttemptID"] as? String),
                "sourceFingerprint": try XCTUnwrap(config["sourceFingerprint"] as? String),
                "configFingerprint": try XCTUnwrap(config["configFingerprint"] as? String),
                "buildFingerprint": try XCTUnwrap(config["buildFingerprint"] as? String),
            ],
            expectedStatusCode: expectedStatusCode
        )
    }

    private func cap15ControlRequest(
        baseURL: URL,
        path: String,
        method: String,
        payload: [String: Any]?,
        expectedStatusCode: Int
    ) throws -> [String: Any] {
        var request = URLRequest(url: baseURL.appendingPathComponent(path))
        request.httpMethod = method
        request.timeoutInterval = 90
        if let payload {
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.httpBody = try JSONSerialization.data(withJSONObject: payload)
        }
        var responseStatus: Int?
        var responseData = Data()
        var responseError: Error?
        var completed = false
        URLSession(configuration: .ephemeral).dataTask(with: request) { data, response, error in
            responseStatus = (response as? HTTPURLResponse)?.statusCode
            responseData = data ?? Data()
            responseError = error
            completed = true
        }.resume()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 90) { completed })
        if let responseError { throw responseError }
        XCTAssertEqual(responseStatus, expectedStatusCode)
        guard responseStatus == expectedStatusCode else {
            throw NSError(
                domain: "DreamJourneyTests.CAP15Control",
                code: responseStatus ?? -1,
                userInfo: [NSLocalizedDescriptionKey: "unexpected control response"]
            )
        }
        guard !responseData.isEmpty else { return [:] }
        return try XCTUnwrap(
            try JSONSerialization.jsonObject(with: responseData) as? [String: Any]
        )
    }

    @MainActor
    private func runManagerEchoRealGateBackendLogicalTwentyMinutes(
        questionCount: Int,
        logicalDuration: TimeInterval = 20 * 60,
        authenticationRejectionSequence: Int?,
        deferAuthenticationRecoveryUntilAfterCapture: Bool = false,
        forceUnusableRecoveryCredential: Bool = false,
        emitCAP15Bridge: Bool = false
    ) throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("manager-real-backend-twenty-minute-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "manager-real-backend-twenty-minute"
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let followUp = EchoLiveMemoryFollowUpStore(
            rootDirectory: root.appendingPathComponent("follow-up", isDirectory: true)
        )
        let checkpoint = EchoLiveMemoryCompletionCheckpointStore(
            rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
        )
        var fakeNow = Date()
        let logicalStart = fakeNow
        let logicalStep = logicalDuration / Double(questionCount)
        let authenticationLifetime = questionCount == 35 ? 240 : 600
        var policyRevision = 1
        var policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "live-integrated-v1",
            policyRevision: policyRevision,
            emergencyRevision: 0,
            expiresAt: fakeNow.addingTimeInterval(300),
            featureEnabled: true,
            releaseVisible: true,
            reason: "liveIntegratedAllowed"
        )
        let tokenFamilyID = "live-integrated-auth-family"
        var authSessions: [BackendAuthSessionContract] = []
        var parentSessionID: String?
        for index in 0..<6 {
            let session = try makeOwnerTruthHTTPTestAuthSession(
                userID: lease.subjectId,
                sessionID: "live-integrated-auth-session-\(index + 1)",
                parentSessionID: parentSessionID,
                tokenFamilyID: tokenFamilyID,
                sessionVersion: index + 1,
                accessTokenSuffix: "generation-\(index + 1)",
                accessExpiresAt: logicalStart.addingTimeInterval(
                    TimeInterval(authenticationLifetime * (index + 1))
                )
            )
            authSessions.append(session)
            parentSessionID = session.sessionId
        }
        var authSession = try XCTUnwrap(authSessions.first)
        var authRefreshCount = 0
        var failedRecoveryCredentialIssued = false
        var didReleaseDeliveryStatusForRecovery = false
        var liveReadPolicyRefresh: ((@escaping (Result<Void, Error>) -> Void) -> Void)!
        let featureGate = FeatureGateService.makeQATestService(
            accountGeneration: {
                FeatureGateService.accountGeneration(forIdentitySource: authSession.sessionId)
            },
            policy: { _, _ in policy },
            now: { fakeNow }
        )
        featureGate.captureServerPolicyManagedRoute(.echoTextInput, risk: .ownerTextCore)

        var diagnostics: [OwnerTruthCandidateInboxDiagnosticEvent] = []
        let backend = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: {
                featureGate.requestServerPolicyManagedDecision(for: $0)
            },
            freshFeatureDecision: {
                featureGate.freshServerPolicyManagedRequestDecision(for: $0)
            },
            featureDecisionRevalidator: {
                featureGate.revalidateServerPolicyManagedRequest($0)
            },
            authSessionRefresher: { captured, completion in
                guard captured.matchesCASIdentity(authSession),
                      authRefreshCount < 12 else {
                    completion(nil)
                    return
                }
                authRefreshCount += 1
                let failThisRecovery = forceUnusableRecoveryCredential
                    && !failedRecoveryCredentialIssued
                    && didReleaseDeliveryStatusForRecovery
                    && fakeNow.timeIntervalSince(logicalStart) >= 1_199
                if failThisRecovery { failedRecoveryCredentialIssued = true }
                authSession = try! self.makeOwnerTruthHTTPTestAuthSession(
                    userID: lease.subjectId,
                    sessionID: "live-integrated-auth-session-\(authRefreshCount + 1)",
                    parentSessionID: captured.sessionId,
                    tokenFamilyID: tokenFamilyID,
                    sessionVersion: authRefreshCount + 1,
                    accessTokenSuffix: "generation-\(authRefreshCount + 1)",
                    accessExpiresAt: fakeNow.addingTimeInterval(
                        failThisRecovery ? -1 : TimeInterval(authenticationLifetime)
                    )
                )
                completion(authSession)
            },
            accountLeaseRuntime: runtime,
            candidateInboxDiagnosticSink: { diagnostics.append($0) },
            liveReadPolicyRefresher: { completion in
                liveReadPolicyRefresh(completion)
            }
        )

        let reviewBatchID = recordID("00000000-0000-0000-0000-0000000009f1")
        var serverThreadID: String?
        var serverSessionID: String?
        var serverThreadVersion = 1
        var serverSessionVersion = 1
        var committedAppendPayloads: [[String: Any]] = []
        var authenticationSequenceDidFail = false
        var committedCountAtAuthenticationRejection: Int?
        var deferredDeliveryStatusResponse: (() -> Void)?
        var didHoldDeliveryStatusOnce = false

        func requestPayload() -> [String: Any] {
            guard let optionalBody = OwnerTruthReviewReadyHTTPURLProtocol
                    .recordedRequestBodies.last,
                  let body = optionalBody,
                  let object = try? JSONSerialization.jsonObject(with: body)
                    as? [String: Any] else {
                return [:]
            }
            return object
        }

        func responseData(_ object: [String: Any]) -> Data {
            try! JSONSerialization.data(withJSONObject: object)
        }

        func naturalInputReceipt(
            payload: [String: Any],
            lifecycle: String,
            includeMessage: Bool,
            closeWatermark: Int? = nil
        ) -> Data {
            var receipt: [String: Any] = [
                "status": OwnerTruthCommandOutcome.created.rawValue,
                "threadId": payload["threadId"] as? String ?? serverThreadID ?? "",
                "sessionId": serverSessionID ?? payload["sessionId"] as? String ?? "",
                "threadVersion": serverThreadVersion,
                "sessionVersion": serverSessionVersion,
                "state": lifecycle,
                "boundary": OwnerTruthInterviewSessionBoundary.open.rawValue,
                "authorityEpoch": 0,
            ]
            if includeMessage {
                receipt["messageId"] = payload["messageId"]
                receipt["messageSequence"] = payload["clientSequenceNumber"]
                receipt["clientSequenceNumber"] = payload["clientSequenceNumber"]
                receipt["continuousClientSequence"] = payload["clientSequenceNumber"]
                receipt["deliveryState"] =
                    OwnerTruthInterviewNaturalInputDeliveryState.contiguous.rawValue
            }
            if let closeWatermark {
                receipt["continuousClientSequence"] = closeWatermark
                receipt["deliveryState"] = OwnerTruthInterviewNaturalInputDeliveryState
                    .closedAfterContiguousDelivery.rawValue
            }
            return responseData([
                "schemaVersion": OwnerTruthInterviewNaturalInputReceipt.schemaVersion,
                "vaultId": lease.vaultId,
                "receipt": receipt,
            ])
        }

        func deliveryStatusData(fromSequence: Int) -> Data {
            let payloads = committedAppendPayloads.filter {
                ($0["clientSequenceNumber"] as? Int ?? 0) >= fromSequence
            }
            let deliveries: [[String: Any]] = payloads.map { payload in
                let commandID = payload["commandId"] as? String ?? ""
                let capturedAt = payload["capturedAt"] as? String ?? ""
                let content: [String: Any] = [
                    "captureMode": OwnerTruthInterviewNaturalInputCaptureMode.live.rawValue,
                    "capturedAt": capturedAt,
                    "schemaVersion": "owner-truth-conversation-v1",
                    "text": payload["text"] as? String ?? "",
                ]
                let contentData = try! JSONSerialization.data(
                    withJSONObject: content,
                    options: [.sortedKeys]
                )
                return [
                    "messageId": payload["messageId"] as? String ?? "",
                    "commandIdHash": SHA256.hash(data: Data(commandID.utf8)).map {
                        String(format: "%02x", $0)
                    }.joined(),
                    "clientSequenceNumber": payload["clientSequenceNumber"] as? Int ?? 0,
                    "author": payload["role"] as? String
                        ?? OwnerTruthInterviewNaturalInputMessageRole.owner.rawValue,
                    "capturedAt": capturedAt,
                    "contentHash": SHA256.hash(data: contentData).map {
                        String(format: "%02x", $0)
                    }.joined(),
                ]
            }
            let continuous = committedAppendPayloads.compactMap {
                $0["clientSequenceNumber"] as? Int
            }.max() ?? 0
            let missing = committedAppendPayloads.contains {
                $0["clientSequenceNumber"] as? Int == fromSequence
            } ? [] : [fromSequence]
            return responseData([
                "schemaVersion": OwnerTruthLiveDeliveryStatus.schemaVersion,
                "vaultId": lease.vaultId,
                "productSessionId": productSessionID,
                "session": [
                    "threadId": serverThreadID ?? "",
                    "sessionId": serverSessionID ?? "",
                    "state": OwnerTruthInterviewSessionLifecycle.active.rawValue,
                    "boundary": OwnerTruthInterviewSessionBoundary.open.rawValue,
                    "threadVersion": serverThreadVersion,
                    "sessionVersion": serverSessionVersion,
                    "authorityEpoch": 0,
                    "continuousClientSequence": continuous,
                    "closeRequestedClientSequence": NSNull(),
                ],
                "observedAt": ISO8601DateFormatter().string(from: fakeNow),
                "window": [
                    "fromClientSequence": fromSequence,
                    "limit": 64,
                    "missingClientSequences": missing,
                    "nextFromClientSequence": NSNull(),
                ],
                "deliveries": deliveries,
                "operations": [],
            ])
        }

        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            let path = request.url?.path ?? ""
            let method = request.httpMethod ?? ""
            if method == "GET", path.hasSuffix("/interview-sessions/current") {
                let currentSession: Any
                if let serverThreadID, let serverSessionID {
                    currentSession = [
                        "status": "resumed",
                        "threadId": serverThreadID,
                        "sessionId": serverSessionID,
                        "threadVersion": serverThreadVersion,
                        "sessionVersion": serverSessionVersion,
                        "state": OwnerTruthInterviewSessionLifecycle.active.rawValue,
                        "boundary": OwnerTruthInterviewSessionBoundary.open.rawValue,
                        "authorityEpoch": 0,
                        "entryMode": OwnerTruthInterviewEntryMode.live.rawValue,
                        "productSessionId": productSessionID,
                        "continuousClientSequence": committedAppendPayloads.compactMap {
                            $0["clientSequenceNumber"] as? Int
                        }.max() ?? 0,
                    ]
                } else {
                    currentSession = NSNull()
                }
                loader.respond(statusCode: 200, body: responseData([
                    "schemaVersion": OwnerTruthInterviewNaturalInputCurrentSession.schemaVersion,
                    "vaultId": lease.vaultId,
                    "currentSession": currentSession,
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/interview-sessions") {
                let payload = requestPayload()
                serverThreadID = payload["threadId"] as? String
                serverSessionID = payload["sessionId"] as? String
                serverThreadVersion = 1
                serverSessionVersion = 1
                loader.respond(
                    statusCode: 201,
                    body: naturalInputReceipt(
                        payload: payload,
                        lifecycle: OwnerTruthInterviewSessionLifecycle.active.rawValue,
                        includeMessage: false
                    )
                )
                return
            }
            if method == "GET", path.hasSuffix("/presentation") {
                loader.respond(statusCode: 200, body: responseData([
                    "schemaVersion": OwnerTruthInterviewNaturalInputContinuation.schemaVersion,
                    "vaultId": lease.vaultId,
                    "presentation": [
                        "state": OwnerTruthInterviewNaturalInputContinuationState
                            .readyForNarrative.rawValue,
                        "canContinue": true,
                        "canContinueLater": true,
                    ],
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/messages") {
                let payload = requestPayload()
                let sequence = payload["clientSequenceNumber"] as? Int ?? 0
                if let authenticationRejectionSequence,
                   sequence == authenticationRejectionSequence,
                   !authenticationSequenceDidFail {
                    authenticationSequenceDidFail = true
                    committedCountAtAuthenticationRejection = committedAppendPayloads.count
                    loader.respond(
                        statusCode: 401,
                        body: Data("{\"detail\":\"invalid or expired access token\"}".utf8)
                    )
                    return
                }
                if !committedAppendPayloads.contains(where: {
                    $0["commandId"] as? String == payload["commandId"] as? String
                }) {
                    committedAppendPayloads.append(payload)
                }
                serverThreadVersion = (payload["expectedThreadVersion"] as? Int ?? 0) + 1
                serverSessionVersion = (payload["expectedSessionVersion"] as? Int ?? 0) + 1
                loader.respond(
                    statusCode: 201,
                    body: naturalInputReceipt(
                        payload: payload,
                        lifecycle: OwnerTruthInterviewSessionLifecycle.active.rawValue,
                        includeMessage: true
                    )
                )
                return
            }
            if method == "GET", path.hasSuffix("/live-delivery-status") {
                let components = URLComponents(url: request.url!, resolvingAgainstBaseURL: false)
                let fromSequence = Int(components?.queryItems?.first {
                    $0.name == "fromClientSequence"
                }?.value ?? "") ?? 1
                if deferAuthenticationRecoveryUntilAfterCapture,
                   !didHoldDeliveryStatusOnce,
                   authenticationSequenceDidFail {
                    didHoldDeliveryStatusOnce = true
                    deferredDeliveryStatusResponse = {
                        loader.respond(
                            statusCode: 200,
                            body: deliveryStatusData(fromSequence: fromSequence)
                        )
                    }
                } else {
                    loader.respond(
                        statusCode: 200,
                        body: deliveryStatusData(fromSequence: fromSequence)
                    )
                }
                return
            }
            if method == "POST", path.hasSuffix("/end") {
                let payload = requestPayload()
                let watermark = payload["lastClientSequenceNumber"] as? Int
                serverThreadVersion = (payload["expectedThreadVersion"] as? Int ?? 0) + 1
                serverSessionVersion = (payload["expectedSessionVersion"] as? Int ?? 0) + 2
                loader.respond(
                    statusCode: 201,
                    body: naturalInputReceipt(
                        payload: payload,
                        lifecycle: OwnerTruthInterviewSessionLifecycle.ended.rawValue,
                        includeMessage: false,
                        closeWatermark: watermark
                    )
                )
                return
            }
            if method == "GET", path.hasSuffix("/interview-review-batches/pending") {
                loader.respond(statusCode: 200, body: responseData([
                    "schemaVersion": OwnerTruthInterviewPendingReviewBatchInbox.schemaVersion,
                    "vaultId": lease.vaultId,
                    "reviewBatches": [[
                        "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased(),
                        "threadId": serverThreadID ?? "",
                        "sessionId": serverSessionID ?? "",
                        "reviewBatchVersion": 1,
                        "sessionVersion": serverSessionVersion,
                        "trigger": OwnerTruthInterviewReviewBatchTrigger.sessionExit.rawValue,
                        "capturedCandidateBatchTurnCount": questionCount,
                    ]],
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/acknowledgement") {
                let payload = requestPayload()
                serverSessionVersion = (payload["expectedSessionVersion"] as? Int
                    ?? serverSessionVersion) + 1
                loader.respond(statusCode: 201, body: responseData([
                    "schemaVersion": OwnerTruthInterviewReviewBatchAcknowledgementReceipt
                        .schemaVersion,
                    "vaultId": lease.vaultId,
                    "status": OwnerTruthInterviewReviewBatchAcknowledgementOutcome
                        .acknowledged.rawValue,
                    "session": [
                        "threadId": serverThreadID ?? "",
                        "sessionId": serverSessionID ?? "",
                        "sessionVersion": serverSessionVersion,
                    ],
                    "reviewBatch": [
                        "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased(),
                        "trigger": OwnerTruthInterviewReviewBatchTrigger.sessionExit.rawValue,
                        "state": "acknowledged",
                        "capturedCandidateBatchTurnCount": questionCount,
                        "rowVersion": 2,
                    ],
                    "candidateProposal": ["status": "notStarted"],
                    "memoryActivation": ["status": "notApplicable"],
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/candidate-proposal/admit") {
                loader.respond(statusCode: 201, body: responseData([
                    "schemaVersion": OwnerTruthInterviewCandidateProposalAdmissionReceipt
                        .schemaVersion,
                    "vaultId": lease.vaultId,
                    "status": OwnerTruthCommandOutcome.created.rawValue,
                    "reviewBatch": [
                        "reviewBatchId": reviewBatchID.rawValue.uuidString.lowercased()
                    ],
                    "source": ["status": "admitted", "kind": "conversation", "version": 1],
                    "candidateExtraction": [
                        "status": "requested",
                        "ownerMessageCount": questionCount,
                    ],
                    "candidate": ["status": "notCreated"],
                    "memoryActivation": ["status": "notApplicable"],
                ]))
                return
            }
            if method == "GET", path.hasSuffix("/candidate-proposal/status") {
                loader.respond(statusCode: 200, body: responseData(
                    self.interviewCandidateProposalStatusPayload(
                        vaultID: lease.vaultId,
                        reviewBatchID: reviewBatchID,
                        candidateExtractionState: .succeeded,
                        candidateReviewState: .reviewReady
                    )
                ))
                return
            }
            XCTFail("Unexpected integrated Live request: \(method) \(path)")
            loader.fail(URLError(.badURL))
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }

        var refreshCount = 0
        var pendingRefresh: ((Bool) -> Void)?
        var deferNextRefresh = false
        let refreshPolicy: (@escaping (Bool) -> Void) -> Void = { completion in
            refreshCount += 1
            let apply = {
                policyRevision += 1
                policy = FeatureGatePolicySnapshot(
                    accessMode: .useCachedPolicy,
                    policyVersion: "live-integrated-v\(policyRevision)",
                    policyRevision: policyRevision,
                    emergencyRevision: 0,
                    expiresAt: fakeNow.addingTimeInterval(300),
                    featureEnabled: true,
                    releaseVisible: true,
                    reason: "liveIntegratedAllowed"
                )
                completion(true)
            }
            if deferNextRefresh {
                deferNextRefresh = false
                pendingRefresh = { _ in apply() }
            } else {
                apply()
            }
        }
        liveReadPolicyRefresh = { completion in
            refreshPolicy { refreshed in
                if refreshed {
                    completion(.success(()))
                } else {
                    completion(.failure(DreamJourneyBackendClient.ClientError.featurePolicyDenied(
                        feature: DJFeature.echoTextInput.rawValue,
                        reason: "policyRefreshFailed"
                    )))
                }
            }
        }
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: backend,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: outbox,
            followUpStore: followUp,
            completionCheckpointStore: checkpoint,
            organizationStatusTimeout: 5,
            deliveryStatusTimeout: 2,
            liveAuthorityNow: { fakeNow },
            naturalInputPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(for: .echoTextInput).allowed
            },
            naturalInputPolicyRefresh: refreshPolicy,
            candidateReviewPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(
                    for: .ownerTruthCandidateReview
                ).allowed
            },
            candidateReviewPolicyRefresh: refreshPolicy
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )
        let manager = DialogEngineManager.shared
        let generation = UUID()
        let operationID = UUID()
        manager.installCanonicalIngressForTesting(
            engineGeneration: generation,
            dialogOperationID: operationID,
            delegate: controller
        )
        defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operationID) }

        func enqueueQuestion(_ index: Int, capturedAt: Date) throws {
            let questionID = "integrated-question-\(index)"
            let replyID = "integrated-reply-\(index)"
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrInfo,
                data: try JSONSerialization.data(withJSONObject: [
                    "question_id": questionID,
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt
            ))
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrResponse,
                data: try JSONSerialization.data(withJSONObject: [
                    "results": [[
                        "text": "第 \(index) 条尚未定稿的合成表达",
                        "is_interim": true,
                    ]],
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.1)
            ))
            let finalPayload = try JSONSerialization.data(withJSONObject: [
                "results": [[
                    "text": "第 \(index) 条完整用户表达。",
                    "is_interim": false,
                ]],
            ])
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrResponse,
                data: finalPayload,
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.2)
            ))
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrResponse,
                data: finalPayload,
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.3)
            ))
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: .asrEnded,
                data: try JSONSerialization.data(withJSONObject: [
                    "question_id": questionID,
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.35)
            ))
            XCTAssertNotNil(manager.enqueueCanonicalAssistantProviderMessageForTesting(
                kind: .response,
                data: try JSONSerialization.data(withJSONObject: [
                    "reply_id": replyID,
                    "delta": "第 \(index) 条完整",
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.4)
            ))
            XCTAssertNotNil(manager.enqueueCanonicalAssistantProviderMessageForTesting(
                kind: .response,
                data: try JSONSerialization.data(withJSONObject: [
                    "reply_id": replyID,
                    "delta": "助手回答。",
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.5)
            ))
            XCTAssertNotNil(manager.enqueueCanonicalAssistantProviderMessageForTesting(
                kind: .ended,
                data: try JSONSerialization.data(withJSONObject: [
                    "reply_id": replyID,
                ]),
                engineGeneration: generation,
                capturedAt: capturedAt.addingTimeInterval(0.6)
            ))
        }

        for index in 1...3 {
            fakeNow = fakeNow.addingTimeInterval(index == 1 ? 0 : logicalStep)
            try enqueueQuestion(index, capturedAt: fakeNow)
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
                committedAppendPayloads.count == index * 2
            })
        }

        fakeNow = fakeNow.addingTimeInterval(logicalStep)
        policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: policy.policyVersion,
            policyRevision: policy.policyRevision,
            emergencyRevision: policy.emergencyRevision,
            expiresAt: fakeNow.addingTimeInterval(-1),
            featureEnabled: true,
            releaseVisible: true,
            reason: "liveIntegratedExpiredForRecovery"
        )
        deferNextRefresh = true
        try enqueueQuestion(4, capturedAt: fakeNow)
        try enqueueQuestion(5, capturedAt: fakeNow.addingTimeInterval(logicalStep))
        try enqueueQuestion(6, capturedAt: fakeNow.addingTimeInterval(logicalStep * 2))
        fakeNow = fakeNow.addingTimeInterval(logicalStep * 2)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
            refreshCount == 1
                && (try? outbox.load(for: lease, productSessionID: productSessionID))?
                    .ownerTurnCount == 6
        })
        XCTAssertEqual(committedAppendPayloads.count, 6)
        let firstRefresh = try XCTUnwrap(pendingRefresh)
        pendingRefresh = nil
        firstRefresh(true)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 8) {
            committedAppendPayloads.count == 12 && coordinator.state == .live
        })

        if questionCount >= 7 {
            for index in 7...questionCount {
                fakeNow = fakeNow.addingTimeInterval(logicalStep)
                try enqueueQuestion(index, capturedAt: fakeNow)
                if deferAuthenticationRecoveryUntilAfterCapture,
                   index * 2 >= (authenticationRejectionSequence ?? Int.max) {
                    let crossedAuthenticationRejection = authenticationRejectionSequence.map {
                        index * 2 >= $0
                    } ?? false
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 8) {
                        let persistedThroughCurrentQuestion = (try? outbox.load(
                            for: lease,
                            productSessionID: productSessionID
                        ))?.lastClientSequenceNumber == index * 2
                        let rejectionIsObserved = !crossedAuthenticationRejection
                            || (authenticationSequenceDidFail
                                && deferredDeliveryStatusResponse != nil)
                        return persistedThroughCurrentQuestion && rejectionIsObserved
                    })
                } else {
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 8) {
                        committedAppendPayloads.count == index * 2
                            && coordinator.state == .live
                    })
                }
            }
        }
        fakeNow = fakeNow.addingTimeInterval(logicalStep)
        XCTAssertEqual(
            fakeNow.timeIntervalSince(logicalStart),
            logicalDuration,
            accuracy: 0.001
        )

        if !deferAuthenticationRecoveryUntilAfterCapture {
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 8) {
                committedAppendPayloads.count == questionCount * 2
                    && (try? outbox.load(for: lease, productSessionID: productSessionID))?
                        .pendingTurns.isEmpty == true
            })
        }

        let openSnapshot = try XCTUnwrap(outbox.load(
            for: lease,
            productSessionID: productSessionID
        ))
        XCTAssertEqual(openSnapshot.ownerTurnCount, questionCount)
        XCTAssertEqual(
            openSnapshot.pendingTurns.count,
            deferAuthenticationRecoveryUntilAfterCapture ? 22 : 0
        )
        XCTAssertEqual(openSnapshot.unsealedCanonicalTurnCount, 0)
        XCTAssertEqual(openSnapshot.lastClientSequenceNumber, questionCount * 2)
        XCTAssertEqual(authenticationSequenceDidFail, authenticationRejectionSequence != nil)
        if let authenticationRejectionSequence {
            XCTAssertEqual(
                committedCountAtAuthenticationRejection,
                authenticationRejectionSequence - 1
            )
        }
        XCTAssertGreaterThanOrEqual(refreshCount, authenticationRejectionSequence == nil ? 1 : 2)
        if questionCount == 35 {
            XCTAssertGreaterThanOrEqual(authRefreshCount, 3)
        } else if logicalDuration >= 65 * 60 {
            XCTAssertGreaterThanOrEqual(authRefreshCount, 6)
        }

        coordinator.finish()
        if deferAuthenticationRecoveryUntilAfterCapture {
            XCTAssertEqual(committedAppendPayloads.count, 48)
            XCTAssertEqual(openSnapshot.lastClientSequenceNumber, 70)
            XCTAssertEqual(openSnapshot.pendingTurns.count, 22)
            XCTAssertTrue(openSnapshot.isClosing || waitForOwnerTruthHTTPUI(timeout: 5) {
                (try? outbox.load(
                    for: lease,
                    productSessionID: productSessionID
                ))?.isClosing == true
            })
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
                deferredDeliveryStatusResponse != nil
            }, "Await the actual held status request before releasing its response")
            let release = try XCTUnwrap(deferredDeliveryStatusResponse)
            deferredDeliveryStatusResponse = nil
            didReleaseDeliveryStatusForRecovery = true
            if forceUnusableRecoveryCredential {
                authSession = try makeOwnerTruthHTTPTestAuthSession(
                    userID: lease.subjectId,
                    sessionID: authSession.sessionId,
                    parentSessionID: authSession.parentSessionId,
                    tokenFamilyID: tokenFamilyID,
                    sessionVersion: authSession.sessionVersion ?? 1,
                    accessTokenSuffix: "generation-\(authRefreshCount + 1)",
                    accessExpiresAt: fakeNow.addingTimeInterval(-1)
                )
            }
            release()
        }
        if forceUnusableRecoveryCredential {
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                failedRecoveryCredentialIssued
            }, "The controlled retry-authority failure must actually occur")
            _ = waitForOwnerTruthHTTPUI(timeout: 2) { coordinator.state == .unavailable }
            XCTAssertNotEqual(
                coordinator.state,
                .unavailable,
                "A failed recovery prerequisite must not regress durable append truth"
            )
            let paused = try XCTUnwrap(outbox.load(
                for: lease,
                productSessionID: productSessionID
            ))
            let head = try XCTUnwrap(paused.pendingTurns.first)
            XCTAssertEqual(paused.pendingTurns.count, 22)
            XCTAssertEqual(paused.pendingDispatchStates[head.messageID], .authenticationRejected)
            XCTAssertFalse(paused.authenticationRetryClaimedMessageIDs.contains(head.messageID))
            XCTAssertNotNil(paused.frozenAppendCommands[head.messageID])
            XCTAssertNotNil(paused.authenticationRejectionEvidence[head.messageID])
            XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.filter {
                $0.httpMethod == "POST" && $0.url?.path.hasSuffix("/messages") == true
            }.count, 49)
            XCTAssertFalse(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.contains {
                $0.url?.path.hasSuffix("/end") == true
            })
            NotificationCenter.default.post(
                name: .djAppLifecycleEventForwarded,
                object: nil,
                userInfo: [
                    AppLifecycleEventNotification.eventKey:
                        AppLifecycleEvent.didEnterBackground.rawValue,
                ]
            )
            NotificationCenter.default.post(
                name: .djAppLifecycleEventForwarded,
                object: nil,
                userInfo: [
                    AppLifecycleEventNotification.eventKey:
                        AppLifecycleEvent.willEnterForeground.rawValue,
                ]
            )
        }
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 8) {
            coordinator.state == .pendingReview
        })

        let requests = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests
        let paths = requests.compactMap { $0.url?.path }
        let appendRequests = paths.filter { $0.hasSuffix("/messages") }
        XCTAssertEqual(
            appendRequests.count,
            questionCount * 2 + (authenticationRejectionSequence == nil ? 0 : 1)
        )
        XCTAssertEqual(
            paths.filter { $0.hasSuffix("/live-delivery-status") }.count,
            authenticationRejectionSequence == nil ? 0 : (forceUnusableRecoveryCredential ? 2 : 1)
        )
        XCTAssertEqual(paths.filter { $0.hasSuffix("/end") }.count, 1)
        XCTAssertEqual(paths.filter { $0.hasSuffix("/acknowledgement") }.count, 1)
        XCTAssertEqual(paths.filter { $0.hasSuffix("/candidate-proposal/admit") }.count, 1)
        XCTAssertEqual(paths.filter { $0.hasSuffix("/candidate-proposal/status") }.count, 1)
        let payloads = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequestBodies.compactMap {
            data -> [String: Any]? in
            guard let data else { return nil }
            return try? JSONSerialization.jsonObject(with: data) as? [String: Any]
        }
        let appendPayloads = payloads.filter { $0["clientSequenceNumber"] != nil }
        let inspectedSequence = authenticationRejectionSequence ?? min(15, questionCount * 2)
        let retriedSequence = appendPayloads.filter {
            $0["clientSequenceNumber"] as? Int == inspectedSequence
        }
        XCTAssertEqual(retriedSequence.count, authenticationRejectionSequence == nil ? 1 : 2)
        XCTAssertEqual(
            Set(retriedSequence.compactMap { $0["commandId"] as? String }).count,
            1,
            "The verified pre-handler auth retry must reuse the original command"
        )
        let nonRetriedCommandIDs = payloads.compactMap { $0["commandId"] as? String }
        XCTAssertEqual(
            nonRetriedCommandIDs.count - Set(nonRetriedCommandIDs).count,
            authenticationRejectionSequence == nil ? 0 : 1,
            "Only the verified authentication rejection may repeat a command ID"
        )
        XCTAssertEqual(
            payloads.first { $0["lastClientSequenceNumber"] != nil }?[
                "lastClientSequenceNumber"
            ] as? Int,
            questionCount * 2
        )
        XCTAssertTrue(diagnostics.contains { $0.event == "taskResumed" })
        XCTAssertTrue(diagnostics.contains {
            $0.event == "responseReceived" && $0.httpStatus == 201
        })
        if emitCAP15Bridge {
            let requestBodies = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequestBodies
            let bridgeRequests: [[String: Any]] = requests.enumerated().map { index, request in
                var item: [String: Any] = [
                    "method": request.httpMethod ?? "",
                    "path": request.url?.path ?? "",
                    "query": request.url?.query ?? "",
                ]
                if requestBodies.indices.contains(index),
                   let data = requestBodies[index],
                   let object = try? JSONSerialization.jsonObject(with: data) {
                    item["body"] = object
                }
                return item
            }
            let bridge: [String: Any] = [
                "schemaVersion": "dreamjourney-cap15-client-bridge-v1",
                "questionCount": questionCount,
                "logicalDurationSeconds": logicalDuration,
                "requests": bridgeRequests,
            ]
            let data = try JSONSerialization.data(withJSONObject: bridge, options: [.sortedKeys])
            print("DJ_CAP15_BRIDGE_BASE64:\(data.base64EncodedString())")
        }
    }

    @MainActor
    func testManagerEchoRealGateBackendExplicitDenyKeepsDiskTurnWithoutMessagePost() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("manager-real-backend-explicit-deny-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "manager-real-backend-explicit-deny"
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        var fakeNow = Date()
        let initialExpiry = fakeNow.addingTimeInterval(300)
        var policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "live-deny-v1",
            policyRevision: 1,
            emergencyRevision: 0,
            expiresAt: initialExpiry,
            featureEnabled: true,
            releaseVisible: true,
            reason: "liveIntegratedAllowed"
        )
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        let featureGate = FeatureGateService.makeQATestService(
            accountGeneration: {
                FeatureGateService.accountGeneration(forIdentitySource: authSession.sessionId)
            },
            policy: { _, _ in policy },
            now: { fakeNow }
        )
        featureGate.captureServerPolicyManagedRoute(.echoTextInput, risk: .ownerTextCore)

        let backend = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: {
                featureGate.requestServerPolicyManagedDecision(for: $0)
            },
            freshFeatureDecision: {
                featureGate.freshServerPolicyManagedRequestDecision(for: $0)
            },
            accountLeaseRuntime: runtime
        )
        var serverThreadID = ""
        var serverSessionID = ""
        var rejectNewMessages = false
        var acceptedMessages = 0
        func requestPayload() -> [String: Any] {
            guard let optionalBody = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequestBodies.last,
                  let data = optionalBody else { return [:] }
            return (try? JSONSerialization.jsonObject(with: data) as? [String: Any]) ?? [:]
        }

        func responseData(_ object: [String: Any]) -> Data {
            try! JSONSerialization.data(withJSONObject: object)
        }

        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            let path = request.url?.path ?? ""
            let method = request.httpMethod ?? ""
            if method == "GET", path.hasSuffix("/interview-sessions/current") {
                loader.respond(statusCode: 200, body: responseData([
                    "schemaVersion": OwnerTruthInterviewNaturalInputCurrentSession.schemaVersion,
                    "vaultId": lease.vaultId,
                    "currentSession": NSNull(),
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/interview-sessions") {
                let payload = requestPayload()
                serverThreadID = payload["threadId"] as? String ?? ""
                serverSessionID = payload["sessionId"] as? String ?? ""
                loader.respond(statusCode: 201, body: responseData([
                    "schemaVersion": OwnerTruthInterviewNaturalInputReceipt.schemaVersion,
                    "vaultId": lease.vaultId,
                    "receipt": [
                        "status": OwnerTruthCommandOutcome.created.rawValue,
                        "threadId": serverThreadID,
                        "sessionId": serverSessionID,
                        "threadVersion": 1,
                        "sessionVersion": 1,
                        "state": OwnerTruthInterviewSessionLifecycle.active.rawValue,
                        "boundary": OwnerTruthInterviewSessionBoundary.open.rawValue,
                        "authorityEpoch": 0,
                    ],
                ]))
                return
            }
            if method == "GET", path.hasSuffix("/presentation") {
                loader.respond(statusCode: 200, body: responseData([
                    "schemaVersion": OwnerTruthInterviewNaturalInputContinuation.schemaVersion,
                    "vaultId": lease.vaultId,
                    "presentation": [
                        "state": OwnerTruthInterviewNaturalInputContinuationState
                            .readyForNarrative.rawValue,
                        "canContinue": true,
                        "canContinueLater": true,
                    ],
                ]))
                return
            }
            if method == "POST", path.hasSuffix("/messages") {
                guard !rejectNewMessages else {
                    XCTFail("a refreshed explicit deny must stop before any additional message POST")
                    loader.fail(URLError(.cancelled))
                    return
                }
                let payload = requestPayload()
                acceptedMessages += 1
                loader.respond(statusCode: 201, body: responseData([
                    "schemaVersion": OwnerTruthInterviewNaturalInputReceipt.schemaVersion,
                    "vaultId": lease.vaultId,
                    "receipt": [
                        "status": OwnerTruthCommandOutcome.created.rawValue,
                        "threadId": serverThreadID,
                        "sessionId": serverSessionID,
                        "threadVersion": (payload["expectedThreadVersion"] as? Int ?? 1) + 1,
                        "sessionVersion": (payload["expectedSessionVersion"] as? Int ?? 1) + 1,
                        "state": OwnerTruthInterviewSessionLifecycle.active.rawValue,
                        "boundary": OwnerTruthInterviewSessionBoundary.open.rawValue,
                        "authorityEpoch": 0,
                        "messageId": payload["messageId"] as? String ?? "",
                        "messageSequence": payload["clientSequenceNumber"] as? Int ?? 1,
                        "clientSequenceNumber": payload["clientSequenceNumber"] as? Int ?? 1,
                        "continuousClientSequence": payload["clientSequenceNumber"] as? Int ?? 1,
                        "deliveryState": OwnerTruthInterviewNaturalInputDeliveryState.contiguous.rawValue,
                    ],
                ]))
                return
            }
            XCTFail("Unexpected explicit-deny Live request: \(method) \(path)")
            loader.fail(URLError(.badURL))
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }

        var refreshCount = 0
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: backend,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: outbox,
            liveAuthorityNow: { fakeNow },
            naturalInputPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(for: .echoTextInput).allowed
            },
            naturalInputPolicyRefresh: { completion in
                refreshCount += 1
                policy = FeatureGatePolicySnapshot(
                    accessMode: .useCachedPolicy,
                    policyVersion: "live-deny-v2",
                    policyRevision: 2,
                    emergencyRevision: 1,
                    expiresAt: fakeNow.addingTimeInterval(300),
                    featureEnabled: false,
                    releaseVisible: false,
                    reason: "policyDenied"
                )
                completion(true)
            },
            candidateReviewPolicyAvailable: {
                featureGate.requestServerPolicyManagedDecision(
                    for: .ownerTruthCandidateReview
                ).allowed
            },
            candidateReviewPolicyRefresh: { completion in completion(false) }
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: coordinator
        )
        let manager = DialogEngineManager.shared
        let generation = UUID()
        let operationID = UUID()
        manager.installCanonicalIngressForTesting(
            engineGeneration: generation,
            dialogOperationID: operationID,
            delegate: controller
        )
        defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operationID) }

        XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrInfo,
            data: try JSONSerialization.data(withJSONObject: ["question_id": "explicit-deny-prime"]),
            engineGeneration: generation,
            capturedAt: fakeNow
        ))
        XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrResponse,
            data: try JSONSerialization.data(withJSONObject: [
                "results": [["text": "策略仍允许时先保存的合成表达。", "is_interim": false]],
            ]),
            engineGeneration: generation,
            capturedAt: fakeNow.addingTimeInterval(0.1)
        ))
        XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrEnded,
            data: try JSONSerialization.data(withJSONObject: [
                "question_id": "explicit-deny-prime",
            ]),
            engineGeneration: generation,
            capturedAt: fakeNow.addingTimeInterval(0.15)
        ))
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
            coordinator.state == .live
                && acceptedMessages == 1
                && (try? outbox.load(for: lease, productSessionID: productSessionID))?.pendingTurns.isEmpty == true
                && OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.contains {
                    $0.httpMethod == "POST"
                        && $0.url?.path.hasSuffix("/interview-sessions") == true
                }
        })
        let messageCountBeforeDeny = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.filter {
            $0.httpMethod == "POST" && $0.url?.path.hasSuffix("/messages") == true
        }.count
        XCTAssertEqual(messageCountBeforeDeny, 1)
        rejectNewMessages = true
        fakeNow = initialExpiry.addingTimeInterval(1)
        XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrInfo,
            data: try JSONSerialization.data(withJSONObject: [
                "question_id": "explicit-deny-question",
            ]),
            engineGeneration: generation,
            capturedAt: fakeNow
        ))
        XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrResponse,
            data: try JSONSerialization.data(withJSONObject: [
                "results": [[
                    "text": "明确拒绝后只保存在本地的合成表达。",
                    "is_interim": false,
                ]],
            ]),
            engineGeneration: generation,
            capturedAt: fakeNow.addingTimeInterval(0.1)
        ))
        XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
            kind: .asrEnded,
            data: try JSONSerialization.data(withJSONObject: [
                "question_id": "explicit-deny-question",
            ]),
            engineGeneration: generation,
            capturedAt: fakeNow.addingTimeInterval(0.15)
        ))

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 5) {
            refreshCount == 1
                && coordinator.state == .syncPaused
                && (try? outbox.load(for: lease, productSessionID: productSessionID))?
                    .ownerTurnCount == 2
        })
        let requests = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests
        XCTAssertEqual(
            requests.filter { $0.url?.path.hasSuffix("/messages") == true }.count - messageCountBeforeDeny,
            0
        )
        XCTAssertEqual(
            try XCTUnwrap(outbox.load(for: lease, productSessionID: productSessionID))
                .pendingTurns.count,
            1
        )
        XCTAssertFalse(
            featureGate.freshServerPolicyManagedRequestDecision(for: .echoTextInput).allowed
        )
    }

