        let productSessionID = "echo-live-status-confirm"
        client.startHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, start: command) }
        }
        client.appendHandler = { _ in
            .failure(InterviewNaturalInputClientSpyError.missingAppendResult)
        }
        client.liveDeliveryStatusHandler = { _, requestedProductSessionID, fromSequence in
            Result {
                let start = try XCTUnwrap(client.startCommand)
                let append = try XCTUnwrap(client.appendCommand)
                XCTAssertEqual(requestedProductSessionID, productSessionID)
                XCTAssertEqual(fromSequence, append.clientSequenceNumber)
                let status = try OwnerTruthLiveDeliveryStatus(
                    backendJSONObject: [
                        "schemaVersion": OwnerTruthLiveDeliveryStatus.schemaVersion,
                        "vaultId": vaultID.rawValue,
                        "productSessionId": productSessionID,
                        "session": [
                            "threadId": start.threadID.rawValue.uuidString.lowercased(),
                            "sessionId": start.sessionID.rawValue.uuidString.lowercased(),
                            "state": "active",
                            "boundary": "open",
                            "threadVersion": 2,
                            "sessionVersion": 2,
                            "authorityEpoch": Int(lease.authorityEpoch) ?? 0,
                            "continuousClientSequence": 1,
                            "closeRequestedClientSequence": NSNull(),
                        ],
                        "observedAt": "2026-09-15T03:00:00Z",
                        "window": [
                            "fromClientSequence": 1,
                            "limit": 64,
                            "missingClientSequences": [],
                            "nextFromClientSequence": NSNull(),
                        ],
                        "deliveries": [[
                            "messageId": append.messageID.rawValue.uuidString.lowercased(),
                            "commandIdHash": SHA256.hash(data: Data(append.commandID.utf8)).map {
                                String(format: "%02x", $0)
                            }.joined(),
                            "clientSequenceNumber": 1,
                            "author": append.role.rawValue,
                            "kind": "freeText",
                            "capturedAt": ISO8601DateFormatter().string(
                                from: try XCTUnwrap(append.capturedAt)
                            ),
                            "contentHash": try OwnerTruthInterviewLiveTurnDelivery(
                                commandID: append.commandID,
                                messageID: append.messageID,
                                clientSequenceNumber: try XCTUnwrap(append.clientSequenceNumber),
                                role: append.role,
                                text: append.text,
                                capturedAt: try XCTUnwrap(append.capturedAt)
                            ).serverContentHash(),
                        ]],
                        "operations": [],
                    ],
                    expectedVaultID: vaultID,
                    expectedSessionID: start.sessionID,
                    expectedProductSessionID: productSessionID
                )
                let localDelivery = try OwnerTruthInterviewLiveTurnDelivery(
                    commandID: append.commandID,
                    messageID: append.messageID,
                    clientSequenceNumber: try XCTUnwrap(append.clientSequenceNumber),
                    role: append.role,
                    text: append.text,
                    capturedAt: try XCTUnwrap(append.capturedAt)
                )
                XCTAssertNotNil(status.delivery(matching: localDelivery))
                return status
            }
        }
        client.scopedCurrentSessionHandler = { _, requestedProductSessionID in
            Result {
                guard let start = client.startCommand else {
                    return try OwnerTruthInterviewNaturalInputCurrentSession(
                        backendJSONObject: [
                            "schemaVersion": OwnerTruthInterviewNaturalInputCurrentSession.schemaVersion,
                            "vaultId": vaultID.rawValue,
                            "currentSession": NSNull(),
                        ],
                        expectedVaultID: vaultID
                    )
                }
                return try OwnerTruthInterviewNaturalInputCurrentSession(
                    backendJSONObject: [
                        "schemaVersion": OwnerTruthInterviewNaturalInputCurrentSession.schemaVersion,
                        "vaultId": vaultID.rawValue,
                        "currentSession": [
                            "status": "resumed",
                            "threadId": start.threadID.rawValue.uuidString.lowercased(),
                            "sessionId": start.sessionID.rawValue.uuidString.lowercased(),
                            "threadVersion": 2,
                            "sessionVersion": 2,
                            "state": "active",
                            "boundary": "open",
                            "entryMode": "live",
                            "productSessionId": requestedProductSessionID ?? "",
                            "continuousClientSequence": 1,
                            "deliveryState": "contiguous",
                        ],
                    ],
                    expectedVaultID: vaultID
                )
            }
        }
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )

        coordinator.appendOwnerTurn("只读状态应确认这一条已提交但回执丢失的合成内容。")

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            coordinator.state == .live
                && (try? store.load(for: lease, productSessionID: productSessionID))?
                    .pendingTurns.isEmpty == true
        })
        XCTAssertEqual(client.appendCommands.count, 1)
        XCTAssertEqual(client.liveDeliveryStatusRequestCount, 1)
        XCTAssertEqual(client.startCommands.count, 1)
    }

    func testLiveDeliveryObservationBudgetIncludesPolicyRefreshWait() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        client.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("echo-delivery-policy-budget-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        var policyAvailable = true
        var policyRefresh: ((Bool) -> Void)?
        var logicalTime: TimeInterval = 100
        client.startHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, start: command) }
        }
        client.appendHandler = { _ in
            policyAvailable = false
            return .failure(InterviewNaturalInputClientSpyError.missingAppendResult)
        }
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease, client: client, accountLeaseRuntime: runtime,
            productSessionID: "echo-delivery-policy-budget",
            liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
            ),
            deliveryObservationNow: { logicalTime },
            naturalInputPolicyAvailable: { policyAvailable },
            naturalInputPolicyRefresh: { policyRefresh = $0 },
            candidateReviewPolicyAvailable: { true }
        )
        coordinator.appendOwnerTurn("过期策略恢复不能越过本场状态读取期限。")
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { policyRefresh != nil })
        logicalTime += 181
        policyAvailable = true
        policyRefresh?(true)
        let refreshProcessed = expectation(description: "policy refresh callback processed")
        DispatchQueue.main.async { refreshProcessed.fulfill() }
        wait(for: [refreshProcessed], timeout: 3)
        XCTAssertEqual(coordinator.state, .statusUnknown)
        XCTAssertEqual(client.liveDeliveryStatusRequestCount, 0)
        XCTAssertEqual(client.appendCommands.count, 1)
    }

    func testLiveDeliveryObservationRejectsInFlightSuccessAfterOverallDeadline() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        client.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("echo-delivery-inflight-budget-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let productSessionID = "echo-delivery-inflight-budget"
        var logicalTime: TimeInterval = 100
        var policyAvailable = true
        var policyRefresh: ((Bool) -> Void)?
        client.startHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, start: command) }
        }
        client.appendHandler = { _ in
            policyAvailable = false
            return .failure(InterviewNaturalInputClientSpyError.missingAppendResult)
        }
        client.deferLiveDeliveryStatus = true
        client.liveDeliveryStatusHandler = { _, _, _ in
            .failure(InterviewNaturalInputClientSpyError.missingLiveDeliveryStatusResult)
        }
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease, client: client, accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
            ),
            deliveryObservationNow: { logicalTime },
            naturalInputPolicyAvailable: { policyAvailable },
            naturalInputPolicyRefresh: { policyRefresh = $0 },
            candidateReviewPolicyAvailable: { true }
        )
        coordinator.appendOwnerTurn("Synthetic in-flight deadline fact.")
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { policyRefresh != nil })
        logicalTime = 279
        policyAvailable = true
        policyRefresh?(true)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            client.liveDeliveryStatusRequestCount == 1
        })
        let status = try liveDeliveryStatus(
            vaultID: vaultID, productSessionID: productSessionID,
            start: XCTUnwrap(client.startCommand),
            deliveries: [XCTUnwrap(client.appendCommand)]
        )
        logicalTime = 281
        client.completeDeferredLiveDeliveryStatus(.success(status))
        let processed = expectation(description: "late status and persistence callbacks processed")
        DispatchQueue.main.async {
            // The status callback may enqueue an acknowledgement on the persistence queue.
            // Wait for that queue and its main callback before checking durable state.
            coordinator.flushPersistenceForTesting {
                processed.fulfill()
            }
        }
        wait(for: [processed], timeout: 3)
        XCTAssertEqual(coordinator.state, .statusUnknown)
        XCTAssertEqual(try store.load(for: lease, productSessionID: productSessionID)?.pendingTurns.count, 1)
        XCTAssertEqual(client.appendCommands.count, 1)
    }

    func testLiveDeliveryObservationKeepsReadingAfterMatchingItemWithStaleEnvelope() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        client.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("echo-delivery-stale-envelope-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let productSessionID = "echo-delivery-stale-envelope"
        var scheduledRetry: (() -> Void)?
        client.startHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, start: command) }
        }
        client.appendHandler = { command in
            if client.appendCommands.count == 1 {
                return Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, append: command) }
            }
            return .failure(InterviewNaturalInputClientSpyError.missingAppendResult)
        }
        client.liveDeliveryStatusHandler = { _, _, _ in
            Result {
                try self.liveDeliveryStatus(
                    vaultID: vaultID, productSessionID: productSessionID,
                    start: XCTUnwrap(client.startCommand),
                    deliveries: [XCTUnwrap(client.appendCommands.last)],
                    threadVersionOverride: client.liveDeliveryStatusRequestCount == 1 ? 1 : nil
                )
            }
        }
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease, client: client, accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
            ),
            deliveryObservationSchedule: { _, action in
                scheduledRetry = action
                return DispatchWorkItem(block: action)
            },
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        coordinator.appendOwnerTurn("First committed synthetic fact.")
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { client.appendCommands.count == 1 })
        coordinator.appendOwnerTurn("Second unknown synthetic fact.")
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            client.liveDeliveryStatusRequestCount == 1 && scheduledRetry != nil
        })
        XCTAssertEqual(try store.load(for: lease, productSessionID: productSessionID)?.pendingTurns.count, 1)
        XCTAssertEqual(client.appendCommands.count, 2)
        scheduledRetry?()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            client.liveDeliveryStatusRequestCount == 2
                && (try? store.load(for: lease, productSessionID: productSessionID))?.pendingTurns.isEmpty == true
        })
        XCTAssertEqual(client.appendCommands.count, 2)
    }

    func testLiveCaptureDeliveryStatusTimeoutIgnoresLateResultAndAllowsBoundedRetry() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        client.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("echo-live-status-timeout-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let productSessionID = "echo-live-status-timeout"
        client.startHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, start: command) }
        }
        client.appendHandler = { _ in
            .failure(InterviewNaturalInputClientSpyError.missingAppendResult)
        }
        client.deferLiveDeliveryStatus = true
        client.liveDeliveryStatusHandler = { _, _, _ in
            .failure(InterviewNaturalInputClientSpyError.missingLiveDeliveryStatusResult)
        }
        client.scopedCurrentSessionHandler = { _, _ in
            Result {
                guard let start = client.startCommand else {
                    return try self.emptyInterviewNaturalInputCurrentSession(vaultID: vaultID)
                }
                return try self.activeLiveCurrentSession(
                    vaultID: vaultID,
                    start: start,
                    productSessionID: productSessionID,
                    continuousClientSequence: 1
                )
            }
        }
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
            ),
            deliveryStatusTimeout: 0.05,
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )

        coordinator.appendOwnerTurn("状态读取超时后不得接受迟到结果或补发未知写。")

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            coordinator.state == .statusUnknown
                && client.liveDeliveryStatusRequestCount == 1
        })
        let start = try XCTUnwrap(client.startCommand)
        let append = try XCTUnwrap(client.appendCommand)
        let lateStatus = try liveDeliveryStatus(
            vaultID: vaultID,
            productSessionID: productSessionID,
            start: start,
            deliveries: [append]
        )
        RunLoop.main.run(until: Date().addingTimeInterval(0.1))
        XCTAssertEqual(coordinator.state, .statusUnknown)
        client.completeDeferredLiveDeliveryStatus(.success(lateStatus))
        RunLoop.main.run(until: Date().addingTimeInterval(0.05))
        XCTAssertEqual(coordinator.state, .statusUnknown)
        XCTAssertEqual(client.appendCommands.count, 1)
        XCTAssertEqual(
            try store.load(for: lease, productSessionID: productSessionID)?.pendingTurns.count,
            1
        )

        client.deferLiveDeliveryStatus = false
        client.liveDeliveryStatusHandler = { _, _, _ in .success(lateStatus) }
        NotificationCenter.default.post(
            name: .djAppLifecycleEventForwarded,
            object: nil,
            userInfo: [AppLifecycleEventNotification.eventKey: AppLifecycleEvent.didEnterBackground.rawValue]
        )
        NotificationCenter.default.post(
            name: .djAppLifecycleEventForwarded,
            object: nil,
            userInfo: [AppLifecycleEventNotification.eventKey: AppLifecycleEvent.willEnterForeground.rawValue]
        )

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            coordinator.state == .live
                && client.liveDeliveryStatusRequestCount == 2
                && (try? store.load(for: lease, productSessionID: productSessionID))?
                    .pendingTurns.isEmpty == true
        })
        XCTAssertEqual(client.appendCommands.count, 1)
    }

    func testLiveCapturePartialStatusNeverPostsUnconfirmedQueuedTurn() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let client = InterviewNaturalInputClientSpy()
        client.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("echo-live-status-partial-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let productSessionID = "echo-live-status-partial"
        client.startHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, start: command) }
        }
        client.appendHandler = { command in
            if client.appendCommands.count == 1 {
                return .failure(InterviewNaturalInputClientSpyError.missingAppendResult)
            }
            return Result {
                try self.interviewNaturalInputReceipt(vaultID: vaultID, append: command)
            }
        }
        client.deferLiveDeliveryStatus = true
        client.liveDeliveryStatusHandler = { _, _, _ in
            .failure(InterviewNaturalInputClientSpyError.missingLiveDeliveryStatusResult)
        }
        client.scopedCurrentSessionHandler = { _, _ in
            Result {
                guard let start = client.startCommand else {
                    return try self.emptyInterviewNaturalInputCurrentSession(vaultID: vaultID)
                }
                return try self.activeLiveCurrentSession(
                    vaultID: vaultID,
                    start: start,
                    productSessionID: productSessionID,
                    continuousClientSequence: 1
                )
            }
        }
        let coordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            productSessionID: productSessionID,
            liveTurnOutboxStore: store,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion", isDirectory: true)
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )

        coordinator.appendOwnerTurn("第一条写入回执未知。")
        coordinator.appendOwnerTurn("第二条已登记但不得在未知恢复中补发。")
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            client.appendCommands.count == 1
                && client.liveDeliveryStatusRequestCount == 1
                && (try? store.load(for: lease, productSessionID: productSessionID))?
                    .pendingTurns.count == 2
        })
        let start = try XCTUnwrap(client.startCommand)
        let firstAppend = try XCTUnwrap(client.appendCommand)
        let partialStatus = try liveDeliveryStatus(
            vaultID: vaultID,
            productSessionID: productSessionID,
            start: start,
            deliveries: [firstAppend]
        )
        client.completeDeferredLiveDeliveryStatus(.success(partialStatus))

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            coordinator.state == .live
                && client.appendCommands.count == 2
                && (try? store.load(for: lease, productSessionID: productSessionID))?
                    .pendingTurns.isEmpty == true
        })
        XCTAssertEqual(client.liveDeliveryStatusRequestCount, 1)
    }

    func testB6ColdRestartNeverReplaysEndAcknowledgementOrAdmissionCommands() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let threadID = recordID("00000000-0000-0000-0000-000000000711")
        let sessionID = recordID("00000000-0000-0000-0000-000000000712")
        let reviewBatchID = recordID("00000000-0000-0000-0000-000000000713")
        let endCommand = try OwnerTruthInterviewEndCommand(
            commandID: "end-command-stable",
            threadID: threadID,
            sessionID: sessionID,
            expectedThreadVersion: 3,
            expectedSessionVersion: 4,
            lastClientSequenceNumber: 2
        )
        let endReceipt = try interviewNaturalInputReceipt(vaultID: vaultID, end: endCommand)
        let acknowledgementCommand = try OwnerTruthInterviewReviewBatchAcknowledgementCommand(
            commandID: "ack-command-stable",
            reviewBatchID: reviewBatchID,
            threadID: threadID,
            sessionID: sessionID,
            expectedSessionVersion: endReceipt.sessionVersion,
            expectedReviewBatchVersion: 1
        )
        let acknowledgementReceipt = try pendingReviewBatchAcknowledgementReceipt(
            vaultID: lease.vaultId,
            reviewBatchID: reviewBatchID,
            threadID: threadID,
            sessionID: sessionID,
            reviewBatchVersion: 2,
            sessionVersion: endReceipt.sessionVersion + 1
        )
        let admissionCommand = try OwnerTruthInterviewCandidateProposalAdmissionCommand(
            commandID: "admit-command-stable",
            reviewBatchID: reviewBatchID,
            expectedReviewBatchVersion: acknowledgementReceipt.reviewBatchVersion
        )

        enum CrashStage: String, CaseIterable {
            case end
            case acknowledgement
            case admission
        }

        for stage in CrashStage.allCases {
            let root = FileManager.default.temporaryDirectory
                .appendingPathComponent("echo-live-checkpoint-\(stage.rawValue)-\(UUID().uuidString)")
            let defaultsName = "echo-live-checkpoint-follow-up-\(UUID().uuidString)"
            let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
            defer {
                try? FileManager.default.removeItem(at: root)
                defaults.removePersistentDomain(forName: defaultsName)
            }
            let store = EchoLiveMemoryCompletionCheckpointStore(rootDirectory: root)
            let productSessionID = "checkpoint-replay-\(stage.rawValue)"
            try store.prepareEnd(endCommand, productSessionID: productSessionID, for: lease)
            if stage != .end {
                try store.acceptEnd(endReceipt, productSessionID: productSessionID, for: lease)
                try store.prepareAcknowledgement(
                    acknowledgementCommand,
                    productSessionID: productSessionID,
                    for: lease
                )
            }
            if stage == .admission {
                try store.acceptAcknowledgement(
                    acknowledgementReceipt,
                    productSessionID: productSessionID,
                    for: lease
                )
                try store.prepareAdmission(
                    admissionCommand,
                    productSessionID: productSessionID,
                    for: lease
                )
            }

            let client = InterviewNaturalInputClientSpy()
            client.endHandler = { [unowned self] command in
                Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, end: command) }
            }
            client.pendingReviewInboxHandler = { [unowned self] in
                Result {
                    try self.pendingReviewBatchInbox(vaultID: lease.vaultId, batches: [(
                        reviewBatchID: reviewBatchID,
                        threadID: threadID,
                        sessionID: sessionID,
                        reviewBatchVersion: 1,
                        sessionVersion: endReceipt.sessionVersion
                    )])
                }
            }
            client.acknowledgementHandler = { [unowned self] command in
                Result {
                    try self.pendingReviewBatchAcknowledgementReceipt(
                        vaultID: lease.vaultId,
                        reviewBatchID: command.reviewBatchID,
                        threadID: command.threadID,
                        sessionID: command.sessionID,
                        reviewBatchVersion: command.expectedReviewBatchVersion + 1,
                        sessionVersion: command.expectedSessionVersion + 1
                    )
                }
            }
            client.admissionHandler = { [unowned self] command in
                Result {
                    try self.candidateProposalAdmissionReceipt(
                        vaultID: lease.vaultId,
                        reviewBatchID: command.reviewBatchID
                    )
                }
            }
            client.proposalStatusHandler = { [unowned self] requestedReviewBatchID in
                Result {
                    try self.interviewCandidateProposalStatus(
                        vaultID: lease.vaultId,
                        reviewBatchID: requestedReviewBatchID,
                        candidateExtractionState: .succeeded,
                        candidateReviewState: .reviewReady
                    )
                }
            }

            let result = EchoLiveMemoryRecoveryService().resumePendingWorkflows(
                accountLease: lease,
                excluding: [],
                client: client,
                accountLeaseRuntime: runtime,
                liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(
                    rootDirectory: root.appendingPathComponent("outbox")
                ),
                followUpStore: EchoLiveMemoryFollowUpStore(defaults: defaults),
                completionCheckpointStore: store,
                organizationStatusTimeout: 1,
                naturalInputPolicyAvailable: { true },
                candidateReviewPolicyAvailable: { true }
            )

            let recovery = try XCTUnwrap(result.coordinators.first, stage.rawValue)
            recovery.start()
            switch stage {
            case .end:
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                    recovery.state == .pendingReview
                }, stage.rawValue)
                XCTAssertEqual(client.pendingReviewInboxRequestCount, 1, stage.rawValue)
                XCTAssertEqual(client.proposalStatusRequestCount, 1, stage.rawValue)
            case .acknowledgement, .admission:
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                    recovery.state == .pendingReview
                }, stage.rawValue)
                XCTAssertEqual(client.proposalStatusRequestCount, 1, stage.rawValue)
            }
            XCTAssertTrue(client.endCommands.isEmpty, stage.rawValue)
            XCTAssertTrue(client.acknowledgementCommands.isEmpty, stage.rawValue)
            XCTAssertTrue(client.admissionCommands.isEmpty, stage.rawValue)
            XCTAssertTrue(client.startCommands.isEmpty)
        }
    }

