    func testB8S01SuspendedPollCallbackCannotStartAnotherRead() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let batchID = recordID("00000000-0000-0000-0000-0000000007c7")
        let client = DeferredB6RecoveryReadClient()
        var scheduledActions: [(TimeInterval, () -> Void)] = []
        let coordinator = EchoLiveMemoryRecoveryCoordinator(
            plan: EchoLiveMemoryRecoveryPlan(
                accountLease: lease,
                productSessionID: "b8-s01-suspended-poll",
                threadID: nil,
                sessionID: nil,
                reviewBatchID: batchID,
                checkpointPhase: .admitted,
                sources: [.completionCheckpoint],
                localRecordRevision: "revision-1"
            ),
            client: client,
            accountLeaseRuntime: runtime,
            organizationStatusTimeout: 30,
            candidateReviewPolicyAvailable: { true },
            schedule: { delay, action in
                scheduledActions.append((delay, action))
                return DispatchWorkItem(block: action)
            }
        )
        coordinator.start()
        client.completeStatus(
            at: 0,
            with: .success(try interviewCandidateProposalStatus(
                vaultID: lease.vaultId,
                reviewBatchID: batchID
            ))
        )
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 1) {
            coordinator.state == .queued
        })
        let stalePoll = try XCTUnwrap(scheduledActions.first(where: { $0.0 == 1 })?.1)

        coordinator.suspend()
        XCTAssertEqual(coordinator.state, .statusUnknown(.staleAttempt))
        stalePoll()
        XCTAssertEqual(client.statusContexts.count, 1)
        XCTAssertEqual(coordinator.state, .statusUnknown(.staleAttempt))
    }

    func testB8S01StalePollFromRoundACannotConsumeRoundBOrClearItsPoll() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let batchID = recordID("00000000-0000-0000-0000-0000000007c9")
        let client = DeferredB6RecoveryReadClient()
        var pollActions: [() -> Void] = []
        let coordinator = EchoLiveMemoryRecoveryCoordinator(
            plan: EchoLiveMemoryRecoveryPlan(
                accountLease: lease,
                productSessionID: "b8-s01-cross-round-poll",
                threadID: nil,
                sessionID: nil,
                reviewBatchID: batchID,
                checkpointPhase: .admitted,
                sources: [.completionCheckpoint],
                localRecordRevision: "revision-1"
            ),
            client: client,
            accountLeaseRuntime: runtime,
            organizationStatusTimeout: 30,
            candidateReviewPolicyAvailable: { true },
            schedule: { delay, action in
                if delay == 1 { pollActions.append(action) }
                return DispatchWorkItem(block: action)
            }
        )

        coordinator.start()
        client.completeStatus(
            at: 0,
            with: .success(try interviewCandidateProposalStatus(
                vaultID: lease.vaultId,
                reviewBatchID: batchID
            ))
        )
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 1) {
            coordinator.state == .queued && pollActions.count == 1
        })
        let roundAPoll = pollActions[0]

        coordinator.suspend()
        coordinator.verifyStatus(startsNewRound: true)
        XCTAssertEqual(client.statusContexts.count, 2)
        let roundBInitialContext = client.statusContexts[1]
        client.completeStatus(
            at: 1,
            with: .success(try interviewCandidateProposalStatus(
                vaultID: lease.vaultId,
                reviewBatchID: batchID
            ))
        )
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 1) {
            coordinator.state == .queued && pollActions.count == 2
        })
        let roundBPoll = pollActions[1]

        roundAPoll()
        XCTAssertEqual(
            client.statusContexts.count,
            2,
            "a stale round-A poll must not spend round B's GET budget"
        )
        XCTAssertEqual(coordinator.state, .queued)

        roundBPoll()
        XCTAssertEqual(client.statusContexts.count, 3)
        XCTAssertEqual(client.statusContexts[2].traceID, roundBInitialContext.traceID)
        XCTAssertEqual(client.statusContexts[2].attempt, roundBInitialContext.attempt + 1)
        XCTAssertEqual(
            client.statusContexts[2].resourceGETCount,
            roundBInitialContext.resourceGETCount + 1
        )
    }

    func testLiveLongMemoryPendingPollingUsesBoundedBackoffAndStopsAtTwentyFourGETBudget() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let batchID = recordID("00000000-0000-0000-0000-0000000007c8")
        let client = DeferredB6RecoveryReadClient()
        var scheduledPolls: [(delay: TimeInterval, action: () -> Void)] = []
        let coordinator = EchoLiveMemoryRecoveryCoordinator(
            plan: EchoLiveMemoryRecoveryPlan(
                accountLease: lease,
            productSessionID: "live-long-memory-twenty-four-get-budget",
                threadID: nil,
                sessionID: nil,
                reviewBatchID: batchID,
                checkpointPhase: .admitted,
                sources: [.completionCheckpoint],
                localRecordRevision: "revision-1"
            ),
            client: client,
            accountLeaseRuntime: runtime,
            organizationStatusTimeout: 30,
            candidateReviewPolicyAvailable: { true },
            schedule: { delay, action in
                if delay <= 10 {
                    scheduledPolls.append((delay, action))
                }
                return DispatchWorkItem(block: action)
            }
        )
        coordinator.start()

        for index in 0..<24 {
            client.completeStatus(
                at: index,
                with: .success(try interviewCandidateProposalStatus(
                    vaultID: lease.vaultId,
                    reviewBatchID: batchID
                ))
            )
            if index < 23 {
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 1) {
                    scheduledPolls.count == index + 1
                })
                scheduledPolls[index].action()
                XCTAssertEqual(client.statusContexts.count, index + 2)
            }
        }

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 1) {
            coordinator.state == .queued
        })
        XCTAssertEqual(client.statusContexts.count, 24)
        XCTAssertEqual(Set(client.statusContexts.map(\.traceID)).count, 1)
        XCTAssertEqual(client.statusContexts.map(\.attempt), Array(1...24))
        XCTAssertEqual(client.statusContexts.map(\.resourceGETCount), Array(0..<24))
        XCTAssertEqual(
            scheduledPolls.map(\.delay),
            [1, 2, 4, 8] + Array(repeating: 10, count: 19)
        )
    }

