    @MainActor
    func testLiveLongMemoryRealControllerAutomaticallyReachesPendingReviewOnSeventhGET() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let batchID = recordID("00000000-0000-0000-0000-0000000007cb")
        let productSessionID = "live-long-memory-seventh-get"
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-seventh-get-\(UUID().uuidString)")
        let defaultsName = "live-seventh-get-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        defer {
            try? FileManager.default.removeItem(at: root)
            defaults.removePersistentDomain(forName: defaultsName)
            OwnerTruthReviewReadyHTTPURLProtocol.reset()
        }

        let followUpStore = EchoLiveMemoryFollowUpStore(
            defaults: defaults,
            rootDirectory: root.appendingPathComponent("follow-up")
        )
        try followUpStore.upsert(
            productSessionID: productSessionID,
            reviewBatchID: batchID,
            for: lease
        )
        let policyStore = ReleasePolicyStore(userDefaults: defaults)
        try saveCandidateReleasePolicy(
            candidateReleasePolicyPayload(
                version: "live-seventh-get-policy-v1",
                revision: 202,
                expiresAt: "2099-01-01T00:00:00Z"
            ),
            store: policyStore,
            scope: candidateReleasePolicyScope(lease: lease)
        )
        let authSession = try makeOwnerTruthHTTPTestAuthSession(
            userID: lease.subjectId,
            sessionID: lease.sessionId
        )
        var readEvents: [OwnerTruthReadDiagnosticEvent] = []
        let harness = try makeCandidatePolicyTestClient(
            runtime: runtime,
            lease: lease,
            authSession: { authSession },
            store: policyStore,
            ownerTruthReadEventSink: { readEvents.append($0) }
        )
        let organizingBody = try JSONSerialization.data(withJSONObject:
            interviewCandidateProposalStatusPayload(
                vaultID: lease.vaultId,
                reviewBatchID: batchID,
                candidateExtractionState: .requested,
                candidateExtractionJobState: .leased,
                candidateExtractionAttempt: 1,
                candidateReviewState: .notReady
            )
        )
        let reviewReadyBody = try JSONSerialization.data(withJSONObject:
            interviewCandidateProposalStatusPayload(
                vaultID: lease.vaultId,
                reviewBatchID: batchID,
                candidateExtractionState: .succeeded,
                candidateExtractionJobState: .succeeded,
                candidateExtractionAttempt: 1,
                candidateReviewState: .reviewReady
            )
        )
        var statusReadCount = 0
        var activeControllerTraceID: String?
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            XCTAssertEqual(request.httpMethod, "GET")
            statusReadCount += 1
            let requestContext = readEvents.last(where: {
                $0.resource == .liveMemoryRecoveryStatus
                    && $0.event == "requestCreated"
            })
            let isActiveSeventhRead = requestContext?.traceID == activeControllerTraceID
                && requestContext?.attempt == 7
            loader.respond(
                statusCode: 200,
                body: isActiveSeventhRead ? reviewReadyBody : organizingBody
            )
        }

        var clock = Date()
        var scheduled: [(delay: TimeInterval, action: () -> Void)] = []
        let result = EchoLiveMemoryRecoveryService(
            registry: EchoLiveMemoryRecoveryRegistry()
        ).resumePendingWorkflows(
            accountLease: lease,
            excluding: [],
            client: harness.client,
            accountLeaseRuntime: runtime,
            liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(
                rootDirectory: root.appendingPathComponent("outbox")
            ),
            followUpStore: followUpStore,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            organizationStatusTimeout: 120,
            now: { clock },
            schedule: { delay, action in
                scheduled.append((delay, action))
                return DispatchWorkItem(block: action)
            },
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: {
                harness.decision(.ownerTruthCandidateReview).allowed
            }
        )
        let coordinator = try XCTUnwrap(result.coordinators.first)
        let controller = EchoViewController()
        controller.installLiveMemoryRecoveryForTesting(
            accountLease: lease,
            coordinator: coordinator
        )

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            statusReadCount == 1 && coordinator.state == .organizing
        })
        let initialTraceID = try XCTUnwrap(
            readEvents.last(where: {
                $0.resource == .liveMemoryRecoveryStatus
                    && $0.event == "resourceContractDecoded"
            })?.traceID
        )
        // Drive the actual post-policy controller boundary explicitly; do not
        // depend on an unrelated shared-policy request completing by chance.
        controller.completeRecoveryPolicyRefreshForTesting()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            readEvents.contains(where: {
                $0.resource == .liveMemoryRecoveryStatus
                    && $0.event == "resourceContractDecoded"
                    && $0.traceID != initialTraceID
            })
        })
        activeControllerTraceID = try XCTUnwrap(
            readEvents.last(where: {
                $0.resource == .liveMemoryRecoveryStatus
                    && $0.event == "resourceContractDecoded"
                    && $0.traceID != initialTraceID
            })?.traceID
        )
        var nextScheduledIndex = 0
        var executedPollCount = 0
        while coordinator.state != .pendingReview {
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                scheduled.dropFirst(nextScheduledIndex).contains(where: { $0.delay < 120 })
                    || coordinator.state == .pendingReview
            })
            if coordinator.state == .pendingReview { break }
            let pollIndex = try XCTUnwrap(
                scheduled.indices.dropFirst(nextScheduledIndex).first(where: {
                    scheduled[$0].delay < 120
                })
            )
            nextScheduledIndex = pollIndex + 1
            let poll = scheduled[pollIndex]
            executedPollCount += 1
            XCTAssertLessThanOrEqual(executedPollCount, 12)
            clock = clock.addingTimeInterval(poll.delay)
            poll.action()
        }

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            coordinator.state == .pendingReview
        })
        XCTAssertEqual(
            controller.liveMemoryRecoveryPresentationForTesting().statusIdentifier,
            "echoLiveMemoryRecoveryPendingReview"
        )
        XCTAssertFalse(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.isEmpty)
        XCTAssertTrue(
            OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.allSatisfy {
                $0.httpMethod == "GET"
            }
        )
        let decodedEvents = readEvents.filter {
            $0.resource == .liveMemoryRecoveryStatus
                && $0.event == "resourceContractDecoded"
        }
        XCTAssertEqual(
            decodedEvents.filter { $0.traceID == activeControllerTraceID }.map(\.attempt),
            Array(1...7)
        )
        XCTAssertEqual(followUpStore.records(for: lease).count, 1)
    }

    @MainActor
