                harness.decision(.ownerTruthCandidateReview).allowed
            }
        )
        coordinator.start()

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            coordinator.state == .pendingReview
        })
        XCTAssertEqual(authRefreshCount, 1)
        XCTAssertEqual(statusGETCount, 2)
        XCTAssertEqual(Set(diagnostics.map(\.traceID)).count, 1)
        XCTAssertEqual(Set(diagnostics.map(\.attempt)), [1, 2])
        XCTAssertEqual(
            diagnostics.last(where: { $0.event == "resourceContractDecoded" })?.attempt,
            2
