    func testB6DeterminateAccessAndContractBlocksCannotBeOverwrittenByOldDeadline() throws {
        enum Mode: CaseIterable { case access, contract }

        for mode in Mode.allCases {
            let (runtime, lease) = try makeActiveRuntime()
            let batchID = recordID("00000000-0000-0000-0000-0000000007e8")
            let client = DeferredB6RecoveryReadClient()
            var scheduled: [(TimeInterval, DispatchWorkItem)] = []
            let coordinator = EchoLiveMemoryRecoveryCoordinator(
                plan: EchoLiveMemoryRecoveryPlan(
                    accountLease: lease,
                    productSessionID: "b6-determinate-\(mode)",
                    threadID: nil,
                    sessionID: nil,
                    reviewBatchID: batchID,
                    checkpointPhase: .admitted,
                    sources: [.followUp],
                    localRecordRevision: "revision-1"
                ),
                client: client,
                accountLeaseRuntime: runtime,
                organizationStatusTimeout: 30,
                candidateReviewPolicyAvailable: { true },
                schedule: { delay, action in
                    let item = DispatchWorkItem(block: action)
                    scheduled.append((delay, item))
                    return item
                }
            )
            coordinator.start()
            let expected: EchoLiveMemoryRecoveryState
            switch mode {
            case .access:
                runtime.publish(session: accountSession(
                    subjectId: "b6-other-subject",
                    vaultId: "b6-other-vault",
                    generation: 2,
                    generationID: UUID()
                ))
                expected = .accessBlocked(.staleLease)
                client.completeStatus(
                    at: 0,
                    with: .success(try interviewCandidateProposalStatus(
                        vaultID: lease.vaultId,
                        reviewBatchID: batchID,
                        candidateExtractionState: .succeeded,
                        candidateReviewState: .reviewReady
                    ))
                )
            case .contract:
                expected = .contractBlocked(.bindingMismatch)
                client.completeStatus(
                    at: 0,
                    with: .success(try interviewCandidateProposalStatus(
                        vaultID: lease.vaultId,
                        reviewBatchID: recordID(
                            "00000000-0000-0000-0000-0000000007e9"
                        ),
                        candidateExtractionState: .succeeded,
                        candidateReviewState: .reviewReady
                    ))
                )
            }
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                coordinator.state == expected
            }, String(describing: mode))
            try XCTUnwrap(scheduled.first(where: { $0.0 >= 29 })).1.perform()
            XCTAssertEqual(coordinator.state, expected, String(describing: mode))
        }
    }

