    func testB6RecoveryMapsProgressTerminalAndTransientFailuresWithoutWrites() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let batchID = recordID("00000000-0000-0000-0000-0000000007b4")
        let progressCases: [(
            String,
            OwnerTruthInterviewCandidateProposalExtractionState,
            OwnerTruthInterviewCandidateProposalExtractionJobState,
            OwnerTruthInterviewCandidateProposalReviewState,
            EchoLiveMemoryRecoveryState
        )] = [
            ("queued", .requested, .pending, .notReady, .queued),
            ("organizing", .requested, .leased, .notReady, .organizing),
            ("retry", .requested, .retryWait, .notReady, .retryWaiting(attempt: 2, maxAttempts: 3)),
            ("review", .succeeded, .succeeded, .reviewReady, .pendingReview),
            ("empty", .succeeded, .succeeded, .noCandidates, .empty),
            ("failed", .failed, .failed, .extractionFailed, .terminalFailure(code: "modelRejected")),
            ("quarantined", .quarantined, .failed, .extractionQuarantined, .quarantined),
        ]

        for testCase in progressCases {
            let client = InterviewNaturalInputClientSpy()
            client.proposalStatusHandler = { [unowned self] requestedBatchID in
                Result {
                    try OwnerTruthInterviewCandidateProposalStatus(
                        backendJSONObject: self.interviewCandidateProposalStatusPayload(
                            vaultID: lease.vaultId,
                            reviewBatchID: requestedBatchID,
                            candidateExtractionState: testCase.1,
                            candidateExtractionJobState: testCase.2,
                            candidateExtractionAttempt: testCase.0 == "retry" ? 2 : 1,
                            candidateExtractionFailureCode: testCase.0 == "failed"
                                ? "modelRejected"
                                : NSNull(),
                            candidateReviewState: testCase.3
                        ),
                        expectedVaultID: try XCTUnwrap(OwnerTruthVaultID(lease.vaultId)),
                        expectedReviewBatchID: requestedBatchID
                    )
                }
            }
            let coordinator = EchoLiveMemoryRecoveryCoordinator(
                plan: EchoLiveMemoryRecoveryPlan(
                    accountLease: lease,
                    productSessionID: "b6-state-\(testCase.0)",
                    threadID: nil,
                    sessionID: nil,
                    reviewBatchID: batchID,
                    checkpointPhase: .admitted,
                    sources: [.followUp],
                    localRecordRevision: "revision-1"
                ),
                client: client,
                accountLeaseRuntime: runtime,
                organizationStatusTimeout: 30,
                candidateReviewPolicyAvailable: { true },
                schedule: { _, action in DispatchWorkItem(block: action) }
            )
            coordinator.start()
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                coordinator.state == testCase.4
            }, testCase.0)
            XCTAssertTrue(client.startCommands.isEmpty, testCase.0)
            XCTAssertTrue(client.endCommands.isEmpty, testCase.0)
            XCTAssertTrue(client.acknowledgementCommands.isEmpty, testCase.0)
            XCTAssertTrue(client.admissionCommands.isEmpty, testCase.0)
        }

        let transientCases: [(String, Error, EchoLiveMemoryRecoveryState)] = [
            ("offline", URLError(.notConnectedToInternet), .statusUnknown(.offline)),
            ("dns", URLError(.dnsLookupFailed), .statusUnknown(.dnsFailure)),
            ("tls", URLError(.secureConnectionFailed), .statusUnknown(.tlsFailure)),
            ("timeout", URLError(.timedOut), .statusUnknown(.timeout)),
            ("server", DreamJourneyBackendClient.ClientError.backendError(
                statusCode: 503,
                context: DreamJourneyBackendClient.BackendErrorContext(detail: "safe")
            ), .statusUnknown(.unknown)),
            ("missing", DreamJourneyBackendClient.ClientError.backendError(
                statusCode: 404,
                context: DreamJourneyBackendClient.BackendErrorContext(detail: "safe")
            ), .statusUnknown(.notObserved)),
            ("policy", DreamJourneyBackendClient.ClientError.featurePolicyDenied(feature: "candidate", reason: "expiredPolicyCache"), .waitingForPolicy),
        ]
        for testCase in transientCases {
            let client = InterviewNaturalInputClientSpy()
            client.proposalStatusHandler = { _ in .failure(testCase.1) }
            let coordinator = EchoLiveMemoryRecoveryCoordinator(
                plan: EchoLiveMemoryRecoveryPlan(
                    accountLease: lease,
                    productSessionID: "b6-failure-\(testCase.0)",
                    threadID: nil,
                    sessionID: nil,
                    reviewBatchID: batchID,
                    checkpointPhase: .admitted,
                    sources: [.followUp],
                    localRecordRevision: "revision-1"
                ),
                client: client,
                accountLeaseRuntime: runtime,
                organizationStatusTimeout: 30,
                candidateReviewPolicyAvailable: { true }
            )
            coordinator.start()
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                coordinator.state == testCase.2
            }, testCase.0)
            XCTAssertTrue(client.endCommands.isEmpty, testCase.0)
            XCTAssertTrue(client.acknowledgementCommands.isEmpty, testCase.0)
            XCTAssertTrue(client.admissionCommands.isEmpty, testCase.0)
        }
    }

