    func testB6RecoveryMergesAllDurableCoordinatesAndIsolatesBatchConflict() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let threadID = recordID("00000000-0000-0000-0000-0000000007c1")
        let sessionID = recordID("00000000-0000-0000-0000-0000000007c2")
        let batchID = recordID("00000000-0000-0000-0000-0000000007c3")
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("b6-merged-coordinates-\(UUID().uuidString)")
        let defaultsName = "b6-merged-coordinates-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        defer {
            try? FileManager.default.removeItem(at: root)
            defaults.removePersistentDomain(forName: defaultsName)
        }
        let checkpointStore = EchoLiveMemoryCompletionCheckpointStore(rootDirectory: root)
        let followUpStore = EchoLiveMemoryFollowUpStore(defaults: defaults)
        let outboxStore = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root.appendingPathComponent("outbox")
        )
        let productSessionID = "b6-all-sources"
        let endCommand = try OwnerTruthInterviewEndCommand(
            commandID: "b6-all-sources-end",
            threadID: threadID,
            sessionID: sessionID,
            expectedThreadVersion: 2,
            expectedSessionVersion: 3,
            lastClientSequenceNumber: 1
        )
        try checkpointStore.prepareEnd(endCommand, productSessionID: productSessionID, for: lease)
        let endReceipt = try interviewNaturalInputReceipt(vaultID: vaultID, end: endCommand)
        try checkpointStore.acceptEnd(endReceipt, productSessionID: productSessionID, for: lease)
        let acknowledgement = try OwnerTruthInterviewReviewBatchAcknowledgementCommand(
            commandID: "b6-all-sources-ack",
            reviewBatchID: batchID,
            threadID: threadID,
            sessionID: sessionID,
            expectedSessionVersion: endReceipt.sessionVersion,
            expectedReviewBatchVersion: 1
        )
        try checkpointStore.prepareAcknowledgement(
            acknowledgement,
            productSessionID: productSessionID,
            for: lease
        )
        try followUpStore.upsert(
            productSessionID: productSessionID,
            reviewBatchID: batchID,
            for: lease
        )
        _ = try outboxStore.enqueue(
            role: .owner,
            text: "隔离合成多来源恢复内容。",
            for: lease,
            productSessionID: productSessionID
        )

        let client = InterviewNaturalInputClientSpy()
        client.proposalStatusHandler = { [unowned self] requestedBatchID in
            Result {
                try self.interviewCandidateProposalStatus(
                    vaultID: lease.vaultId,
                    reviewBatchID: requestedBatchID,
                    candidateExtractionState: .succeeded,
                    candidateReviewState: .reviewReady
                )
            }
        }
        let service = EchoLiveMemoryRecoveryService(registry: EchoLiveMemoryRecoveryRegistry())
        let result = service.resumePendingWorkflows(
            accountLease: lease,
            excluding: [],
            client: client,
            accountLeaseRuntime: runtime,
            liveTurnOutboxStore: outboxStore,
            followUpStore: followUpStore,
            completionCheckpointStore: checkpointStore,
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let recovery = try XCTUnwrap(result.coordinators.first)
        XCTAssertEqual(recovery.plan.sources, [.completionCheckpoint, .followUp, .liveTurnOutbox])
        XCTAssertEqual(recovery.plan.reviewBatchID, batchID)
        recovery.start()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            recovery.state == .pendingReview
        })
        XCTAssertTrue(client.endCommands.isEmpty)
        XCTAssertTrue(client.acknowledgementCommands.isEmpty)
        XCTAssertTrue(client.admissionCommands.isEmpty)

        try followUpStore.upsert(
            productSessionID: productSessionID,
            reviewBatchID: recordID("00000000-0000-0000-0000-0000000007c4"),
            for: lease
        )
        let conflicted = EchoLiveMemoryRecoveryService(
            registry: EchoLiveMemoryRecoveryRegistry()
        ).resumePendingWorkflows(
            accountLease: lease,
            excluding: [],
            client: client,
            accountLeaseRuntime: runtime,
            liveTurnOutboxStore: outboxStore,
            followUpStore: followUpStore,
            completionCheckpointStore: checkpointStore,
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        XCTAssertTrue(conflicted.coordinators.isEmpty)
        XCTAssertEqual(conflicted.blockedRecords, [
            EchoLiveMemoryRecoveryBlockedRecord(
                productSessionID: productSessionID,
                reason: .bindingMismatch
            ),
        ])
    }

