    @MainActor
    func testNewestBlockedColdStartSceneDoesNotPresentOlderValidScene() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("blocked-newer-scene-\(UUID().uuidString)")
        let defaultsName = "blocked-newer-scene-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        defer {
            try? FileManager.default.removeItem(at: root)
            defaults.removePersistentDomain(forName: defaultsName)
        }
        let oldTime = Date(timeIntervalSince1970: 1_790_000_000)
        let newTime = oldTime.addingTimeInterval(300)
        var clock = oldTime
        let checkpoints = EchoLiveMemoryCompletionCheckpointStore(
            rootDirectory: root.appendingPathComponent("checkpoints"),
            now: { clock }
        )
        let oldEnd = try OwnerTruthInterviewEndCommand(
            commandID: "old-scene-end",
            threadID: OwnerTruthRecordID(rawValue: UUID()),
            sessionID: OwnerTruthRecordID(rawValue: UUID()),
            expectedThreadVersion: 2,
            expectedSessionVersion: 2,
            lastClientSequenceNumber: 1
        )
        try checkpoints.prepareEnd(oldEnd, productSessionID: "old-scene", for: lease)
        clock = newTime
        let newEnd = try OwnerTruthInterviewEndCommand(
            commandID: "new-scene-end",
            threadID: OwnerTruthRecordID(rawValue: UUID()),
            sessionID: OwnerTruthRecordID(rawValue: UUID()),
            expectedThreadVersion: 2,
            expectedSessionVersion: 2,
            lastClientSequenceNumber: 1
        )
        try checkpoints.prepareEnd(newEnd, productSessionID: "new-scene", for: lease)
        let endReceipt = try interviewNaturalInputReceipt(vaultID: vaultID, end: newEnd)
