            threadID: newEnd.threadID,
            sessionID: newEnd.sessionID,
            expectedSessionVersion: endReceipt.sessionVersion,
            expectedReviewBatchVersion: 1
        )
        try checkpoints.prepareAcknowledgement(
            acknowledgement, productSessionID: "new-scene", for: lease
        )
        let followUps = EchoLiveMemoryFollowUpStore(defaults: defaults)
        try followUps.upsert(
            productSessionID: "new-scene",
            reviewBatchID: OwnerTruthRecordID(rawValue: UUID()),
            for: lease
        )
        let client = InterviewNaturalInputClientSpy()
        let result = EchoLiveMemoryRecoveryService(
            registry: EchoLiveMemoryRecoveryRegistry()
        ).resumePendingWorkflows(
            accountLease: lease, excluding: [], client: client,
            accountLeaseRuntime: runtime,
            liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(
                rootDirectory: root.appendingPathComponent("outbox")
            ),
            followUpStore: followUps,
            completionCheckpointStore: checkpoints,
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        XCTAssertEqual(result.coordinators.map(\.trackedProductSessionID), ["old-scene"])
        XCTAssertEqual(result.blockedRecords, [EchoLiveMemoryRecoveryBlockedRecord(
