    @MainActor
    func testB6CompletionObservationPersistenceFailurePreservesLegacyCoordinateForFreshRead() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("b6-completion-observation-failure-\(UUID().uuidString)")
        let defaultsName = "b6-completion-observation-failure-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        defer {
            try? FileManager.default.removeItem(at: root)
            defaults.removePersistentDomain(forName: defaultsName)
        }
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
        let blockedV2Root = root.appendingPathComponent("follow-up-v2-blocked")
        try Data("not-a-directory".utf8).write(to: blockedV2Root, options: .atomic)
        let followUpStore = EchoLiveMemoryFollowUpStore(
            defaults: defaults,
            rootDirectory: blockedV2Root
        )
        let batchID = recordID("00000000-0000-0000-0000-0000000007eb")
        let workflow = "b6-completion-observation-write-failure"
        let timestamp = Date(timeIntervalSince1970: 1_700_000_100)
        let legacyRecord = EchoLiveMemoryFollowUpRecord(
            productSessionID: workflow,
            reviewBatchID: batchID.rawValue,
            createdAt: timestamp,
            updatedAt: timestamp
        )
        let scope = [lease.subjectId, lease.vaultId, lease.authorityEpoch]
            .joined(separator: "|")
        let digest = SHA256.hash(data: Data(scope.utf8)).map {
            String(format: "%02x", $0)
        }.joined()
        let legacyKey = "echo.live-memory-follow-up.v1.\(digest)"
        let legacyData = try JSONEncoder().encode([legacyRecord])
        defaults.set(legacyData, forKey: legacyKey)

        let client = InterviewNaturalInputClientSpy()
        client.proposalStatusHandler = { [unowned self] requestedBatchID in
            Result {
                try self.interviewCandidateProposalStatus(
                    vaultID: lease.vaultId,
                    reviewBatchID: requestedBatchID,
                    candidateExtractionState: .succeeded,
                    candidateReviewState: .reviewReady
                )
            }
        }
        let makeResult: (EchoLiveMemoryRecoveryRegistry) -> EchoLiveMemoryRecoveryResult = {
            registry in
            EchoLiveMemoryRecoveryService(registry: registry).resumePendingWorkflows(
                accountLease: lease,
                excluding: [],
                client: client,
                accountLeaseRuntime: runtime,
                liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(
                    rootDirectory: root.appendingPathComponent("outbox")
                ),
                followUpStore: followUpStore,
                completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                    rootDirectory: root.appendingPathComponent("checkpoints")
                ),
                naturalInputPolicyAvailable: { true },
                candidateReviewPolicyAvailable: { true }
            )
        }

        var firstController: EchoViewController? = EchoViewController()
        let firstCoordinator = try XCTUnwrap(
            makeResult(EchoLiveMemoryRecoveryRegistry()).coordinators.first
        )
        firstController?.installLiveMemoryRecoveryForTesting(
            accountLease: lease,
            coordinator: firstCoordinator
        )
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            firstCoordinator.state == .pendingReview
        })
        XCTAssertEqual(defaults.data(forKey: legacyKey), legacyData)
        XCTAssertEqual(followUpStore.scan(for: lease).records, [legacyRecord])
        firstController = nil

        let secondCoordinator = try XCTUnwrap(
            makeResult(EchoLiveMemoryRecoveryRegistry()).coordinators.first
        )
        let secondController = EchoViewController()
        secondController.installLiveMemoryRecoveryForTesting(
            accountLease: lease,
            coordinator: secondCoordinator
        )
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            client.proposalStatusRequestCount == 2 && secondCoordinator.state == .pendingReview
        })
        XCTAssertEqual(defaults.data(forKey: legacyKey), legacyData)
        XCTAssertTrue(client.startCommands.isEmpty)
        XCTAssertTrue(client.endCommands.isEmpty)
        XCTAssertTrue(client.acknowledgementCommands.isEmpty)
        XCTAssertTrue(client.admissionCommands.isEmpty)
    }

