    @MainActor
    func testClosingOutboxWithFrozenStartIsDiscoveredBeforeOlderWorkflowReadOnly() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("live-closing-outbox-discovery-\(UUID().uuidString)")
        let defaultsName = "live-closing-outbox-discovery-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        defer {
            try? FileManager.default.removeItem(at: root)
            defaults.removePersistentDomain(forName: defaultsName)
        }
        let oldSession = "historical-completed-workflow"
        let currentSession = "current-closing-outbox"
        let followUpStore = EchoLiveMemoryFollowUpStore(
            defaults: defaults, rootDirectory: root.appendingPathComponent("follow-up"),
            now: { Date(timeIntervalSince1970: 1_000) }
        )
        try followUpStore.upsert(
            productSessionID: oldSession,
            reviewBatchID: recordID("00000000-0000-0000-0000-0000000007db"),
            for: lease
        )
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root.appendingPathComponent("outbox"),
            now: { Date(timeIntervalSince1970: 2_000) }
        )
        let command = try OwnerTruthInterviewNaturalInputStartCommand(
            commandID: "current-closing-start-command",
            threadID: recordID("00000000-0000-0000-0000-0000000007dc"),
            sessionID: recordID("00000000-0000-0000-0000-0000000007dd"),
            entryMode: .live,
            productSessionID: currentSession
        )
        _ = try outbox.prepareStart(command, for: lease, productSessionID: currentSession)
        let snapshot = try outbox.enqueue(
            role: .owner,
            text: "当前关闭场的合成正文。",
            for: lease,
            productSessionID: currentSession
        )
        _ = try outbox.markClosing(
            lastClientSequenceNumber: snapshot.lastClientSequenceNumber,
            for: lease,
            productSessionID: currentSession
        )
        let client = InterviewNaturalInputClientSpy()
        client.pendingReviewInboxHandler = { [unowned self] in
            Result { try self.pendingReviewBatchInbox(vaultID: lease.vaultId, batches: []) }
        }
        let result = EchoLiveMemoryRecoveryService(
            registry: EchoLiveMemoryRecoveryRegistry()
        ).resumePendingWorkflows(
            accountLease: lease,
            excluding: [],
            client: client,
            accountLeaseRuntime: runtime,
            liveTurnOutboxStore: outbox,
            followUpStore: followUpStore,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        XCTAssertEqual(result.coordinators.first?.trackedProductSessionID, currentSession)
        XCTAssertFalse(result.blockedRecords.contains {
            $0.productSessionID == currentSession
        })
        guard let current = result.coordinators.first,
              current.trackedProductSessionID == currentSession else { return }
        let controller = EchoViewController()
        controller.installLiveMemoryRecoveryForTesting(
            accountLease: lease, coordinator: current
        )
        if let historical = result.coordinators.first(where: {
            $0.trackedProductSessionID == oldSession
        }) {
            controller.addLiveMemoryRecoveryForTesting(
                accountLease: lease, coordinator: historical
            )
        }
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            client.liveDeliveryStatusRequestCount == 1
                && current.state == .statusUnknown(.notObserved)
        })
        XCTAssertFalse(controller.liveMemoryRecoveryPresentationForTesting().actionVisible)
        controller.tapLiveMemoryRecoveryVerificationForTesting()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            client.liveDeliveryStatusRequestCount == 2
        })
        XCTAssertEqual(client.pendingReviewInboxRequestCount, 0)
        XCTAssertTrue(client.startCommands.isEmpty)
        XCTAssertTrue(client.endCommands.isEmpty)
        XCTAssertTrue(client.acknowledgementCommands.isEmpty)
        XCTAssertTrue(client.admissionCommands.isEmpty)
        XCTAssertEqual(
            try outbox.load(for: lease, productSessionID: currentSession)?.preparedStartCommand,
            command
        )
    }

    @MainActor
    func testClosingOutboxColdStartUsesRealBackendClientAndRejectsForeignDeliveryBinding() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("closing-outbox-real-http-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let productSessionID = "closing-outbox-real-http"
        let threadID = recordID("00000000-0000-0000-0000-0000000007e1")
        let sessionID = recordID("00000000-0000-0000-0000-0000000007e2")
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root.appendingPathComponent("outbox")
        )
        let start = try OwnerTruthInterviewNaturalInputStartCommand(
            commandID: "closing-outbox-real-http-start",
            threadID: threadID,
            sessionID: sessionID,
            entryMode: .live,
            productSessionID: productSessionID
        )
        _ = try outbox.prepareStart(start, for: lease, productSessionID: productSessionID)
        let queued = try outbox.enqueue(
            role: .owner, text: "Synthetic cold-start evidence.",
            for: lease, productSessionID: productSessionID
        )
        _ = try outbox.markClosing(
            lastClientSequenceNumber: queued.lastClientSequenceNumber,
            for: lease, productSessionID: productSessionID
        )
        let auth = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        let policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "cold-start-read-v1",
            policyRevision: 1,
            emergencyRevision: 1,
            expiresAt: Date().addingTimeInterval(300),
            featureEnabled: true,
            releaseVisible: true,
            reason: "ownerReadEnabled"
        )
        let evaluator = FeatureGateEvaluator()
        let decision: (DJFeature) -> FeatureDecision = { feature in
            evaluator.capture(
                feature: feature, risk: .ownerTextCore, purpose: .request,
                localEnabled: true, qaSyntheticOverride: false,
                accountGeneration: FeatureGateService.accountGeneration(
                    forIdentitySource: auth.sessionId
                ),
                policy: policy
            )
        }
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { auth },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: decision,
            freshFeatureDecision: decision,
            featureDecisionRevalidator: { captured in
                evaluator.revalidateForRequest(
                    captured: captured, localEnabled: true,
                    accountGeneration: FeatureGateService.accountGeneration(
                        forIdentitySource: auth.sessionId
                    ),
                    currentPolicy: policy
                )
            },
            accountLeaseRuntime: runtime
        )
        var methods: [String] = []
        var requestedPaths: [String] = []
        let startHash = SHA256.hash(data: Data(start.commandID.utf8)).map {
            String(format: "%02x", $0)
        }.joined()
        var foreign = true
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            methods.append(request.httpMethod ?? "")
            requestedPaths.append(request.url?.path ?? "")
            let body = try! JSONSerialization.data(withJSONObject: [
                "schemaVersion": OwnerTruthLiveDeliveryStatus.schemaVersion,
                "vaultId": lease.vaultId,
                "productSessionId": productSessionID,
                "session": [
                    "threadId": threadID.rawValue.uuidString.lowercased(),
                    "sessionId": sessionID.rawValue.uuidString.lowercased(),
                    "state": "active", "boundary": "open",
                    "threadVersion": 1, "sessionVersion": 1,
                    "authorityEpoch": 0, "continuousClientSequence": 0,
                    "closeRequestedClientSequence": NSNull(),
                ],
                "observedAt": "2026-09-23T00:00:00Z",
                "window": [
                    "fromClientSequence": 1, "limit": 64,
                    "missingClientSequences": [1],
                    "nextFromClientSequence": NSNull(),
                ],
                "deliveries": [],
                "operations": [[
                    "operation": OwnerTruthLiveDeliveryOperationKind.startInterviewSession.rawValue,
                    "commandIdHash": foreign ? String(repeating: "0", count: 64) : startHash,
                    "receiptId": "00000000-0000-0000-0000-0000000007e3",
                    "threadId": threadID.rawValue.uuidString.lowercased(),
                    "sessionId": sessionID.rawValue.uuidString.lowercased(),
                    "resultState": OwnerTruthInterviewSessionLifecycle.active.rawValue,
                ]],
            ])
            loader.respond(statusCode: 200, body: body)
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
        let result = EchoLiveMemoryRecoveryService(
            registry: EchoLiveMemoryRecoveryRegistry()
        ).resumePendingWorkflows(
            accountLease: lease, excluding: [], client: client,
            accountLeaseRuntime: runtime,
            liveTurnOutboxStore: outbox,
            followUpStore: EchoLiveMemoryFollowUpStore(
                rootDirectory: root.appendingPathComponent("follow-up")
            ),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let coordinator = try XCTUnwrap(result.coordinators.first)
        let controller = EchoViewController()
        controller.installLiveMemoryRecoveryForTesting(
            accountLease: lease, coordinator: coordinator
        )
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { !methods.isEmpty })
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            coordinator.state == .contractBlocked(.bindingMismatch)
        }, "state=\(coordinator.state), methods=\(methods)")
        let rejectedReadCount = methods.count
        XCTAssertGreaterThanOrEqual(rejectedReadCount, 1)
        XCTAssertLessThanOrEqual(rejectedReadCount, 2)
        XCTAssertTrue(methods.allSatisfy { $0 == "GET" })
        XCTAssertTrue(requestedPaths.allSatisfy { $0.hasSuffix("/live-delivery-status") })
        foreign = false
        let resumed = EchoLiveMemoryRecoveryService(
            registry: EchoLiveMemoryRecoveryRegistry()
        ).resumePendingWorkflows(
            accountLease: lease, excluding: [], client: client,
            accountLeaseRuntime: runtime,
            liveTurnOutboxStore: outbox,
            followUpStore: EchoLiveMemoryFollowUpStore(
                rootDirectory: root.appendingPathComponent("follow-up")
            ),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let resumedCoordinator = try XCTUnwrap(resumed.coordinators.first)
        let reopened = EchoViewController()
        reopened.installLiveMemoryRecoveryForTesting(
            accountLease: lease, coordinator: resumedCoordinator
        )
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            resumedCoordinator.state == .statusUnknown(.notObserved)
        }, "state=\(resumedCoordinator.state), methods=\(methods)")
        XCTAssertGreaterThan(methods.count, rejectedReadCount)
        XCTAssertLessThanOrEqual(methods.count, rejectedReadCount + 2)
        XCTAssertTrue(methods.allSatisfy { $0 == "GET" })
        XCTAssertTrue(requestedPaths.allSatisfy { $0.hasSuffix("/live-delivery-status") })
        XCTAssertEqual(
            try outbox.load(for: lease, productSessionID: productSessionID)?.preparedStartCommand,
            start
        )
    }

    func testLiveRecoveryClassifiesCheckpointFailuresPerWorkflowWithoutRepairOrReplay() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let threadID = recordID("00000000-0000-0000-0000-00000000072a")
        let sessionID = recordID("00000000-0000-0000-0000-00000000072b")
        let endCommand = try OwnerTruthInterviewEndCommand(
            commandID: "checkpoint-scan-end-command",
            threadID: threadID,
            sessionID: sessionID,
            expectedThreadVersion: 3,
            expectedSessionVersion: 4,
            lastClientSequenceNumber: 1
        )
        let cases: [(String, EchoLiveMemoryRecoveryBlockReason, (([String: Any]) -> [String: Any])?)] = [
            ("decode", .checkpointDecodeInvalid, nil),
            ("schema", .checkpointSchemaUnsupported, { object in
                var changed = object
                changed["schemaVersion"] = "echo-live-memory-completion-v0"
                return changed
            }),
            ("scope", .checkpointScopeMismatch, { object in
                var changed = object
                changed["productSessionID"] = "foreign-product-session"
                return changed
            }),
        ]

        for (name, expectedReason, mutation) in cases {
            let root = FileManager.default.temporaryDirectory
                .appendingPathComponent("echo-live-checkpoint-scan-\(name)-\(UUID().uuidString)")
            let defaultsName = "echo-live-checkpoint-scan-\(name)-\(UUID().uuidString)"
            let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
            defer {
                try? FileManager.default.removeItem(at: root)
                defaults.removePersistentDomain(forName: defaultsName)
            }
            let outbox = OwnerTruthInterviewLiveTurnOutboxStore(
                rootDirectory: root.appendingPathComponent("outbox")
            )
            let checkpointStore = EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            )
            let productSessionID = "checkpoint-scan-\(name)"
            let snapshot = try outbox.enqueue(
                role: .owner,
                text: "隔离合成检查点内容。",
                for: lease,
                productSessionID: productSessionID
            )
            _ = try outbox.markClosing(
                lastClientSequenceNumber: snapshot.lastClientSequenceNumber,
                for: lease,
                productSessionID: productSessionID
            )
            try checkpointStore.prepareEnd(
                endCommand,
                productSessionID: productSessionID,
                for: lease
            )
            let checkpointURL = try XCTUnwrap(
                FileManager.default.enumerator(
                    at: root.appendingPathComponent("completion"),
                    includingPropertiesForKeys: nil
                )?.compactMap { $0 as? URL }.first { $0.pathExtension == "json" }
            )
            let originalData = try Data(contentsOf: checkpointURL)
            if let mutation {
                let object = try XCTUnwrap(
                    JSONSerialization.jsonObject(with: originalData) as? [String: Any]
                )
                let changed = try XCTUnwrap(mutation(object))
                try JSONSerialization.data(withJSONObject: changed, options: [.sortedKeys])
                    .write(to: checkpointURL, options: .atomic)
            } else {
                try Data("{".utf8).write(to: checkpointURL, options: .atomic)
            }

            let client = InterviewNaturalInputClientSpy()
            let result = EchoLiveMemoryRecoveryService().resumePendingWorkflows(
                accountLease: lease,
                excluding: [],
                client: client,
                accountLeaseRuntime: runtime,
                liveTurnOutboxStore: outbox,
                followUpStore: EchoLiveMemoryFollowUpStore(defaults: defaults),
                completionCheckpointStore: checkpointStore,
                naturalInputPolicyAvailable: { true },
                candidateReviewPolicyAvailable: { true }
            )

            XCTAssertTrue(result.coordinators.isEmpty, name)
            XCTAssertEqual(
                result.blockedRecords,
                [EchoLiveMemoryRecoveryBlockedRecord(
                    productSessionID: productSessionID,
                    reason: expectedReason
                )],
                name
            )
            XCTAssertTrue(client.endCommands.isEmpty, name)
            XCTAssertNotNil(try outbox.load(for: lease, productSessionID: productSessionID), name)
            XCTAssertTrue(FileManager.default.fileExists(atPath: checkpointURL.path), name)
        }
    }

