    func testBackendGeneratedCandidateStatusV3FixturesDecodeExactRecoveryStates() throws {
        let fixtureURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent(
                "Fixtures/OwnerTruth/owner-truth-candidate-status-v3-backend-generated.json"
            )
        let data = try Data(contentsOf: fixtureURL)
        let root = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: data) as? [String: Any]
        )
        XCTAssertEqual(root["syntheticDataOnly"] as? Bool, true)
        XCTAssertEqual(
            root["generatedBy"] as? String,
            "scripts/generate-owner-truth-candidate-status-ios-fixtures.py"
        )
        XCTAssertEqual((root["backendHead"] as? String)?.count, 40)
        XCTAssertEqual((root["productionSerializerSHA256"] as? String)?.count, 64)
        XCTAssertEqual((root["productionRouteSHA256"] as? String)?.count, 64)
        XCTAssertEqual(root["generatedVia"] as? String, "fastapiStatusRoute")
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(root["vaultId"] as? String ?? ""))
        let batchUUID = try XCTUnwrap(
            UUID(uuidString: root["reviewBatchId"] as? String ?? "")
        )
        let batchID = OwnerTruthRecordID(rawValue: batchUUID)
        let cases = try XCTUnwrap(root["cases"] as? [String: [String: Any]])

        let queued = try OwnerTruthInterviewCandidateProposalStatus(
            backendJSONObject: try XCTUnwrap(cases["queued"]),
            expectedVaultID: vaultID,
            expectedReviewBatchID: batchID
        )
        XCTAssertEqual(queued.candidateExtractionJobState, .pending)
        XCTAssertEqual(queued.candidateReviewState, .notReady)

        let retryWaiting = try OwnerTruthInterviewCandidateProposalStatus(
            backendJSONObject: try XCTUnwrap(cases["retryWaiting"]),
            expectedVaultID: vaultID,
            expectedReviewBatchID: batchID
        )
        XCTAssertEqual(retryWaiting.candidateExtractionJobState, .retryWait)
        XCTAssertEqual(retryWaiting.candidateExtractionAttempt, 1)
        XCTAssertTrue(retryWaiting.candidateExtractionRetryable)

        let failed = try OwnerTruthInterviewCandidateProposalStatus(
            backendJSONObject: try XCTUnwrap(cases["failed"]),
            expectedVaultID: vaultID,
            expectedReviewBatchID: batchID
        )
        XCTAssertEqual(failed.candidateExtractionState, .failed)
        XCTAssertEqual(failed.candidateReviewState, .extractionFailed)
        XCTAssertEqual(
            failed.candidateExtractionFailureCode,
            "candidateExtraction.live.supportValidate.factOmitted"
        )

        let reviewReady = try OwnerTruthInterviewCandidateProposalStatus(
            backendJSONObject: try XCTUnwrap(cases["reviewReady"]),
            expectedVaultID: vaultID,
            expectedReviewBatchID: batchID
        )
        XCTAssertEqual(reviewReady.candidateExtractionState, .succeeded)
        XCTAssertEqual(reviewReady.candidateExtractionJobState, .succeeded)
        XCTAssertEqual(reviewReady.candidateReviewState, .reviewReady)
    }

    @MainActor
    func testBackendRouteGeneratedStatusV3ResponsesDriveRealRecoveryController() throws {
        let fixtureURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent(
                "Fixtures/OwnerTruth/owner-truth-candidate-status-v3-backend-generated.json"
            )
        let rootObject = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: Data(contentsOf: fixtureURL))
                as? [String: Any]
        )
        let fixtureVaultID = try XCTUnwrap(rootObject["vaultId"] as? String)
        let fixtureBatchID = try XCTUnwrap(rootObject["reviewBatchId"] as? String)
        let batchID = recordID(fixtureBatchID)
        let cases = try XCTUnwrap(rootObject["cases"] as? [String: [String: Any]])
        let expectedIdentifiers = [
            "queued": "echoLiveMemoryRecoveryQueued",
            "retryWaiting": "echoLiveMemoryRecoveryRetryWaiting",
            "failed": "echoLiveMemoryRecoveryTerminalFailure",
            "reviewReady": "echoLiveMemoryRecoveryPendingReview",
        ]

        for name in ["queued", "retryWaiting", "failed", "reviewReady"] {
            let runtime = AccountLeaseRuntime(authorityEpoch: "epoch-v1")
            runtime.publish(session: accountSession(
                subjectId: fixtureVaultID,
                vaultId: fixtureVaultID,
                generation: 1,
                generationID: UUID()
            ))
            let lease = try XCTUnwrap(runtime.capture(forSubjectId: fixtureVaultID))
            let caseRoot = FileManager.default.temporaryDirectory
                .appendingPathComponent("status-route-fixture-\(name)-\(UUID().uuidString)")
            let defaultsName = "status-route-fixture-\(name)-\(UUID().uuidString)"
            let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
            defer {
                try? FileManager.default.removeItem(at: caseRoot)
                defaults.removePersistentDomain(forName: defaultsName)
                OwnerTruthReviewReadyHTTPURLProtocol.reset()
            }
            let followUpStore = EchoLiveMemoryFollowUpStore(
                defaults: defaults,
                rootDirectory: caseRoot.appendingPathComponent("follow-up")
            )
            try followUpStore.upsert(
                productSessionID: "status-route-fixture-\(name)",
                reviewBatchID: batchID,
                for: lease
            )
            let policyStore = ReleasePolicyStore(userDefaults: defaults)
            try saveCandidateReleasePolicy(
                candidateReleasePolicyPayload(
                    version: "status-route-fixture-policy-v1",
                    revision: 191,
                    expiresAt: "2099-01-01T00:00:00Z"
                ),
                store: policyStore,
                scope: candidateReleasePolicyScope(lease: lease)
            )
            let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: fixtureVaultID)
            let harness = try makeCandidatePolicyTestClient(
                runtime: runtime,
                lease: lease,
                authSession: { authSession },
                store: policyStore
            )
            let responseBody = try JSONSerialization.data(
                withJSONObject: try XCTUnwrap(cases[name]),
                options: [.sortedKeys]
            )
            let policyBody = try JSONSerialization.data(withJSONObject:
                candidateReleasePolicyPayload(
                    version: "status-route-fixture-policy-v2",
                    revision: 192,
                    expiresAt: "2099-01-01T00:00:00Z"
                )
            )
            OwnerTruthReviewReadyHTTPURLProtocol.install { request, protocolInstance in
                XCTAssertEqual(request.httpMethod, "GET", name)
                switch request.url?.path {
                case "/v2/release-policy":
                    protocolInstance.respond(statusCode: 200, body: policyBody)
                case let path? where path.lowercased().hasSuffix(
                        "/interview-review-batches/\(fixtureBatchID.lowercased())/candidate-proposal/status"
                    ):
                    protocolInstance.respond(statusCode: 200, body: responseBody)
                default:
                    XCTFail("Unexpected request path: \(request.url?.path ?? "nil")", file: #filePath, line: #line)
                    protocolInstance.fail(URLError(.unsupportedURL))
                }
            }
            let recovery = try XCTUnwrap(
                EchoLiveMemoryRecoveryService(registry: EchoLiveMemoryRecoveryRegistry())
                    .resumePendingWorkflows(
                        accountLease: lease,
                        excluding: [],
                        client: harness.client,
                        accountLeaseRuntime: runtime,
                        liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(
                            rootDirectory: caseRoot.appendingPathComponent("outbox")
                        ),
                        followUpStore: followUpStore,
                        completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                            rootDirectory: caseRoot.appendingPathComponent("completion")
                        ),
                        naturalInputPolicyAvailable: { true },
                        candidateReviewPolicyAvailable: {
                            harness.decision(.ownerTruthCandidateReview).allowed
                        }
                    ).coordinators.first
            )
            let controller = EchoViewController()
            controller.installLiveMemoryRecoveryForTesting(
                accountLease: lease,
                coordinator: recovery
            )
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                controller.liveMemoryRecoveryPresentationForTesting().statusIdentifier
                    == expectedIdentifiers[name]
            }, name)
            recovery.suspend()
            XCTAssertEqual(
                OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.filter {
                    $0.url?.path.lowercased().hasSuffix(
                        "/interview-review-batches/\(fixtureBatchID.lowercased())/candidate-proposal/status"
                    ) == true
                }.count,
                1,
                name
            )
            XCTAssertTrue(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.allSatisfy {
                $0.httpMethod == "GET"
            }, name)
        }
    }

