            XCTAssertTrue(client.endCommands.isEmpty, name)
            XCTAssertTrue(client.acknowledgementCommands.isEmpty, name)
            XCTAssertTrue(client.admissionCommands.isEmpty, name)
        }
    }

    @MainActor
    func testLiveSuccessfulTerminalCleanupFailureStaysTerminalAndRetriesIdempotently() throws {
        let terminalCases: [(
            String,
            OwnerTruthInterviewCandidateProposalReviewState,
            EchoLiveMemoryCaptureState
        )] = [
            ("pendingReview", .reviewReady, .pendingReview),
            ("empty", .noCandidates, .empty),
        ]

        for (terminalName, reviewState, expectedState) in terminalCases {
            for failAt in 1...3 {
                let (runtime, lease) = try makeActiveRuntime()
                let productSessionID = "terminal-cleanup-\(terminalName)-\(failAt)"
                let batchID = recordID(UUID().uuidString)
                let root = FileManager.default.temporaryDirectory
                    .appendingPathComponent("terminal-cleanup-\(UUID().uuidString)")
                let defaultsName = "terminal-cleanup-\(UUID().uuidString)"
                let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
                let fileManager = RemoveFailureFileManager(failAtRemoveCall: failAt)
                defer {
                    try? FileManager.default.removeItem(at: root)
                    defaults.removePersistentDomain(forName: defaultsName)
                }
                let outboxStore = OwnerTruthInterviewLiveTurnOutboxStore(
                    rootDirectory: root.appendingPathComponent("outbox"),
                    fileManager: fileManager
                )
                _ = try outboxStore.enqueue(
                    role: .owner,
                    text: "仅用于成功终态清理失败的隔离合成内容。",
                    for: lease,
                    productSessionID: productSessionID
                )
                let followUpStore = EchoLiveMemoryFollowUpStore(
                    defaults: defaults,
                    rootDirectory: root.appendingPathComponent("follow-up"),
                    fileManager: fileManager
                )
                try followUpStore.upsert(
                    productSessionID: productSessionID,
                    reviewBatchID: batchID,
                    for: lease
                )
                let checkpointStore = EchoLiveMemoryCompletionCheckpointStore(
                    rootDirectory: root.appendingPathComponent("completion"),
                    fileManager: fileManager
                )
                try seedB8S01AdmittedCheckpoint(
                    store: checkpointStore,
                    productSessionID: productSessionID,
                    lease: lease,
                    threadID: recordID(UUID().uuidString),
                    sessionID: recordID(UUID().uuidString),
                    reviewBatchID: batchID
                )
                let client = InterviewNaturalInputClientSpy()
                client.proposalStatusHandler = { [unowned self] requestedBatchID in
                    Result {
                        try self.interviewCandidateProposalStatus(
                            vaultID: lease.vaultId,
                            reviewBatchID: requestedBatchID,
                            candidateExtractionState: .succeeded,
                            candidateReviewState: reviewState
                        )
                    }
                }
                let coordinator = EchoLiveMemoryCaptureCoordinator(
                    accountLease: lease,
                    client: client,
                    accountLeaseRuntime: runtime,
                    productSessionID: productSessionID,
                    liveTurnOutboxStore: outboxStore,
                    followUpStore: followUpStore,
                    completionCheckpointStore: checkpointStore,
                    organizationStatusTimeout: 1,
                    naturalInputPolicyAvailable: { true },
                    candidateReviewPolicyAvailable: { true }
                )
                let controller = EchoViewController()
                controller.installLiveMemoryCaptureForTesting(
                    accountLease: lease,
                    coordinator: coordinator
                )

                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                    coordinator.state == expectedState && fileManager.removeCallCount >= failAt
                }, "\(terminalName)-\(failAt)")
                XCTAssertEqual(coordinator.state, expectedState)
                XCTAssertEqual(outboxStore.snapshots(for: lease).count, failAt == 1 ? 1 : 0)
                XCTAssertEqual(followUpStore.records(for: lease).count, failAt <= 2 ? 1 : 0)
                XCTAssertEqual(checkpointStore.records(for: lease).count, 1)
                XCTAssertTrue(client.startCommands.isEmpty)
                XCTAssertTrue(client.endCommands.isEmpty)
                XCTAssertTrue(client.acknowledgementCommands.isEmpty)
                XCTAssertTrue(client.admissionCommands.isEmpty)

                let retryCoordinator = EchoLiveMemoryCaptureCoordinator(
                    accountLease: lease,
                    client: client,
                    accountLeaseRuntime: runtime,
                    productSessionID: productSessionID,
                    liveTurnOutboxStore: outboxStore,
                    followUpStore: followUpStore,
                    completionCheckpointStore: checkpointStore,
                    organizationStatusTimeout: 1,
                    naturalInputPolicyAvailable: { true },
                    candidateReviewPolicyAvailable: { true }
                )
                let replacementController = EchoViewController()
                replacementController.installLiveMemoryCaptureForTesting(
                    accountLease: lease,
                    coordinator: retryCoordinator
                )
                retryCoordinator.resumeOrganization(reviewBatchID: batchID)
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
                    client.proposalStatusRequestCount == 2
                        && outboxStore.snapshots(for: lease).isEmpty
                        && followUpStore.records(for: lease).isEmpty
                        && checkpointStore.records(for: lease).isEmpty
                }, "retry-\(terminalName)-\(failAt)")
                XCTAssertEqual(coordinator.state, expectedState)
                XCTAssertEqual(retryCoordinator.state, expectedState)
                XCTAssertTrue(client.startCommands.isEmpty)
                XCTAssertTrue(client.endCommands.isEmpty)
                XCTAssertTrue(client.acknowledgementCommands.isEmpty)
                XCTAssertTrue(client.admissionCommands.isEmpty)
                try outboxStore.remove(for: lease, productSessionID: productSessionID)
                try followUpStore.remove(productSessionID: productSessionID, for: lease)
                try checkpointStore.remove(productSessionID: productSessionID, for: lease)
            }
        }
    }

