        try checkpointStore.prepareEnd(end, productSessionID: productSessionID, for: lease)
        try checkpointStore.acceptEnd(ended, productSessionID: productSessionID, for: lease)
        try checkpointStore.prepareAcknowledgement(
            acknowledgement,
            productSessionID: productSessionID,
            for: lease
        )
        try checkpointStore.acceptAcknowledgement(
            acknowledged,
            productSessionID: productSessionID,
            for: lease
        )
        try checkpointStore.prepareAdmission(
            admission,
            productSessionID: productSessionID,
            for: lease
        )
        try checkpointStore.acceptAdmission(
            try candidateProposalAdmissionReceipt(
                vaultID: lease.vaultId,
                reviewBatchID: batchID
            ),
            productSessionID: productSessionID,
            for: lease
        )

        let client = InterviewNaturalInputClientSpy()
        client.proposalStatusHandler = { [unowned self] requestedBatchID in
            Result {
                try self.interviewCandidateProposalStatus(
                    vaultID: lease.vaultId,
                    reviewBatchID: requestedBatchID,
                    candidateExtractionState: .failed,
                    candidateReviewState: .extractionFailed
