        coordinator.resumeOrganization(reviewBatchID: batchID)

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            coordinator.state == .terminalFailure(code: nil)
        })
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            followUpStore.records(for: lease).first?.lastRecoveryObservation?.kind
                == .terminalFailure
        })
        RunLoop.main.run(until: Date().addingTimeInterval(0.05))
        XCTAssertEqual(outboxStore.snapshots(for: lease).count, 1)
        XCTAssertEqual(followUpStore.records(for: lease).count, 1)
        XCTAssertEqual(checkpointStore.records(for: lease).count, 1)
        XCTAssertEqual(client.proposalStatusRequestCount, 1)
        XCTAssertTrue(client.startCommands.isEmpty)
        XCTAssertTrue(client.endCommands.isEmpty)
        XCTAssertTrue(client.acknowledgementCommands.isEmpty)
        XCTAssertTrue(client.admissionCommands.isEmpty)
    }

