    @MainActor
    func testLiveExpiredAuthenticationRefreshesBeforeStartExposure() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let expired = try makeOwnerTruthHTTPTestAuthSession(
            userID: lease.subjectId,
            sessionID: "live-expired-session",
            tokenFamilyID: "live-auth-family",
            sessionVersion: 1,
            accessTokenSuffix: "expired",
            accessExpiresAt: Date(timeIntervalSince1970: 1_700_000_000)
        )
        let successor = try makeOwnerTruthHTTPTestAuthSession(
            userID: lease.subjectId,
            sessionID: "live-successor-session",
            parentSessionID: expired.sessionId,
            tokenFamilyID: "live-auth-family",
            sessionVersion: 2,
            accessTokenSuffix: "successor",
            accessExpiresAt: Date(timeIntervalSince1970: 1_700_003_600)
        )
        var activeSession = expired
        var refreshCount = 0
        let evaluator = FeatureGateEvaluator()
        let policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "live-auth-policy-v1",
            policyRevision: 1,
            emergencyRevision: 0,
            expiresAt: Date().addingTimeInterval(3_600),
            featureEnabled: true,
            releaseVisible: true,
            reason: "liveAuthAllowed"
        )
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { activeSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: { feature in
                evaluator.capture(
                    feature: feature,
                    risk: .ownerTextCore,
                    purpose: .request,
                    localEnabled: true,
                    qaSyntheticOverride: false,
                    accountGeneration: activeSession.sessionId,
                    policy: policy
                )
            },
            freshFeatureDecision: { feature in
                evaluator.capture(
                    feature: feature,
                    risk: .ownerTextCore,
                    purpose: .request,
                    localEnabled: true,
                    qaSyntheticOverride: false,
                    accountGeneration: activeSession.sessionId,
                    policy: policy
                )
            },
            featureDecisionRevalidator: { decision in
                evaluator.revalidateForRequest(
                    captured: decision,
                    localEnabled: true,
                    accountGeneration: activeSession.sessionId,
                    currentPolicy: policy
                )
            },
            authSessionRefresher: { captured, completion in
                refreshCount += 1
                XCTAssertTrue(captured.matchesCASIdentity(expired))
                activeSession = successor
                completion(successor)
            },
            accountLeaseRuntime: runtime
        )
        var postAuthorization: String?
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            if request.httpMethod == "GET" {
                loader.respond(statusCode: 200, body: try! JSONSerialization.data(withJSONObject: [
                    "schemaVersion": OwnerTruthInterviewNaturalInputCurrentSession.schemaVersion,
                    "vaultId": lease.vaultId,
                    "currentSession": NSNull(),
                ]))
                return
            }
            postAuthorization = request.value(forHTTPHeaderField: "Authorization")
            let body = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequestBodies.last!!
            let payload = try! JSONSerialization.jsonObject(with: body) as! [String: Any]
            loader.respond(statusCode: 201, body: try! JSONSerialization.data(withJSONObject: [
                "schemaVersion": OwnerTruthInterviewNaturalInputReceipt.schemaVersion,
                "vaultId": vaultID.rawValue,
                "receipt": [
                    "status": "created",
                    "threadId": payload["threadId"]!,
                    "sessionId": payload["sessionId"]!,
                    "threadVersion": 1,
                    "sessionVersion": 1,
                    "state": "active",
                    "boundary": "open",
                    "authorityEpoch": 0,
                ],
            ]))
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }

        let useCase = OwnerTruthInterviewNaturalInputUseCase(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            entryMode: .live,
            productSessionID: "live-expired-auth",
            authorityNow: { Date(timeIntervalSince1970: 1_700_000_100) }
        )
        useCase.send(.start)

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            useCase.viewState.phase == .ready
        })
        XCTAssertEqual(refreshCount, 1)
        XCTAssertEqual(postAuthorization, "Bearer \(successor.accessToken)")
    }

    func testLiveAuthenticationRefreshRechecksClockBeforeAcceptingSuccessor() throws {
        let (runtime, lease) = try makeActiveRuntime()
        var fakeNow = Date(timeIntervalSince1970: 1_700_010_000)
        let expired = try makeOwnerTruthHTTPTestAuthSession(
            userID: lease.subjectId,
            sessionID: "live-clock-expired",
            tokenFamilyID: "live-clock-family",
            sessionVersion: 1,
            accessTokenSuffix: "expired",
            accessExpiresAt: fakeNow.addingTimeInterval(-1)
        )
        let shortLivedSuccessor = try makeOwnerTruthHTTPTestAuthSession(
            userID: lease.subjectId,
            sessionID: "live-clock-successor",
            parentSessionID: expired.sessionId,
            tokenFamilyID: "live-clock-family",
            sessionVersion: 2,
            accessTokenSuffix: "successor",
            accessExpiresAt: fakeNow.addingTimeInterval(20)
        )
        var active = expired
        var deferredRefresh: ((BackendAuthSessionContract?) -> Void)?
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { active },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: { feature in
                FeatureDecision(
                    decisionId: "unused-clock-decision",
                    feature: feature,
                    purpose: .request,
                    policyVersion: "unused",
                    policyRevision: 1,
                    emergencyRevision: 0,
                    validatedPolicyRevision: 1,
                    validatedEmergencyRevision: 0,
                    accountGeneration: active.sessionId,
                    allowed: false,
                    reason: "unused",
                    expiresAt: fakeNow
                )
            },
            authSessionRefresher: { _, completion in deferredRefresh = completion },
            accountLeaseRuntime: runtime
        )
        var accepted: Bool?
        client.prepareOwnerTruthInterviewNaturalInputAuthentication(
            accountLease: lease,
            now: { fakeNow },
            minimumValidity: 30
        ) { accepted = $0 }
        XCTAssertNotNil(deferredRefresh)

        fakeNow = fakeNow.addingTimeInterval(25)
        active = shortLivedSuccessor
        deferredRefresh?(shortLivedSuccessor)

        XCTAssertEqual(accepted, false)
    }

