    func testLiveReadGETsUseCredentialSuccessorAndFreshHeadersAfter401() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let sessionID = recordID("00000000-0000-0000-0000-0000000009b2")
        let threadID = recordID("00000000-0000-0000-0000-0000000009b1")
        let productSessionID = "live-get-auth-successor"
        let policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "live-get-policy-v1",
            policyRevision: 9,
            emergencyRevision: 0,
            expiresAt: Date().addingTimeInterval(600),
            featureEnabled: true,
            releaseVisible: true,
            reason: "echoTextInputEnabled"
        )

        func runRead(
            suffix: String,
            invoke: (DreamJourneyBackendClient, @escaping (Result<Void, Error>) -> Void) -> Void
        ) throws {
            let first = try makeOwnerTruthHTTPTestAuthSession(
                userID: lease.subjectId,
                sessionID: "live-get-\(suffix)-session-1",
                tokenFamilyID: "live-get-\(suffix)-family",
                sessionVersion: 1,
                accessTokenSuffix: "first"
            )
            let successor = try makeOwnerTruthHTTPTestAuthSession(
                userID: lease.subjectId,
                sessionID: "live-get-\(suffix)-session-2",
                parentSessionID: first.sessionId,
                tokenFamilyID: "live-get-\(suffix)-family",
                sessionVersion: 2,
                accessTokenSuffix: "second"
            )
            var active = first
            let evaluator = FeatureGateEvaluator()
            let client = DreamJourneyBackendClient.makeQATestClient(
                baseURL: URL(string: "https://owner-truth.qa.invalid")!,
                session: try makeOwnerTruthHTTPTestSession(),
                authenticatedSession: { active },
                currentUserID: { lease.subjectId },
                privateAccessAllowed: { true },
                featureDecision: { feature in
                    evaluator.capture(
                        feature: feature,
                        risk: .ownerTextCore,
                        purpose: .request,
                        localEnabled: true,
                        qaSyntheticOverride: false,
                        accountGeneration: FeatureGateService.accountGeneration(
                            forIdentitySource: active.sessionId
                        ),
                        policy: policy
                    )
                },
                freshFeatureDecision: { feature in
                    evaluator.capture(
                        feature: feature,
                        risk: .ownerTextCore,
                        purpose: .request,
                        localEnabled: true,
                        qaSyntheticOverride: false,
                        accountGeneration: FeatureGateService.accountGeneration(
                            forIdentitySource: active.sessionId
                        ),
                        policy: policy
                    )
                },
                featureDecisionRevalidator: { decision in
                    evaluator.revalidateForRequest(
                        captured: decision,
                        localEnabled: true,
                        accountGeneration: FeatureGateService.accountGeneration(
                            forIdentitySource: active.sessionId
                        ),
                        currentPolicy: policy
                    )
                },
                accountLeaseRuntime: runtime
            )
            var requestCount = 0
            var policyMetadataFailures: [String] = []
            OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
                requestCount += 1
                let requiredPolicyHeaders: [String: String] = [
                    "X-DreamJourney-Feature": DJFeature.echoTextInput.rawValue,
                    "X-DreamJourney-Feature-Allowed": "true",
                    "X-DreamJourney-Account-Generation": FeatureGateService
                        .accountGeneration(forIdentitySource: active.sessionId),
                    "X-DreamJourney-Policy-Audience": "owner",
                    "X-DreamJourney-Policy-Cohort": "authenticatedOwner",
                    "X-DreamJourney-Policy-Version": "live-get-policy-v1",
                    "X-DreamJourney-Policy-Revision": "9",
                    "X-DreamJourney-Emergency-Revision": "0",
                ]
                let missing = requiredPolicyHeaders.compactMap { name, expected in
                    request.value(forHTTPHeaderField: name) == expected ? nil : name
                }
                let decisionID = request.value(
                    forHTTPHeaderField: "X-DreamJourney-Feature-Decision-Id"
                )?.trimmingCharacters(in: .whitespacesAndNewlines)
                if !missing.isEmpty || decisionID?.isEmpty != false {
                    policyMetadataFailures.append(contentsOf: missing)
                    if decisionID?.isEmpty != false {
                        policyMetadataFailures.append("X-DreamJourney-Feature-Decision-Id")
                    }
                    loader.respond(
                        statusCode: 403,
                        body: Data("{\"detail\":\"missing policy metadata\"}".utf8)
                    )
                    return
                }
                if requestCount == 1 {
                    active = successor
                    loader.respond(
                        statusCode: 401,
                        body: Data("{\"code\":\"access_expired\",\"detail\":\"expired\"}".utf8)
                    )
                    return
                }
                let path = request.url?.path ?? ""
                if path.hasSuffix("/interview-sessions/current") {
                    loader.respond(statusCode: 200, body: try! JSONSerialization.data(
                        withJSONObject: [
                            "schemaVersion": OwnerTruthInterviewNaturalInputCurrentSession.schemaVersion,
                            "vaultId": vaultID.rawValue,
                            "currentSession": NSNull(),
                        ]
                    ))
                } else {
                    loader.respond(statusCode: 200, body: try! JSONSerialization.data(
                        withJSONObject: [
                            "schemaVersion": OwnerTruthLiveDeliveryStatus.schemaVersion,
                            "vaultId": vaultID.rawValue,
                            "productSessionId": productSessionID,
                            "session": [
                                "threadId": threadID.rawValue.uuidString.lowercased(),
                                "sessionId": sessionID.rawValue.uuidString.lowercased(),
                                "state": "active",
                                "boundary": "open",
                                "threadVersion": 1,
                                "sessionVersion": 1,
                                "authorityEpoch": 0,
                                "continuousClientSequence": 0,
                                "closeRequestedClientSequence": NSNull(),
                            ],
                            "observedAt": "2026-09-18T00:00:00Z",
                            "window": [
                                "fromClientSequence": 1,
                                "limit": 64,
                                "missingClientSequences": [1],
                                "nextFromClientSequence": NSNull(),
                            ],
                            "deliveries": [],
                            "operations": [],
                        ]
                    ))
                }
            }
            defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
            var result: Result<Void, Error>?
            invoke(client) { result = $0 }
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { result != nil })
            try XCTUnwrap(result).get()
            XCTAssertTrue(policyMetadataFailures.isEmpty)
            XCTAssertEqual(requestCount, 2)
            XCTAssertEqual(
                OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.map {
                    $0.value(forHTTPHeaderField: "Authorization")
                },
                ["Bearer \(first.accessToken)", "Bearer \(successor.accessToken)"]
            )
        }

        try runRead(suffix: "current") { client, completion in
            client.fetchOwnerTruthInterviewNaturalInputCurrentSession(
                vaultID: vaultID,
                productSessionID: productSessionID
            ) { result in completion(result.map { _ in () }) }
        }
        try runRead(suffix: "status") { client, completion in
            client.fetchOwnerTruthLiveDeliveryStatus(
                accountLease: lease,
                vaultID: vaultID,
                sessionID: sessionID,
                productSessionID: productSessionID,
                fromClientSequence: 1
            ) { result in completion(result.map { _ in () }) }
        }
    }

