    func testPersonMemoryProfileDecodesOneNarrativePerStableDimension() throws {
        let vaultID = try XCTUnwrap(OwnerTruthVaultID("vault-person-profile"))
        let experienceID = "00000000-0000-0000-0000-000000000101"
        let knowledgeID = "00000000-0000-0000-0000-000000000102"
        func dimension(
            _ key: String,
            title: String,
            narrative: String? = nil,
            ids: [String] = [],
            versionIDs: [String] = []
        ) -> [String: Any] {
            [
                "dimension": key,
                "title": title,
                "status": narrative == nil ? "empty" : "ready",
                "narrative": narrative ?? NSNull(),
                "supportingMemoryCount": ids.count,
                "supportingMemoryIds": ids,
                "supportingMemoryVersionIds": versionIDs,
            ]
        }
        let paragraphs = [
            "小时候常在老院子里听外祖父讲故事，这些经历让我更重视家人。",
            "面对复杂工作，我习惯先拆分问题，再逐项验证。",
        ]
        let profile = try OwnerTruthPersonMemoryProfile(
            backendJSONObject: [
                "schemaVersion": OwnerTruthPersonMemoryProfile.schemaVersion,
                "algorithmVersion": OwnerTruthPersonMemoryProfile.algorithmVersion,
                "state": "ready",
                "vaultId": vaultID.rawValue,
                "profileVersion": String(repeating: "a", count: 64),
                "updatedAt": "2026-08-25T10:00:00Z",
                "memoryCount": 2,
                "lifeRecord": [
                    "schemaVersion": OwnerTruthPersonLifeRecord.schemaVersion,
                    "algorithmVersion": OwnerTruthPersonLifeRecord.algorithmVersion,
                    "format": "plainText",
                    "state": "ready",
                    "title": "我的人生记录",
                    "paragraphCount": paragraphs.count,
                    "paragraphs": paragraphs,
                    "text": paragraphs.joined(separator: "\n\n"),
                    "paragraphEvidence": [
                        [
                            "paragraphIndex": 0,
                            "supportingMemoryCount": 1,
                            "supportingMemoryIds": [experienceID],
                            "supportingMemoryVersionIds": [
                                "00000000-0000-0000-0000-000000000201"
                            ],
                        ],
                        [
                            "paragraphIndex": 1,
                            "supportingMemoryCount": 1,
                            "supportingMemoryIds": [knowledgeID],
                            "supportingMemoryVersionIds": [
                                "00000000-0000-0000-0000-000000000202"
                            ],
                        ],
                    ],
                ],
                "lifeStory": lifeStoryFixture(
                    paragraphs: paragraphs,
                    experienceID: experienceID,
                    knowledgeID: knowledgeID
                ),
                "dimensions": [
                    dimension(
                        "lifeEvent",
                        title: "经历与人生轨迹",
                        narrative: "这些正式记忆共同勾勒出两段人生经历。",
                        ids: [experienceID],
                        versionIDs: ["00000000-0000-0000-0000-000000000201"]
                    ),
                    dimension(
                        "knowledge",
                        title: "知识与经验",
                        narrative: "目前沉淀出一项经验。",
                        ids: [knowledgeID],
                        versionIDs: ["00000000-0000-0000-0000-000000000202"]
                    ),
                    dimension("emotion", title: "情感与牵挂"),
                    dimension(
                        "relationship",
                        title: "家庭与社会关系",
                        narrative: "正式记忆中出现了一位重要人物。",
                        ids: [experienceID],
                        versionIDs: ["00000000-0000-0000-0000-000000000201"]
                    ),
                    dimension("personality", title: "性格特征"),
                    dimension("value", title: "价值观与人生选择"),
                    dimension("habit", title: "习惯与偏好"),
                    dimension("goal", title: "目标与愿望"),
                    dimension("identity", title: "身份与角色"),
                    dimension("reflection", title: "反思与人生理解"),
                ],
                "memoryModel": [
                    "schemaVersion": OwnerTruthPersonMemoryModelSummary.schemaVersion,
                    "algorithmVersion": OwnerTruthPersonMemoryModelSummary.algorithmVersion,
                    "state": "ready",
                    "modelVersion": String(repeating: "a", count: 64),
                    "sourceFingerprint": String(repeating: "b", count: 64),
                    "memoryCount": 2,
                    "consolidatedMemoryCount": 2,
                    "unresolvedConflictCount": 0,
                    "cognitiveItemCount": 2,
                    "entityCount": 3,
                    "relationCount": 2,
                    "biographyDocumentVersion": String(repeating: "c", count: 64),
                ],
            ],
            expectedVaultID: vaultID
        )

        XCTAssertEqual(profile.memoryCount, 2)
        XCTAssertEqual(profile.lifeRecord.title, "我的人生记录")
        XCTAssertEqual(profile.lifeRecord.paragraphs, paragraphs)
        XCTAssertEqual(profile.lifeRecord.paragraphEvidence.map(\.paragraphIndex), [0, 1])
        XCTAssertEqual(
            profile.lifeRecord.paragraphEvidence[0].supportingMemoryIDs,
            [recordID(experienceID)]
        )
        XCTAssertFalse(profile.lifeRecord.text?.contains("#") == true)
        XCTAssertEqual(profile.lifeStory.title, "我的人生记录")
        XCTAssertEqual(profile.lifeStory.chapters.map(\.title), ["家庭与成长", "经验与信念"])
        XCTAssertEqual(
            Set(profile.lifeStory.chapters.flatMap(\.supportingMemoryIDs)),
            Set([recordID(experienceID), recordID(knowledgeID)])
        )
        XCTAssertFalse(profile.lifeStory.isLegacyFallback)
        XCTAssertEqual(profile.dimensions.map(\.kind), OwnerTruthPersonMemoryDimensionKind.allCases)
        XCTAssertEqual(profile.dimensions[0].supportingMemoryIDs.count, 1)
        XCTAssertTrue(profile.dimensions[0].narrative?.contains("共同勾勒") == true)
        XCTAssertEqual(profile.dimensions[2].status, .empty)
        XCTAssertNil(profile.dimensions[2].narrative)
        XCTAssertEqual(profile.memoryModel.modelVersion, profile.profileVersion)
        XCTAssertEqual(profile.memoryModel.memoryCount, profile.memoryCount)
        XCTAssertEqual(profile.memoryModel.consolidatedMemoryCount, 2)
        XCTAssertEqual(profile.memoryModel.unresolvedConflictCount, 0)
        XCTAssertEqual(profile.memoryModel.biographyDocumentVersion, profile.lifeStory.documentVersion)
    }

