    func testArchiveCreationOptionsKeepOwnerTruthSourceHiddenByDefault() {
        let defaultOptions = MemoryArchiveCreationOption.availableOptions(
            isAudioUploadEnabled: false,
            isVideoUploadEnabled: false,
            isTimeLettersEnabled: false
        )
        let closedPilotOptions = MemoryArchiveCreationOption.availableOptions(
            isAudioUploadEnabled: false,
            isVideoUploadEnabled: false,
            isTimeLettersEnabled: false,
            isOwnerTruthTextCaptureEnabled: true,
            isOwnerTruthMediaCaptureEnabled: true
        )
        let internalMediaOptions = MemoryArchiveCreationOption.availableOptions(
            isAudioUploadEnabled: false,
            isVideoUploadEnabled: false,
            isTimeLettersEnabled: false,
            isOwnerTruthTextCaptureEnabled: true,
            isOwnerTruthMediaCaptureEnabled: true,
            includesProductClosedMedia: true
        )
        let textOnlyAuthorityOptions = MemoryArchiveCreationOption.availableOptions(
            isAudioUploadEnabled: true,
            isVideoUploadEnabled: true,
            isTimeLettersEnabled: false,
            isOwnerTruthTextCaptureEnabled: true,
            isOwnerTruthMediaCaptureEnabled: false
        )

        XCTAssertEqual(defaultOptions.map(\.title), ["添加文字描述", "选择照片"])
        XCTAssertFalse(defaultOptions.contains(where: \.submitsOwnerTruthSource))
        XCTAssertEqual(closedPilotOptions.filter(\.submitsOwnerTruthSource).count, 1)
        XCTAssertEqual(
            closedPilotOptions.map(\.title),
            ["记录文字", "选择图片", "选择文档"]
        )
        XCTAssertEqual(
            closedPilotOptions.compactMap(\.ownerTruthMediaKind),
            [.image, .document]
        )
        XCTAssertEqual(
            internalMediaOptions.map(\.title),
            ["记录文字", "选择图片", "选择文档", "选择音频", "选择视频"]
        )
        XCTAssertEqual(
            textOnlyAuthorityOptions.map(\.title),
            ["记录文字", "选择图片", "选择文档"]
        )
        XCTAssertEqual(
            textOnlyAuthorityOptions.map(\.isAvailable),
            [true, false, false]
        )
        XCTAssertFalse(
            textOnlyAuthorityOptions.contains {
                if case .archive = $0.route { return true }
                return false
            }
        )
    }

    func testOwnerTruthMediaCreationPolicyRequiresExplicitProcessingChoice() throws {
        XCTAssertTrue(OwnerTruthMediaCreationPolicy.requiresExternalProcessingChoice(for: .image))
        XCTAssertFalse(OwnerTruthMediaCreationPolicy.requiresExternalProcessingChoice(for: .audio))
        XCTAssertFalse(OwnerTruthMediaCreationPolicy.requiresExternalProcessingChoice(for: .document))
        XCTAssertFalse(OwnerTruthMediaCreationPolicy.requiresExternalProcessingChoice(for: .video))
        XCTAssertEqual(OwnerTruthMediaCreationPolicy.maximumFileSizeMB(for: .image), 20)
        XCTAssertEqual(OwnerTruthMediaCreationPolicy.maximumFileSizeMB(for: .audio), 50)
        XCTAssertEqual(OwnerTruthMediaCreationPolicy.maximumFileSizeMB(for: .document), 50)
        XCTAssertEqual(OwnerTruthMediaCreationPolicy.maximumFileSizeMB(for: .video), 50)

        XCTAssertThrowsError(
            try OwnerTruthMediaCreationPolicy.makeCommand(
                mediaKind: .image,
                fileName: "memory.jpg",
                contentType: "image/jpeg",
                content: Data("image".utf8),
                allowExternalProcessing: nil
            )
        ) { error in
            XCTAssertEqual(
                error as? OwnerTruthMediaCreationPolicyError,
                .externalProcessingChoiceRequired
            )
        }

        let documentCommand = try OwnerTruthMediaCreationPolicy.makeCommand(
            mediaKind: .document,
            fileName: "memory.pdf",
            contentType: "application/pdf",
            content: Data("document".utf8),
            allowExternalProcessing: true
        )
        XCTAssertFalse(documentCommand.allowExternalProcessing)

        let markdownCommand = try OwnerTruthMediaCreationPolicy.makeCommand(
            mediaKind: .document,
            fileName: "memory.md",
            contentType: "text/markdown",
            content: Data("# Memory".utf8),
            allowExternalProcessing: nil
        )
        XCTAssertEqual(markdownCommand.contentType, "text/markdown")
        XCTAssertFalse(markdownCommand.allowExternalProcessing)

        let videoCommand = try OwnerTruthMediaCreationPolicy.makeCommand(
            mediaKind: .video,
            fileName: "memory.mov",
            contentType: "video/quicktime",
            content: Data("video".utf8),
            allowExternalProcessing: true
        )
        XCTAssertFalse(videoCommand.allowExternalProcessing)
        XCTAssertEqual(
            OwnerTruthMediaCreationPolicy.successMessage(for: .video),
            "已保存，暂不分析"
        )
    }

