    func testV5CorrectionPreviewDoesNotSubmitUntilBoundProposalConfirmed() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let candidateID = recordID("00000000-0000-0000-0000-000000000171")
        let client = CandidateReviewClientSpy()
        let inbox = try v5CandidateInbox(vaultID: lease.vaultId, candidateID: candidateID)
        let sourceCandidate = try XCTUnwrap(inbox.candidates.first)
        let correctedText = "我在 2016 年从 A 大学计算机专业毕业。"
        let correctedValue: [String: OwnerTruthJSONValue] = [
            "statement": .string(correctedText),
        ]
        let resolvedHash = String(repeating: "c", count: 64)
        let correctedInbox = try v5CandidateInbox(
            vaultID: lease.vaultId,
            candidateID: candidateID,
            statement: correctedText,
            candidateHash: resolvedHash,
            proposalHash: String(repeating: "d", count: 64)
        )
        let proposal = try XCTUnwrap(correctedInbox.candidates.first?.proposedChangeSet)
        let frozenCorrection = OwnerTruthFrozenCorrectionInput(
            correctedValueSchemaVersion: sourceCandidate.contentSchemaVersion,
            correctedValue: correctedValue
        )
        client.inboxResult = .success(inbox)
        client.correctionPreviewResult = .success(OwnerTruthCandidateCorrectionPreviewEnvelope(
            vaultID: try XCTUnwrap(OwnerTruthVaultID(lease.vaultId)),
            candidateID: candidateID,
            proposal: proposal,
            correctionBinding: OwnerTruthCandidateCorrectionBinding(
                sourceCandidateVersion: sourceCandidate.candidateVersion,
                sourceCandidateContentHash: sourceCandidate.contentHash,
                submittedCorrection: frozenCorrection,
                resolvedContentHash: resolvedHash
            )
        ))
        client.reviewResult = .success(try decisionResult(
            candidateID: candidateID,
            decision: .corrected,
            candidateBeforeHash: String(repeating: "a", count: 64),
            candidateVersion: 4,
            candidateAfterHash: resolvedHash
        ))
        let useCase = OwnerTruthCandidateReviewUseCase(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { true },
            commandIDFactory: { "candidate-review-v5-preview-confirm-001" }
        )

        useCase.send(.refresh)
        var verifiedPreview: OwnerTruthVerifiedCorrectionPreview?
        useCase.previewCorrection(
            candidateID: candidateID,
            correctedPrimaryValue: correctedText
        ) { result in
            switch result {
            case .success(let preview):
                verifiedPreview = preview
            case .failure(let error):
                XCTFail("expected V5 correction preview: \(error)")
            }
        }

        XCTAssertEqual(client.reviewedCommands.count, 0)
        let preview = try XCTUnwrap(verifiedPreview)
        let boundProposal = preview.proposal
        XCTAssertNotEqual(boundProposal.candidateContentHash, sourceCandidate.contentHash)
        useCase.send(.correct(
            candidateID: candidateID,
            correctedPrimaryValue: correctedText,
            proposedChangeSet: boundProposal,
            verifiedCorrectionPreview: preview
        ))

        let command = try XCTUnwrap(client.reviewedCommands.first)
        XCTAssertEqual(command.action, .correct)
        XCTAssertEqual(command.expectedChangeSetID, boundProposal.changeSetID)
        XCTAssertEqual(command.expectedProposalHash, boundProposal.proposalHash)
        XCTAssertEqual(useCase.viewState.notice, .candidateCorrected)
    }

    func testV5CorrectionRejectsReceiptWhoseAfterHashDoesNotMatchVerifiedPreview() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let candidateID = recordID("00000000-0000-0000-0000-0000000001c8")
        let client = CandidateReviewClientSpy()
        let inbox = try v5CandidateInbox(vaultID: lease.vaultId, candidateID: candidateID)
        let candidate = try XCTUnwrap(inbox.candidates.first)
        let correctedText = "测试阅读清单代号是晨星。"
        let frozen = OwnerTruthFrozenCorrectionInput(
            correctedValueSchemaVersion: candidate.contentSchemaVersion,
            correctedValue: ["statement": .string(correctedText)]
        )
        let resolvedHash = String(repeating: "c", count: 64)
        let correctedInbox = try v5CandidateInbox(
            vaultID: lease.vaultId,
            candidateID: candidateID,
            statement: correctedText,
            candidateHash: resolvedHash,
            proposalHash: String(repeating: "d", count: 64)
        )
        let proposal = try XCTUnwrap(correctedInbox.candidates.first?.proposedChangeSet)
        client.inboxResult = .success(inbox)
        client.correctionPreviewResult = .success(OwnerTruthCandidateCorrectionPreviewEnvelope(
            vaultID: candidate.vaultID,
            candidateID: candidateID,
            proposal: proposal,
            correctionBinding: OwnerTruthCandidateCorrectionBinding(
                sourceCandidateVersion: candidate.candidateVersion,
                sourceCandidateContentHash: candidate.contentHash,
                submittedCorrection: frozen,
                resolvedContentHash: resolvedHash
            )
        ))
        client.reviewResult = .success(try decisionResult(
            candidateID: candidateID,
            decision: .corrected,
            candidateBeforeHash: candidate.contentHash,
            candidateVersion: candidate.candidateVersion + 1,
            candidateAfterHash: String(repeating: "e", count: 64)
        ))
        let useCase = OwnerTruthCandidateReviewUseCase(
            accountLease: lease,
            client: client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { true }
        )

        useCase.send(.refresh)
        var verified: OwnerTruthVerifiedCorrectionPreview?
        useCase.previewCorrection(
            candidateID: candidateID,
            correctedPrimaryValue: correctedText
        ) { result in
            verified = try? result.get()
        }
        let preview = try XCTUnwrap(verified)
        useCase.send(.correct(
            candidateID: candidateID,
            correctedPrimaryValue: correctedText,
            proposedChangeSet: preview.proposal,
            verifiedCorrectionPreview: preview
        ))

        XCTAssertEqual(client.reviewedCommands.count, 1)
        XCTAssertEqual(useCase.viewState.phase, .failed)
        XCTAssertEqual(useCase.viewState.notice, .reviewResultMismatch)
        XCTAssertEqual(useCase.viewState.items.map(\.id), [candidateID])
    }

    func testCorrectionPreviewEnvelopeFailsClosedForMissingOrMalformedBinding() throws {
        let vaultID = try XCTUnwrap(OwnerTruthVaultID("vault-correction-envelope"))
        let candidateID = recordID("00000000-0000-0000-0000-0000000001c1")
        let base = v5CorrectionPreviewJSONObject(
            vaultID: vaultID.rawValue,
            candidateID: candidateID,
            correctedText: "测试阅读清单代号是晨星。"
        )

        func assertFailure(
            _ object: [String: Any],
            _ expected: String,
            file: StaticString = #filePath,
            line: UInt = #line
        ) {
            XCTAssertThrowsError(
                try OwnerTruthCandidateCorrectionPreviewEnvelope(
                    backendJSONObject: object,
                    expectedVaultID: vaultID,
                    expectedCandidateID: candidateID
                ),
                file: file,
                line: line
            ) { error in
                XCTAssertEqual(
                    error as? OwnerTruthRemoteContractError,
                    .invalidInbox(expected),
                    file: file,
                    line: line
                )
            }
        }

        var missingBinding = base
        missingBinding.removeValue(forKey: "correctionBinding")
        assertFailure(missingBinding, "correctionBindingMissing")

        var unsupportedSchema = base
        var binding = try XCTUnwrap(unsupportedSchema["correctionBinding"] as? [String: Any])
        binding["schemaVersion"] = "owner-truth-candidate-correction-binding-v0"
        unsupportedSchema["correctionBinding"] = binding
        assertFailure(unsupportedSchema, "bindingSchemaUnsupported")

        var invalidTypedInput = base
        binding = try XCTUnwrap(invalidTypedInput["correctionBinding"] as? [String: Any])
        binding["submittedCorrection"] = [
            "correctedValueSchemaVersion": "owner-truth-v5",
            "correctedValue": ["statement": Date()],
        ]
        invalidTypedInput["correctionBinding"] = binding
        assertFailure(invalidTypedInput, "submittedCorrectionInvalid")
    }

    func testVerifiedCorrectionPreviewRejectsIndependentBindingMismatches() throws {
        let vaultID = try XCTUnwrap(OwnerTruthVaultID("vault-correction-matrix"))
        let candidateID = recordID("00000000-0000-0000-0000-0000000001c2")
        let inbox = try v5CandidateInbox(vaultID: vaultID.rawValue, candidateID: candidateID)
        let candidate = try XCTUnwrap(inbox.candidates.first)
        let correctedText = "测试阅读清单代号是晨星。"
        let frozen = OwnerTruthFrozenCorrectionInput(
            correctedValueSchemaVersion: candidate.contentSchemaVersion,
            correctedValue: ["statement": .string(correctedText)]
        )
        let resolvedHash = String(repeating: "c", count: 64)
        let correctedInbox = try v5CandidateInbox(
            vaultID: vaultID.rawValue,
            candidateID: candidateID,
            statement: correctedText,
            candidateHash: resolvedHash,
            proposalHash: String(repeating: "d", count: 64)
        )
        let proposal = try XCTUnwrap(correctedInbox.candidates.first?.proposedChangeSet)
        let source = OwnerTruthSourceCandidateBinding(candidate: candidate)

        func assertFailure(
            binding: OwnerTruthCandidateCorrectionBinding,
            frozen expectedFrozen: OwnerTruthFrozenCorrectionInput = frozen,
            memoryRevision: Int = 9,
            expected: String,
            file: StaticString = #filePath,
            line: UInt = #line
        ) {
            let envelope = OwnerTruthCandidateCorrectionPreviewEnvelope(
                vaultID: vaultID,
                candidateID: candidateID,
                proposal: proposal,
                correctionBinding: binding
            )
            XCTAssertThrowsError(
                try OwnerTruthVerifiedCorrectionPreview(
                    envelope: envelope,
                    sourceCandidate: source,
                    frozenCorrection: expectedFrozen,
                    memoryRevision: memoryRevision,
                    traceID: "synthetic-correction-trace"
                ),
                file: file,
                line: line
            ) { error in
                XCTAssertEqual(
                    error as? OwnerTruthRemoteContractError,
                    .invalidInbox(expected),
                    file: file,
                    line: line
                )
            }
        }

        assertFailure(
            binding: OwnerTruthCandidateCorrectionBinding(
                sourceCandidateVersion: candidate.candidateVersion + 1,
                sourceCandidateContentHash: candidate.contentHash,
                submittedCorrection: frozen,
                resolvedContentHash: resolvedHash
            ),
            expected: "sourceCandidateVersionMismatch"
        )
        assertFailure(
            binding: OwnerTruthCandidateCorrectionBinding(
                sourceCandidateVersion: candidate.candidateVersion,
                sourceCandidateContentHash: String(repeating: "e", count: 64),
                submittedCorrection: frozen,
                resolvedContentHash: resolvedHash
            ),
            expected: "sourceCandidateHashMismatch"
        )
        let typedDifferentInput = OwnerTruthFrozenCorrectionInput(
            correctedValueSchemaVersion: candidate.contentSchemaVersion,
            correctedValue: [
                "statement": .string(correctedText),
                "confidence": .number(0.724),
                "verified": .bool(true),
                "tags": .array([]),
                "optional": .null,
            ]
        )
        assertFailure(
            binding: OwnerTruthCandidateCorrectionBinding(
                sourceCandidateVersion: candidate.candidateVersion,
                sourceCandidateContentHash: candidate.contentHash,
                submittedCorrection: typedDifferentInput,
                resolvedContentHash: resolvedHash
            ),
            expected: "submittedCorrectionMismatch"
        )
        assertFailure(
            binding: OwnerTruthCandidateCorrectionBinding(
                sourceCandidateVersion: candidate.candidateVersion,
                sourceCandidateContentHash: candidate.contentHash,
                submittedCorrection: frozen,
                resolvedContentHash: String(repeating: "f", count: 64)
            ),
            expected: "resolvedContentHashMismatch"
        )
        assertFailure(
            binding: OwnerTruthCandidateCorrectionBinding(
                sourceCandidateVersion: candidate.candidateVersion,
                sourceCandidateContentHash: candidate.contentHash,
                submittedCorrection: frozen,
                resolvedContentHash: resolvedHash
            ),
            memoryRevision: 10,
            expected: "memoryRevisionMismatch"
        )
    }

    @MainActor
    func testCorrectionPreviewRealClientUIKitRequiresSecondConfirmationAndUsesFrozenInput() throws {
        UIView.setAnimationsEnabled(false)
        defer { UIView.setAnimationsEnabled(true) }
        let fixtureURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/OwnerTruth/b4-correction-preview-real-builder.json")
        let fixtureData = try Data(contentsOf: fixtureURL)
        let fixture = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: fixtureData) as? [String: Any]
        )
        XCTAssertEqual(fixture["syntheticDataOnly"] as? Bool, true)
        let originalCandidate = try XCTUnwrap(fixture["originalCandidate"] as? [String: Any])
        let preview = try XCTUnwrap(fixture["correctionPreview"] as? [String: Any])
        let vaultID = try XCTUnwrap(preview["vaultId"] as? String)
        let candidateID = recordID(try XCTUnwrap(preview["candidateId"] as? String))
        let proposal = try XCTUnwrap(preview["proposedChangeSet"] as? [String: Any])
        let correctionBinding = try XCTUnwrap(preview["correctionBinding"] as? [String: Any])
        let submittedCorrection = try XCTUnwrap(
            correctionBinding["submittedCorrection"] as? [String: Any]
        )
        let submittedValue = try XCTUnwrap(
            submittedCorrection["correctedValue"] as? [String: Any]
        )
        let correctedText = try XCTUnwrap(submittedValue["statement"] as? String)
        let sourceHash = try XCTUnwrap(
            correctionBinding["sourceCandidateContentHash"] as? String
        )
        let resolvedHash = try XCTUnwrap(correctionBinding["resolvedContentHash"] as? String)
        let memoryRevision = try XCTUnwrap(proposal["baseMemoryRevision"] as? Int)
        let candidateVersion = try XCTUnwrap(originalCandidate["candidateVersion"] as? Int)
        XCTAssertNotEqual(sourceHash, resolvedHash)
        XCTAssertEqual(proposal["candidateContentHash"] as? String, resolvedHash)
        let runtime = AccountLeaseRuntime(authorityEpoch: "epoch-v1")
        runtime.publish(session: accountSession(
            subjectId: "owner-a",
            vaultId: vaultID,
            generation: 1,
            generationID: UUID(uuidString: "00000000-0000-0000-0000-000000000101")!
        ))
        let lease = try XCTUnwrap(runtime.capture(forSubjectId: "owner-a"))
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        let defaultsName = "correction-preview-policy-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        defer { defaults.removePersistentDomain(forName: defaultsName) }
        let policyStore = ReleasePolicyStore(userDefaults: defaults)
        try saveCandidateReleasePolicy(
            candidateReleasePolicyPayload(
                version: "correction-preview-policy-v1",
                revision: 1,
                expiresAt: "2099-01-01T00:00:00Z"
            ),
            store: policyStore,
            scope: candidateReleasePolicyScope(lease: lease)
        )
        let harness = try makeCandidatePolicyTestClient(
            runtime: runtime,
            lease: lease,
            authSession: { authSession },
            store: policyStore
        )
        let inbox: [String: Any] = [
            "schemaVersion": OwnerTruthCandidateInbox.schemaVersion,
            "vaultId": vaultID,
            "memoryRevision": memoryRevision,
            "candidates": [originalCandidate],
        ]
        _ = try OwnerTruthCandidateInbox(
            backendJSONObject: inbox,
            expectedVaultID: try XCTUnwrap(OwnerTruthVaultID(vaultID))
        )
        let emptyInbox: [String: Any] = [
            "schemaVersion": OwnerTruthCandidateInbox.schemaVersion,
            "vaultId": vaultID,
            "memoryRevision": memoryRevision + 1,
            "candidates": [],
        ]
        let decision: [String: Any] = [
            "schemaVersion": "owner-truth-candidate-decision-memory-v1",
            "status": "created",
            "receipt": [
                "receiptId": "00000000-0000-0000-0000-0000000001c4",
                "candidateId": candidateID.rawValue.uuidString.lowercased(),
                "decision": "corrected",
                "candidateVersion": candidateVersion + 1,
                "candidateBeforeHash": sourceHash,
                "candidateAfterHash": resolvedHash,
                "correctedValueId": "00000000-0000-0000-0000-0000000001c5",
            ],
            "memoryActivation": [
                "status": "created",
                "memoryId": "00000000-0000-0000-0000-0000000001c6",
                "memoryVersionId": "00000000-0000-0000-0000-0000000001c7",
                "contentHash": resolvedHash,
            ],
            "memoryRevision": memoryRevision + 1,
        ]
        var inboxCount = 0
        var previewPOSTCount = 0
        var decisionPOSTCount = 0
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            switch (request.httpMethod, request.url?.path ?? "") {
            case ("GET", let path) where path.hasSuffix("/candidates"):
                inboxCount += 1
                loader.respond(
                    statusCode: 200,
                    body: try! JSONSerialization.data(
                        withJSONObject: inboxCount == 1 ? inbox : emptyInbox
                    )
                )
            case ("POST", let path) where path.hasSuffix("/changeset-preview"):
                previewPOSTCount += 1
                loader.respond(
                    statusCode: 200,
                    body: try! JSONSerialization.data(withJSONObject: preview)
                )
            case ("POST", let path) where path.hasSuffix("/decisions"):
                decisionPOSTCount += 1
                loader.respond(
                    statusCode: 200,
                    body: try! JSONSerialization.data(withJSONObject: decision)
                )
            default:
                XCTFail("Unexpected request \(request.httpMethod ?? "") \(request.url?.path ?? "")")
                loader.fail(URLError(.unsupportedURL))
            }
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }

        let controller = OwnerTruthCandidateInboxViewController(
            accountLease: lease,
            client: harness.client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { harness.decision(.ownerTruthCandidateReview).allowed },
            pendingResultStore: OwnerTruthCandidateReviewTransientPendingResultStore()
        )
        var renderedState: OwnerTruthCandidateInboxViewState?
        controller.onViewStateRendered = { renderedState = $0 }
        let navigationController = ImmediateNavigationController(rootViewController: controller)
        let windowScene = try XCTUnwrap(
            UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.first
        )
        let window = UIWindow(windowScene: windowScene)
        window.frame = UIScreen.main.bounds
        window.rootViewController = navigationController
        window.makeKeyAndVisible()
        defer { window.isHidden = true }
        controller.loadViewIfNeeded()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            inboxCount == 1 && renderedState?.items.count == 1
        })

        let table = try XCTUnwrap(
            buttonOrLabel(in: controller.view, identifier: "owner-truth-candidate-inbox-list")
                as? UITableView
        )
        table.delegate?.tableView?(table, didSelectRowAt: IndexPath(row: 0, section: 0))
        let detail = try XCTUnwrap(
            navigationController.topViewController as? OwnerTruthCandidateDetailViewController
        )
        try XCTUnwrap(button(
            in: detail.view,
            identifier: "owner-truth-candidate-detail-correct"
        )).sendActions(for: .touchUpInside)
        let input = try XCTUnwrap(textView(
            in: detail.view,
            identifier: "owner-truth-candidate-correction-input"
        ))
        input.text = correctedText
        try XCTUnwrap(button(
            in: detail.view,
            identifier: "owner-truth-candidate-correction-submit"
        )).sendActions(for: .touchUpInside)

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            previewPOSTCount == 1
                && detail.presentedViewController?.view.accessibilityIdentifier
                    == "owner-truth-correction-preview"
        })
        XCTAssertEqual(decisionPOSTCount, 0)
        let previewController = try XCTUnwrap(detail.presentedViewController)
        let previewText = try XCTUnwrap(
            buttonOrLabel(
                in: previewController.view,
                identifier: "owner-truth-correction-preview-content"
            ) as? UITextView
        ).text ?? ""
        XCTAssertTrue(previewText.contains(correctedText))
        XCTAssertTrue(previewText.contains("基于正式记忆第 \(memoryRevision) 次修订快照"))
        attachUIKitEvidence(view: window, name: "T01-correction-preview-h1-not-h0")

        try XCTUnwrap(button(
            in: previewController.view,
            identifier: "owner-truth-correction-preview-confirm"
        )).sendActions(for: .touchUpInside)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) {
            decisionPOSTCount == 1
        })
        XCTAssertEqual(inboxCount, 1)
        let requests = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests
        XCTAssertEqual(requests.filter { $0.url?.path.hasSuffix("/changeset-preview") == true }.count, 1)
        XCTAssertEqual(requests.filter { $0.url?.path.hasSuffix("/decisions") == true }.count, 1)
        let decisionIndex = try XCTUnwrap(requests.firstIndex {
            $0.url?.path.hasSuffix("/decisions") == true
        })
        let decisionData = try XCTUnwrap(
            OwnerTruthReviewReadyHTTPURLProtocol.recordedRequestBodies[decisionIndex]
        )
        let decisionPayload = try XCTUnwrap(
            try JSONSerialization.jsonObject(with: decisionData) as? [String: Any]
        )
        XCTAssertEqual(decisionPayload["expectedCandidateVersion"] as? Int, candidateVersion)
        XCTAssertEqual(decisionPayload["expectedMemoryRevision"] as? Int, memoryRevision)
        XCTAssertEqual(
            decisionPayload["correctedValue"] as? [String: String],
            ["statement": correctedText]
        )
    }

