                "vaultId": vaultID.rawValue,
                "candidates": [candidate(
                    content: ["summary": "缺少 facets 的 V2 候选"],
                    schema: "owner-truth-v2"
                )],
            ],
            expectedVaultID: vaultID
        )
        XCTAssertEqual(invalidInbox.candidates.first?.facetsState, .invalid)
    }

