    func testMemoryVersionHistoryMapsCurrentAndSupersededVersionsWithLeaseFence() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let memoryID = recordID("00000000-0000-0000-0000-000000000014")
        let response: [String: Any] = [
            "schemaVersion": OwnerTruthMemoryVersionHistory.schemaVersion,
            "vaultId": vaultID.rawValue,
            "memoryKind": "experience",
            "perspectiveType": "firstPerson",
            "epistemicStatus": "recalled",
            "sensitivity": "standard",
            "memoryStatus": "active",
            "versions": [
                [
                    "versionNumber": 2,
                    "status": "current",
                    "decision": "corrected",
                    "contentSchemaVersion": "owner-truth-v2",
                    "content": [
                        "summary": "外祖父在院子里讲故事",
                        "facets": [
                            "people": [[
                                "value": "外祖父",
                                "evidenceMode": "ownerStated",
                                "confidence": 1.0,
                            ]],
                            "time": [],
                            "places": [],
                            "relationships": [],
                            "emotions": [],
                            "values": [],
                            "personality": [],
                            "confidence": 1.0,
                        ],
                    ],
                    "sourceCount": 1,
                    "createdAt": "2026-08-08T11:00:00Z",
                ],
                [
                    "versionNumber": 1,
                    "status": "superseded",
                    "decision": "accepted",
                    "contentSchemaVersion": "owner-truth-v1",
                    "content": ["summary": "父亲在院子里讲故事"],
                    "sourceCount": 1,
                    "createdAt": "2026-08-08T10:00:00Z",
                ],
            ],
        ]
        let history = try OwnerTruthMemoryVersionHistory(
            backendJSONObject: response,
            expectedVaultID: vaultID
        )
        XCTAssertEqual(history.versions.map(\.versionNumber), [2, 1])
        XCTAssertEqual(history.versions.map(\.status), [.current, .superseded])
        XCTAssertEqual(history.versions.map(\.decision), [.corrected, .accepted])

        let client = CandidateReviewClientSpy()
        client.memoryVersionHistoryResult = .success(history)
        let useCase = OwnerTruthMemoryVersionHistoryUseCase(
            accountLease: lease,
            memoryID: memoryID,
            client: client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { true }
        )
        useCase.refresh()

        XCTAssertEqual(useCase.viewState.phase, .ready)
        XCTAssertEqual(useCase.viewState.items.map(\.versionNumber), [2, 1])
        XCTAssertEqual(useCase.viewState.items.first?.summary, "外祖父在院子里讲故事")
        XCTAssertEqual(useCase.viewState.items.first?.status, .current)
        guard case .available(let facets)? = useCase.viewState.items.first?.facetsState else {
            return XCTFail("current V2 MemoryVersion facets must be available")
        }
        XCTAssertEqual(facets.values(for: .people).first?.value, "外祖父")
        XCTAssertEqual(useCase.viewState.items.last?.facetsState, .legacyNotAvailable)

        client.deferMemoryVersionHistory = true
        useCase.refresh()
        runtime.publish(session: accountSession(
            subjectId: "owner-b",
            vaultId: "vault-b",
            generation: 2,
            generationID: UUID(uuidString: "00000000-0000-0000-0000-000000000118")!
        ))
        client.completeDeferredMemoryVersionHistory(.success(history))

        XCTAssertEqual(useCase.viewState.phase, .unavailable)
        XCTAssertTrue(useCase.viewState.items.isEmpty)
    }

    func testCorrectReviewCommandRequiresValueAndProducesOnlyCorrectPayload() throws {
        XCTAssertThrowsError(
            try OwnerTruthCandidateReviewCommand(
                commandID: "candidate-correct-missing-value",
                expectedCandidateVersion: 1,
                action: .correct,
                reasonCode: "ownerCorrected"
            )
        ) { error in
            XCTAssertEqual(
                error as? OwnerTruthRemoteContractError,
                .invalidCommand("correct requires correctedValue and correctedValueSchemaVersion")
            )
        }

        let command = try OwnerTruthCandidateReviewCommand(
            commandID: "candidate-correct-001",
            expectedCandidateVersion: 2,
            action: .correct,
            correctedValue: ["summary": .string("更正后的记忆")],
            correctedValueSchemaVersion: "owner-truth-candidate-content-v1",
            reasonCode: "ownerCorrected"
        )

        let payload = command.backendPayload
        XCTAssertEqual(payload["action"] as? String, "correct")
        XCTAssertEqual(payload["expectedCandidateVersion"] as? Int, 2)
        XCTAssertEqual(
            (payload["correctedValue"] as? [String: Any])?["summary"] as? String,
            "更正后的记忆"
        )
        XCTAssertEqual(payload["correctedValueSchemaVersion"] as? String, "owner-truth-candidate-content-v1")

        XCTAssertThrowsError(
            try OwnerTruthCandidateReviewCommand(
                commandID: "candidate-accept-with-value",
                expectedCandidateVersion: 1,
                action: .accept,
                correctedValue: ["summary": .string("不应发送")],
                reasonCode: "ownerReviewed"
            )
        )

        let changeSetID = OwnerTruthRecordID(
            rawValue: UUID(uuidString: "00000000-0000-0000-0000-000000000077")!
        )
        let bound = try OwnerTruthCandidateReviewCommand(
            commandID: "candidate-bound-preview-001",
            expectedCandidateVersion: 2,
            action: .accept,
            reasonCode: "ownerReviewed",
            expectedMemoryRevision: 9,
            expectedChangeSetID: changeSetID,
            expectedProposalHash: String(repeating: "c", count: 64)
        )
        XCTAssertEqual(
            bound.backendPayload["expectedChangeSetId"] as? String,
            changeSetID.rawValue.uuidString.lowercased()
        )
        XCTAssertEqual(
            bound.backendPayload["expectedProposalHash"] as? String,
            String(repeating: "c", count: 64)
        )
        XCTAssertThrowsError(
            try OwnerTruthCandidateReviewCommand(
                commandID: "candidate-incomplete-preview-001",
                expectedCandidateVersion: 1,
                action: .accept,
                reasonCode: "ownerReviewed",
                expectedChangeSetID: changeSetID
            )
        )
    }

