    func testLiveV5SingleConfirmationCarriesDisplayedProposalBinding() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let batch = recordID("00000000-0000-0000-0000-000000000105")
        let candidateID = recordID("00000000-0000-0000-0000-000000000107")
        let item = try XCTUnwrap(v5CandidateInbox(vaultID: lease.vaultId, candidateID: candidateID, operationKind: "add").candidates.first)
        let proposal = try XCTUnwrap(item.proposedChangeSet)
        let operation = try XCTUnwrap(proposal.operations.first)
        let diff = operation.factDiff
        let raw: [String: Any] = [
            "schemaVersion": OwnerTruthCandidateChangeSetProposal.schemaVersion,
            "proposalId": proposal.proposalID.rawValue.uuidString,
            "proposalHash": proposal.proposalHash,
            "candidateContentHash": proposal.candidateContentHash,
            "candidateVersion": proposal.candidateVersion,
            "changeSetId": proposal.changeSetID.rawValue.uuidString,
            "baseMemoryRevision": proposal.baseMemoryRevision,
            "dependencies": [],
            "operations": [["operationIndex": 0, "operationKind": "add", "reason": operation.reason,
                "changedFields": operation.changedFields, "anticipatedActivation": "create",
                "factDiff": ["before": NSNull(), "after": diff.after?.backendJSONObject ?? NSNull(),
                    "candidate": diff.candidate.backendJSONObject,
                    "changedFields": [["path": "content", "before": NSNull(), "after": diff.after?.backendJSONObject ?? NSNull()]],
                    "evidence": ["beforeCount": 0, "candidateCount": 1, "afterCount": 1, "addedCount": 1]]]],
        ]
        let confirmation = try interviewCandidateConfirmation(vaultID: lease.vaultId, reviewBatchID: batch,
            batchCandidateID: recordID("00000000-0000-0000-0000-000000000106"), singleCandidateID: candidateID,
            singleMemoryKind: .knowledge, singleContentSchemaVersion: "owner-truth-v5",
            singleContent: item.content.mapValues(\.backendJSONObject), singleProposal: raw).bound(to: lease)
        for action in [OwnerTruthCandidateReviewAction.accept, .reject] {
            let client = InterviewCandidateConfirmationSingleActionClientSpy(); client.deferResult = true
            let useCase = OwnerTruthInterviewCandidateConfirmationSingleActionUseCase(accountLease: lease,
                confirmation: confirmation, client: client, confirmationReader: InterviewCandidateConfirmationClientSpy(),
                accountLeaseRuntime: runtime, releasePolicyAvailable: { true })
            useCase.send(action == .accept ? .accept(candidateID: candidateID) : .reject(candidateID: candidateID))
            let payload = try XCTUnwrap(client.requestedCommands.first).backendPayload
            XCTAssertTrue((payload["commandId"] as? String)?.hasPrefix("interview-single-") == true)
            XCTAssertNotNil((payload["commandId"] as? String)?.range(of: "^[A-Za-z][A-Za-z0-9_.:-]{0,127}$", options: .regularExpression))
            XCTAssertEqual(payload["expectedMemoryRevision"] as? Int, proposal.baseMemoryRevision)
            XCTAssertEqual((payload["expectedChangeSetId"] as? String)?.lowercased(), proposal.changeSetID.rawValue.uuidString.lowercased())
            XCTAssertEqual(payload["expectedProposalHash"] as? String, proposal.proposalHash)
        }
    }

