            capturedAt: capturedAt
        )

        let append = try delivery.appendCommand(
            threadID: threadID,
            sessionID: sessionID,
            expectedThreadVersion: 4,
            expectedSessionVersion: 5
        )
        let end = try OwnerTruthInterviewEndCommand(
            commandID: "live-end-command-001",
