        XCTAssertEqual(useCase.viewState.latestReceipt?.lifecycle, .paused)
        XCTAssertEqual(useCase.viewState.continuation?.state, .paused)
        XCTAssertEqual(useCase.viewState.continuation?.canContinue, false)
