    func testB8AdmissionRefreshUsesFreshDecisionThroughRealBackend() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let reviewBatchID = recordID("00000000-0000-0000-0000-000000000865")
        let acknowledgementReceipt = try pendingReviewBatchAcknowledgementReceipt(
            vaultID: lease.vaultId,
            reviewBatchID: reviewBatchID,
            threadID: recordID("00000000-0000-0000-0000-000000000866"),
            sessionID: recordID("00000000-0000-0000-0000-000000000867"),
            reviewBatchVersion: 7,
            sessionVersion: 5
        )
        let session = try makeOwnerTruthHTTPTestSession()
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        var policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "b8-candidate-expired-v1",
            policyRevision: 40,
            emergencyRevision: 2,
            expiresAt: Date().addingTimeInterval(-30),
            featureEnabled: true,
            releaseVisible: true,
            reason: "candidateReviewEnabled"
        )
        let featureGate = FeatureGateService.makeQATestService(
            accountGeneration: { "b8-same-account-generation" },
            policy: { _, _ in policy }
        )
        featureGate.captureServerPolicyManagedRoute(.ownerTruthCandidateReview)
        XCTAssertFalse(featureGate.requestServerPolicyManagedDecision(
            for: .ownerTruthCandidateReview
        ).allowed)
        var diagnostics: [OwnerTruthCandidateInboxDiagnosticEvent] = []
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: session,
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: {
                featureGate.requestServerPolicyManagedDecision(for: $0)
            },
            freshFeatureDecision: {
                featureGate.freshServerPolicyManagedRequestDecision(for: $0)
            },
            accountLeaseRuntime: runtime,
            candidateInboxDiagnosticSink: { diagnostics.append($0) }
        )
        let body = try JSONSerialization.data(withJSONObject: [
            "schemaVersion": OwnerTruthInterviewCandidateProposalAdmissionReceipt.schemaVersion,
            "vaultId": lease.vaultId,
            "status": OwnerTruthCommandOutcome.created.rawValue,
            "reviewBatch": ["reviewBatchId": reviewBatchID.rawValue.uuidString],
            "source": ["status": "admitted", "kind": "conversation", "version": 1],
            "candidateExtraction": ["status": "requested", "ownerMessageCount": 1],
            "candidate": ["status": "notCreated"],
            "memoryActivation": ["status": "notApplicable"],
        ])
        OwnerTruthReviewReadyHTTPURLProtocol.install { _, loader in
            loader.respond(statusCode: 201, body: body)
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
        var policyAvailable = false
        let useCase = OwnerTruthInterviewCandidateProposalAdmissionUseCase(
            accountLease: lease,
            acknowledgementReceipt: acknowledgementReceipt,
            client: client,
            accountLeaseRuntime: runtime,
            releasePolicyAvailable: {
                policyAvailable && featureGate.requestServerPolicyManagedDecision(
                    for: .ownerTruthCandidateReview
                ).allowed
            },
            refreshReleasePolicy: { completion in
                policy = FeatureGatePolicySnapshot(
                    accessMode: .useCachedPolicy,
                    policyVersion: "b8-candidate-fresh-v2",
                    policyRevision: 41,
                    emergencyRevision: 2,
                    expiresAt: Date().addingTimeInterval(300),
                    featureEnabled: true,
                    releaseVisible: true,
                    reason: "candidateReviewEnabled"
                )
                policyAvailable = true
                completion(true)
            }
        )

        useCase.send(.admit)

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) { useCase.viewState.phase != .admitting })
        XCTAssertEqual(useCase.viewState.phase, .admitted)
        XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 1)
        XCTAssertEqual(vaultID, useCase.viewState.receipt?.vaultID)
        XCTAssertFalse(featureGate.requestServerPolicyManagedDecision(
            for: .ownerTruthCandidateReview
        ).allowed, "the old route remains denied and must not authorize admission")
        let traces = Set(diagnostics.map(\.traceID))
        XCTAssertEqual(traces.count, 1)
        XCTAssertTrue(diagnostics.contains { $0.event == "featureRevalidated" })
        XCTAssertTrue(diagnostics.contains { $0.event == "requestCreated" })
        XCTAssertTrue(diagnostics.contains { $0.event == "taskResumed" })
        XCTAssertTrue(diagnostics.contains {
            $0.event == "responseReceived" && $0.httpStatus == 201
        })
        XCTAssertTrue(diagnostics.contains { $0.event == "typedDecodeSucceeded" })
    }

