    func testB8AdmissionRealBackendPreflightDenialsIdentifyStageAndNeverCreatePost() throws {
        let previousRuntimePolicy = RecoveryRuntimePolicyStore.shared.currentPolicy
        let normalRuntimePolicy = BackendRecoveryRuntimePolicy(json: [
            "schemaVersion": 1,
            "mode": "normal",
            "authorityEpoch": "epoch-v1",
            "writesAllowed": true,
            "authenticatedSessionPolicy": "preserve",
            "cacheWritePolicy": "enabled",
            "scope": "globalRecoveryFence",
            "configurationValid": true,
            "contractVersion": 1,
        ])
        let blockedRuntimePolicy = BackendRecoveryRuntimePolicy(json: [
            "schemaVersion": 1,
            "mode": "maintenance",
            "authorityEpoch": "epoch-v1",
            "writesAllowed": false,
            "authenticatedSessionPolicy": "preserve",
            "cacheWritePolicy": "disabled",
            "scope": "globalRecoveryFence",
            "configurationValid": true,
            "contractVersion": 1,
        ])
        RecoveryRuntimePolicyStore.shared.update(normalRuntimePolicy)
        defer { RecoveryRuntimePolicyStore.shared.update(previousRuntimePolicy) }
        OwnerTruthReviewReadyHTTPURLProtocol.install { _, _ in
            XCTFail("an admission rejected by preflight must not reach the controlled upstream")
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }

        func runCase(
            name: String,
            runtime: AccountLeaseRuntime,
            lease: AccountLease,
            authenticatedSession: BackendAuthSessionContract?,
            privateAccessAllowed: Bool,
            currentUserID: String,
            runtimePolicy: BackendRecoveryRuntimePolicy
        ) throws -> [OwnerTruthCandidateInboxDiagnosticEvent] {
            RecoveryRuntimePolicyStore.shared.update(runtimePolicy)
            let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
            let command = try OwnerTruthInterviewCandidateProposalAdmissionCommand(
                commandID: "b8-preflight-\(name)",
                reviewBatchID: recordID("00000000-0000-0000-0000-00000000086d"),
                expectedReviewBatchVersion: 7
            )
            var diagnostics: [OwnerTruthCandidateInboxDiagnosticEvent] = []
            let client = DreamJourneyBackendClient.makeQATestClient(
                baseURL: URL(string: "https://owner-truth.qa.invalid")!,
                session: try makeOwnerTruthHTTPTestSession(),
                authenticatedSession: { authenticatedSession },
                currentUserID: { currentUserID },
                privateAccessAllowed: { privateAccessAllowed },
                featureDecision: Self.ownerTruthHTTPTestFeatureDecision,
                accountLeaseRuntime: runtime,
                candidateInboxDiagnosticSink: { diagnostics.append($0) }
            )
            var outcome: OwnerTruthInterviewWriteTransportOutcome<
                OwnerTruthInterviewCandidateProposalAdmissionReceipt
            >?

            client.admitOwnerTruthInterviewCandidateProposalWrite(
                accountLease: lease,
                vaultID: vaultID,
                command: command
            ) { outcome = $0 }

            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) { outcome != nil }, name)
            guard case .notSent? = outcome else {
                XCTFail("\(name) must be classified as notSent")
                return diagnostics
            }
            XCTAssertTrue(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.isEmpty, name)
            return diagnostics
        }

        let (privateRuntime, privateLease) = try makeActiveRuntime()
        let privateAuth = try makeOwnerTruthHTTPTestAuthSession(userID: privateLease.subjectId)
        let privateDiagnostics = try runCase(
            name: "private-ui",
            runtime: privateRuntime,
            lease: privateLease,
            authenticatedSession: privateAuth,
            privateAccessAllowed: false,
            currentUserID: privateLease.subjectId,
            runtimePolicy: normalRuntimePolicy
        )
        XCTAssertTrue(privateDiagnostics.contains {
            $0.event == "requestDenied" && $0.stage == "privateUI"
        })

        let (authRuntime, authLease) = try makeActiveRuntime()
        let authDiagnostics = try runCase(
            name: "authentication",
            runtime: authRuntime,
            lease: authLease,
            authenticatedSession: nil,
            privateAccessAllowed: true,
            currentUserID: authLease.subjectId,
            runtimePolicy: normalRuntimePolicy
        )
        XCTAssertTrue(authDiagnostics.contains {
            $0.event == "requestDenied" && $0.stage == "authentication"
        })

        let (scopeRuntime, scopeLease) = try makeActiveRuntime()
        let wrongSubjectAuth = try makeOwnerTruthHTTPTestAuthSession(userID: "owner-b")
        let scopeDiagnostics = try runCase(
            name: "authentication-scope",
            runtime: scopeRuntime,
            lease: scopeLease,
            authenticatedSession: wrongSubjectAuth,
            privateAccessAllowed: true,
            currentUserID: scopeLease.subjectId,
            runtimePolicy: normalRuntimePolicy
        )
        XCTAssertTrue(scopeDiagnostics.contains {
            $0.event == "requestDenied" && $0.stage == "authenticationScope"
        })

        let (leaseRuntime, staleLease) = try makeActiveRuntime()
        leaseRuntime.publish(session: accountSession(
            subjectId: staleLease.subjectId,
            vaultId: staleLease.vaultId,
            generation: staleLease.generation + 1,
            generationID: UUID(uuidString: "00000000-0000-0000-0000-00000000086e")!,
            sessionID: "b8-preflight-successor"
        ))
        let staleLeaseAuth = try makeOwnerTruthHTTPTestAuthSession(userID: staleLease.subjectId)
        let leaseDiagnostics = try runCase(
            name: "application-lease",
            runtime: leaseRuntime,
            lease: staleLease,
            authenticatedSession: staleLeaseAuth,
            privateAccessAllowed: true,
            currentUserID: staleLease.subjectId,
            runtimePolicy: normalRuntimePolicy
        )
        XCTAssertTrue(leaseDiagnostics.contains {
            $0.event == "clientLeaseChecked" && $0.stage == "admissionPreflight"
        })

        let (runtimePolicyRuntime, runtimePolicyLease) = try makeActiveRuntime()
        let runtimePolicyAuth = try makeOwnerTruthHTTPTestAuthSession(
            userID: runtimePolicyLease.subjectId
        )
        let runtimeDiagnostics = try runCase(
            name: "runtime-policy",
            runtime: runtimePolicyRuntime,
            lease: runtimePolicyLease,
            authenticatedSession: runtimePolicyAuth,
            privateAccessAllowed: true,
            currentUserID: runtimePolicyLease.subjectId,
            runtimePolicy: blockedRuntimePolicy
        )
        XCTAssertTrue(runtimeDiagnostics.contains {
            $0.event == "requestRuntimeChecked" && $0.stage == "runtimePolicy"
        })
        let allDiagnostics = privateDiagnostics
            + authDiagnostics
            + scopeDiagnostics
            + leaseDiagnostics
            + runtimeDiagnostics
        XCTAssertFalse(allDiagnostics.contains {
            $0.event == "typedDecodeSucceeded" || $0.event == "typedDecodeFailed"
        }, "preflight denials have no response body to type-decode")
        XCTAssertTrue(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.isEmpty)
    }

