    func testB8AdmissionPolicyRefreshDeadlineRejectsLateSuccessWithoutTransport() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let reviewBatchID = recordID("00000000-0000-0000-0000-000000000891")
        let acknowledgementReceipt = try pendingReviewBatchAcknowledgementReceipt(
            vaultID: lease.vaultId,
            reviewBatchID: reviewBatchID,
            threadID: recordID("00000000-0000-0000-0000-000000000892"),
            sessionID: recordID("00000000-0000-0000-0000-000000000893"),
            reviewBatchVersion: 2,
            sessionVersion: 2
        )
        let client = InterviewCandidateProposalAdmissionClientSpy()
        var policyAvailable = false
        var refreshCompletion: ((Bool) -> Void)?
        var deadlineAction: (() -> Void)?
        let useCase = OwnerTruthInterviewCandidateProposalAdmissionUseCase(
            accountLease: lease,
            acknowledgementReceipt: acknowledgementReceipt,
            client: client,
            accountLeaseRuntime: runtime,
            releasePolicyAvailable: { policyAvailable },
            refreshReleasePolicy: { refreshCompletion = $0 },
            policyRefreshTimeout: 30,
            schedulePolicyRefreshTimeout: { _, action in
                deadlineAction = action
                return DispatchWorkItem(block: {})
            }
        )

        useCase.send(.admit)
        XCTAssertEqual(useCase.viewState.phase, .waitingForPolicy)

        try XCTUnwrap(deadlineAction)()
        XCTAssertEqual(useCase.viewState.phase, .unavailable)
        XCTAssertEqual(useCase.viewState.notice, .policyRefreshTimedOut)
        XCTAssertTrue(client.requestedCommands.isEmpty)

        policyAvailable = true
        try XCTUnwrap(refreshCompletion)(true)
        XCTAssertTrue(client.requestedCommands.isEmpty, "late policy success cannot expose a write")
    }

    func testB8CompletionCheckpointPersistsUnknownOutcomeForEveryWriteStage() throws {
        let (_, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("b8-write-outcome-checkpoint-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let store = EchoLiveMemoryCompletionCheckpointStore(rootDirectory: root)
        let productSessionID = "b8-write-outcome-checkpoint"
        let threadID = recordID("00000000-0000-0000-0000-0000000008a1")
        let sessionID = recordID("00000000-0000-0000-0000-0000000008a2")
        let reviewBatchID = recordID("00000000-0000-0000-0000-0000000008a3")
        let endCommand = try OwnerTruthInterviewEndCommand(
            commandID: "b8-end-command",
            threadID: threadID,
            sessionID: sessionID,
            expectedThreadVersion: 1,
            expectedSessionVersion: 1,
            lastClientSequenceNumber: 1
        )
        try store.prepareEnd(endCommand, productSessionID: productSessionID, for: lease)
        try store.recordEndTransportOutcome(
            .outcomeUnknown,
            command: endCommand,
            productSessionID: productSessionID,
            for: lease
        )
        XCTAssertEqual(
            try store.load(productSessionID: productSessionID, for: lease)?.endTransportOutcome,
            .outcomeUnknown
        )

        let endReceipt = try interviewNaturalInputReceipt(vaultID: vaultID, end: endCommand)
        try store.acceptEnd(endReceipt, productSessionID: productSessionID, for: lease)
        let acknowledgementCommand = try OwnerTruthInterviewReviewBatchAcknowledgementCommand(
            commandID: "b8-ack-command",
            reviewBatchID: reviewBatchID,
            threadID: threadID,
            sessionID: sessionID,
            expectedSessionVersion: endReceipt.sessionVersion,
            expectedReviewBatchVersion: 1
        )
        try store.prepareAcknowledgement(
            acknowledgementCommand,
            productSessionID: productSessionID,
            for: lease
        )
        try store.recordAcknowledgementTransportOutcome(
            .outcomeUnknown,
            command: acknowledgementCommand,
            productSessionID: productSessionID,
            for: lease
        )
        XCTAssertEqual(
            try store.load(
                productSessionID: productSessionID,
                for: lease
            )?.acknowledgementTransportOutcome,
            .outcomeUnknown
        )
    }

