    func testB8AdmissionRequestCancelledBeforeTaskCreationIsNotSent() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let reviewBatchID = recordID("00000000-0000-0000-0000-0000000008b2")
        let command = try OwnerTruthInterviewCandidateProposalAdmissionCommand(
            commandID: "b8-admit-cancel-before-resume",
            reviewBatchID: reviewBatchID,
            expectedReviewBatchVersion: 4
        )
        let adapterStarted = expectation(description: "admission entered request adapter")
        let interceptor = Adapter { _, _, _ in
            adapterStarted.fulfill()
        }
        let session = try makeOwnerTruthHTTPTestSession(interceptor: interceptor)
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        var events: [OwnerTruthCandidateInboxDiagnosticEvent] = []
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: session,
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: Self.ownerTruthHTTPTestFeatureDecision,
            accountLeaseRuntime: runtime,
            candidateInboxDiagnosticSink: { events.append($0) }
        )
        OwnerTruthReviewReadyHTTPURLProtocol.install { _, _ in
            XCTFail("A suspended admission must not reach the controlled upstream")
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
        var outcome: OwnerTruthInterviewWriteTransportOutcome<
            OwnerTruthInterviewCandidateProposalAdmissionReceipt
        >?

        client.admitOwnerTruthInterviewCandidateProposalWrite(
            accountLease: lease,
            vaultID: vaultID,
            command: command
        ) { outcome = $0 }

        wait(for: [adapterStarted], timeout: 2)
        XCTAssertTrue(events.contains { $0.event == "requestCreated" })
        XCTAssertFalse(events.contains { $0.event == "taskCreated" })
        XCTAssertFalse(events.contains { $0.event == "taskResumed" })
        let cancellationFinished = expectation(description: "cancel suspended admission")
        session.cancelAllRequests {
            cancellationFinished.fulfill()
        }
        wait(for: [cancellationFinished], timeout: 2)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) { outcome != nil })
        guard case .notSent? = outcome else {
            return XCTFail("a request cancelled before task resume must remain notSent")
        }
        XCTAssertFalse(events.contains { $0.event == "taskResumed" })
        XCTAssertTrue(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.isEmpty)
    }

