    private func seedB8S01AdmittedCheckpoint(
        store: EchoLiveMemoryCompletionCheckpointStore,
        productSessionID: String,
        lease: AccountLease,
        threadID: OwnerTruthRecordID,
        sessionID: OwnerTruthRecordID,
        reviewBatchID: OwnerTruthRecordID
    ) throws {
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let end = try OwnerTruthInterviewEndCommand(
            commandID: "b8-s01-end-\(productSessionID)",
            threadID: threadID,
            sessionID: sessionID,
            expectedThreadVersion: 1,
            expectedSessionVersion: 1,
            lastClientSequenceNumber: 1
        )
        let ended = try interviewNaturalInputReceipt(vaultID: vaultID, end: end)
        let acknowledgement = try OwnerTruthInterviewReviewBatchAcknowledgementCommand(
            commandID: "b8-s01-ack-\(productSessionID)",
            reviewBatchID: reviewBatchID,
            threadID: threadID,
            sessionID: sessionID,
            expectedSessionVersion: ended.sessionVersion,
            expectedReviewBatchVersion: 1
        )
        let acknowledged = try pendingReviewBatchAcknowledgementReceipt(
            vaultID: lease.vaultId,
            reviewBatchID: reviewBatchID,
            threadID: threadID,
            sessionID: sessionID,
            reviewBatchVersion: 2,
            sessionVersion: ended.sessionVersion + 1
        )
        let admission = try OwnerTruthInterviewCandidateProposalAdmissionCommand(
            commandID: "b8-s01-admit-\(productSessionID)",
            reviewBatchID: reviewBatchID,
            expectedReviewBatchVersion: acknowledged.reviewBatchVersion
        )
        try store.prepareEnd(end, productSessionID: productSessionID, for: lease)
        try store.acceptEnd(ended, productSessionID: productSessionID, for: lease)
        try store.prepareAcknowledgement(
            acknowledgement,
            productSessionID: productSessionID,
            for: lease
        )
        try store.acceptAcknowledgement(
            acknowledged,
            productSessionID: productSessionID,
            for: lease
        )
        try store.prepareAdmission(
            admission,
            productSessionID: productSessionID,
            for: lease
        )
        try store.acceptAdmission(
            try candidateProposalAdmissionReceipt(
                vaultID: lease.vaultId,
                reviewBatchID: reviewBatchID
            ),
            productSessionID: productSessionID,
            for: lease
        )
    }

    private func g02PendingGroupDirectoryURL() -> URL {
        let root = FileManager.default.urls(
            for: .applicationSupportDirectory,
            in: .userDomainMask
        ).first ?? FileManager.default.temporaryDirectory
        return root.appendingPathComponent(
            "b4-g02-pending-group-process-restart",
            isDirectory: true
        )
    }

