    private func liveDeliveryStatus(
        vaultID: OwnerTruthVaultID,
        productSessionID: String,
        start: OwnerTruthInterviewNaturalInputStartCommand,
        deliveries: [OwnerTruthInterviewNaturalInputAppendCommand],
        threadVersionOverride: Int? = nil
    ) throws -> OwnerTruthLiveDeliveryStatus {
        let sortedDeliveries = deliveries.sorted {
            ($0.clientSequenceNumber ?? 0) < ($1.clientSequenceNumber ?? 0)
        }
        let firstSequence = sortedDeliveries.first?.clientSequenceNumber ?? 1
        let continuousSequence = sortedDeliveries.last?.clientSequenceNumber ?? 0
        return try OwnerTruthLiveDeliveryStatus(
            backendJSONObject: [
                "schemaVersion": OwnerTruthLiveDeliveryStatus.schemaVersion,
                "vaultId": vaultID.rawValue,
                "productSessionId": productSessionID,
                "session": [
                    "threadId": start.threadID.rawValue.uuidString.lowercased(),
                    "sessionId": start.sessionID.rawValue.uuidString.lowercased(),
                    "state": "active",
                    "boundary": "open",
                    "threadVersion": threadVersionOverride ?? max(1, continuousSequence + 1),
                    "sessionVersion": max(1, continuousSequence + 1),
                    "authorityEpoch": 0,
                    "continuousClientSequence": continuousSequence,
                    "closeRequestedClientSequence": NSNull(),
                ],
                "observedAt": "2026-09-15T03:00:00Z",
                "window": [
                    "fromClientSequence": firstSequence,
                    "limit": 64,
                    "missingClientSequences": [],
                    "nextFromClientSequence": NSNull(),
                ],
                "deliveries": try sortedDeliveries.map { append in
                    [
                        "messageId": append.messageID.rawValue.uuidString.lowercased(),
                        "commandIdHash": SHA256.hash(data: Data(append.commandID.utf8)).map {
                            String(format: "%02x", $0)
                        }.joined(),
                        "clientSequenceNumber": try XCTUnwrap(append.clientSequenceNumber),
                        "author": append.role.rawValue,
                        "kind": "freeText",
                        "capturedAt": ISO8601DateFormatter().string(
                            from: try XCTUnwrap(append.capturedAt)
                        ),
                        "contentHash": try OwnerTruthInterviewLiveTurnDelivery(
                            commandID: append.commandID,
                            messageID: append.messageID,
                            clientSequenceNumber: try XCTUnwrap(append.clientSequenceNumber),
                            role: append.role,
                            text: append.text,
                            capturedAt: try XCTUnwrap(append.capturedAt)
                        ).serverContentHash(),
                    ] as [String: Any]
                },
                "operations": [],
            ],
            expectedVaultID: vaultID,
            expectedSessionID: start.sessionID,
            expectedProductSessionID: productSessionID
        )
    }

    private func interviewNaturalInputReceipt(
        vaultID: OwnerTruthVaultID,
        append: OwnerTruthInterviewNaturalInputAppendCommand
    ) throws -> OwnerTruthInterviewNaturalInputReceipt {
        var receipt: [String: Any] = [
            "status": OwnerTruthCommandOutcome.created.rawValue,
            "threadId": append.threadID.rawValue.uuidString,
            "sessionId": append.sessionID.rawValue.uuidString,
            "threadVersion": append.expectedThreadVersion + 1,
            "sessionVersion": append.expectedSessionVersion + 1,
            "state": OwnerTruthInterviewSessionLifecycle.active.rawValue,
            "boundary": OwnerTruthInterviewSessionBoundary.open.rawValue,
            "messageId": append.messageID.rawValue.uuidString,
            "messageSequence": 1,
            "authorityEpoch": 0,
        ]
        if let clientSequenceNumber = append.clientSequenceNumber {
            receipt["clientSequenceNumber"] = clientSequenceNumber
            receipt["continuousClientSequence"] = clientSequenceNumber
            receipt["deliveryState"] = OwnerTruthInterviewNaturalInputDeliveryState.contiguous.rawValue
        }
        return try OwnerTruthInterviewNaturalInputReceipt(
            backendJSONObject: [
                "schemaVersion": OwnerTruthInterviewNaturalInputReceipt.schemaVersion,
                "vaultId": vaultID.rawValue,
                "receipt": receipt,
            ],
            expectedVaultID: vaultID
        )
    }

