    func testMIC01ExpiredRouteWithCurrentAllowedPolicyIssuesOneVoiceTicket() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        var now = Date(timeIntervalSince1970: 1_800_000_000)
        var policyExpiry = now.addingTimeInterval(5)
        let gate = FeatureGateService.makeQATestService(
            accountGeneration: { authSession.sessionId },
            policy: { _, _ in
                FeatureGatePolicySnapshot(
                    accessMode: .useCachedPolicy,
                    policyVersion: "mic-01-current-policy",
                    policyRevision: 7,
                    emergencyRevision: 0,
                    expiresAt: policyExpiry,
                    featureEnabled: true,
                    releaseVisible: true,
                    reason: "allowed"
                )
            },
            now: { now }
        )
        XCTAssertTrue(gate.captureServerPolicyManagedRoute(.echoTextInput).allowed)
        now = now.addingTimeInterval(10)
        policyExpiry = now.addingTimeInterval(300)
        XCTAssertEqual(
            gate.requestServerPolicyManagedDecision(for: .echoTextInput).reason,
            "capturedPolicyExpired"
        )
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
            freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
            featureDecisionRevalidator: { gate.revalidateServerPolicyManagedRequest($0) },
            accountLeaseRuntime: runtime
        )
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
        let role = "Synthetic formal-memory role"
        let digest = SHA256.hash(data: Data(role.utf8)).map {
            String(format: "%02x", $0)
        }.joined()
        let providerHash = "sha256:\(digest)"
        let snapshot: [String: Any] = [
            "schemaVersion": "formal-memory-conversation-v3",
            "projectionCheckpoint": "checkpoint-mic-01",
            "authorityEpoch": 7,
            "memoryRevision": 1,
            "contextHash": "sha256:synthetic-context",
            "providerRoleText": role,
            "providerContextHash": providerHash,
            "coreFacts": [],
            "coverage": ["eligibleFactCount": 0, "omittedFactCount": 0],
        ]
        let response = try JSONSerialization.data(withJSONObject: [
            "status": "ready",
            "credentialMode": "oneTimeBackendProxyTicket",
            "accessPath": "backendRealtimeProxy",
            "mobileDirectAllowed": false,
            "brokerStatus": "verified",
            "providerReady": true,
            "releaseVisible": true,
            "retryable": true,
            "contractVersion": 7,
            "expiresAt": "2099-01-01T00:00:00Z",
            "echoSession": [
                "productSessionId": "mic-01-product-session",
                "targetPersonaId": lease.subjectId,
                "projectionCheckpoint": "checkpoint-mic-01",
                "authorityEpoch": 7,
                "memoryRevision": 1,
                "contextHash": "sha256:synthetic-context",
                "providerContextHash": providerHash,
            ],
            "sessionContext": [
                "systemRole": role,
                "speakingStyle": "neutral",
                "providerRoleText": role,
                "providerContextHash": providerHash,
                "formalMemorySnapshot": snapshot,
            ],
            "proxy": [
                "address": "wss://api.example.test",
                "uri": "/voice/realtime-stream",
                "sessionToken": "djv_synthetic_ticket",
                "sessionHeader": "X-DreamJourney-Voice-Session",
                "sdkClientID": "dreamjourney-realtime-proxy",
                "sdkClientKey": "proxy-session",
                "sdkResourceID": "dreamjourney.realtime.proxy",
                "uid": "dju_synthetic",
            ],
        ])
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            XCTAssertEqual(request.url?.path, "/voice/realtime-token")
            XCTAssertEqual(request.httpMethod, "POST")
            loader.respond(statusCode: 200, body: response)
        }
        let completed = expectation(description: "MIC-01 ticket completion")
        var issued = false
        client.fetchRealtimeVoiceConfig(userId: lease.subjectId) { result in
            if case .success(let config) = result {
                issued = !config.isBlocked
            }
            completed.fulfill()
        }
        wait(for: [completed], timeout: 5)
        XCTAssertTrue(issued, "current allowed policy must authorize this new launch")
        XCTAssertEqual(
            OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 1,
            "exactly one voice ticket POST, no policy refresh on a fresh cache"
        )
    }

