            ],
            "sessionContext": [
                "systemRole": role,
                "speakingStyle": "neutral",
                "providerRoleText": role,
                "providerContextHash": providerHash,
                "formalMemorySnapshot": snapshot,
            ],
            "proxy": [
                "address": "wss://api.example.test",
                "uri": "/voice/realtime-stream",
                "sessionToken": "djv_synthetic_ticket",
                "sessionHeader": "X-DreamJourney-Voice-Session",
                "sdkClientID": "dreamjourney-realtime-proxy",
                "sdkClientKey": "proxy-session",
                "sdkResourceID": "dreamjourney.realtime.proxy",
                "uid": "dju_synthetic",
            ],
        ])
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            XCTAssertEqual(request.url?.path, "/voice/realtime-token")
            XCTAssertEqual(request.httpMethod, "POST")
            loader.respond(statusCode: 200, body: response)
        }
        let controller = EchoViewController()
        var sdkConfigurations = 0
        var sdkStarts = 0
        let sdkStarted = expectation(description: "MIC-01 SDK start")
        let listening = expectation(description: "MIC-01 controller listening")
        controller.installVoiceLaunchBoundariesForTesting(
            accountLease: lease,
            client: client,
            permission: { $0(true) },
            configureSDK: { _ in sdkConfigurations += 1; return true },
            startSDK: { callback in
                sdkStarts += 1
                callback()
                sdkStarted.fulfill()
            },
            prepareAudio: { true }
        )
        controller.onVoiceListeningForTesting { listening.fulfill() }
        controller.tapMicrophoneForTesting()
        wait(for: [sdkStarted, listening], timeout: 5)
        XCTAssertTrue(controller.isVoiceListeningForTesting)
        XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 1)
        XCTAssertEqual(sdkConfigurations, 1)
        XCTAssertEqual(sdkStarts, 1)
    }

    func testMIC05OldSDKCallbackAfterStopCannotReplaceNewListening() throws {
