    private func assertMIC05QueuedControllerEventCannotCompleteNewLaunch(
        _ event: String
    ) throws {
            let ownerID = "mic-05-queued-\(event)-owner"
            let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: ownerID)
            let previousUser = UserManager.shared.currentUser
            let runtime = AccountLeaseRuntime.shared
            runtime.updateAuthorityEpoch("mic-05-queued-\(event)-epoch")
            runtime.publish(session: accountSession(
                subjectId: ownerID,
                vaultId: "mic-05-queued-\(event)-vault",
                generation: 1,
                generationID: UUID(),
                sessionID: authSession.sessionId
            ))
            UserManager.shared.setSyntheticCurrentUserForTesting(UserModel(
                id: ownerID, nickname: "Synthetic owner", phone: ""
            ))
            defer {
                OwnerTruthReviewReadyHTTPURLProtocol.reset()
                UserManager.shared.setSyntheticCurrentUserForTesting(previousUser)
                runtime.publish(session: nil)
            }
            let lease = try XCTUnwrap(runtime.capture(forSubjectId: ownerID))
            let now = Date(timeIntervalSince1970: 1_800_000_000)
            let gate = FeatureGateService.makeQATestService(
                accountGeneration: { authSession.sessionId },
                policy: { _, _ in FeatureGatePolicySnapshot(
                    accessMode: .useCachedPolicy,
                    policyVersion: "mic-05-queued-policy",
                    policyRevision: 7,
                    emergencyRevision: 0,
                    expiresAt: now.addingTimeInterval(300),
                    featureEnabled: true,
                    releaseVisible: true,
                    reason: "allowed"
                ) },
                now: { now }
            )
            let client = DreamJourneyBackendClient.makeQATestClient(
                baseURL: URL(string: "https://owner-truth.qa.invalid")!,
                session: try makeOwnerTruthHTTPTestSession(),
                authenticatedSession: { authSession },
                currentUserID: { ownerID },
                privateAccessAllowed: { true },
                featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
                freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
                accountLeaseRuntime: runtime
            )
            let response = try micVoiceTicketResponse(
                ownerID: ownerID, productSessionID: "mic-05-queued-product"
            )
            OwnerTruthReviewReadyHTTPURLProtocol.install { _, loader in
                loader.respond(statusCode: 200, body: response)
            }
            let controller = EchoViewController()
            let firstStarted = expectation(description: "\(event) A SDK start")
            let secondStarted = expectation(description: "\(event) B SDK start")
            let listening = expectation(description: "\(event) B listening")
            var sdkCallbacks: [() -> Void] = []
            var queuedEvents: [() -> Void] = []
            controller.installVoiceLaunchBoundariesForTesting(
                accountLease: lease,
                client: client,
                permission: { $0(true) },
                configureSDK: { _ in true },
                startSDK: { callback in
                    sdkCallbacks.append(callback)
                    if sdkCallbacks.count == 1 { firstStarted.fulfill() }
                    if sdkCallbacks.count == 2 { secondStarted.fulfill() }
                },
                prepareAudio: { true }
            )
            controller.setVoiceDelegateEventSchedulerForTesting { queuedEvents.append($0) }
            controller.onVoiceListeningForTesting { listening.fulfill() }
            controller.tapMicrophoneForTesting()
            wait(for: [firstStarted], timeout: 5)
            if event == "success" {
                sdkCallbacks[0]()
            } else {
                controller.onError(error: NSError(domain: "MIC05", code: 1))
            }
            XCTAssertEqual(queuedEvents.count, 1)
            let oldEvent = queuedEvents.removeFirst()
            controller.tapMicrophoneForTesting()
            controller.tapMicrophoneForTesting()
            wait(for: [secondStarted], timeout: 5)
            let secondAttempt = try XCTUnwrap(controller.activeVoiceLaunchAttemptForTesting)
            oldEvent()
            XCTAssertTrue(secondAttempt.isActive)
            XCTAssertTrue(controller.activeVoiceLaunchAttemptForTesting === secondAttempt)
            XCTAssertFalse(controller.isVoiceListeningForTesting)
            sdkCallbacks[1]()
            XCTAssertEqual(queuedEvents.count, 1)
            if !queuedEvents.isEmpty {
                queuedEvents.removeFirst()()
            } else {
                XCTFail("B callback was not queued after the old \(event) event")
            }
            wait(for: [listening], timeout: 5)
            XCTAssertTrue(controller.isVoiceListeningForTesting)
            XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 2)
    }

    func testMIC19OldDiskCaptureSurvivesNewDenyAndNewSDKFailure() throws {
        let ownerID = "mic-19-owner"
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: ownerID)
        let previousUser = UserManager.shared.currentUser
        let runtime = AccountLeaseRuntime.shared
        runtime.updateAuthorityEpoch("mic-19-epoch")
        runtime.publish(session: accountSession(
            subjectId: ownerID,
            vaultId: "mic-19-vault",
            generation: 1,
            generationID: UUID(),
            sessionID: authSession.sessionId
        ))
        UserManager.shared.setSyntheticCurrentUserForTesting(UserModel(
            id: ownerID, nickname: "Synthetic owner", phone: ""
        ))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("mic19-\(UUID().uuidString)")
        let defaultsName = "mic19-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        defer {
            OwnerTruthReviewReadyHTTPURLProtocol.reset()
            UserManager.shared.setSyntheticCurrentUserForTesting(previousUser)
            runtime.publish(session: nil)
            defaults.removePersistentDomain(forName: defaultsName)
            try? FileManager.default.removeItem(at: root)
        }
        let lease = try XCTUnwrap(runtime.capture(forSubjectId: ownerID))
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root.appendingPathComponent("outbox")
        )
        let followUp = EchoLiveMemoryFollowUpStore(
            defaults: defaults, rootDirectory: root.appendingPathComponent("followup")
        )
        let checkpoint = EchoLiveMemoryCompletionCheckpointStore(
            rootDirectory: root.appendingPathComponent("checkpoint")
        )
        let sceneA = "mic-19-scene-a"
        let pendingA = try outbox.enqueue(
            role: .owner, text: "旧场仍须保存的合成正文。",
            for: lease, productSessionID: sceneA
        )
        _ = try outbox.markClosing(
            lastClientSequenceNumber: pendingA.lastClientSequenceNumber,
            for: lease, productSessionID: sceneA
        )
        try followUp.upsert(
            productSessionID: sceneA,
            reviewBatchID: recordID("00000000-0000-0000-0000-000000000919"),
            for: lease
        )
        let oldOutbox = try XCTUnwrap(outbox.load(for: lease, productSessionID: sceneA))
        let oldFollowUp = followUp.records(for: lease)
        let oldCheckpoint = try checkpoint.load(productSessionID: sceneA, for: lease)
        let oldClient = InterviewNaturalInputClientSpy()
        let oldCoordinator = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: oldClient,
            accountLeaseRuntime: runtime,
            productSessionID: sceneA,
            liveTurnOutboxStore: outbox,
            followUpStore: followUp,
            completionCheckpointStore: checkpoint,
            naturalInputPolicyAvailable: { false },
            candidateReviewPolicyAvailable: { false }
        )
        let blockedDiagnosticRoot = root.appendingPathComponent("diagnostics-file")
        try Data("occupied".utf8).write(to: blockedDiagnosticRoot)
        let blockedDiagnostics = EchoVoiceLaunchDiagnosticStore(
            rootDirectory: blockedDiagnosticRoot
        )
        let now = Date(timeIntervalSince1970: 1_800_000_000)
        func makeClient(allowed: Bool) throws -> DreamJourneyBackendClient {
            let gate = FeatureGateService.makeQATestService(
                accountGeneration: { authSession.sessionId },
                policy: { _, _ in FeatureGatePolicySnapshot(
                    accessMode: .useCachedPolicy,
                    policyVersion: "mic-19-policy",
                    policyRevision: 7,
                    emergencyRevision: 0,
                    expiresAt: now.addingTimeInterval(300),
                    featureEnabled: allowed,
                    releaseVisible: allowed,
                    reason: allowed ? "allowed" : "disabled"
                ) },
                now: { now }
            )
            return DreamJourneyBackendClient.makeQATestClient(
                baseURL: URL(string: "https://owner-truth.qa.invalid")!,
                session: try makeOwnerTruthHTTPTestSession(),
                authenticatedSession: { authSession },
                currentUserID: { ownerID },
                privateAccessAllowed: { true },
                featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
                freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
                accountLeaseRuntime: runtime
            )
        }
        let denied = EchoViewController()
        let deniedTerminal = expectation(description: "MIC-19 B denied before ticket")
        denied.installVoiceLaunchBoundariesForTesting(
            accountLease: lease,
            client: try makeClient(allowed: false),
            permission: { $0(true) },
            configureSDK: { _ in XCTFail("denied B configured SDK"); return false },
            startSDK: { _ in XCTFail("denied B started SDK") },
            prepareAudio: { true },
            capturesMemory: true
        )
        denied.installLiveMemoryCaptureForTesting(
            accountLease: lease, coordinator: oldCoordinator
        )
        denied.setVoiceLaunchDiagnosticStoreForTesting(blockedDiagnostics)
        denied.onVoiceLaunchTerminalForTesting { _ in deniedTerminal.fulfill() }
        denied.tapMicrophoneForTesting()
        wait(for: [deniedTerminal], timeout: 5)
        XCTAssertTrue(denied.hasActiveLiveMemoryCaptureForTesting(oldCoordinator))
        XCTAssertEqual(try outbox.load(for: lease, productSessionID: sceneA), oldOutbox)
        XCTAssertEqual(followUp.records(for: lease), oldFollowUp)
        XCTAssertEqual(try checkpoint.load(productSessionID: sceneA, for: lease), oldCheckpoint)
        XCTAssertTrue(oldClient.endCommands.isEmpty)
        XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 0)
        blockedDiagnostics.waitForPendingWrites()
        XCTAssertTrue(blockedDiagnostics.persistenceFailed(ownerID: ownerID))

        let sceneB = "mic-19-scene-b"
        let response = try micVoiceTicketResponse(ownerID: ownerID, productSessionID: sceneB)
        OwnerTruthReviewReadyHTTPURLProtocol.install { _, loader in
            loader.respond(statusCode: 200, body: response)
        }
        let failing = EchoViewController()
        var newCoordinator: EchoLiveMemoryCaptureCoordinator?
        let sdkStarted = expectation(description: "MIC-19 B SDK started")
        let failedTerminal = expectation(description: "MIC-19 B SDK failed")
        failing.installVoiceLaunchBoundariesForTesting(
            accountLease: lease,
            client: try makeClient(allowed: true),
            permission: { $0(true) },
            configureSDK: { _ in true },
            startSDK: { _ in
                sdkStarted.fulfill()
                failing.onError(error: NSError(domain: "MIC19", code: 1))
            },
            prepareAudio: { true },
            capturesMemory: true
        )
        failing.setVoiceLaunchCaptureFactoryForTesting { captureLease, productSessionID in
            let coordinator = EchoLiveMemoryCaptureCoordinator(
                accountLease: captureLease,
                client: InterviewNaturalInputClientSpy(),
                accountLeaseRuntime: runtime,
                productSessionID: productSessionID,
                liveTurnOutboxStore: outbox,
                followUpStore: followUp,
                completionCheckpointStore: checkpoint,
                naturalInputPolicyAvailable: { false },
                candidateReviewPolicyAvailable: { false }
            )
            newCoordinator = coordinator
            return coordinator
        }
        failing.setVoiceLaunchDiagnosticStoreForTesting(blockedDiagnostics)
        failing.onVoiceLaunchTerminalForTesting { _ in failedTerminal.fulfill() }
        failing.tapMicrophoneForTesting()
        wait(for: [sdkStarted, failedTerminal], timeout: 5)
        XCTAssertNotNil(newCoordinator)
        XCTAssertEqual(try outbox.load(for: lease, productSessionID: sceneA), oldOutbox)
        XCTAssertEqual(followUp.records(for: lease), oldFollowUp)
        XCTAssertEqual(try checkpoint.load(productSessionID: sceneA, for: lease), oldCheckpoint)
        XCTAssertTrue(oldClient.endCommands.isEmpty)
        XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 1)
        blockedDiagnostics.waitForPendingWrites()
        XCTAssertTrue(blockedDiagnostics.persistenceFailed(ownerID: ownerID))
        XCTAssertEqual(try Data(contentsOf: blockedDiagnosticRoot), Data("occupied".utf8))
    }

    @MainActor
    func testMIC19ActiveAAppendContinuesAfterBSDKFailure() throws {
        for failure in ["sdk", "deny", "timeout", "control"] {
