    @MainActor
    private func exerciseMIC19ActiveAppend(failure: String) throws {
        let ownerID = "mic-19-active-\(failure)-\(UUID().uuidString)"
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: ownerID)
        let runtime = AccountLeaseRuntime.shared
        let previousUser = UserManager.shared.currentUser
        runtime.updateAuthorityEpoch("mic-19-active-epoch")
        runtime.publish(session: accountSession(
            subjectId: ownerID, vaultId: "mic-19-active-vault",
            generation: 1, generationID: UUID(), sessionID: authSession.sessionId
        ))
        UserManager.shared.setSyntheticCurrentUserForTesting(UserModel(
            id: ownerID, nickname: "Synthetic owner", phone: ""
        ))
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("mic19-active-\(UUID().uuidString)")
        defer {
            OwnerTruthReviewReadyHTTPURLProtocol.reset()
            DialogEngineManager.shared.closeCanonicalIngressForTesting()
            UserManager.shared.setSyntheticCurrentUserForTesting(previousUser)
            runtime.publish(session: nil)
            try? FileManager.default.removeItem(at: root)
        }
        let lease = try XCTUnwrap(runtime.capture(forSubjectId: ownerID))
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let clientA = InterviewNaturalInputClientSpy()
        clientA.freshNaturalInputDecision = Self.liveNaturalInputDecision(for: lease)
        clientA.scopedCurrentSessionHandler = { expectedVaultID, _ in
            Result { try self.emptyInterviewNaturalInputCurrentSession(vaultID: expectedVaultID) }
        }
        clientA.typedStartHandler = { command in
            .committed(try! self.interviewNaturalInputReceipt(vaultID: vaultID, start: command))
        }
        clientA.deferAppend = true
        clientA.endHandler = { command in
            Result { try self.interviewNaturalInputReceipt(vaultID: vaultID, end: command) }
        }
        let outbox = OwnerTruthInterviewLiveTurnOutboxStore(
            rootDirectory: root.appendingPathComponent("outbox")
        )
        let sceneA = "mic-19-active-a"
        let sceneB = "mic-19-active-b"
        let coordinatorA = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease, client: clientA, accountLeaseRuntime: runtime,
            productSessionID: sceneA, liveTurnOutboxStore: outbox,
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("checkpoint")
            ),
            naturalInputPolicyAvailable: { true },
            candidateReviewPolicyAvailable: { true }
        )
        let controllerA = EchoViewController()
        controllerA.installLiveMemoryCaptureForTesting(
            accountLease: lease, coordinator: coordinatorA
        )
        let manager = DialogEngineManager.shared
        manager.setCanonicalIngressDeliverySchedulerForTesting { $0() }
        let generationA = UUID()
        let operationA = UUID()
        manager.installCanonicalIngressForTesting(
            engineGeneration: generationA, dialogOperationID: operationA,
            delegate: controllerA
        )
        defer { manager.setCanonicalIngressDeliverySchedulerForTesting { $0() } }
        func enqueueA(_ kind: DialogProviderCanonicalIngressKind,
                      _ fields: [String: Any]) throws {
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: kind,
                data: try JSONSerialization.data(withJSONObject: fields),
                engineGeneration: generationA
            ))
        }
        try enqueueA(.asrInfo, ["question_id": "active-a-q1"])
        try enqueueA(.asrResponse, [
            "question_id": "active-a-q1",
            "results": [["text": "旧场正在提交的正文。", "is_interim": false]],
        ])
        try enqueueA(.asrEnded, ["question_id": "active-a-q1"])
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            clientA.appendCommands.count == 1
        }, "A must reach an actual in-flight append before B starts")
        let frozenAppend = try XCTUnwrap(clientA.appendCommands.first)
        let diskBeforeB = try XCTUnwrap(outbox.load(for: lease, productSessionID: sceneA))
        XCTAssertEqual(diskBeforeB.ownerTurnCount, 1)
        XCTAssertFalse(diskBeforeB.frozenAppendCommands.isEmpty)
        XCTAssertTrue(clientA.endCommands.isEmpty)

        let now = Date(timeIntervalSince1970: 1_800_000_000)
        let gate = FeatureGateService.makeQATestService(
            accountGeneration: { authSession.sessionId },
            policy: { _, _ in FeatureGatePolicySnapshot(
                accessMode: .useCachedPolicy, policyVersion: "mic-19-active-policy",
                policyRevision: 7, emergencyRevision: 0,
                expiresAt: now.addingTimeInterval(300),
                featureEnabled: failure != "deny", releaseVisible: true,
                reason: failure == "deny" ? "disabled" : "allowed"
            ) }, now: { now }
        )
        let backend = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { authSession }, currentUserID: { ownerID },
            privateAccessAllowed: { true },
            featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
            freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
            accountLeaseRuntime: runtime
        )
        let ticket = try micVoiceTicketResponse(ownerID: ownerID, productSessionID: sceneB)
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            XCTAssertEqual(request.url?.path, "/voice/realtime-token")
            loader.respond(statusCode: 200, body: ticket)
        }
        let controllerB = EchoViewController()
        let clientB = InterviewNaturalInputClientSpy()
        var coordinatorB: EchoLiveMemoryCaptureCoordinator?
        var sdkStarted = 0
        var terminals: [String] = []
        var clock: TimeInterval = 100
        var watchdog: DispatchWorkItem?
        controllerB.installVoiceLaunchBoundariesForTesting(
            accountLease: lease, client: backend,
            timeout: 15, clock: { clock }, scheduler: { _, work in watchdog = work },
            permission: { $0(true) }, configureSDK: { _ in true },
            startSDK: { _ in
                sdkStarted += 1
                if failure == "sdk" {
                    controllerB.onError(error: NSError(domain: "MIC19", code: 1))
                } else if failure == "timeout" {
                    clock = 116
                    watchdog?.perform()
                }
            },
            prepareAudio: { true }, capturesMemory: true
        )
        controllerB.setVoiceLaunchCaptureFactoryForTesting { captureLease, productSessionID in
            let coordinator = EchoLiveMemoryCaptureCoordinator(
                accountLease: captureLease, client: clientB,
                accountLeaseRuntime: runtime, productSessionID: productSessionID,
                liveTurnOutboxStore: outbox,
                completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                    rootDirectory: root.appendingPathComponent("checkpoint")
                ),
                naturalInputPolicyAvailable: { false },
                candidateReviewPolicyAvailable: { false }
            )
            coordinatorB = coordinator
            return coordinator
        }
        controllerB.onVoiceLaunchTerminalForTesting { terminals.append($0) }
        if failure != "control" {
            controllerB.tapMicrophoneForTesting()
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) { terminals.count == 1 })
            XCTAssertEqual(terminals.count, 1)
            XCTAssertEqual(sdkStarted, failure == "deny" ? 0 : 1)
            XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count,
                failure == "deny" ? 0 : 1)
            if failure == "deny" {
                XCTAssertNil(coordinatorB)
            } else {
                XCTAssertNotNil(coordinatorB)
                XCTAssertEqual(coordinatorB?.state, .empty, "B closes its own empty capture")
                let ownCapture = try XCTUnwrap(coordinatorB)
                XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
                    !controllerB.hasActiveLiveMemoryCaptureForTesting(ownCapture)
                }, "B's real release callback must finish")
            }
        }
        XCTAssertEqual(try outbox.load(for: lease, productSessionID: sceneA), diskBeforeB)
        XCTAssertTrue(clientA.endCommands.isEmpty)
        XCTAssertTrue(clientB.endCommands.isEmpty)
        XCTAssertTrue(clientB.acknowledgementCommands.isEmpty)
        XCTAssertTrue(clientB.admissionCommands.isEmpty)

        clientA.deferAppend = false
        clientA.completeDeferredAppend(.success(try interviewNaturalInputReceipt(
            vaultID: vaultID, append: frozenAppend
        )))
        controllerA.finishLiveMemoryCaptureForTesting()
        let aFinished = waitForOwnerTruthHTTPUI(timeout: 5) {
            clientA.endCommands.count == 1
        }
        let afterA = try outbox.load(for: lease, productSessionID: sceneA)
        XCTAssertTrue(aFinished,
            "A end missing: appendCount=\(clientA.appendCommands.count) "
                + "frozen=\(afterA?.frozenAppendCommands.count ?? -1) "
                + "closeIntent=\(afterA?.closeIntentRequestedAt != nil) "
                + "closeSequence=\(String(describing: afterA?.closeRequestedLastClientSequenceNumber)) "
                + "dispatch=\(String(describing: afterA?.pendingDispatchStates[frozenAppend.messageID]))"
        )
        XCTAssertTrue(runtime.validate(lease, at: .commit).allowed)
        XCTAssertEqual(clientA.endCommands.count, 1)
        XCTAssertEqual(clientA.appendCommands.map(\.text), ["旧场正在提交的正文。"])
        XCTAssertTrue(clientB.endCommands.isEmpty)
    }

