    func testMICManagerProductionLaunchControlWithControlledSDKBoundary() {
        let control = DialogVoiceLaunchExecutionControl()
        var uptime: TimeInterval = 100
        var sdkStarts = 0
        let expiredSetup = UUID()
        control.begin(operationID: expiredSetup, pendingID: "setup", isValid: { uptime < 115 })
        var ingressInstalled = false
        var terminalCount = 0
        let expiredResult: Int? = control.performStartSubmission(
            operationID: expiredSetup,
            preflight: { control.permits(expiredSetup) },
            installIngress: {
                ingressInstalled = true
                uptime = 116 // Deadline crosses after preflight, before SDK commit.
            },
            onRejected: {
                ingressInstalled = false
                terminalCount += 1
                XCTAssertTrue(control.cancel(operationID: expiredSetup))
            },
            send: {
                sdkStarts += 1
                return 0
            }
        )
        XCTAssertNil(expiredResult)
        XCTAssertEqual(sdkStarts, 0)
        XCTAssertFalse(ingressInstalled)
        XCTAssertEqual(terminalCount, 1)
        XCTAssertFalse(control.acceptsSessionStarted(expiredSetup))

        // A stale operation must not cancel the replacement launch's resources.
        let replacement = UUID()
        control.begin(operationID: replacement, pendingID: "replacement", isValid: { true })
        XCTAssertFalse(control.cancel(operationID: expiredSetup))
        XCTAssertEqual(control.operationID, replacement)
        XCTAssertEqual(control.pendingID, "replacement")

        let superseded = UUID()
        let successor = UUID()
        control.begin(operationID: superseded, pendingID: "superseded", isValid: { true })
        let supersededResult: Int? = control.performStartSubmission(
            operationID: superseded,
            preflight: { control.permits(superseded) },
            installIngress: {
                control.begin(operationID: successor, pendingID: "successor", isValid: { true })
            },
            onRejected: {
                XCTAssertFalse(control.cancel(operationID: superseded))
                terminalCount += 1
            },
            send: { sdkStarts += 1; return 0 }
        )
        XCTAssertNil(supersededResult)
        XCTAssertEqual(sdkStarts, 0)
        XCTAssertEqual(terminalCount, 2)
        XCTAssertEqual(control.operationID, successor)
        XCTAssertEqual(control.pendingID, "successor")

        uptime = 200
        let failedStart = UUID()
        control.begin(operationID: failedStart, pendingID: "failed", isValid: { uptime < 215 })
        XCTAssertNotNil(control.performStartSubmission(
            operationID: failedStart,
            preflight: { control.permits(failedStart) },
            installIngress: {},
            onRejected: { XCTFail("valid start rejected") },
            send: { sdkStarts += 1; return 1 }
        ))
        XCTAssertTrue(control.failStart(failedStart))
        XCTAssertFalse(control.acceptsSessionStarted(failedStart))

        let pending = UUID()
        control.begin(operationID: pending, pendingID: "pending", isValid: { uptime < 215 })
        XCTAssertNotNil(control.performStartSubmission(
            operationID: pending,
            preflight: { control.permits(pending) },
            installIngress: {},
            onRejected: { XCTFail("valid start rejected") },
            send: { sdkStarts += 1; return 0 }
        ))
        XCTAssertTrue(control.cancel(pendingID: "pending"))
        XCTAssertFalse(control.acceptsSessionStarted(pending))
        XCTAssertFalse(control.failStart(pending))

        let current = UUID()
        control.begin(operationID: current, pendingID: "current", isValid: { uptime < 215 })
        XCTAssertNotNil(control.performStartSubmission(
            operationID: current,
            preflight: { control.permits(current) },
            installIngress: {},
            onRejected: { XCTFail("valid start rejected") },
            send: { sdkStarts += 1; return 0 }
        ))
        XCTAssertFalse(control.cancel(pendingID: "pending"))
        XCTAssertTrue(control.acceptsSessionStarted(current))
        XCTAssertTrue(control.complete(pendingID: "current"))
        XCTAssertTrue(control.permits(current))
        XCTAssertEqual(sdkStarts, 3)

        let late = UUID()
        control.begin(operationID: late, pendingID: "late", isValid: { uptime < 215 })
        XCTAssertTrue(control.markStartSubmitted(late))
        uptime = 216
        XCTAssertFalse(control.acceptsSessionStarted(late))
        XCTAssertFalse(control.markStartSubmitted(late))
        XCTAssertFalse(control.cancel(pendingID: "current"))
    }

