    func testMIC11OldRuntimeResponseCannotReplaceNewAccountAuthority() throws {
        let (runtime, oldLease) = try makeActiveRuntime()
        let oldSession = try makeOwnerTruthHTTPTestAuthSession(userID: oldLease.subjectId)
        let gate = FeatureGateService.makeQATestService(
            accountGeneration: { oldSession.sessionId },
            policy: { _, _ in FeatureGatePolicySnapshot(
                accessMode: .useCachedPolicy, policyVersion: "mic-11-runtime-policy",
                policyRevision: 7, emergencyRevision: 0,
                expiresAt: Date().addingTimeInterval(300), featureEnabled: true,
                releaseVisible: true, reason: "allowed"
            ) }
        )
        let previousUser = UserManager.shared.currentUser
        let previousPolicy = RecoveryRuntimePolicyStore.shared.currentPolicy
        defer {
            OwnerTruthReviewReadyHTTPURLProtocol.reset()
            RecoveryRuntimePolicyStore.shared.update(previousPolicy)
            UserManager.shared.setSyntheticCurrentUserForTesting(previousUser)
            runtime.publish(session: nil)
        }
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { oldSession },
            currentUserID: { oldLease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
            accountLeaseRuntime: runtime
        )
        var oldLoader: OwnerTruthReviewReadyHTTPURLProtocol?
        let requestStarted = expectation(description: "old runtime request started")
        OwnerTruthReviewReadyHTTPURLProtocol.install { _, loader in
            oldLoader = loader
            requestStarted.fulfill()
        }
        let completed = expectation(description: "old runtime callback completed")
        client.fetchRuntimeConfig { result in
            if case .success = result { XCTFail("stale runtime response must not be applied") }
            completed.fulfill()
        }
        wait(for: [requestStarted], timeout: 5)
        let newEpoch = "mic-11-new-epoch-\(UUID().uuidString)"
        runtime.updateAuthorityEpoch(newEpoch)
        runtime.publish(session: accountSession(
            subjectId: "mic-11-new-owner", vaultId: "mic-11-new-vault",
            generation: 2, generationID: UUID(), sessionID: "mic-11-new-session"
        ))
        oldLoader?.respond(statusCode: 200, body: try JSONSerialization.data(withJSONObject: [
            "recovery": [
                "schemaVersion": 1, "mode": "normal", "authorityEpoch": oldLease.authorityEpoch,
                "writesAllowed": true, "authenticatedSessionPolicy": "preserve",
                "cacheWritePolicy": "enabled", "scope": "globalRecoveryFence",
                "configurationValid": true, "contractVersion": 1,
            ],
        ]))
        wait(for: [completed], timeout: 5)
        let newLease = try XCTUnwrap(runtime.capture(forSubjectId: "mic-11-new-owner"))
        XCTAssertEqual(newLease.authorityEpoch, newEpoch)
        XCTAssertEqual(RecoveryRuntimePolicyStore.shared.currentPolicy, previousPolicy)
    }

