        )
        XCTAssertEqual(record.terminalReason, "timeout")
        XCTAssertEqual(record.firstFailureStage, .sdkStart)
        XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 1)
        XCTAssertEqual(sdkStarts, 1)
        XCTAssertFalse(controller.isVoiceListeningForTesting)
        XCTAssertNil(controller.activeVoiceLaunchAttemptForTesting)
    }

