    func testMIC02ExpiredCurrentPolicyRefreshesOnceThenIssuesOneTicket() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        var now = Date(timeIntervalSince1970: 1_800_000_000)
        var expiry = now.addingTimeInterval(5)
        let gate = FeatureGateService.makeQATestService(
            accountGeneration: { authSession.sessionId },
            policy: { _, _ in FeatureGatePolicySnapshot(
                accessMode: .useCachedPolicy,
                policyVersion: "mic-02-policy",
                policyRevision: 7,
                emergencyRevision: 0,
                expiresAt: expiry,
                featureEnabled: true,
                releaseVisible: true,
                reason: "allowed"
            ) },
            now: { now }
        )
        XCTAssertTrue(gate.captureServerPolicyManagedRoute(.echoTextInput).allowed)
        now = now.addingTimeInterval(10)
        XCTAssertFalse(gate.freshServerPolicyManagedRequestDecision(for: .echoTextInput).allowed)
        var refreshes = 0
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
            freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
            featureDecisionRevalidator: { gate.revalidateServerPolicyManagedRequest($0) },
            accountLeaseRuntime: runtime,
            liveReadPolicyRefresher: { completion in
                refreshes += 1
                expiry = now.addingTimeInterval(300)
                completion(.success(()))
            }
        )
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
        let response = try micVoiceTicketResponse(
            ownerID: lease.subjectId, productSessionID: "mic-02-product"
        )
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            XCTAssertEqual(request.url?.path, "/voice/realtime-token")
            loader.respond(statusCode: 200, body: response)
        }
        let completed = expectation(description: "MIC-02 ticket")
        var ready = false
        client.fetchRealtimeVoiceConfig(userId: lease.subjectId) { result in
            if case .success(let config) = result { ready = !config.isBlocked }
            completed.fulfill()
        }
        wait(for: [completed], timeout: 5)
        XCTAssertTrue(ready)
        XCTAssertEqual(refreshes, 1)
        XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 1)
    }

