    func testMIC07CanonicalPreHandler401AllowsOneAuthRecovery() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let original = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        let successor = try makeOwnerTruthHTTPTestAuthSession(
            userID: lease.subjectId,
            sessionID: "mic-07-successor",
            parentSessionID: original.sessionId,
            sessionVersion: 2,
            accessTokenSuffix: "mic-07-successor"
        )
        var currentSession = original
        let now = Date(timeIntervalSince1970: 1_800_000_000)
        let gate = FeatureGateService.makeQATestService(
            accountGeneration: { currentSession.sessionId },
            policy: { _, _ in FeatureGatePolicySnapshot(
                accessMode: .useCachedPolicy,
                policyVersion: "mic-07-positive-policy",
                policyRevision: 7,
                emergencyRevision: 0,
                expiresAt: now.addingTimeInterval(300),
                featureEnabled: true,
                releaseVisible: true,
                reason: "allowed"
            ) },
            now: { now }
        )
        var authRefreshes = 0
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { currentSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: { gate.requestServerPolicyManagedDecision(for: $0) },
            freshFeatureDecision: { gate.freshServerPolicyManagedRequestDecision(for: $0) },
            authSessionRefresher: { _, completion in
                authRefreshes += 1
                currentSession = successor
                completion(successor)
            },
            accountLeaseRuntime: runtime
        )
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
        let readyResponse = try micVoiceTicketResponse(
            ownerID: lease.subjectId, productSessionID: "mic-07-product"
        )
        let preHandler = try JSONSerialization.data(withJSONObject: [
            "detail": "invalid or expired access token"
        ])
        OwnerTruthReviewReadyHTTPURLProtocol.install { _, loader in
            if OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count == 1 {
                loader.respond(statusCode: 401, body: preHandler)
            } else {
                loader.respond(statusCode: 200, body: readyResponse)
            }
        }
        let completed = expectation(description: "MIC-07 canonical 401 recovery")
        var ready = false
        client.fetchRealtimeVoiceConfig(userId: lease.subjectId) { result in
            if case .success(let config) = result { ready = !config.isBlocked }
            completed.fulfill()
        }
        wait(for: [completed], timeout: 5)
        XCTAssertTrue(ready)
        XCTAssertEqual(authRefreshes, 1)
        XCTAssertEqual(OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests.count, 2)
    }

