            "expiresAt": expiresAt,
            "minClient": 1,
            "emergencyRevision": 1,
            "audience": audience,
            "cohort": cohort,
            "source": "server",
            "shadowMode": false,
            "snapshotDecision": enabled ? "allow" : "deny",
            "features": [[
                "feature": DJFeature.ownerTruthCandidateReview.backendReleasePolicyFeature,
                "enabled": enabled,
                "releaseVisible": enabled,
                "audience": audience,
                "cohort": cohort,
