    func testFormalMemoryPolicyM03FreshReadDecisionDoesNotReuseExpiredRoute() {
        var policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "formal-route-expired-v1",
            policyRevision: 30,
            emergencyRevision: 2,
            expiresAt: Date().addingTimeInterval(-30),
            featureEnabled: true,
            releaseVisible: true,
            reason: "formalMemoryEnabled"
        )
        let service = FeatureGateService.makeQATestService(
            accountGeneration: { "same-account-generation" },
            policy: { _, _ in policy }
        )
        service.captureServerPolicyManagedRoute(.ownerTruthCandidateReview)
        XCTAssertFalse(service.requestServerPolicyManagedDecision(
            for: .ownerTruthCandidateReview
        ).allowed)

        policy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "formal-route-fresh-v2",
            policyRevision: 31,
            emergencyRevision: 2,
            expiresAt: Date().addingTimeInterval(300),
            featureEnabled: true,
            releaseVisible: true,
            reason: "formalMemoryEnabled"
        )

        let staleRouteDecision = service.requestServerPolicyManagedDecision(
            for: .ownerTruthCandidateReview
        )
        XCTAssertFalse(staleRouteDecision.allowed)
        XCTAssertEqual(staleRouteDecision.policyRevision, 30)

        let readDecision = service.freshServerPolicyManagedRequestDecision(
            for: .ownerTruthCandidateReview
        )
        XCTAssertTrue(readDecision.allowed)
        XCTAssertEqual(readDecision.policyRevision, 31)
        XCTAssertEqual(readDecision.purpose, .request)
    }

