    @MainActor
    func testFormalMemoryPolicyM25DiagnosticsKeepHTTPAbsentForDNSFailure() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let authSession = try makeOwnerTruthHTTPTestAuthSession(
            userID: lease.subjectId,
            accessTokenSuffix: "secret-must-not-appear"
        )
        let evaluator = FeatureGateEvaluator()
        let freshPolicy = FeatureGatePolicySnapshot(
            accessMode: .useCachedPolicy,
            policyVersion: "formal-diagnostics-v1",
            policyRevision: 70,
            emergencyRevision: 1,
            expiresAt: Date().addingTimeInterval(300),
            featureEnabled: true,
            releaseVisible: true,
            reason: "formalMemoryEnabled"
        )
        var events: [OwnerTruthReadDiagnosticEvent] = []
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: { authSession },
            currentUserID: { lease.subjectId },
            privateAccessAllowed: { true },
            featureDecision: { feature in
                evaluator.capture(
                    feature: feature,
                    risk: .ownerTextCore,
                    purpose: .request,
                    localEnabled: true,
                    qaSyntheticOverride: false,
                    accountGeneration: authSession.sessionId,
                    policy: freshPolicy
                )
            },
            featureDecisionRevalidator: { decision in
                evaluator.revalidateForRequest(
                    captured: decision,
                    localEnabled: true,
                    accountGeneration: authSession.sessionId,
                    currentPolicy: freshPolicy
                )
            },
            accountLeaseRuntime: runtime,
            ownerTruthReadDiagnosticSink: { events.append($0) }
        )
        OwnerTruthReviewReadyHTTPURLProtocol.install { _, loader in
            loader.fail(URLError(.cannotFindHost))
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }
        let completed = expectation(description: "formal DNS failure completes")
        let context = OwnerTruthReadContext(resource: .formalMemoryList)
        let handle = client.fetchOwnerTruthFormalMemoriesRead(
            accountLease: lease,
            vaultID: vaultID,
            query: try OwnerTruthFormalMemoryQuery(),
            readContext: context
        ) { outcome in
            XCTAssertEqual(outcome.readContext.traceID, context.traceID)
            guard case .failure = outcome.result else {
                XCTFail("DNS failure must not produce a successful formal-memory read")
                completed.fulfill()
                return
            }
            completed.fulfill()
        }
        wait(for: [completed], timeout: 2)
        withExtendedLifetime(handle) {}
        let traceEvents = events.filter { $0.traceID == context.traceID }
        XCTAssertTrue(traceEvents.contains(where: { $0.event == "taskCreated" }))
        XCTAssertTrue(traceEvents.contains(where: { $0.event == "transportCompleted" }))
        XCTAssertFalse(traceEvents.contains(where: { $0.event == "responseReceived" }))
        XCTAssertTrue(traceEvents.allSatisfy { $0.httpStatus == nil })
        XCTAssertTrue(traceEvents.allSatisfy {
            $0.reason?.contains("secret-must-not-appear") != true
        })
    }

