        XCTAssertEqual(uiEvents.last?.attempt, 2)
    }

    @MainActor
    func testFormalMemoryPolicyM13M14SharedPolicyFlightSurvivesFirstReadCancellation() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let vaultID = try XCTUnwrap(OwnerTruthVaultID(lease.vaultId))
        let authSession = try makeOwnerTruthHTTPTestAuthSession(userID: lease.subjectId)
        let defaultsName = "formal-candidate-policy-shared-flight-\(UUID().uuidString)"
        let defaults = try XCTUnwrap(UserDefaults(suiteName: defaultsName))
        defer { defaults.removePersistentDomain(forName: defaultsName) }
        let store = ReleasePolicyStore(userDefaults: defaults)
        try saveCandidateReleasePolicy(
            candidateReleasePolicyPayload(
                version: "formal-shared-expired-v1",
                revision: 100,
                expiresAt: "2026-09-13T00:00:00Z"
            ),
            store: store,
            scope: candidateReleasePolicyScope(lease: lease)
        )
        let harness = try makeCandidatePolicyTestClient(
            runtime: runtime,
            lease: lease,
            authSession: { authSession },
            store: store
        )
        let freshPolicy = candidateReleasePolicyPayload(
            version: "formal-shared-fresh-v2",
            revision: 101,
            expiresAt: "2099-01-01T00:00:00Z"
        )
        let inboxData = try JSONSerialization.data(withJSONObject: [
            "schemaVersion": OwnerTruthCandidateInbox.schemaVersion,
            "vaultId": vaultID.rawValue,
            "memoryRevision": 123,
            "candidates": [],
        ])
        var policyLoader: OwnerTruthReviewReadyHTTPURLProtocol?
        OwnerTruthReviewReadyHTTPURLProtocol.install { request, loader in
            switch request.url?.path {
            case "/v2/release-policy":
                policyLoader = loader
            case "/v2/vaults/\(vaultID.rawValue)/candidates":
                loader.respond(statusCode: 200, body: inboxData)
            case "/v2/vaults/\(vaultID.rawValue)/memories":
                XCTFail("Cancelled formal-memory waiter must not start its resource GET")
                loader.fail(URLError(.cancelled))
            default:
                XCTFail("Unexpected request path: \(request.url?.path ?? "nil")")
                loader.fail(URLError(.unsupportedURL))
            }
        }
        defer { OwnerTruthReviewReadyHTTPURLProtocol.reset() }

        var cancelledFormalCompletionCount = 0
        let formalHandle = harness.client.fetchOwnerTruthFormalMemoriesRead(
            accountLease: lease,
            vaultID: vaultID,
            query: try OwnerTruthFormalMemoryQuery(),
            readContext: OwnerTruthReadContext(resource: .formalMemoryList)
        ) { _ in
            cancelledFormalCompletionCount += 1
        }
        let candidateUseCase = OwnerTruthCandidateReviewUseCase(
            accountLease: lease,
            client: harness.client,
            accountLeaseRuntime: runtime,
            qaGateEnabled: { harness.decision(.ownerTruthCandidateReview).allowed },
            pendingResultStore: OwnerTruthCandidateReviewTransientPendingResultStore()
        )
        candidateUseCase.send(.refresh)
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 2) { policyLoader != nil })
        formalHandle.cancel()
        policyLoader?.respond(
            statusCode: 200,
            body: try JSONSerialization.data(withJSONObject: freshPolicy)
        )

        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            candidateUseCase.viewState.phase == .empty
        })
        let requests = OwnerTruthReviewReadyHTTPURLProtocol.recordedRequests
        XCTAssertEqual(requests.filter { $0.url?.path == "/v2/release-policy" }.count, 1)
        XCTAssertEqual(requests.filter { $0.url?.path.hasSuffix("/candidates") == true }.count, 1)
        XCTAssertEqual(requests.filter { $0.url?.path.hasSuffix("/memories") == true }.count, 0)
        XCTAssertEqual(cancelledFormalCompletionCount, 0)
    }

