            engineGeneration: generation,
            dialogOperationID: operationID,
            delegate: controller
        )
        defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operationID) }

        func enqueue(_ kind: DialogProviderCanonicalIngressKind, _ payload: [String: Any]) throws {
            XCTAssertNotNil(manager.enqueueCanonicalProviderMessageForTesting(
                kind: kind,
                data: try JSONSerialization.data(withJSONObject: payload),
                engineGeneration: generation
            ))
