            "question_id": "cap02-q1",
            "results": [["text": "可信严格终稿。", "is_interim": false]],
        ])
        try enqueue(.asrResponse, [
            "question_id": "cap02-q1",
            "results": [["text": "未确认的中间稿", "is_interim": true]],
        ])
        try enqueue(.asrEnded, ["question_id": "cap02-q1"])

