    @MainActor
    func testR202CompletedAssistantIdentitySurvivesOneHundredFiftyReplies() throws {
        for replyCount in [40, 100, 150] {
            let (runtime, lease) = try makeActiveRuntime()
            let root = FileManager.default.temporaryDirectory
                .appendingPathComponent("r202-completed-replies-\(replyCount)-\(UUID().uuidString)")
            defer { try? FileManager.default.removeItem(at: root) }
            let sessionID = "r202-session-\(replyCount)"
            let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
            let coordinator = EchoLiveMemoryCaptureCoordinator(
                accountLease: lease,
                client: InterviewNaturalInputClientSpy(),
                accountLeaseRuntime: runtime,
                productSessionID: sessionID,
                liveTurnOutboxStore: store,
                completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                    rootDirectory: root.appendingPathComponent("completion")
                ),
                naturalInputPolicyAvailable: { false },
                candidateReviewPolicyAvailable: { false }
            )
            let controller = EchoViewController()
            controller.installLiveMemoryCaptureForTesting(accountLease: lease, coordinator: coordinator)
            let manager = DialogEngineManager.shared
            let generation = UUID()
            let operationID = UUID()
            manager.installCanonicalIngressForTesting(
                engineGeneration: generation,
                dialogOperationID: operationID,
                delegate: controller
            )
            defer { manager.closeCanonicalIngressForTesting(dialogOperationID: operationID) }

            for index in 0..<replyCount {
                let replyID = "r202-\(index)"
                XCTAssertNotNil(manager.enqueueCanonicalRawProviderMessageForTesting(
                    rawEventCode: DialogProviderSDKEventClassifier.chatResponse,
                    data: try JSONSerialization.data(withJSONObject: [
                        "reply_id": replyID, "text": "助手正文\(index)。",
                    ]),
                    engineGeneration: generation
                ))
                XCTAssertNotNil(manager.enqueueCanonicalRawProviderMessageForTesting(
                    rawEventCode: DialogProviderSDKEventClassifier.chatEnded,
                    data: try JSONSerialization.data(withJSONObject: ["reply_id": replyID]),
                    engineGeneration: generation
                ))
                // This scenario measures retained identity across a long session,
                // not an unlimited instantaneous ingress queue. Capacity overload
                // is independently asserted at 129 outstanding writes.
                if (index + 1) % 16 == 0 {
                    var batchIdle = false
                    coordinator.notifyWhenCanonicalPersistenceIdleForTesting { batchIdle = true }
                    XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 30) { batchIdle })
                    XCTAssertNil(coordinator.firstCaptureFailure)
                }
            }
            var initialPersistenceIdle = false
            coordinator.notifyWhenCanonicalPersistenceIdleForTesting {
                initialPersistenceIdle = true
            }
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 30) {
                initialPersistenceIdle
            })
            XCTAssertEqual(
                try store.load(for: lease, productSessionID: sessionID)?
                    .canonicalCoverageSummary.deliveryCount,
                replyCount
            )

            for index in 0..<replyCount {
                let replyID = "r202-\(index)"
                _ = manager.enqueueCanonicalRawProviderMessageForTesting(
                    rawEventCode: DialogProviderSDKEventClassifier.chatResponse,
                    data: try JSONSerialization.data(withJSONObject: [
                        "reply_id": replyID, "text": "迟到片段\(index)",
                    ]),
                    engineGeneration: generation
                )
                _ = manager.enqueueCanonicalRawProviderMessageForTesting(
                    rawEventCode: DialogProviderSDKEventClassifier.chatEnded,
                    data: try JSONSerialization.data(withJSONObject: ["reply_id": replyID]),
                    engineGeneration: generation
                )
            }
            var replayPersistenceIdle = false
            coordinator.notifyWhenCanonicalPersistenceIdleForTesting {
                replayPersistenceIdle = true
            }
            XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 30) {
                replayPersistenceIdle
            })
            let replaySnapshot = try XCTUnwrap(
                store.load(for: lease, productSessionID: sessionID)
            )
            XCTAssertEqual(replaySnapshot.canonicalCoverageSummary.deliveryCount, replyCount)
            XCTAssertEqual(replaySnapshot.canonicalConflictCount, 0)
            XCTAssertEqual(replaySnapshot.pendingTurns.count, replyCount)
            manager.closeCanonicalIngressForTesting(dialogOperationID: operationID)
        }
    }

    func testR203ManifestRegistrationAloneDoesNotResolveUnpersistedObservation() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("r203-manifest-registration-window-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let sessionID = "r203-registration-window"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let initial = NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: "r203-turn",
            role: .owner,
            text: "已持久正文甲。",
            finality: .complete,
            finalityEvidence: .explicitFinal,
            evidenceSource: .resultsIsInterim,
            sealing: .observeAndSeal,
            capturedAt: Date(timeIntervalSince1970: 1_700_001_000)
        )
        _ = try store.upsertCanonicalTurn(initial, for: lease, productSessionID: sessionID)
        let pending = NativeLiveCanonicalTranscriptMember(
            canonicalTurnID: initial.canonicalTurnID,
            handoffID: "r203-handoff-new-observation",
            role: .owner,
            capturedAt: Date(),
            ingressOrdinal: 9,
            ingressKind: .asrResponse
        )
        _ = try store.requestClose(
            acceptedHandoffs: [pending],
            for: lease,
            productSessionID: sessionID
        )
        _ = try store.registerCanonicalMember(pending, for: lease, productSessionID: sessionID)

        let rebuilt = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let snapshot = try XCTUnwrap(rebuilt.load(for: lease, productSessionID: sessionID))
        XCTAssertEqual(snapshot.pendingCloseManifestHandoffCount, 1)
        XCTAssertEqual(snapshot.canonicalConflictCount, 0)
        XCTAssertGreaterThan(snapshot.unsealedCanonicalTurnCount, 0)
    }

    func testIDEMP01DefaultEmptyRepeatedClosePreservesResolvedManifestAfterRebuild() throws {
        let (_, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("idemp01-repeated-close-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let sessionID = "idemp01-repeated-close"
        let store = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        let handled = NativeLiveCanonicalTranscriptMember(
            canonicalTurnID: "idemp01-handled-turn",
            handoffID: "idemp01-handled-handoff",
            role: .owner,
            capturedAt: Date(timeIntervalSince1970: 1_700_001_010),
            ingressOrdinal: 1,
            ingressKind: .asrResponse
        )
        let pending = NativeLiveCanonicalTranscriptMember(
            canonicalTurnID: "idemp01-pending-turn",
            handoffID: "idemp01-pending-handoff",
            role: .owner,
            capturedAt: Date(timeIntervalSince1970: 1_700_001_011),
            ingressOrdinal: 2,
            ingressKind: .asrResponse
        )
        let event = NativeLiveCanonicalTranscriptEvent(
            canonicalTurnID: handled.canonicalTurnID,
            role: .owner,
            text: "已完成持久交接的合成正文。",
            finality: .complete,
            finalityEvidence: .explicitFinal,
            evidenceSource: .resultsIsInterim,
            observationID: "idemp01-observation",
            ingressOrdinal: handled.ingressOrdinal,
            capturedAt: handled.capturedAt
        )

        _ = try store.requestClose(
            acceptedHandoffs: [handled],
            for: lease,
            productSessionID: sessionID
        )
        _ = try store.persistCanonicalHandoff(
            member: handled,
            event: event,
            for: lease,
            productSessionID: sessionID
        )
        XCTAssertEqual(
            try store.load(for: lease, productSessionID: sessionID)?
                .pendingCloseManifestHandoffCount,
            0
        )

        _ = try store.requestClose(
            acceptedHandoffs: [handled],
            for: lease,
            productSessionID: sessionID
        )
        _ = try store.requestClose(for: lease, productSessionID: sessionID)

        let rebuilt = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        XCTAssertEqual(
            try rebuilt.load(for: lease, productSessionID: sessionID)?
                .pendingCloseManifestHandoffCount,
            0,
            "a default empty repeated close must not revoke a completed handoff"
        )

        let pendingSessionID = "idemp01-pending-control"
        _ = try rebuilt.requestClose(
            acceptedHandoffs: [pending],
            for: lease,
            productSessionID: pendingSessionID
        )
        _ = try rebuilt.requestClose(for: lease, productSessionID: pendingSessionID)
        let rebuiltControl = OwnerTruthInterviewLiveTurnOutboxStore(rootDirectory: root)
        XCTAssertEqual(
            try rebuiltControl.load(for: lease, productSessionID: pendingSessionID)?
                .pendingCloseManifestHandoffCount,
            1,
            "an unhandled manifest member must remain pending"
        )
    }

