    @MainActor
    func testR205ActiveCriticalSessionSurvivesTwoNewerCriticalSessionsAndReclaimsQuota() throws {
        let (runtime, lease) = try makeActiveRuntime()
        let root = FileManager.default.temporaryDirectory
            .appendingPathComponent("r205-active-critical-quota-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: root) }
        let diagnostics = NativeLiveDiagnosticsRingStore(
            rootDirectory: root,
            maximumEventCount: 4,
            maximumSessionCount: 2,
            maximumTotalBytes: 64 * 1_024
        )
        var active: EchoLiveMemoryCaptureCoordinator? = EchoLiveMemoryCaptureCoordinator(
            accountLease: lease,
            client: InterviewNaturalInputClientSpy(),
            accountLeaseRuntime: runtime,
            productSessionID: "r205-active",
            liveTurnOutboxStore: OwnerTruthInterviewLiveTurnOutboxStore(
                rootDirectory: root.appendingPathComponent("outbox")
            ),
            completionCheckpointStore: EchoLiveMemoryCompletionCheckpointStore(
                rootDirectory: root.appendingPathComponent("completion")
            ),
            criticalDiagnosticsStore: diagnostics,
            naturalInputPolicyAvailable: { false },
            candidateReviewPolicyAvailable: { false }
        )
        let controller = EchoViewController()
        controller.installLiveMemoryCaptureForTesting(
            accountLease: lease,
            coordinator: try XCTUnwrap(active)
        )
        diagnostics.recordFirstCriticalFailure(
            accountLease: lease,
            providerSessionID: "r205-active",
            stage: "canonicalBody",
            reason: "storageFailure"
        )
        diagnostics.recordFirstCriticalFailure(
            accountLease: lease,
            providerSessionID: "r205-newer-1",
            stage: "canonicalBody",
            reason: "storageFailure"
        )
        diagnostics.recordFirstCriticalFailure(
            accountLease: lease,
            providerSessionID: "r205-newer-2",
            stage: "canonicalBody",
            reason: "storageFailure"
        )
        diagnostics.waitForPendingWrites()
        XCTAssertNotNil(diagnostics.snapshot(
            accountLease: lease,
            providerSessionID: "r205-active"
        ).firstCriticalFailure)

        controller.finishLiveMemoryCaptureForTesting()
        XCTAssertTrue(waitForOwnerTruthHTTPUI(timeout: 3) {
            guard let active else { return false }
            return active.canReleaseCaptureOwnership
                && !controller.hasActiveLiveMemoryCaptureForTesting(active)
        })
        active = nil
        diagnostics.waitForPendingWrites()
        diagnostics.recordFirstCriticalFailure(
            accountLease: lease,
            providerSessionID: "r205-newer-3",
            stage: "canonicalBody",
            reason: "storageFailure"
        )
        diagnostics.waitForPendingWrites()
        XCTAssertNil(diagnostics.snapshot(
            accountLease: lease,
            providerSessionID: "r205-active"
        ).firstCriticalFailure)
        XCTAssertNil(active)
    }

    private func makeCandidatePolicyTestClient(
        runtime: AccountLeaseRuntime,
        lease: AccountLease,
        authSession: @escaping () -> BackendAuthSessionContract?,
        authSessionRefresher: ((
            BackendAuthSessionContract,
            @escaping (BackendAuthSessionContract?) -> Void
        ) -> Void)? = nil,
        store: ReleasePolicyStore,
        policyTimeout: TimeInterval = 15,
        eventSink: @escaping (OwnerTruthCandidateInboxDiagnosticEvent) -> Void = { _ in },
        ownerTruthReadEventSink: @escaping (OwnerTruthReadDiagnosticEvent) -> Void = { _ in }
    ) throws -> (
        client: DreamJourneyBackendClient,
        decision: (DJFeature) -> FeatureDecision,
        snapshot: () -> FeatureGatePolicySnapshot
    ) {
        let evaluator = FeatureGateEvaluator()
        let clientBuild = FeatureGateService.shared.clientBuild
        let scope = candidateReleasePolicyScope(lease: lease, clientBuild: clientBuild)
        let snapshot = {
            BackendCachedReleasePolicyEvaluation(
                cache: store.evaluate(scope: scope, risk: .ownerTextCore),
                risk: .ownerTextCore
            ).featureGatePolicySnapshot(for: .ownerTruthCandidateReview)
        }
        let decision: (DJFeature) -> FeatureDecision = { feature in
            evaluator.capture(
                feature: feature,
                risk: .ownerTextCore,
                purpose: .request,
                localEnabled: true,
                qaSyntheticOverride: false,
                accountGeneration: authSession()?.sessionId ?? "missing-session",
                policy: snapshot()
            )
        }
        let client = DreamJourneyBackendClient.makeQATestClient(
            baseURL: URL(string: "https://owner-truth.qa.invalid")!,
            session: try makeOwnerTruthHTTPTestSession(),
            authenticatedSession: authSession,
            currentUserID: { authSession()?.userId },
            privateAccessAllowed: { true },
            featureDecision: decision,
            featureDecisionRevalidator: { captured in
                evaluator.revalidateForRequest(
                    captured: captured,
                    localEnabled: true,
                    accountGeneration: authSession()?.sessionId ?? "missing-session",
                    currentPolicy: snapshot()
                )
            },
            authSessionRefresher: authSessionRefresher,
            accountLeaseRuntime: runtime,
            releasePolicyStore: store,
            candidateInboxDiagnosticSink: eventSink,
            ownerTruthReadDiagnosticSink: ownerTruthReadEventSink,
            candidateInboxPolicyTimeout: policyTimeout
        )
        return (client, decision, snapshot)
    }

    private func waitForOwnerTruthHTTPUI(
        timeout: TimeInterval,
        until condition: @escaping () -> Bool
    ) -> Bool {
        let deadline = Date().addingTimeInterval(timeout)
        while !condition(), Date() < deadline {
            RunLoop.main.run(until: Date().addingTimeInterval(0.01))
        }
        return condition()
    }
}

private final class DeferredFormalMemoryReadClient: OwnerTruthFormalMemoryClient {
    private let vaultID: OwnerTruthVaultID
    private(set) var queries: [OwnerTruthFormalMemoryQuery] = []
    private var listCompletions: [(Result<OwnerTruthFormalMemoryPage, Error>) -> Void] = []

    init(vaultID: String) {
        self.vaultID = OwnerTruthVaultID(vaultID)!
    }

    func fetchOwnerTruthFormalMemories(
        vaultID: OwnerTruthVaultID,
        query: OwnerTruthFormalMemoryQuery,
        completion: @escaping (Result<OwnerTruthFormalMemoryPage, Error>) -> Void
    ) {
        queries.append(query)
        listCompletions.append(completion)
    }

    func fetchOwnerTruthFormalMemory(
        vaultID: OwnerTruthVaultID,
