private final class FailFirstAttemptPerAtomicWrite {
    private let lock = NSLock()
    private var shouldFail = true
    private(set) var failureCount = 0
    private(set) var successCount = 0

    func write(_ data: Data, to url: URL) throws {
        lock.lock()
        if shouldFail {
            shouldFail = false
            failureCount += 1
            lock.unlock()
            throw CocoaError(.fileWriteUnknown)
        }
        shouldFail = true
        successCount += 1
        lock.unlock()
        _ = try KnowledgeLocalStoragePolicy.write(data, to: url)
    }
}

private final class AlwaysFailingAtomicWrite {
    private let lock = NSLock()
    private(set) var attemptCount = 0

    func write(_ data: Data, to url: URL) throws {
        lock.lock()
        attemptCount += 1
        lock.unlock()
        throw CocoaError(.fileWriteUnknown)
    }
}

private final class FailFirstAtomicWriteOperation {
    private let lock = NSLock()
    private(set) var failedAttemptCount = 0
    private(set) var successCount = 0

    func write(_ data: Data, to url: URL) throws {
        lock.lock()
        if failedAttemptCount < 2 {
            failedAttemptCount += 1
            lock.unlock()
            throw CocoaError(.fileWriteUnknown)
        }
        successCount += 1
        lock.unlock()
        _ = try KnowledgeLocalStoragePolicy.write(data, to: url)
    }
}

private final class ToggleAtomicWriteOperation {
    private let lock = NSLock()
    private var failing: Bool

    init(failing: Bool) {
        self.failing = failing
    }

    func setFailing(_ failing: Bool) {
        lock.lock()
        self.failing = failing
        lock.unlock()
    }

    func write(_ data: Data, to url: URL) throws {
        lock.lock()
        let shouldFail = failing
        lock.unlock()
        if shouldFail {
            throw CocoaError(.fileWriteUnknown)
        }
        _ = try KnowledgeLocalStoragePolicy.write(data, to: url)
    }
}

private final class BlockingNextAtomicWrite {
    private let lock = NSLock()
    private let entered = DispatchSemaphore(value: 0)
    private let release = DispatchSemaphore(value: 0)
    private var shouldBlockNext = false

    func blockNextWrite() {
        lock.lock()
        shouldBlockNext = true
        lock.unlock()
    }

    func waitUntilBlocked(timeout: TimeInterval) -> Bool {
        entered.wait(timeout: .now() + timeout) == .success
    }

    func releaseBlockedWrite() {
        release.signal()
    }

    func write(_ data: Data, to url: URL) throws {
        lock.lock()
        let shouldBlock = shouldBlockNext
        if shouldBlockNext { shouldBlockNext = false }
        lock.unlock()
        if shouldBlock {
            entered.signal()
            _ = release.wait(timeout: .now() + 5)
        }
        _ = try KnowledgeLocalStoragePolicy.write(data, to: url)
    }
}

private final class RemoveFailureFileManager: FileManager {
    private let failAtRemoveCall: Int
    private let counterLock = NSLock()
    private var storedRemoveCallCount = 0

    init(failAtRemoveCall: Int) {
        self.failAtRemoveCall = failAtRemoveCall
        super.init()
    }

    var removeCallCount: Int {
        counterLock.lock()
        defer { counterLock.unlock() }
        return storedRemoveCallCount
    }

    override func removeItem(at URL: URL) throws {
        counterLock.lock()
        storedRemoveCallCount += 1
        let shouldFail = storedRemoveCallCount == failAtRemoveCall
        counterLock.unlock()
        if shouldFail {
            throw CocoaError(.fileWriteUnknown)
        }
        try super.removeItem(at: URL)
    }
}

private final class OwnerTruthReviewReadyHTTPURLProtocol: URLProtocol {
    typealias RequestHandler = (URLRequest, OwnerTruthReviewReadyHTTPURLProtocol) -> Void

    private static let lock = NSLock()
    private static var handler: RequestHandler?
    private static var requests: [URLRequest] = []
    private static var requestBodies: [Data?] = []

    static var recordedRequests: [URLRequest] {
        lock.lock()
        defer { lock.unlock() }
        return requests
    }

    static var recordedRequestBodies: [Data?] {
        lock.lock()
        defer { lock.unlock() }
        return requestBodies
    }

    static func install(handler: @escaping RequestHandler) {
        lock.lock()
        requests = []
        requestBodies = []
        self.handler = handler
        lock.unlock()
    }

    static func reset() {
        lock.lock()
        handler = nil
        requests = []
        requestBodies = []
        lock.unlock()
    }

    override class func canInit(with request: URLRequest) -> Bool {
        request.url?.host == "owner-truth.qa.invalid"
    }

    override class func canonicalRequest(for request: URLRequest) -> URLRequest {
        request
    }

    override func startLoading() {
        let handler: RequestHandler?
        let body = Self.bodyData(from: request)
        Self.lock.lock()
        Self.requests.append(request)
        Self.requestBodies.append(body)
        handler = Self.handler
        Self.lock.unlock()

        guard let handler else {
            client?.urlProtocol(self, didFailWithError: URLError(.badServerResponse))
            return
        }
        handler(request, self)
    }

    private let stopLock = NSLock()
    private var stopped = false
    var didStopLoading: Bool {
        stopLock.lock(); defer { stopLock.unlock() }
        return stopped
    }
    override func stopLoading() {
        stopLock.lock(); stopped = true; stopLock.unlock()
    }

    private static func bodyData(from request: URLRequest) -> Data? {
        if let body = request.httpBody {
            return body
        }
        guard let stream = request.httpBodyStream else { return nil }
        stream.open()
        defer { stream.close() }
        var body = Data()
        var buffer = [UInt8](repeating: 0, count: 4_096)
        while stream.hasBytesAvailable {
            let count = stream.read(&buffer, maxLength: buffer.count)
            guard count >= 0 else { return nil }
            if count == 0 { break }
            body.append(buffer, count: count)
        }
        return body
    }

    func respond(statusCode: Int, body: Data) {
        guard let url = request.url,
              let response = HTTPURLResponse(
                url: url,
                statusCode: statusCode,
                httpVersion: "HTTP/1.1",
                headerFields: ["Content-Type": "application/json"]
              ) else {
            client?.urlProtocol(self, didFailWithError: URLError(.badServerResponse))
            return
        }
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: body)
        client?.urlProtocolDidFinishLoading(self)
    }

    func fail(_ error: Error) {
        client?.urlProtocol(self, didFailWithError: error)
    }
}

private final class OwnerTruthMediaUploadSecretStoreSpy: OwnerTruthMediaUploadSecretStoring {
    private var values: [String: OwnerTruthMediaUploadToken] = [:]

    func save(
        _ token: OwnerTruthMediaUploadToken,
        scopeDigest: String,
        taskID: UUID
    ) throws {
        values[key(scopeDigest: scopeDigest, taskID: taskID)] = token
    }

    func load(scopeDigest: String, taskID: UUID) throws -> OwnerTruthMediaUploadToken? {
        values[key(scopeDigest: scopeDigest, taskID: taskID)]
    }

    func remove(scopeDigest: String, taskID: UUID) throws {
        values.removeValue(forKey: key(scopeDigest: scopeDigest, taskID: taskID))
    }

    private func key(scopeDigest: String, taskID: UUID) -> String {
        "\(scopeDigest):\(taskID.uuidString.lowercased())"
    }
}

