private final class CorrectionRequestClientSpy: OwnerTruthCorrectionRequestClient {
    var requestResult: Result<OwnerTruthCorrectionRequestReceipt, Error>?
    var deferRequest = false
    private var deferredRequestCompletion: ((Result<OwnerTruthCorrectionRequestReceipt, Error>) -> Void)?
    private(set) var requestedCommands: [OwnerTruthCorrectionRequestCommand] = []

    func requestOwnerTruthCorrection(
        vaultID: OwnerTruthVaultID,
        expectedOwnerSubjectID: String,
        command: OwnerTruthCorrectionRequestCommand,
        completion: @escaping (Result<OwnerTruthCorrectionRequestReceipt, Error>) -> Void
    ) {
        requestedCommands.append(command)
        if deferRequest {
            deferredRequestCompletion = completion
            return
        }
        completion(requestResult ?? .failure(CorrectionRequestClientSpyError.missingRequestResult))
    }

    func completeDeferredRequest(_ result: Result<OwnerTruthCorrectionRequestReceipt, Error>) {
        let completion = deferredRequestCompletion
        deferredRequestCompletion = nil
        completion?(result)
    }
}

private enum CorrectionRequestClientSpyError: Error {
    case missingRequestResult
}

private final class CorrectionResolutionClientSpy: OwnerTruthCorrectionResolutionClient {
    var changeSetPreviewResult: Result<OwnerTruthCandidateChangeSetProposal, Error>?
    var resolutionResult: Result<OwnerTruthCorrectionResolutionReceipt, Error>?
    var deferResolution = false
    private var deferredResolutionCompletion: ((Result<OwnerTruthCorrectionResolutionReceipt, Error>) -> Void)?
    private(set) var previewedCandidateIDs: [OwnerTruthRecordID] = []
    private(set) var requestedCommands: [OwnerTruthCorrectionResolutionCommand] = []

    func previewOwnerTruthCorrectionChangeSet(
        vaultID: OwnerTruthVaultID,
        candidateID: OwnerTruthRecordID,
        correctedValue: [String: OwnerTruthJSONValue]?,
        correctedValueSchemaVersion: String?,
        completion: @escaping (Result<OwnerTruthCandidateChangeSetProposal, Error>) -> Void
    ) {
        previewedCandidateIDs.append(candidateID)
        completion(changeSetPreviewResult ?? .failure(CorrectionResolutionClientSpyError.missingPreviewResult))
    }

    func resolveOwnerTruthCorrection(
        vaultID: OwnerTruthVaultID,
        expectedOwnerSubjectID: String,
        command: OwnerTruthCorrectionResolutionCommand,
        completion: @escaping (Result<OwnerTruthCorrectionResolutionReceipt, Error>) -> Void
    ) {
        requestedCommands.append(command)
        if deferResolution {
            deferredResolutionCompletion = completion
            return
        }
        completion(resolutionResult ?? .failure(CorrectionResolutionClientSpyError.missingResolutionResult))
    }

    func completeDeferredResolution(_ result: Result<OwnerTruthCorrectionResolutionReceipt, Error>) {
        let completion = deferredResolutionCompletion
        deferredResolutionCompletion = nil
        completion?(result)
    }
}

private enum CorrectionResolutionClientSpyError: Error {
    case missingPreviewResult
    case missingResolutionResult
}

@MainActor
private final class ImmediateNavigationController: UINavigationController {
    override func pushViewController(_ viewController: UIViewController, animated: Bool) {
        super.setViewControllers(viewControllers + [viewController], animated: false)
    }

    @discardableResult
    override func popViewController(animated: Bool) -> UIViewController? {
        guard viewControllers.count > 1, let removed = viewControllers.last else {
            return nil
        }
        super.setViewControllers(Array(viewControllers.dropLast()), animated: false)
        return removed
    }
}

private final class MICIngressDelegateSpy: DialogEngineDelegate {
    var events: [NativeLiveCanonicalTranscriptEvent] = []

    func onDialogStarted() {}
    func onASRResult(text: String, isFinal: Bool) {}
    func onTTSStarted(text: String) {}
    func onTTSFinished() {}
    func onChatStreaming(text: String) {}
    func onError(error: Error) {}
    func onDialogEnded(reason: DialogEndReason) {}
    func onCanonicalTranscriptEvent(_ event: NativeLiveCanonicalTranscriptEvent) {
        events.append(event)
    }
}


extension OwnerTruthContractsTests {
    func testLiveTenMinuteLimitWaitsForCurrentTurnAndFarewell() {
        var limit = EchoLiveSessionLimit(); limit.start(now: 0)
        XCTAssertEqual(limit.tick(now: 599, busy: false), .none)
        XCTAssertEqual(limit.tick(now: 600, busy: true), .none)
        limit.progress(now: 650)
        XCTAssertEqual(limit.tick(now: 701, busy: true), .none)
        XCTAssertEqual(limit.tick(now: 702, busy: false), .farewell)
        XCTAssertEqual(limit.tick(now: 703, busy: false), .none)
        XCTAssertEqual(limit.tick(now: 722, busy: false), .farewellTimeout)
        XCTAssertEqual(limit.tick(now: 723, busy: false), .none)
    }
    func testLiveTenMinuteLimitReconnectStallAndCancellation() {
        var limit = EchoLiveSessionLimit(); limit.start(now: 20); limit.start(now: 500)
        XCTAssertEqual(limit.tick(now: 620, busy: false), .farewell)
        var stalled = EchoLiveSessionLimit(); stalled.start(now: 0)
        XCTAssertEqual(stalled.tick(now: 600, busy: true), .none)
        XCTAssertEqual(stalled.tick(now: 689, busy: true), .none)
        XCTAssertEqual(stalled.tick(now: 690, busy: true), .stalledClose)
        var cancelled = EchoLiveSessionLimit(); cancelled.start(now: 0); cancelled.cancel()
        XCTAssertEqual(cancelled.tick(now: 1000, busy: false), .none)
    }
}


extension OwnerTruthContractsTests {
    @MainActor
    func testLiveTenMinuteControllerFarewellClosesAndPersistsPendingTail() throws {
        try verifyRecoveryGracefulClose(waitForDeadline: false, tenMinute: true)
    }
    @MainActor
    func testLiveTenMinuteOldFarewellCannotCloseNewSession() throws {
        let controller = EchoViewController()
        var completions: [() -> Void] = []
        controller.beginLiveLimitForTesting(now: 0, pause: { true }, playback: { _, done in completions.append(done) })
        controller.tickLiveLimitForTesting(now: 600, busy: false)
        XCTAssertEqual(completions.count, 1)
        controller.beginLiveLimitForTesting(now: 700, pause: { true }, playback: { _, done in completions.append(done) })
        completions[0]()
        XCTAssertTrue(controller.liveLimitSessionOpenForTesting)
        controller.tickLiveLimitForTesting(now: 1300, busy: false)
        XCTAssertEqual(completions.count, 2)
        completions[1]()
        XCTAssertFalse(controller.liveLimitSessionOpenForTesting)
    }
}
